-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — ČÁST 1/2 (53 z 105 tras)
-- Rozděleno na 2 části kvůli délce. Spusť VŠECHNY části (pořadí nerozhoduje).
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
-- Sloupec pro filtr států (idempotentní; v každé části pro jistotu).
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Hrady a zámky jižní Vysočiny  (010_hrady.json)
  delete from public.routes where name = 'Hrady a zámky jižní Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hrady a zámky jižní Vysočiny', 'Okruh po nejkrásnějších hradech a zámcích jižní Vysočiny vede převážně po klidných silnicích II. a III. třídy s příjemným střídáním lesních úseků, rybníků a rozhlédnutých plání Českomoravské vrchoviny. Trasa nabízí svižné zatáčky kolem Kamene a Roštejna i pohodovější přejezdy mezi historickými městečky Žirovnice, Kamenice nad Lipou a Telč. Vrcholem je zastávka v UNESCO městě Telč s renesančním zámkem a náměstím. Nejlepší je jaro až podzim; pozor na úzké a místy hrbolaté lesní silnice u Roštejna a na turistický provoz v Telči za slunečných víkendů.', 'loop', 175, 225, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.424, "lng": 15.015, "label": "Hrad Kámen"}, {"lat": 49.30264, "lng": 15.0793, "label": "Zámek Kamenice nad Lipou"}, {"lat": 49.254, "lng": 15.185, "label": "Zámek Žirovnice"}, {"lat": 49.183, "lng": 15.455, "label": "Zámek Telč"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.424,15.015%7C49.30264,15.0793%7C49.254,15.185%7C49.183,15.455%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_a_l%C3%ADpa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDirovnice%20z%C3%A1mek%20zdola.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn_hrad_03.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg"}'::text[], '{"Hrad Kámen","Zámek Kamenice nad Lipou","Zámek Žirovnice","Zámek Telč","Hrad Roštejn","Restaurace: Gril u Osla / El Grill de Burro (Telč)"}'::text[], '{"Česko"}'::text[], false, 10, 'approved');

  -- Za rozhlednami Vysočiny  (020_rozhledny.json)
  delete from public.routes where name = 'Za rozhlednami Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Za rozhlednami Vysočiny', 'Kompaktní vyhlídkový okruh po malebných silnicích druhé a třetí třídy kolem Pelhřimova a Pacova, který se ZÁMĚRNĚ vyhýbá dálnicím i rychlostním silnicím a drží se klidných okresek přes lesy a pahorkatinu Vysočiny. Trasa nabízí táhlé zatáčky, střídání stoupání a sjezdů a otevřené výhledy z hřebenů Křemešnické vrchoviny, nejlepší je od května do října, kdy jsou rozhledny přístupné a vozovka suchá. Pozor na úzké lesní úseky, občasný štěrk a listí v zatáčkách, v obcích na cyklisty a zemědělskou techniku. Povrch je vesměs slušný, ale místy hrbolatý, proto volte plynulou jízdu. Okruh začíná i končí v Mezné u Pelhřimova.', 'loop', 118, 195, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.431, "lng": 15.223, "label": "Pelhřimov – Masarykovo náměstí"}, {"lat": 49.4035, "lng": 15.32711, "label": "Rozhledna Pípalka na Křemešníku"}, {"lat": 49.376, "lng": 15.435, "label": "Čeřínek – Přední skála"}, {"lat": 49.53578, "lng": 15.00367, "label": "Strážiště u Pacova"}, {"lat": 49.42439, "lng": 15.01388, "label": "Hrad Kámen"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.431,15.223%7C49.4035,15.32711%7C49.376,15.435%7C49.53578,15.00367%7C49.42439,15.01388', 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99edn%C3%AD%20sk%C3%A1la%20(017).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaple%20svat%C3%A9ho%20Jana%20K%C5%99titele%20pod%20Str%C3%A1%C5%BEi%C5%A1t%C4%9Bm%20(Q67180794)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C3%A1men.jpg"}'::text[], '{"Rozhledna Pípalka na Křemešníku","Pelhřimov – Masarykovo náměstí","Restaurace: PATRO (Pelhřimov)","Čeřínek – Přední skála","Strážiště u Pacova","Hrad Kámen"}'::text[], '{"Česko"}'::text[], false, 20, 'approved');

  -- Přehrady a voda Vysočiny  (030_prehrady.json)
  delete from public.routes where name = 'Přehrady a voda Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Přehrady a voda Vysočiny', 'Pohodová okružní jízda po vodních dílech severně od Pelhřimova, vhodná i pro méně zkušené jezdce. Z domácí základny v Mezné vyrazíte přes Červenou Řečici k nádrži Trnávka a dál údolím řeky Želivky k premonstrátskému klášteru v Želivě. Trasa záměrně vede pouze po klidných silnicích druhé a třetí třídy a zcela se vyhýbá dálnicím, takže si užijete zvlněnou krajinu Vysočiny, lesy a hladiny přehrad. Vrcholem je monumentální hráz vodárenské nádrže Švihov (Želivka), odkud se vracíte přes Sedlickou přehradu zpět na jih. Ideální je počítat se zastávkami na koupání a fotky u vody.', 'loop', 118, 165, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – základna Mezná"}, {"lat": 49.425, "lng": 15.18, "label": "Červená Řečice"}, {"lat": 49.518, "lng": 15.212, "label": "Vodní nádrž Trnávka"}, {"lat": 49.53, "lng": 15.215, "label": "Klášter Želiv"}, {"lat": 49.676, "lng": 15.151, "label": "Vodní nádrž Švihov (Želivka)"}, {"lat": 49.51377, "lng": 15.27026, "label": "Vodní nádrž Sedlice"}, {"lat": 49.43, "lng": 15.28, "label": "Humpolec – zpáteční směr"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.425,15.18%7C49.518,15.212%7C49.53,15.215%7C49.676,15.151%7C49.51377,15.27026%7C49.43,15.28', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20the%20Nativity%20of%20the%20Virgin%20Mary%20(%C5%BDeliv)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20Svihov%20A.%20Hraz-Lavka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gustav%20Mahler%20birth%20house%20in%20Kali%C5%A1t%C4%9B%2C%20Pelh%C5%99imov%20District.JPG"}'::text[], '{"Vodní nádrž Trnávka","Klášter Želiv","Vodní nádrž Švihov (Želivka)","Vodní nádrž Sedlice","Restaurace: Mahler Penzion (Kaliště)"}'::text[], '{"Česko"}'::text[], false, 30, 'approved');

  -- UNESCO trojúhelník – Telč, Třebíč, Zelená hora  (040_unesco.json)
  delete from public.routes where name = 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora', 'Okružní vyjížďka po třech památkách UNESCO na Vysočině vede výhradně po scénických silnicích II. a III. třídy – dálnicím a rychlostním silnicím se zcela vyhýbá. Z Mezné u Pelhřimova zamíříte na jih k renesanční Telči, odtud východními údolími řek přes Jaroměřice a Třebíč do srdce Vysočiny. Trasa nabízí svižné zatáčky, lesní úseky kolem rybníků a mírné stoupání k Zelené hoře nad Žďárem. Cesta je středně náročná, s dostatkem zastávek na prohlídky historických center a možností občerstvení ve městech.', 'poi', 215, 270, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí a zámek"}, {"lat": 49.093, "lng": 15.893, "label": "Jaroměřice nad Rokytnou"}, {"lat": 49.219, "lng": 15.877, "label": "Třebíč – bazilika a židovská čtvrť"}, {"lat": 49.35, "lng": 15.9, "label": "Náměšť nad Oslavou – průjezd"}, {"lat": 49.45, "lng": 15.94, "label": "Velké Meziříčí – průjezd"}, {"lat": 49.588, "lng": 15.942, "label": "Zelená hora, Žďár nad Sázavou"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.588,15.942&travelmode=driving&waypoints=49.184,15.453%7C49.093,15.893%7C49.219,15.877%7C49.35,15.9%7C49.45,15.94', 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice%20nad%20rokytnou%20barocco%20castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Jewish%20Synagogue.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg"}'::text[], '{"Zámek a náměstí Telč","Zámek Jaroměřice nad Rokytnou","Restaurace: Adam''s Bar & Bistro (Třebíč)","Bazilika sv. Prokopa v Třebíči","Židovská čtvrť Třebíč","Poutní kostel sv. Jana Nepomuckého na Zelené hoře"}'::text[], '{"Česko"}'::text[], false, 40, 'approved');

  -- Údolím řeky Sázavy  (050_sazava.json)
  delete from public.routes where name = 'Údolím řeky Sázavy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolím řeky Sázavy', 'Malebná trasa sleduje kroutící se údolí řeky Sázavy proti proudu od Lipnice nad Sázavou až po Sázavský klášter a záměrně se vyhýbá dálnicím. Silnice se vinou podél řeky, střídají stoupání k hradům nad údolím s klidnými úseky mezi lesy a skalami. Nejlepší je jezdit v květnu až září, kdy je asfalt suchý a údolí nejzelenější. Pozor na úzké a místy nekvalitní vozovky, kamení a listí v zatáčkách a na frekventované úseky u hradů v hlavní turistické sezóně. Jde o středně náročnou celodenní vyjížďku s pěti zastávkami u hradů a klášterů nad řekou.', 'poi', 98, 150, 'medium',
     '[{"lat": 49.614, "lng": 15.413, "label": "Hrad Lipnice nad Sázavou"}, {"lat": 49.669, "lng": 15.404, "label": "Zámek Světlá nad Sázavou"}, {"lat": 49.696, "lng": 15.278, "label": "Hrad Ledeč nad Sázavou"}, {"lat": 49.81, "lng": 14.928, "label": "Hrad Český Šternberk"}, {"lat": 49.876, "lng": 14.898, "label": "Sázavský klášter"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.614,15.413&destination=49.876,14.898&travelmode=driving&waypoints=49.669,15.404%7C49.696,15.278%7C49.81,14.928', 'https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-%2028.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG"}'::text[], '{"Hrad Lipnice nad Sázavou","Zámek Světlá nad Sázavou","Hrad Ledeč nad Sázavou","Hrad Český Šternberk","Restaurace: Pod Hradem (Český Šternberk)","Sázavský klášter"}'::text[], '{"Česko"}'::text[], false, 50, 'approved');

  -- Žďárské vrchy – skály a serpentiny  (060_zdarske.json)
  delete from public.routes where name = 'Žďárské vrchy – skály a serpentiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Žďárské vrchy – skály a serpentiny', 'Okruh Žďárskými vrchy vede úzkými, klikatými silnicemi skalnatou vrchovinou plnou žulových skalních měst, hlubokých lesů a rašelinišť. Trasa se úmyslně vyhýbá dálnicím i rychlostním silnicím – jede se výhradně po zvlněných okreskách plných zatáček a stoupání kolem nejvyšších vrcholů oblasti. Nejlepší je jaro až podzim; v létě si užijete stinné lesní úseky, na podzim barvy a výhledy, ale pozor na vlhké listí a chladné údolní mlhy. Buďte opatrní na úzkých hřebenových cestách, na štěrk a písek v zatáčkách po lesních pracích a na cyklisty a chodce v okolí turistických skal. Vzhledem k převýšení, technickým serpentinám a proměnlivému povrchu jde o náročnější okruh pro zkušenější jezdce.', 'loop', 118, 175, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.6636, "lng": 16.0533, "label": "Sněžné"}, {"lat": 49.66056, "lng": 16.07222, "label": "Drátník (Dráteník)"}, {"lat": 49.67079, "lng": 16.03238, "label": "Devět skal"}, {"lat": 49.68606, "lng": 16.09333, "label": "Čtyři palice"}, {"lat": 49.55497, "lng": 16.27954, "label": "Rozhledna Karasín"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.6636,16.0533%7C49.66056,16.07222%7C49.67079,16.03238%7C49.68606,16.09333%7C49.55497,16.27954', 'https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg"}'::text[], '{"Skalní útvar Devět skal","Skály Čtyři palice","Skalní útvar Drátník","Restaurace: Hotel Sněžné – Restaurace (Sněžné)","Městys Sněžné (Milovy)","Rozhledna Karasín"}'::text[], '{"Česko"}'::text[], false, 60, 'approved');

  -- Rybníky a zámky Třeboňska  (070_trebonsko.json)
  delete from public.routes where name = 'Rybníky a zámky Třeboňska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rybníky a zámky Třeboňska', 'Pohodová okružní jízda malebnou rybniční krajinou Třeboňska po rovinatých silnicích druhé a třetí třídy, zcela bez dálnic a rychlostních silnic. Trasa vede od renesančního zámku v Jindřichově Hradci přes pohádkový vodní zámek Červená Lhota k historickému městu Třeboň s rybníkem Svět. Cesta pokračuje po hrázi největšího rybníka v Česku – Rožmberka – lemované mohutnými duby a končí u novogotické Schwarzenberské hrobky. Silnice jsou převážně klidné, s minimem stoupání, ideální pro nenáročnou vyjížďku a focení. Počítejte s tempem odpovídajícím poznávání památek a časem na zastávky u vody.', 'poi', 118, 180, 'easy',
     '[{"lat": 49.144, "lng": 15.003, "label": "Jindřichův Hradec – zámek"}, {"lat": 49.198, "lng": 15.077, "label": "Zámek Červená Lhota"}, {"lat": 49.061, "lng": 14.804, "label": "Rybník Rožmberk – hráz"}, {"lat": 49.02, "lng": 14.783, "label": "Schwarzenberská hrobka"}, {"lat": 49.003, "lng": 14.771, "label": "Třeboň – zámek a rybník Svět"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.144,15.003&destination=49.003,14.771&travelmode=driving&waypoints=49.198,15.077%7C49.061,14.804%7C49.02,14.783', 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_u_T%C5%99ebon%C4%9B.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG"}'::text[], '{"Zámek Jindřichův Hradec","Zámek Červená Lhota","Rybník Rožmberk – hráz","Schwarzenberská hrobka","Restaurace: Šupina a Šupinka (Třeboň)","Třeboň – zámek a rybník Svět"}'::text[], '{"Česko"}'::text[], false, 70, 'approved');

  -- Vltava, Orlík a Zvíkov  (080_orlik.json)
  delete from public.routes where name = 'Vltava, Orlík a Zvíkov' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Vltava, Orlík a Zvíkov', 'Malebný okruh podél Orlické přehrady a řeky Vltavy, který propojuje čtyři romantické zastávky nad rozlehlou vodní hladinou. Trasa vede výhradně po klidných silnicích druhé a třetí třídy, dálnicím a rychlostním silnicím se zcela vyhýbá. Užijete si zatáčky nad zálivy přehrady, hluboké lesy a nádherné výhledy z vysokých mostů. Ideální je zastavit na zámku Orlík, přejet Podolský most a zamířit k hradu Zvíkov nad soutokem Vltavy a Otavy. Kombinace svižných úseků a poklidných partií u vody dělá z okruhu příjemnou celodenní vyjížďku.', 'poi', 68, 110, 'medium',
     '[{"lat": 49.539, "lng": 14.164, "label": "Hráz vodní nádrže Orlík"}, {"lat": 49.5175, "lng": 14.16972, "label": "Zámek Orlík nad Vltavou"}, {"lat": 49.4, "lng": 14.29, "label": "Kostel Červená nad Vltavou"}, {"lat": 49.35645, "lng": 14.26352, "label": "Podolský most"}, {"lat": 49.437, "lng": 14.1885, "label": "Hrad Zvíkov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.539,14.164&destination=49.437,14.1885&travelmode=driving&waypoints=49.5175,14.16972%7C49.4,14.29%7C49.35645,14.26352', 'https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerven%C3%A1%20014.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG"}'::text[], '{"Vodní nádrž Orlík – hráz","Zámek Orlík nad Vltavou","Restaurace: U Cvrků (Orlík nad Vltavou)","Kostel Červená nad Vltavou","Podolský most","Hrad Zvíkov"}'::text[], '{"Česko"}'::text[], false, 80, 'approved');

  -- Husitské Táborsko a Chýnovská jeskyně  (090_taborsko.json)
  delete from public.routes where name = 'Husitské Táborsko a Chýnovská jeskyně' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Husitské Táborsko a Chýnovská jeskyně', 'Okružní jízda po malebných silnicích druhé třídy Táborskem, kompletně mimo dálnice a rychlostní komunikace. Z Mezné u Pelhřimova zamíříte přes klidné okresky do husitského Tábora, pokračujete k romantické zřícenině Kozího hrádku a dále zvlněnou krajinou na Chýnov k unikátní jeskyni. Zpáteční část vede přes Bechyni s proslulým mostem Duha a kolem rozhledny Hýlačka nad Táborem zpět na základnu. Trasa nabízí střídání táhlých zatáček v údolí Lužnice a lesních úseků, je vhodná na klidnou celodenní vyjížďku.', 'loop', 142, 215, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.4111, "lng": 14.6558, "label": "Tábor – Žižkovo náměstí a hrad Kotnov"}, {"lat": 49.39775, "lng": 14.72642, "label": "Kozí hrádek"}, {"lat": 49.42944, "lng": 14.83306, "label": "Chýnovská jeskyně"}, {"lat": 49.297, "lng": 14.469, "label": "Zámek Bechyně a most Duha"}, {"lat": 49.389, "lng": 14.643, "label": "Rozhledna Hýlačka"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.4111,14.6558%7C49.39775,14.72642%7C49.42944,14.83306%7C49.297,14.469%7C49.389,14.643', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], '{"Tábor – Žižkovo náměstí a hrad Kotnov","Restaurace: Goldie (Tábor)","Kozí hrádek","Chýnovská jeskyně","Zámek Bechyně a most Duha","Rozhledna Hýlačka"}'::text[], '{"Česko"}'::text[], false, 90, 'approved');

  -- Orlické hory, Adršpach a Broumovsko  (1000_cz_orlicke.json)
  delete from public.routes where name = 'Orlické hory, Adršpach a Broumovsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Orlické hory, Adršpach a Broumovsko', 'Dvoudenní okruh po nejkrásnějších koutech Kladského pomezí a Orlických hor, který vás provede skalními městy, historickými zámky, pohraničními pevnostmi i horskými hřebeny. Trasa se záměrně vyhýbá dálnicím a vede výhradně po klidných silnicích druhé a třetí třídy, aby si motorkář naplno vychutnal serpentiny, výhledy a atmosféru podhůří. První den doporučujeme věnovat severní části okruhu: Adršpašsko-teplickým skálám, Broumovským stěnám, zámku v Náchodě a pevnosti Dobrošov s přespáním v okolí Náchoda nebo Deštného. Druhý den zamíříte do Orlických hor přes Deštné a Masarykovu chatu na Šerlichu, sjedete údolím Metuje k romantickému Peklu a přes Nové Město nad Metují se vydáte až k dominantní Kunětické hoře, odkud se vrátíte zpět. Počítejte s převýšeními, úzkými horskými úseky a nutností plánovat zastávky na jídlo, protože v horách bývají restaurace jen v obcích. Celý okruh je fyzicky i řidičsky středně náročný a odměnou jsou jedny z nejfotogeničtějších scenérií východních Čech.', 'loop', 245, 360, 'medium',
     '[{"lat": 50.61526, "lng": 16.12271, "label": "Adršpašsko-teplické skály"}, {"lat": 50.527, "lng": 16.315, "label": "Broumovské stěny"}, {"lat": 50.41857, "lng": 16.1619, "label": "Zámek Náchod"}, {"lat": 50.4155, "lng": 16.166, "label": "Restaurace: U Slovana (Náchod)"}, {"lat": 50.402, "lng": 16.202, "label": "Pevnost Dobrošov"}, {"lat": 50.30163, "lng": 16.35442, "label": "Deštné v Orlických horách"}, {"lat": 50.30163, "lng": 16.35442, "label": "Restaurace: Kozí chlívek (Deštné v Orlických horách)"}, {"lat": 50.32564, "lng": 16.38635, "label": "Masarykova chata na Šerlichu"}, {"lat": 50.37924, "lng": 16.18716, "label": "Peklo (Bartoňova útulna)"}, {"lat": 50.34377, "lng": 16.1497, "label": "Nové Město nad Metují (zámek)"}, {"lat": 50.08, "lng": 15.81306, "label": "Kunětická hora"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.61526,16.12271&destination=50.08,15.81306&travelmode=driving&waypoints=50.527,16.315%7C50.41857,16.1619%7C50.4155,16.166%7C50.402,16.202%7C50.30163,16.35442%7C50.30163,16.35442%7C50.32564,16.38635%7C50.37924,16.18716', 'https://commons.wikimedia.org/wiki/Special:FilePath/Adr%C5%A1pa%C5%A1skoteplick%C3%A9%20sk%C3%A1ly%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Adr%C5%A1pa%C5%A1skoteplick%C3%A9%20sk%C3%A1ly%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NPR%20Broumovsk%C3%A9%20st%C4%9Bny%2C%20Sup%C3%AD%20hn%C3%ADzdo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N-S%2075%20(Dobrosov)%20a%20budova%20muzea.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panoramatick%C3%BD%20pohled%20na%20Orlick%C3%A9%20Z%C3%A1ho%C5%99%C3%AD%2C%20okres%20Rychnov%20nad%20Kn%C4%9B%C5%BEnou.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20nad%20Metuj%C3%AD%20Peklo%202011%203.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/NMM%20zamek%20z%20nam%20DSC00231.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad-kuneticka%20hora.jpg"}'::text[], '{"Adršpašsko-teplické skály","Broumovské stěny","Zámek Náchod","Restaurace: U Slovana (Náchod)","Pevnost Dobrošov","Deštné v Orlických horách","Restaurace: Kozí chlívek (Deštné v Orlických horách)","Masarykova chata na Šerlichu","Peklo (Bartoňova útulna)","Nové Město nad Metují (zámek)","Kunětická hora"}'::text[], '{"Česko"}'::text[], false, 1000, 'approved');

  -- Nejlepší zatáčky Javořické vrchoviny  (100_javoricka.json)
  delete from public.routes where name = 'Nejlepší zatáčky Javořické vrchoviny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nejlepší zatáčky Javořické vrchoviny', 'Náročný okruh po nejlepších serpentinách Javořické vrchoviny, který se drží výhradně okresek a lesních silnic a zcela se vyhýbá dálnicím. Od základny míříte přes Telč k nekonečně klikatým lesním úsekům pod nejvyšším vrcholem Vysočiny Javořicí (837 m), kde se vinou uzoučké asfaltky mezi smrčinami. Trasa protíná romantické okolí Velkého Pařezitého rybníka, žulové kraje Mrákotína a lesní hrad Roštejn, přičemž nabízí husté střídání zatáček, stoupání a klesání. Nejlepší je jaro až brzký podzim; v lesních stínech bývá i za sucha vlhko a listí či štěrk, pozor na zvěř, cyklisty a úzké krajnice bez svodidel. Ve vlhku a za šera jeďte defenzivně, povrch okresek je místy hrbolatý.', 'loop', 118, 195, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí"}, {"lat": 49.157, "lng": 15.412, "label": "Mrákotín"}, {"lat": 49.153, "lng": 15.351, "label": "Javořice 837 m"}, {"lat": 49.17, "lng": 15.4, "label": "Velký Pařezitý rybník"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.184,15.453%7C49.157,15.412%7C49.153,15.351%7C49.17,15.4%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn%20z%20Javo%C5%99ice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Javorice%202014-08%2012560.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%202020-06-16.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG"}'::text[], '{"Zámek a náměstí Telč","Restaurace: Restaurant Zach (Telč)","Mrákotín – žulové lomy a pomník","Javořice","Velký Pařezitý rybník","Hrad Roštejn"}'::text[], '{"Česko"}'::text[], false, 100, 'approved');

  -- České středohoří a Litoměřicko  (1010_cz_stredohori.json)
  delete from public.routes where name = 'České středohoří a Litoměřicko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'České středohoří a Litoměřicko', 'Jednodenní okruh Českým středohořím a Litoměřickem, který spojuje sopečné vrcholy, románské památky, majestátní zříceniny i barokní zámek nad meandry Labe. Trasa začíná i končí pod Milešovkou, vede přes horu Říp, Házmburk, Terezín, historické jádro Litoměřic a hrad Střekov až k proslulé Portě Bohemice a zámku Ploskovice. Celý okruh je záměrně vedený po silnicích II. a III. třídy a vyhýbá se dálnicím (D8) i rychlostním úsekům, abyste si užili klidnou jízdu krajinou plnou vyhaslých sopek, vinic a výhledů. Silnice jsou zvlněné a v serpentinách pod vrcholy nabízejí zábavnou, ale nenáročnou jízdu vhodnou i pro méně zkušené motorkáře. Ideální je vyrazit za jasného počasí, kdy je z hřebenů středohoří vidět daleko do Polabí i k Krušným horám.', 'loop', 118, 320, 'easy',
     '[{"lat": 50.55491, "lng": 13.93109, "label": "Milešovka"}, {"lat": 50.38645, "lng": 14.28957, "label": "Říp (rotunda sv. Jiří)"}, {"lat": 50.434, "lng": 14.01557, "label": "hrad Házmburk"}, {"lat": 50.51306, "lng": 14.15889, "label": "Terezín (památník)"}, {"lat": 50.53412, "lng": 14.1313, "label": "Litoměřice (náměstí)"}, {"lat": 50.53318, "lng": 14.1376, "label": "Restaurace: Dobrá Bašta (Litoměřice)"}, {"lat": 50.639, "lng": 14.051, "label": "Střekov (hrad, Ústí nad Labem)"}, {"lat": 50.539, "lng": 14.066, "label": "Porta Bohemica (vyhlídka)"}, {"lat": 50.5598, "lng": 14.2012, "label": "zámek Ploskovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.55491,13.93109&destination=50.5598,14.2012&travelmode=driving&waypoints=50.38645,14.28957%7C50.434,14.01557%7C50.51306,14.15889%7C50.53412,14.1313%7C50.53318,14.1376%7C50.639,14.051%7C50.539,14.066', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mile%C5%A1ovka%20(837%20m),%20pohled%20z%20lesa%20na%20%C3%BApat%C3%AD.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mile%C5%A1ovka%20(837%20m),%20pohled%20z%20lesa%20na%20%C3%BApat%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rotunda%20svat%C3%A9ho%20Ji%C5%99%C3%AD%20a%20svat%C3%A9ho%20Vojt%C4%9Bcha%20%C5%98%C3%ADp.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20H%C3%A1zmburk%20(Klap%C3%BD)%20-%20%C4%8Cern%C3%A1%20v%C4%9B%C5%BE.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Czech-2013-Terezin-Theresienstadt-Arbeit%20macht%20frei.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20M%C3%ADrov%C3%A9%20n%C3%A1m.%20%C4%8Dp.160-161.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20Mezibran%C3%AD,%20hradby%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Strekov%20Usti%20nad%20Labem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9%20%C5%BDernoseky,%20Porta%20Bohemica,%20p%C5%99%C3%ADrodn%C3%AD%20rezervace%20Kalv%C3%A1rie.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ploskovice%20Schloss4.JPG"}'::text[], '{"Milešovka","Říp (rotunda sv. Jiří)","hrad Házmburk","Terezín (památník)","Litoměřice (náměstí)","Restaurace: Dobrá Bašta (Litoměřice)","Střekov (hrad, Ústí nad Labem)","Porta Bohemica (vyhlídka)","zámek Ploskovice"}'::text[], '{"Česko"}'::text[], false, 1010, 'approved');

  -- Vranovsko, Bítov a Národní park Podyjí  (1020_cz_podyji.json)
  delete from public.routes where name = 'Vranovsko, Bítov a Národní park Podyjí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Vranovsko, Bítov a Národní park Podyjí', 'Malebná dvoudenní okružní jízda podél hlubokého kaňonu řeky Dyje, která propojuje romantické zámky, hrady i zříceniny s divokou přírodou Národního parku Podyjí. Trasa začíná u pohádkového zámku Vranov nad Dyjí, pokračuje kolem Vranovské přehrady k mohutnému hradu Bítov a tajemné zřícenině Cornštejn. Odtud se stáčí přes vyhlídky Podyjí do nejmenšího rakouského města Hardegg a končí v historickém Znojmě se slavnou rotundou, podzemím a vinařským Šatovem. Jízda záměrně vede pouze po klidných silnicích II. a III. třídy a okresních spojkách údolím Dyje, takže se úplně vyhýbá dálnicím i rychlostním silnicím. Serpentiny nad přehradou a lesní úseky Podyjí nabízejí požitkářskou jízdu s neustálými výhledy, proto počítejte s pomalejším tempem a častými zastávkami.', 'poi', 118, 430, 'medium',
     '[{"lat": 48.89257, "lng": 15.81085, "label": "Vranov nad Dyjí (zámek)"}, {"lat": 48.90982, "lng": 15.81181, "label": "Vranovská přehrada"}, {"lat": 48.944, "lng": 15.701, "label": "Hrad Bítov"}, {"lat": 48.929, "lng": 15.721, "label": "Zřícenina Cornštejn"}, {"lat": 48.90989, "lng": 15.82118, "label": "Restaurace: U Vodnáře (Vranov nad Dyjí)"}, {"lat": 48.853, "lng": 16.059, "label": "NP Podyjí – Sealsfieldův kámen"}, {"lat": 48.85, "lng": 15.87, "label": "Hardegg"}, {"lat": 48.85541, "lng": 16.04352, "label": "Znojmo – rotunda svaté Kateřiny"}, {"lat": 48.8557, "lng": 16.0487, "label": "Znojemské podzemí"}, {"lat": 48.8544, "lng": 16.0492, "label": "Restaurace: Bistrograf (Znojmo)"}, {"lat": 48.796, "lng": 16.01, "label": "Šatov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.89257,15.81085&destination=48.796,16.01&travelmode=driving&waypoints=48.90982,15.81181%7C48.944,15.701%7C48.929,15.721%7C48.90989,15.82118%7C48.853,16.059%7C48.85,15.87%7C48.85541,16.04352%7C48.8557,16.0487', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji%20Castle%20CZ%20873.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji%20Castle%20CZ%20873.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GuentherZ%201995%20IMG0028%20Vranov%20nad%20Dyji%20TalsperreIMG.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20bitov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20resevoir%20from%20Corn%C5%A1tejn%20viewpoint%2C%20B%C3%ADtov%2C%20Znojmo%20District.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03(js).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Podyj%C3%AD%2C%20Sealsfield%C5%AFv%20k%C3%A1men%20-%20vyhl%C3%ADdka%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Thayatal%2CHardegg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20(Znaim)%20-%20Rotunda%20svat%C3%A9%20Kate%C5%99iny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo-The%20Underground%20Passages%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kino%20Sv%C4%9Bt%2C%20Znojmo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov%2C%20Malovan%C3%BD%20sklep.jpg"}'::text[], '{"Vranov nad Dyjí (zámek)","Vranovská přehrada","Hrad Bítov","Zřícenina Cornštejn","Restaurace: U Vodnáře (Vranov nad Dyjí)","NP Podyjí – Sealsfieldův kámen","Hardegg","Znojmo – rotunda svaté Kateřiny","Znojemské podzemí","Restaurace: Bistrograf (Znojmo)","Šatov"}'::text[], '{"Česko","Rakousko"}'::text[], false, 1020, 'approved');

  -- Plzeňsko, Český les a Chodsko  (1030_cz_plzensko.json)
  delete from public.routes where name = 'Plzeňsko, Český les a Chodsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Plzeňsko, Český les a Chodsko', 'Okruh z Plzně vede za nejkrásnějšími hrady a rozhlednami západních Čech a záměrně se vyhýbá dálnicím i rychlostním silnicím – jede se výhradně po klidných silnicích II. a III. třídy, které lemují řeky Úhlavu a Otavu a stoupají do hřebenů Českého lesa. První den doporučujeme z Plzně přes vodní hrad Švihov a mohutnou zříceninu Rabí až do Domažlic, srdce Chodska, kde je ideální přenocovat. Druhý den pokračujete k nejstaršímu kamennému hradu v Česku Přimdě, na nejvyšší vrchol Českého lesa Čerchov a přes rozhlednu Koráb u Kdyně zpět přes Klatovy do Plzně. Trasa je zvlněná, s řadou zatáček a stoupání, proto ji hodnotíme jako středně náročnou a ideální na dva dny. Motorkáři ocení plynulé okresky bez kamionů, výhledy na bavorské pomezí a hustou síť hradů, muzeí a chodských hospůdek.', 'loop', 265, 420, 'medium',
     '[{"lat": 49.74675, "lng": 13.38758, "label": "Plzeň – Pivovar Plzeňský Prazdroj"}, {"lat": 49.74745, "lng": 13.37761, "label": "Plzeň – Katedrála sv. Bartoloměje"}, {"lat": 49.4832, "lng": 13.2818, "label": "Vodní hrad Švihov"}, {"lat": 49.27997, "lng": 13.619, "label": "Hrad Rabí"}, {"lat": 49.44054, "lng": 12.92649, "label": "Domažlice – náměstí Míru a Chodský hrad"}, {"lat": 49.44199, "lng": 12.92722, "label": "Restaurace: Městský pivovar Domažlice (Domažlice)"}, {"lat": 49.67783, "lng": 12.67206, "label": "Hrad Přimda – nejstarší hrad v Česku"}, {"lat": 49.38134, "lng": 12.78246, "label": "Čerchov – Kurzova rozhledna (Klenčí pod Čerchovem)"}, {"lat": 49.39547, "lng": 13.0753, "label": "Rozhledna Koráb (Kdyně)"}, {"lat": 49.39722, "lng": 13.28694, "label": "Klatovy – Černá věž a katakomby"}, {"lat": 49.39723, "lng": 13.29443, "label": "Restaurace: Pilsner Urquell Original Restaurant Střelnice (Klatovy)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.74675,13.38758&destination=49.39723,13.29443&travelmode=driving&waypoints=49.74745,13.37761%7C49.4832,13.2818%7C49.27997,13.619%7C49.44054,12.92649%7C49.44199,12.92722%7C49.67783,12.67206%7C49.38134,12.78246%7C49.39547,13.0753', 'https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88sk%C3%BD%20Prazdroj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88sk%C3%BD%20Prazdroj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88%20Cathedral%20of%20Saint%20Bartholomew-0146%20crop.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20Hrad%20%C5%A0vihov%20-%20Water%20Castle%20Svihov%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Rab%C3%AD%20Castle%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20a%20Dolej%C5%A1%C3%AD%20br%C3%A1na%20(8856).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20Komensk%C3%A9ho%2011,%20m%C4%9Bstsk%C3%BD%20pivovar%20(9326).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Primda%20Gesamtansicht.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerchov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kdyn%C4%9B%20-%20rozhledna%20Kor%C3%A1b,%20schodi%C5%A1t%C4%9B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez%20Klatovy%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Klatovy%20namesti.JPG"}'::text[], '{"Plzeň – Pivovar Plzeňský Prazdroj","Plzeň – Katedrála sv. Bartoloměje","Vodní hrad Švihov","Hrad Rabí","Domažlice – náměstí Míru a Chodský hrad","Restaurace: Městský pivovar Domažlice (Domažlice)","Hrad Přimda – nejstarší hrad v Česku","Čerchov – Kurzova rozhledna (Klenčí pod Čerchovem)","Rozhledna Koráb (Kdyně)","Klatovy – Černá věž a katakomby","Restaurace: Pilsner Urquell Original Restaurant Střelnice (Klatovy)"}'::text[], '{"Česko"}'::text[], false, 1030, 'approved');

  -- Malá Fatra a Terchová  (1100_sk_mala_fatra.json)
  delete from public.routes where name = 'Malá Fatra a Terchová' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Malá Fatra a Terchová', 'Okružní scénická trasa srdcem Malé Fatry, která spojuje divokou Vrátnu dolinu, romantické soutěsky a folklorní klenoty Terchovska a Rajecka. Z Terchové vyrazíte k Jánošíkovým dierám a k monumentální soše Juraje Jánošíka, poté sjedete pod hrad Strečno nad Váhom a zamíříte za malovanými domy v Čičmanech. Cestou zpět projedete kolem bizarních Súľovských skal a přes Žilinu se vrátíte zpět do Terchové. Trasa je koncipována výhradně po silnicích II. a III. třídy a údolními cestami — dálnicím a rychlostním silnicím (např. D1 a D3) se záměrně vyhýbá, aby si motorkář vychutnal serpentiny, vyhlídky a klidný provoz. Ideální je rozložit okruh na 1–2 dny s přenocováním v Terchové nebo Žilině.', 'loop', 165, 690, 'medium',
     '[{"lat": 49.2086, "lng": 19.0396, "label": "Vrátna dolina (Terchová)"}, {"lat": 49.2534, "lng": 19.0727, "label": "Jánošíkove diery"}, {"lat": 49.2543, "lng": 19.0378, "label": "Rozhľadňa / socha Jánošík (Terchová)"}, {"lat": 49.217, "lng": 19.0972, "label": "Malý Rozsutec"}, {"lat": 49.2033, "lng": 19.0539, "label": "Restaurace: Koliba Starý dvor Vrátna (Terchová)"}, {"lat": 49.17694, "lng": 18.86278, "label": "Hrad Strečno"}, {"lat": 48.95, "lng": 18.51667, "label": "Čičmany (maľované domy)"}, {"lat": 49.165, "lng": 18.595, "label": "Súľovské skaly"}, {"lat": 49.2512, "lng": 19.0692, "label": "Restaurace: Terchovská Koliba Diery (Terchová)"}, {"lat": 49.22315, "lng": 18.73941, "label": "Žilina"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.2086,19.0396&destination=49.22315,18.73941&travelmode=driving&waypoints=49.2534,19.0727%7C49.2543,19.0378%7C49.217,19.0972%7C49.2033,19.0539%7C49.17694,18.86278%7C48.95,18.51667%7C49.165,18.595%7C49.2512,19.0692', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Terchov%C3%A1%20-%20Socha%20J%C3%A1no%C5%A1%C3%ADka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1rodn%C3%AD%20park%20Mal%C3%A1%20Fatra,%20NPR%20Rozsutec%20-%20Mal%C3%BD%20Rozsutec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stre%C4%8Dno%20castle%20Slovakia%20Frontlook.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Ci%C4%8Dmany%20(Csicsm%C3%A1ny,%20Zimmermannshau)%20-%20old%20house.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1u%C4%8Dn%C3%BD%20chodn%C3%ADk%20S%C3%BA%C4%BEovsk%C3%A9%20skaly%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zilina%20SVK%20Square01.JPG"}'::text[], '{"Vrátna dolina (Terchová)","Jánošíkove diery","Rozhľadňa / socha Jánošík (Terchová)","Malý Rozsutec","Restaurace: Koliba Starý dvor Vrátna (Terchová)","Hrad Strečno","Čičmany (maľované domy)","Súľovské skaly","Restaurace: Terchovská Koliba Diery (Terchová)","Žilina"}'::text[], '{"Slovensko"}'::text[], false, 1100, 'approved');

  -- Slavonicko a Česká Kanada  (110_slavonicko.json)
  delete from public.routes where name = 'Slavonicko a Česká Kanada' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slavonicko a Česká Kanada', 'Malebný okruh Českou Kanadou po klidných lesních silničkách bez dálnic a rychlostních komunikací. Trasa vede mezi rybníky, borovými lesy a žulovými balvany od renesančních Slavonic přes romantickou zříceninu Landštejna a Nové Bystřice s proslulou úzkokolejkou až k majestátnímu zámku v Jindřichově Hradci. Silnice jsou úzké, málo frekventované a plné plynulých zatáček, ideální pro pohodovou jízdu tempem, které si užijete. Doporučujeme počítat s častými zastávkami na focení a odpočinek u vody. Dálnicím a hlavním tahům se celá trasa záměrně vyhýbá.', 'poi', 118, 195, 'medium',
     '[{"lat": 48.999, "lng": 15.351, "label": "Slavonice - renesanční náměstí"}, {"lat": 48.995, "lng": 15.19, "label": "Staré Město pod Landštejnem"}, {"lat": 48.9878, "lng": 15.22902, "label": "Hrad Landštejn"}, {"lat": 49.02, "lng": 15.104, "label": "Nová Bystřice - úzkokolejka"}, {"lat": 49.142, "lng": 15.003, "label": "Zámek Jindřichův Hradec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.999,15.351&destination=49.142,15.003&travelmode=driving&waypoints=48.995,15.19%7C48.9878,15.22902%7C49.02,15.104', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem,%20z%C3%A1mek%20Dobroho%C5%99%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG"}'::text[], '{"Slavonice – renesanční sgrafitové náměstí","Hrad Landštejn","Rybník Osika / Staré Město pod Landštejnem","Nová Bystřice – úzkokolejka","Restaurace: Pivovar Nová Bystřice (Nová Bystřice)","Zámek Jindřichův Hradec"}'::text[], '{"Česko"}'::text[], false, 110, 'approved');

  -- Nízke Tatry – Chopok a Demänovská dolina  (1110_sk_nizke_tatry.json)
  delete from public.routes where name = 'Nízke Tatry – Chopok a Demänovská dolina' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nízke Tatry – Chopok a Demänovská dolina', 'Dvoudenní scénická jízda srdcem slovenských Nízkých Tater, která spojuje velehorské panorama Chopku s tajemným podzemím Demänovské doliny a malebnými dědinami Liptova. Trasa se záměrně vyhýbá dálnicím (D1) a vede po klidných horských a údolních silnicích, kde si užijete zatáčky, výhledy a autentickou atmosféru regionu. První den projedete Demänovskou dolinou k lanovce na Chopok, navštívíte obě slavné jeskyně a přenocujete v okolí Jasné či Ružomberku. Druhý den vede přes UNESCO dědinu Vlkolínec, kolem přehrady Liptovská Mara a přes Ružomberok dolů k rekreačnímu středisku Tále a hornické obci Špania Dolina. Počítejte s pomalejším tempem v horských úsecích a na úzkých silnicích k dědinám. Rozdělení: 1. den – Demänovská dolina, Chopok a jeskyně; 2. den – Vlkolínec, Liptovská Mara, Ružomberok, Tále a Špania Dolina. Pozn.: celá trasa se vyhýbá dálnicím a využívá výhradně silnice nižších tříd s výhledy do krajiny.', 'poi', 175, 540, 'medium',
     '[{"lat": 48.9433, "lng": 19.5911, "label": "Chopok (Jasná)"}, {"lat": 48.99806, "lng": 19.58306, "label": "Demänovská jaskyňa slobody"}, {"lat": 49.01625, "lng": 19.58278, "label": "Demänovská ľadová jaskyňa"}, {"lat": 49.03927, "lng": 19.2773, "label": "Vlkolínec (UNESCO)"}, {"lat": 49.09861, "lng": 19.48889, "label": "Liptovská Mara"}, {"lat": 49.0769, "lng": 19.3084, "label": "Ružomberok"}, {"lat": 48.83, "lng": 19.58, "label": "Bystrá / Tále"}, {"lat": 48.80747, "lng": 19.13401, "label": "Špania Dolina"}, {"lat": 48.972, "lng": 19.585, "label": "Restaurace: Slovenská Koliba Jasná (Demänovská Dolina)"}, {"lat": 49.053, "lng": 19.294, "label": "Restaurace: Koliba pod Vlkolíncom (Ružomberok)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9433,19.5911&destination=49.053,19.294&travelmode=driving&waypoints=48.99806,19.58306%7C49.01625,19.58278%7C49.03927,19.2773%7C49.09861,19.48889%7C49.0769,19.3084%7C48.83,19.58%7C48.80747,19.13401%7C48.972,19.585', 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzk%C3%A9%20Tatry,%20Chopok%20(7).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzk%C3%A9%20Tatry,%20Chopok%20(7).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Demanova%20Cave%20of%20Freedom%2024.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Demanovska%20ladova%20jaskyna%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Liptovska%20Mara%20od%20pol.%20Ratkovie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ru%C5%BEomberok,%20centrum.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tatry%20Dolina%20Bystrej%20dron%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spania%20Dolina%202007%2011.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jasn%C3%A1%20-%20Chopok,%20N%C3%ADzk%C3%A9%20Tatry-01.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG"}'::text[], '{"Chopok (Jasná)","Demänovská jaskyňa slobody","Demänovská ľadová jaskyňa","Vlkolínec (UNESCO)","Liptovská Mara","Ružomberok","Bystrá / Tále","Špania Dolina","Restaurace: Slovenská Koliba Jasná (Demänovská Dolina)","Restaurace: Koliba pod Vlkolíncom (Ružomberok)"}'::text[], '{"Slovensko"}'::text[], false, 1110, 'approved');

  -- Orava – Oravský hrad a Roháče  (1120_sk_orava.json)
  delete from public.routes where name = 'Orava – Oravský hrad a Roháče' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Orava – Oravský hrad a Roháče', 'Scénická dvoudenní jízda srdcem slovenské Oravy, která spojuje majestátní Oravský hrad, tyrkysovou Oravskou priehradu a divoké štíty Roháčů v Západních Tatrách. Trasa se záměrně vyhýbá dálnicím a rychlostním silnicím – vede výhradně po klidných regionálních silnicích II. a III. třídy s výhledy na hory, dřevěné oravské vesnice a horské doliny. První den vyrazíte od Oravského hradu k Oravské priehrade a Slanickému ostrovu umenia, zastavíte se v Trstené a přespíte v okolí Zuberce. Druhý den vás čeká skanzen Brestová, výjezd na Zverovku k Ťatliakovu plesu, návrat přes Dolný Kubín a závěrečná procházka romantickou Kvačianskou dolinou. Počítejte s úzkými serpentinami a horským počasím – jízda je fyzicky i technicky středně náročná, odměnou jsou ale jedny z nejkrásnějších výhledů na severním Slovensku.', 'poi', 195, 420, 'medium',
     '[{"lat": 49.26185, "lng": 19.35854, "label": "Oravský hrad (Oravský Podzámok)"}, {"lat": 49.4, "lng": 19.55, "label": "Oravská priehrada"}, {"lat": 49.40673, "lng": 19.51618, "label": "Slanický ostrov umenia"}, {"lat": 49.36085, "lng": 19.61061, "label": "Trstená"}, {"lat": 49.2661, "lng": 19.638, "label": "Restaurace: Koliba pod Roháčmi (Zuberec)"}, {"lat": 49.26591, "lng": 19.66297, "label": "Zuberec (skanzen Brestová)"}, {"lat": 49.2291, "lng": 19.7126, "label": "Roháče / Zverovka (Ťatliakovo pleso)"}, {"lat": 49.20983, "lng": 19.30341, "label": "Restaurace: Reštaurácia Marína (Dolný Kubín)"}, {"lat": 49.20983, "lng": 19.30341, "label": "Dolný Kubín"}, {"lat": 49.19063, "lng": 19.54196, "label": "Kvačianska dolina"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.26185,19.35854&destination=49.19063,19.54196&travelmode=driving&waypoints=49.4,19.55%7C49.40673,19.51618%7C49.36085,19.61061%7C49.2661,19.638%7C49.26591,19.66297%7C49.2291,19.7126%7C49.20983,19.30341%7C49.20983,19.30341', 'https://commons.wikimedia.org/wiki/Special:FilePath/Orava%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orava%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oravska%20priehrada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Slanick%C3%BD%20ostrov%20umenia,%20Oravsk%C3%A1%20priehrada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trsten%C3%A11.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20oravskej%20dediny%2C%20Zuberec-Brestova%20(15).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20oravskej%20dediny%20Zuberec%20-%20Brestov%C3%A1%20(10).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Roh%C3%A1%C4%8De,%20pleso.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20Kubin%20Hviezdoslavovo%20nam%202-1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20kubin%20town%20center.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kvacianska%20dolina%2001.jpg"}'::text[], '{"Oravský hrad (Oravský Podzámok)","Oravská priehrada","Slanický ostrov umenia","Trstená","Restaurace: Koliba pod Roháčmi (Zuberec)","Zuberec (skanzen Brestová)","Roháče / Zverovka (Ťatliakovo pleso)","Restaurace: Reštaurácia Marína (Dolný Kubín)","Dolný Kubín","Kvačianska dolina"}'::text[], '{"Slovensko"}'::text[], false, 1120, 'approved');

  -- Banská Štiavnica a Štiavnické vrchy  (1130_sk_stiavnica.json)
  delete from public.routes where name = 'Banská Štiavnica a Štiavnické vrchy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Banská Štiavnica a Štiavnické vrchy', 'Jednodenní okruh po srdci Štiavnických vrchov, který spojuje středověké báňské město Banská Štiavnica se sopečnými kopci, tajchy a barokními památkami regionu Hont. Trasa vede po malebných regionálních cestách přes Svätý Anton, Počúvadlo a přes hřebeny až k Banské Bystrici a zpět. Vědomě se vyhýbá dálnicím a rychlostním silnicím (žiadna diaľnica) – jede se výhradně po klikatých silnicích druhé a třetí třídy s množstvím zatáček a výhledů, což je pro motorkáře to pravé. Cestou nabírá výšku k rozhledně Sitno, nejvyššímu vrcholu pohoří, a klesá k romantickému jezeru Počúvadlo. Počítejte s pomalejším tempem kvůli úzkým a členitým úsekům, zato s odměnou v podobě panoramat, UNESCO památek a klidných horských serpentin.', 'loop', 128, 210, 'medium',
     '[{"lat": 48.45931, "lng": 18.89122, "label": "Banská Štiavnica – Starý zámok"}, {"lat": 48.45561, "lng": 18.896, "label": "Banská Štiavnica – Nový zámok"}, {"lat": 48.4626, "lng": 18.908, "label": "Kalvária Banská Štiavnica"}, {"lat": 48.4214, "lng": 18.94286, "label": "Kaštieľ Svätý Anton"}, {"lat": 48.40307, "lng": 18.87716, "label": "Sitno – rozhľadňa"}, {"lat": 48.40953, "lng": 18.85678, "label": "Tajch Počúvadlo"}, {"lat": 48.45889, "lng": 18.8965, "label": "Restaurace: 4Sochy Restaurant (Banská Štiavnica)"}, {"lat": 48.73529, "lng": 19.14511, "label": "Banská Bystrica – Námestie SNP"}, {"lat": 48.71789, "lng": 19.15364, "label": "Vartovka – rozhľadňa a hvezdáreň"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.45931,18.89122&destination=48.71789,19.15364&travelmode=driving&waypoints=48.45561,18.896%7C48.4626,18.908%7C48.4214,18.94286%7C48.40307,18.87716%7C48.40953,18.85678%7C48.45889,18.8965%7C48.73529,19.14511', 'https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%BD%20z%C3%A1mok,%20Bansk%C3%A1%20%C5%A0tiavnica%20-%20hradn%C3%BD%20m%C3%BAr.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%BD%20z%C3%A1mok,%20Bansk%C3%A1%20%C5%A0tiavnica%20-%20hradn%C3%BD%20m%C3%BAr.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20from%20Nov%C3%BD%20z%C3%A1mok%202007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kalvaria%20Banska%20Stiavnica,%20Dolny%20kostol.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1tie%C4%BE%20Sv%C3%A4t%C3%BD%20Anton%201%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhladna%20sitno.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jazero%20Po%C4%8D%C3%BAvadlo%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/969%2001%20Bansk%C3%A1%20%C5%A0tiavnica,%20Slovakia%20-%20panoramio%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Banska%20Bystrica%20SNP%20Square.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vartovka%20v%C4%9B%C5%BE.JPG"}'::text[], '{"Banská Štiavnica – Starý zámok","Banská Štiavnica – Nový zámok","Kalvária Banská Štiavnica","Kaštieľ Svätý Anton","Sitno – rozhľadňa","Tajch Počúvadlo","Restaurace: 4Sochy Restaurant (Banská Štiavnica)","Banská Bystrica – Námestie SNP","Vartovka – rozhľadňa a hvezdáreň"}'::text[], '{"Slovensko"}'::text[], false, 1130, 'approved');

  -- Slovenský kras a Zádielska tiesňava  (1140_sk_slovensky_kras.json)
  delete from public.routes where name = 'Slovenský kras a Zádielska tiesňava' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slovenský kras a Zádielska tiesňava', 'Táto scénická okružná trasa vás prevedie srdcom Slovenského krasu, jedinečnej krasovej krajiny zapísanej v zozname UNESCO. Začína v najhlbšej rokline Slovenska, Zádielskej tiesňave, a pokračuje popri slávnych jaskyniach Domica, Gombasecká a Jasovská, pričom nevynechá ani majestátny hrad Krásna Hôrka a romantický kaštieľ Betliar. Vyvrcholením je návšteva metropoly východu Košíc s dominantným Dómom svätej Alžbety. Trasa je vedená zámerne po malebných okresných a druhotriednych cestách cez planiny a údolia Rožňavska, dálniciam a rýchlostným cestám sa úplne vyhýba, aby ste si naplno vychutnali kľukaté serpentíny a výhľady. Vzhľadom na množstvo zastávok a jaskynné prehliadky odporúčame rozdeliť si okruh na dva dni s prenocovaním v okolí Rožňavy alebo Košíc.', 'poi', 175, 690, 'medium',
     '[{"lat": 48.6336, "lng": 20.82322, "label": "Zádielska tiesňava"}, {"lat": 48.5489, "lng": 20.5036, "label": "Silická ľadnica"}, {"lat": 48.4778, "lng": 20.4703, "label": "jaskyňa Domica"}, {"lat": 48.5628, "lng": 20.4665, "label": "Gombasecká jaskyňa"}, {"lat": 48.64956, "lng": 20.52661, "label": "Restaurace: Apetit reštaurácia (Rožňava)"}, {"lat": 48.65837, "lng": 20.60027, "label": "hrad Krásna Hôrka"}, {"lat": 48.70603, "lng": 20.51045, "label": "kaštieľ Betliar"}, {"lat": 48.67696, "lng": 20.97617, "label": "Jasovská jaskyňa"}, {"lat": 48.71958, "lng": 21.25812, "label": "Košice (Dóm sv. Alžbety)"}, {"lat": 48.7234, "lng": 21.2569, "label": "Restaurace: Med Malina (Košice)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.6336,20.82322&destination=48.7234,21.2569&travelmode=driving&waypoints=48.5489,20.5036%7C48.4778,20.4703%7C48.5628,20.4665%7C48.64956,20.52661%7C48.65837,20.60027%7C48.70603,20.51045%7C48.67696,20.97617%7C48.71958,21.25812', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zadiel%20canyon%20from%20north.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zadiel%20canyon%20from%20north.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Silicka%20ladnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Domica%20Cave%2022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia%20Gombasecka%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava-panorama.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Betliar%2C%20ka%C5%A1tie%C4%BE%2C%20park%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/JasovskaJaskyna2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%B3m%20sv%C3%A4tej%20Al%C5%BEbety%20-%20z%20juhu%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%A1ice%2C%20Hlavn%C3%A1%20ulica%203.JPG"}'::text[], '{"Zádielska tiesňava","Silická ľadnica","jaskyňa Domica","Gombasecká jaskyňa","Restaurace: Apetit reštaurácia (Rožňava)","hrad Krásna Hôrka","kaštieľ Betliar","Jasovská jaskyňa","Košice (Dóm sv. Alžbety)","Restaurace: Med Malina (Košice)"}'::text[], '{"Slovensko"}'::text[], false, 1140, 'approved');

  -- Wachau – údolí Dunaje a vinice  (1200_at_wachau.json)
  delete from public.routes where name = 'Wachau – údolí Dunaje a vinice' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Wachau – údolí Dunaje a vinice', 'Wachau je jeden z nejkrásnějších úseků Dunaje a zapsaný na seznamu UNESCO – kombinace strmých vinic, barokních klášterů, hradních zřícenin a malebných vinařských městeček. Trasa vede po obou březích Dunaje mezi Melkem a Kremží, kde se silnice line těsně podél řeky a mezi terasovitými vinohrady. Začnete u velkolepého benediktinského opatství Melk, projedete kolem zříceniny Aggstein a Willendorfu, kde byla nalezena slavná Venuše. Přejedete přívozem nebo mostem na druhý břeh a pokračujete přes Spitz, Weißenkirchen a Dürnstein až do Kremže, zakončeno návštěvou opatství Göttweig na protějším kopci. Trasa se ZÁMĚRNĚ VYHÝBÁ dálnicím (dálnici A1 nechte stranou) – jede se pomalými panoramatickými silnicemi B3 a B33 po březích Dunaje, kde si vychutnáte scenérii a zastávky. Ideální jednodenní výlet plný vína, historie a nádherných výhledů na řeku.', 'poi', 78, 180, 'easy',
     '[{"lat": 48.2281, "lng": 15.33064, "label": "Klášter Melk (Stift Melk)"}, {"lat": 48.3144, "lng": 15.4217, "label": "Zřícenina Aggstein (Burgruine Aggstein)"}, {"lat": 48.3167, "lng": 15.3833, "label": "Willendorf (naleziště Venuše)"}, {"lat": 48.36433, "lng": 15.41989, "label": "Spitz an der Donau"}, {"lat": 48.3973, "lng": 15.4696, "label": "Weißenkirchen in der Wachau (vinice)"}, {"lat": 48.3998, "lng": 15.4728, "label": "Restaurace: Heuriger Walter Denk (Weißenkirchen)"}, {"lat": 48.3975, "lng": 15.5219, "label": "Dürnstein (zřícenina a modrá věž)"}, {"lat": 48.40984, "lng": 15.59646, "label": "Krems an der Donau (Steiner Tor)"}, {"lat": 48.36778, "lng": 15.6125, "label": "Klášter Göttweig (Stift Göttweig)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.2281,15.33064&destination=48.36778,15.6125&travelmode=driving&waypoints=48.3144,15.4217%7C48.3167,15.3833%7C48.36433,15.41989%7C48.3973,15.4696%7C48.3998,15.4728%7C48.3975,15.5219%7C48.40984,15.59646', 'https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20-%20Stift.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20-%20Stift.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20Aggstein%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Willendorf-Venus-1468.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spitz%20an%20der%20Donau%20-%20Ruine%20Hinterhaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau%20-%20Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Duernstein%20Wachau.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Steiner%20Tor,%20Krems%20an%20der%20Donau,%20Lower%20Austria,%2020210729%201017%200929.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Furth%20bei%20G%C3%B6ttweig%20-%20Stift%20G%C3%B6ttweig%20(a).JPG"}'::text[], '{"Klášter Melk (Stift Melk)","Zřícenina Aggstein (Burgruine Aggstein)","Willendorf (naleziště Venuše)","Spitz an der Donau","Weißenkirchen in der Wachau (vinice)","Restaurace: Heuriger Walter Denk (Weißenkirchen)","Dürnstein (zřícenina a modrá věž)","Krems an der Donau (Steiner Tor)","Klášter Göttweig (Stift Göttweig)"}'::text[], '{"Rakousko"}'::text[], false, 1200, 'approved');

  -- Za hradem Pernštejn a Novým Městem na Moravě  (120_pernstejn.json)
  delete from public.routes where name = 'Za hradem Pernštejn a Novým Městem na Moravě' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Za hradem Pernštejn a Novým Městem na Moravě', 'Okruh vede z Mezné u Pelhřimova přes východní Vysočinu po malebných silnicích II. a III. třídy, přičemž se zcela vyhýbá dálnicím – žádné úseky po D1 se nejedou. Trasa vás provede zvlněnou krajinou Žďárských vrchů se zatáčkovitými úseky, lesy a výhledy, ideálními pro pohodovou i svižnější jízdu. Cestou navštívíte skvěle zachovalý gotický hrad Pernštejn, poutní kostel na Zelené hoře, historické náměstí v Novém Městě na Moravě i rozhlednu Horní les. Silnice jsou převážně kvalitní, místy užší a klikaté v okolí říčních údolí Svratky, což z okruhu dělá zajímavý celodenní zážitek. Doporučujeme jet za suchého počasí, protože některé lesní úseky mohou být stinné a vlhké.', 'poi', 205, 300, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.58806, "lng": 15.94167, "label": "Zámek Žďár nad Sázavou / Zelená hora"}, {"lat": 49.56111, "lng": 16.07417, "label": "Nové Město na Moravě"}, {"lat": 49.5899, "lng": 16.34235, "label": "Rozhledna Horní les"}, {"lat": 49.55028, "lng": 16.31333, "label": "Hrad Pernštejn"}, {"lat": 49.524, "lng": 16.259, "label": "Bystřice nad Pernštejnem / Zubštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.58806,15.94167%7C49.56111,16.07417%7C49.5899,16.34235%7C49.55028,16.31333%7C49.524,16.259', 'https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rove%C4%8Dn%C3%A9%20-%20rozhledna%20Horn%C3%AD%20les,%202024-10,%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pern%C5%A1tejn%20(Pernstein)%20-%20by%20Pudelek%2003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pivonice%20-%20hrad%20Zub%C5%A1tejn,%20obr01.jpg"}'::text[], '{"Zámek Žďár nad Sázavou a Zelená hora","Nové Město na Moravě – náměstí a Horácká galerie","Restaurace: Penzion U Martina (Nové Město na Moravě)","Rozhledna Horní les","Hrad Pernštejn","Bystřice nad Pernštejnem a hrad Zubštejn"}'::text[], '{"Česko"}'::text[], false, 120, 'approved');

  -- Salzkammergut – Hallstatt a jezera  (1210_at_salzkammergut.json)
  delete from public.routes where name = 'Salzkammergut – Hallstatt a jezera' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Salzkammergut – Hallstatt a jezera', 'Okružní scénická trasa srdcem rakouského Salzkammergutu, kraje smaragdových jezer, alpských štítů a císařských měst. Vede výhradně po klikatých spolkových a regionálních silnicích kolem jezer Wolfgangsee, Traunsee, Attersee a Mondsee, s odbočkami k Hallstattu, Gosausee a horskému masivu Dachstein. Dálnicím (dálnice/Autobahn) se trasa záměrně vyhýbá, jede se po vedlejších horských a příjezerních silnicích, které nabízejí nejkrásnější výhledy a jsou pro motorkáře nejzábavnější. Den 1: Hallstatt – Dachstein/Krippenstein – Gosausee – Bad Ischl – St. Wolfgang (přenocování u Wolfgangsee). Den 2: St. Wolfgang – Gmunden (Traunsee) – Attersee – Mondsee – zpět do Hallstattu. Počítejte s úzkými serpentinami, letním provozem u Hallstattu a chladnějším počasím ve vyšších polohách u Dachsteinu.', 'loop', 265, 660, 'medium',
     '[{"lat": 47.56223, "lng": 13.64926, "label": "Hallstatt"}, {"lat": 47.5242, "lng": 13.69196, "label": "Dachstein – Krippenstein (Five Fingers)"}, {"lat": 47.53333, "lng": 13.48333, "label": "Gosausee"}, {"lat": 47.714, "lng": 13.6234, "label": "Bad Ischl – Kaiservilla"}, {"lat": 47.7393, "lng": 13.4467, "label": "St. Wolfgang im Salzkammergut (Wolfgangsee)"}, {"lat": 47.91131, "lng": 13.79224, "label": "Gmunden – zámek Ort (Traunsee)"}, {"lat": 47.9, "lng": 13.55, "label": "Attersee"}, {"lat": 47.85559, "lng": 13.34342, "label": "Mondsee"}, {"lat": 47.7133, "lng": 13.6268, "label": "Restaurace: Weinhaus Attwenger (Bad Ischl)"}, {"lat": 47.7387, "lng": 13.4481, "label": "Restaurace: Seerestaurant im Weissen Rössl (St. Wolfgang)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.56223,13.64926&destination=47.7387,13.4481&travelmode=driving&waypoints=47.5242,13.69196%7C47.53333,13.48333%7C47.714,13.6234%7C47.7393,13.4467%7C47.91131,13.79224%7C47.9,13.55%7C47.85559,13.34342%7C47.7133,13.6268', 'https://commons.wikimedia.org/wiki/Special:FilePath/HALLSTATT.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/HALLSTATT.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dachstein%20Krippenstein-Seilbahn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vorderer%20Gosausee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaiservilla%20Bad%20Ischl.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Wolfgang%20im%20Salzkammergut%20-%20Ortsansicht.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Orth%20am%20Traunsee%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Attersee%20-%20S%C3%BCdostansicht.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mondsee%20-%20Basilika%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kurhaus%20Bad%20Ischl.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Wolfgang%20am%20Wolfgangsee.jpg"}'::text[], '{"Hallstatt","Dachstein – Krippenstein (Five Fingers)","Gosausee","Bad Ischl – Kaiservilla","St. Wolfgang im Salzkammergut (Wolfgangsee)","Gmunden – zámek Ort (Traunsee)","Attersee","Mondsee","Restaurace: Weinhaus Attwenger (Bad Ischl)","Restaurace: Seerestaurant im Weissen Rössl (St. Wolfgang)"}'::text[], '{"Rakousko"}'::text[], false, 1210, 'approved');

  -- Zillertal a Gerlos Alpenstrasse  (1220_at_zillertal.json)
  delete from public.routes where name = 'Zillertal a Gerlos Alpenstrasse' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Zillertal a Gerlos Alpenstrasse', 'Náročný jednodenní okruh srdcem tyrolského Zillertalu, který spojuje ledovcová panoramata, horské průsmyky a nejvyšší vodopád Rakouska. Trasa záměrně vede pouze po malebných horských a údolních silnicích a zcela se vyhýbá dálnicím (dálnicím se vyhýbáme). Počítejte se zpoplatněnými alpskými silnicemi – Gerlos Alpenstrasse i Zillertaler Höhenstraße vybírají mýtné na mýtnicích. Serpentiny, prudká stoupání a úzké panoramatické úseky kladou vysoké nároky na řidiče i motorku, proto je trasa hodnocena jako obtížná. Odměnou jsou výhledy na ledovec Hintertux, tyrkysové jezero Achensee a hukot Krimmelských vodopádů. Ideální na celý den s dostatkem času na zastávky a fotografování.', 'poi', 205, 420, 'hard',
     '[{"lat": 47.16919, "lng": 11.86515, "label": "Mayrhofen"}, {"lat": 47.2336, "lng": 11.882, "label": "Zell am Ziller"}, {"lat": 47.24286, "lng": 12.10939, "label": "Gerlos Alpenstrasse (Gerlospass)"}, {"lat": 47.1922, "lng": 12.1695, "label": "Krimmelské vodopády (Krimml)"}, {"lat": 47.1928, "lng": 12.1715, "label": "Restaurace: Hanke''s Café Restaurant (Krimml)"}, {"lat": 47.2, "lng": 11.83, "label": "Zillertaler Höhenstraße"}, {"lat": 47.4333, "lng": 11.7167, "label": "Achensee"}, {"lat": 47.0639, "lng": 11.6639, "label": "Hintertux (ledovec)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.16919,11.86515&destination=47.0639,11.6639&travelmode=driving&waypoints=47.2336,11.882%7C47.24286,12.10939%7C47.1922,12.1695%7C47.1928,12.1715%7C47.2,11.83%7C47.4333,11.7167', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mayrhofen%20view.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mayrhofen%20view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pfarrkirche%20Zell%20a.%20Ziller%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gerlospass%20mautstelle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zillertaler%20Hoehenstrasse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Achensee%20Pertisau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hintertuxer%20Gletscher.jpg"}'::text[], '{"Mayrhofen","Zell am Ziller","Gerlos Alpenstrasse (Gerlospass)","Krimmelské vodopády (Krimml)","Restaurace: Hanke''s Café Restaurant (Krimml)","Zillertaler Höhenstraße","Achensee","Hintertux (ledovec)"}'::text[], '{"Rakousko"}'::text[], false, 1220, 'approved');

  -- Silvretta Hochalpenstrasse  (1230_at_silvretta.json)
  delete from public.routes where name = 'Silvretta Hochalpenstrasse' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Silvretta Hochalpenstrasse', 'Silvretta Hochalpenstrasse patří k nejkrásnějším alpským silnicím Evropy a spojuje vorarlberský Montafon s tyrolským Paznaunem přes sedlo Bielerhöhe ve výšce 2032 metrů. Trasa začíná v Partenenu, stoupá 34 serpentinami k tyrkysovému Silvretta-Stausee a klesá do Galtüru a Ischglu, přičemž po celou dobu nabízí výhledy na ledovce a vrchol Piz Buin. Jde o náročnou jednodenní trasu s prudkými stoupáními, ostrými zatáčkami a nadmořskou výškou přes 2000 metrů, proto je vhodná pro zkušené motorkáře. Záměrně se vyhýbáme dálnicím (rakouským Autobahnám) a jedeme výhradně scénickými horskými silnicemi, abyste si užili panorama a klid Alp. Silvretta Hochalpenstrasse je zpoplatněná mýtem (osobní automobily a motocykly platí za průjezd), silnice bývá kvůli sněhu otevřená zhruba od června do října. Pro jízdu si vyhraďte celý den a počítejte s chladnějším počasím ve výškách.', 'poi', 92, 190, 'hard',
     '[{"lat": 46.91778, "lng": 10.09429, "label": "Bielerhöhe (Silvretta-Stausee)"}, {"lat": 46.96898, "lng": 10.06066, "label": "Partenen"}, {"lat": 46.96856, "lng": 10.18932, "label": "Galtür"}, {"lat": 47.0667, "lng": 9.9167, "label": "Montafon (Schruns)"}, {"lat": 46.97219, "lng": 10.11939, "label": "Kops Stausee"}, {"lat": 47.153, "lng": 9.8219, "label": "Bludenz"}, {"lat": 47.01184, "lng": 10.28842, "label": "Ischgl"}, {"lat": 46.9678, "lng": 10.1878, "label": "Restaurace: Tiroler Stube (Galtür)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.91778,10.09429&destination=46.9678,10.1878&travelmode=driving&waypoints=46.96898,10.06066%7C46.96856,10.18932%7C47.0667,9.9167%7C46.97219,10.11939%7C47.153,9.8219%7C47.01184,10.28842', 'https://commons.wikimedia.org/wiki/Special:FilePath/Silvretta_Stausee_001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Silvretta_Stausee_001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Partenen_Vorarlberg_0486.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Galtur-Wirl%20Tirol%20skiresort%20with%20comfortable%20lifts%20(Alpkogelbahn)%20at%2025%20Februari%202015%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kronengasse_2_Schruns.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Steigleitung%20vom%20Pumpwerk%20Kleinvermunt%20zum%20Kopssee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bludenz_Altes_Rathaus-2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Ischgl_Pardorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Galtur%20and%20town%20hall%20by%20night%20-%20panoramio.jpg"}'::text[], '{"Bielerhöhe (Silvretta-Stausee)","Partenen","Galtür","Montafon (Schruns)","Kops Stausee","Bludenz","Ischgl","Restaurace: Tiroler Stube (Galtür)"}'::text[], '{"Rakousko"}'::text[], false, 1230, 'approved');

  -- Semmering a Mariazell  (1240_at_semmering.json)
  delete from public.routes where name = 'Semmering a Mariazell' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Semmering a Mariazell', 'Okružní trasa spojuje dva klenoty rakouských předalpin — historický průsmyk Semmering a poutní městečko Mariazell. Vyjíždí se od úpatí Rax a Schneebergu, kde se silnice vine údolím Höllental, pokračuje přes zvlněné hřebeny do Štýrska a zpět. Cesta je vedena záměrně po malebných horských a údolních silnicích, VYHÝBÁ SE DÁLNICÍM (dálnice) — místo rychlé A2 volíme klikaté okresní silnice se sériemi zatáček, výhledy na viadukty Semmeringbahn a lesnaté sedla. Počítejte s pomalejším tempem, mnoha vyhlídkami a možností rozdělit trasu do dvou dnů s přespáním v Mariazell. Ideální je jaro až podzim, kdy jsou v provozu horské dráhy i lanovky.', 'loop', 265, 420, 'medium',
     '[{"lat": 47.643, "lng": 15.831, "label": "Semmering — viadukt Kalte Rinne (Semmeringbahn, UNESCO)"}, {"lat": 47.6912, "lng": 15.8427, "label": "Höllental a Rax — lanovka Raxseilbahn"}, {"lat": 47.79036, "lng": 15.91088, "label": "Schneeberg — zubačka Salamander (Puchberg am Schneeberg)"}, {"lat": 47.41, "lng": 15.275, "label": "Bruck an der Mur — Hauptplatz a Železná studna"}, {"lat": 47.6, "lng": 15.0833, "label": "Hochschwab — vrchol masivu"}, {"lat": 47.77275, "lng": 15.31863, "label": "Mariazell — bazilika Panny Marie"}, {"lat": 47.33594, "lng": 15.37411, "label": "Bärenschützklamm — soutěska (Mixnitz)"}, {"lat": 47.7732, "lng": 15.3198, "label": "Restaurace: Brauhaus Mariazell (Mariazell)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.643,15.831&destination=47.7732,15.3198&travelmode=driving&waypoints=47.6912,15.8427%7C47.79036,15.91088%7C47.41,15.275%7C47.6,15.0833%7C47.77275,15.31863%7C47.33594,15.37411', 'https://commons.wikimedia.org/wiki/Special:FilePath/Breitenstein%20-%20Semmeringbahn,%20Viadukt%20Kalte%20Rinne.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Breitenstein%20-%20Semmeringbahn,%20Viadukt%20Kalte%20Rinne.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Reichenau%20-%20Raxseilbahn,%20Talstation.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schneebergbahn%20Salamander%20Ausfahrt%20zum%20Schneeberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bruck%20Mur%20Hauptplatz%207952.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hochschwab,%20Fleischer%20Biwak%20von%20G''hacktstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basilika%20von%20Mariazell%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Steiermark%20B%C3%A4rensch%C3%BCtzklamm%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mariazell%20-%20Brunnen,%20Hauptplatz.JPG"}'::text[], '{"Semmering — viadukt Kalte Rinne (Semmeringbahn, UNESCO)","Höllental a Rax — lanovka Raxseilbahn","Schneeberg — zubačka Salamander (Puchberg am Schneeberg)","Bruck an der Mur — Hauptplatz a Železná studna","Hochschwab — vrchol masivu","Mariazell — bazilika Panny Marie","Bärenschützklamm — soutěska (Mixnitz)","Restaurace: Brauhaus Mariazell (Mariazell)"}'::text[], '{"Rakousko"}'::text[], false, 1240, 'approved');

  -- Deutsche Alpenstraße – Neuschwanstein a Berchtesgaden  (1300_de_alpenstrasse.json)
  delete from public.routes where name = 'Deutsche Alpenstraße – Neuschwanstein a Berchtesgaden' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Deutsche Alpenstraße – Neuschwanstein a Berchtesgaden', 'Legendární Německá alpská silnice (Deutsche Alpenstraße) vede podél celého bavorského podhůří Alp od pohádkového zámku Neuschwanstein až po Berchtesgaden u rakouských hranic. Trasa je záměrně vedena po klikatých panoramatických silnicích a horských průsmycích – dálnicím (Autobahn) se cíleně vyhýbáme, protože kouzlo této cesty spočívá v pomalé jízdě serpentinami kolem tyrkysových jezer a alpských luk. Doporučujeme rozdělit trasu na 2–3 dny: 1. den Neuschwanstein → Wieskirche → Oberammergau → Garmisch-Partenkirchen (přenocování pod Zugspitze), 2. den Walchensee → Sylvensteinsee → Tegernsee, 3. den Berchtesgaden → Königssee → Roßfeld panoramatická silnice → Orlí hnízdo. Silnice jsou úzké, s prudkými zatáčkami a horskými stoupáními, proto je obtížnost hodnocena jako náročná. Naplánujte si dostatek času na fotopauzy – výhledy na Zugspitze, Watzmann a alpská jezera patří k nejkrásnějším v Německu.', 'poi', 385, 690, 'hard',
     '[{"lat": 47.55773, "lng": 10.74965, "label": "Zámek Neuschwanstein (Schwangau)"}, {"lat": 47.68055, "lng": 10.90044, "label": "Wieskirche (Steingaden)"}, {"lat": 47.59566, "lng": 11.07235, "label": "Oberammergau"}, {"lat": 47.49209, "lng": 11.09576, "label": "Garmisch-Partenkirchen (Zugspitze)"}, {"lat": 47.4922, "lng": 11.0947, "label": "Restaurace: Zum Wildschütz (Garmisch-Partenkirchen)"}, {"lat": 47.59225, "lng": 11.34685, "label": "Walchensee"}, {"lat": 47.57935, "lng": 11.54403, "label": "Sylvensteinsee"}, {"lat": 47.7123, "lng": 11.7582, "label": "Tegernsee"}, {"lat": 47.63236, "lng": 13.00187, "label": "Berchtesgaden"}, {"lat": 47.6305, "lng": 13.0032, "label": "Restaurace: Gasthof Neuhaus (Berchtesgaden)"}, {"lat": 47.55567, "lng": 12.97802, "label": "Königssee"}, {"lat": 47.65083, "lng": 13.05, "label": "Roßfeld panoramatická silnice"}, {"lat": 47.61144, "lng": 13.04212, "label": "Kehlsteinhaus (Orlí hnízdo)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.55773,10.74965&destination=47.61144,13.04212&travelmode=driving&waypoints=47.68055,10.90044%7C47.59566,11.07235%7C47.49209,11.09576%7C47.4922,11.0947%7C47.59225,11.34685%7C47.57935,11.54403%7C47.7123,11.7582%7C47.63236,13.00187', 'https://commons.wikimedia.org/wiki/Special:FilePath/Neuschwanstein_Castle_panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Neuschwanstein_Castle_panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wieskirche_rococo_interior.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberammergau_L%C3%BCftlmalerei_3.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Walchensee-ortspanorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sylvensteinbruecke.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tegernsee,_Miesbach,_Germany.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6See_Bartholom%C3%A4_mit_Watzmann.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Berchtesgaden_Rossfeld_Panoramastra%C3%9Fe_(Berchtesgaden)_1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kehlsteinhaus_mit_Blick_auf_den_Untersberg.jpg"}'::text[], '{"Zámek Neuschwanstein (Schwangau)","Wieskirche (Steingaden)","Oberammergau","Garmisch-Partenkirchen (Zugspitze)","Restaurace: Zum Wildschütz (Garmisch-Partenkirchen)","Walchensee","Sylvensteinsee","Tegernsee","Berchtesgaden","Restaurace: Gasthof Neuhaus (Berchtesgaden)","Königssee","Roßfeld panoramatická silnice","Kehlsteinhaus (Orlí hnízdo)"}'::text[], '{"Německo"}'::text[], false, 1300, 'approved');

  -- Bavorský les (Bayerischer Wald)  (1310_de_bavorsky_les.json)
  delete from public.routes where name = 'Bavorský les (Bayerischer Wald)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bavorský les (Bayerischer Wald)', 'Okruh Bavorským lesem je jedna z nejkrásnějších motorkářských tras příhraničního Bavorska, plná táhlých zatáček, hlubokých smrkových lesů a výhledů na nejvyšší vrcholy Šumavy z německé strany. Trasa spojuje sklářská města Zwiesel, Frauenau a Bodenmais s národním parkem Bavorský les, korunovou stezkou v Neuschönau i romantickou hradní zříceninou Weißenstein nad Regenem. Vede převážně po klikatých okreskách a horských silnicích údolím Lamer Winkel a pod masivy Velkého Javoru (Großer Arber) a Rachelu. Doporučujeme rozložit okruh na jeden až dva dny a spojit ho s prohlídkou sklárny nebo výstupem lanovkou na Javor. Trasa se ZÁMĚRNĚ VYHÝBÁ dálnicím a rychlostním silnicím (Autobahn) — jede se jen po scénických silnicích druhé a třetí třídy, aby si jezdec užil krajinu i požitek z řízení.', 'loop', 185, 480, 'medium',
     '[{"lat": 49.1073, "lng": 13.134, "label": "Velký Javor (Großer Arber)"}, {"lat": 48.97854, "lng": 13.38897, "label": "Rachel (Großer Rachel)"}, {"lat": 49.0169, "lng": 13.2377, "label": "Zwiesel (sklárny)"}, {"lat": 49.0668, "lng": 13.0996, "label": "Bodenmais"}, {"lat": 48.89113, "lng": 13.48465, "label": "Korunová stezka Neuschönau (Baumwipfelpfad)"}, {"lat": 48.94, "lng": 13.4, "label": "Národní park Bavorský les (Nationalpark Bayerischer Wald)"}, {"lat": 48.98811, "lng": 13.29838, "label": "Frauenau (muzeum skla)"}, {"lat": 48.9509, "lng": 13.1414, "label": "Regen (hrad Weißenstein)"}, {"lat": 49.19718, "lng": 13.05089, "label": "Lam"}, {"lat": 49.018, "lng": 13.236, "label": "Restaurace: Zur Waldbahn (Zwiesel)"}, {"lat": 49.071, "lng": 13.087, "label": "Restaurace: Genussrestaurant DAS FRANZ (Bodenmais)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.1073,13.134&destination=49.071,13.087&travelmode=driving&waypoints=48.97854,13.38897%7C49.0169,13.2377%7C49.0668,13.0996%7C48.89113,13.48465%7C48.94,13.4%7C48.98811,13.29838%7C48.9509,13.1414%7C49.19718,13.05089', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arber-Gipfelregion.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arber-Gipfelregion.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fer%20Rachel,%20Bayerischen%20Wald.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zwiesel-Glasbl%C3%A4ser-1-Asio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Marktplatz%20Bodenmais.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baumturm,%20Baumwipfelpfad%20Neusch%C3%B6nau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%BCrberg%20Bayerischer%20Wald.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/00%204562%20Glasmuseum%20Frauenau.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burgruine%20Wei%C3%9Fenstein%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/LamerWinkel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bahnhof%20Zwiesel%20(Bay)%202016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bodenmais%20-%20Panorama%20-%202015.jpg"}'::text[], '{"Velký Javor (Großer Arber)","Rachel (Großer Rachel)","Zwiesel (sklárny)","Bodenmais","Korunová stezka Neuschönau (Baumwipfelpfad)","Národní park Bavorský les (Nationalpark Bayerischer Wald)","Frauenau (muzeum skla)","Regen (hrad Weißenstein)","Lam","Restaurace: Zur Waldbahn (Zwiesel)","Restaurace: Genussrestaurant DAS FRANZ (Bodenmais)"}'::text[], '{"Německo"}'::text[], false, 1310, 'approved');

  -- Saské Švýcarsko – Bastei  (1320_de_saske_svycarsko.json)
  delete from public.routes where name = 'Saské Švýcarsko – Bastei' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Saské Švýcarsko – Bastei', 'Jednodenní okružní jízda po nejkrásnějších místech Saského Švýcarska (Sächsische Schweiz) na německé straně Labských pískovců. Trasa spojuje slavný skalní most Bastei, mohutnou pevnost Königstein, romantické jezírko Amselsee v Rathenu a stolovou horu Lilienstein s divokými skalisky Schrammsteine a skalní bránou Kuhstall. Zpáteční část vede přes historická náměstí měst Pirna a Stadt Wehlen podél řeky Labe. Trasa se záměrně VYHÝBÁ dálnicím a Autobahnům – jede se výhradně po klikatých krajinských a údolních silnicích s nádhernými výhledy na pískovcové skály. Ideální celodenní scénický okruh pro milovníky přírody a fotografie.', 'loop', 78, 210, 'easy',
     '[{"lat": 50.96146, "lng": 14.07306, "label": "Bastei (skalní most)"}, {"lat": 50.91917, "lng": 14.0574, "label": "Pevnost Königstein"}, {"lat": 50.96439, "lng": 14.08139, "label": "Rathen – Amselsee"}, {"lat": 50.92472, "lng": 14.08333, "label": "Lilienstein"}, {"lat": 50.91775, "lng": 14.15361, "label": "Restaurace: zum Franz (Bad Schandau)"}, {"lat": 50.92556, "lng": 14.19806, "label": "Schrammsteine"}, {"lat": 50.91556, "lng": 14.26472, "label": "Kuhstall"}, {"lat": 50.96139, "lng": 14.03444, "label": "Pirna (staré město)"}, {"lat": 50.9578, "lng": 14.03188, "label": "Stadt Wehlen"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.96146,14.07306&destination=50.9578,14.03188&travelmode=driving&waypoints=50.91917,14.0574%7C50.96439,14.08139%7C50.92472,14.08333%7C50.91775,14.15361%7C50.92556,14.19806%7C50.91556,14.26472%7C50.96139,14.03444', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bastei%20bridge,%20Nationalpark%20S%C3%A4chsische%20Schweiz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bastei%20bridge,%20Nationalpark%20S%C3%A4chsische%20Schweiz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20photo%20of%20Festung%20K%C3%B6nigstein,%20October%202008.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kurort%20Rathen%20-%20Amselsee%20mit%20Fels%20Lokomotive.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lilienstein%20mountain%20from%20K%C3%B6nigstein%20fortress%20on%20a%20foggy%20morning.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Schandau-Eberhard%20Wolf-Sendigbrunnen%2010%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schrammsteine%20in%20der%20S%C3%A4chsischen%20Schweiz%20(05).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Felsentor%20Kuhstall%20-%20S%C3%A4chsische%20Schweiz%2022.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Pirna%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dorf%20Wehlen%20Nationalpark%20S%C3%A4chsische%20Schweiz.JPG"}'::text[], '{"Bastei (skalní most)","Pevnost Königstein","Rathen – Amselsee","Lilienstein","Restaurace: zum Franz (Bad Schandau)","Schrammsteine","Kuhstall","Pirna (staré město)","Stadt Wehlen"}'::text[], '{"Německo"}'::text[], false, 1320, 'approved');

  -- Franské Švýcarsko (Fränkische Schweiz)  (1330_de_frankische.json)
  delete from public.routes where name = 'Franské Švýcarsko (Fränkische Schweiz)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Franské Švýcarsko (Fränkische Schweiz)', 'Okružní jednodenní vyjížďka srdcem Franského Švýcarska, kraje bílých vápencových skalních věží, hlubokých údolí řek Wiesent a Püttlach a stovek jeskyní. Trasa vědomě obchází dálnice (Autobahn A9/A73) a vede po malebných zemských a okresních silnicích, které se vinou pod skalními stěnami, kolem hradů a poutních kostelů. Začínáme v Pottensteinu u Čertovy jeskyně, projedeme skalní vesnicí Tüchersfeld, kolem baziliky v Gößweinsteinu a romantickými lázeňskými obcemi Streitberg a Muggendorf v údolí Wiesent. Sever okruhu tvoří skalní zahrada Sanspareil a hrad Rabenstein, na jihozápadě si můžeme odbočkou přidat světové dědictví UNESCO Bamberg. Silnice jsou úzké a klikaté s množstvím zatáček, proto je vhodná spíše pro pokročilejší jezdce a pomalejší tempo se vyplatí.', 'loop', 165, 240, 'medium',
     '[{"lat": 49.75435, "lng": 11.42007, "label": "Pottenstein – Teufelská jeskyně (Teufelshöhle)"}, {"lat": 49.7678, "lng": 11.4266, "label": "Tüchersfeld – Fränkische-Schweiz-Museum"}, {"lat": 49.77, "lng": 11.34, "label": "Gößweinstein – bazilika a hrad"}, {"lat": 49.75514, "lng": 11.26549, "label": "Restaurace: Gasthof Zur Guten Einkehr (Gößweinstein-Morschreuth)"}, {"lat": 49.78333, "lng": 11.26667, "label": "Streitberg – zřícenina Streitburg a Neideck"}, {"lat": 49.80222, "lng": 11.26139, "label": "Muggendorf"}, {"lat": 49.9833, "lng": 11.36, "label": "Sanspareil – skalní zahrada a hrad Zwernitz"}, {"lat": 49.8237, "lng": 11.3695, "label": "Hrad Rabenstein (Ahorntal)"}, {"lat": 49.89173, "lng": 10.88631, "label": "Bamberg – historické centrum (UNESCO)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.75435,11.42007&destination=49.89173,10.88631&travelmode=driving&waypoints=49.7678,11.4266%7C49.77,11.34%7C49.75514,11.26549%7C49.78333,11.26667%7C49.80222,11.26139%7C49.9833,11.36%7C49.8237,11.3695', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teufelsh%C3%B6hle%2CBarbarossabart.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Teufelsh%C3%B6hle%2CBarbarossabart.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Felsburg%20T%C3%BCchersfeld.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Goessweinstein-Basilika2-Asio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Basilika-Apotheke%20G%C3%B6ssweinstein%20Marktplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Streitburg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muggendorf%20Kirche%20-20191020-RM-103635.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wonsees%2C%20Felsengarten%20Sanspareil%2C%20Morgenl%C3%A4ndischer%20Bau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Rabenstein-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Altes%20Rathaus%20(Bamberg)%2001.JPG"}'::text[], '{"Pottenstein – Teufelská jeskyně (Teufelshöhle)","Tüchersfeld – Fränkische-Schweiz-Museum","Gößweinstein – bazilika a hrad","Restaurace: Gasthof Zur Guten Einkehr (Gößweinstein-Morschreuth)","Streitberg – zřícenina Streitburg a Neideck","Muggendorf","Sanspareil – skalní zahrada a hrad Zwernitz","Hrad Rabenstein (Ahorntal)","Bamberg – historické centrum (UNESCO)"}'::text[], '{"Německo"}'::text[], false, 1330, 'approved');

  -- Kladsko – Kotlina Kłodzka  (1400_pl_kladsko.json)
  delete from public.routes where name = 'Kladsko – Kotlina Kłodzka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kladsko – Kotlina Kłodzka', 'Okruh Kladskou kotlinou (Kotlina Kłodzka) je nádherná scénická trasa spojující Stolové hory, lázeňská městečka a historické pevnosti na česko-polském pomezí. Vyjíždí se přes hraniční přechody u Náchodu nebo Zlatých Hor a projíždí se klikatými silnicemi mezi Kudowou-Zdrój, Kłodzkem a Bystrzycí Kłodzkou. Trasa je ideální na jeden delší nebo pohodový dvoudenní výlet s noclehem v některém z lázeňských měst. Krajina střídá skalní města, pískovcové věže, barokní baziliky a horské průsmyky. Silnice jsou úzké a zatáčkovité, což z okruhu dělá zážitek přesně pro motorkáře. Trasa se ZÁMĚRNĚ VYHÝBÁ dálnicím a rychlostním silnicím – vede výhradně po scénických regionálních a horských silnicích, aby si jezdec užil výhledy a plynulé zatáčky.', 'loop', 185, 420, 'medium',
     '[{"lat": 50.48438, "lng": 16.3416, "label": "Szczeliniec Wielki (Stolové hory / Góry Stołowe)"}, {"lat": 50.46109, "lng": 16.30917, "label": "Błędne Skały"}, {"lat": 50.44272, "lng": 16.24266, "label": "Kudowa-Zdrój"}, {"lat": 50.49013, "lng": 16.45584, "label": "Wambierzyce (bazilika)"}, {"lat": 50.44139, "lng": 16.65306, "label": "Kłodzko (pevnost + podzemí)"}, {"lat": 50.4349, "lng": 16.6615, "label": "Restaurace: Restauracja Korona (Kłodzko)"}, {"lat": 50.44272, "lng": 16.24266, "label": "Restaurace: Restauracja Merkury (Kudowa-Zdrój)"}, {"lat": 50.30179, "lng": 16.64231, "label": "Bystrzyca Kłodzka"}, {"lat": 50.4045, "lng": 16.39549, "label": "Duszniki-Zdrój (Muzeum papírnictví)"}, {"lat": 50.43983, "lng": 16.87475, "label": "Zlatý Stok / Złoty Stok (jeskyně a zlatý důl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.48438,16.3416&destination=50.43983,16.87475&travelmode=driving&waypoints=50.46109,16.30917%7C50.44272,16.24266%7C50.49013,16.45584%7C50.44139,16.65306%7C50.4349,16.6615%7C50.44272,16.24266%7C50.30179,16.64231%7C50.4045,16.39549', 'https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/B%C5%82%C4%99dne%20Ska%C5%82y.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2009.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wambierzyce%20-%20Bazylika.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20K%C5%82odzko,%20don%C5%BCon%20na%20twierdzy%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2024%20Galeria%20Twierdza%20K%C5%82odzko%20(07).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2015%20Ratusz%20w%20Bystrzycy%20K%C5%82odzkiej%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki%20-%20muzeum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%82oty%20Stok%20-%20Muzeum%20Kopalni%20Z%C5%82ota.JPG"}'::text[], '{"Szczeliniec Wielki (Stolové hory / Góry Stołowe)","Błędne Skały","Kudowa-Zdrój","Wambierzyce (bazilika)","Kłodzko (pevnost + podzemí)","Restaurace: Restauracja Korona (Kłodzko)","Restaurace: Restauracja Merkury (Kudowa-Zdrój)","Bystrzyca Kłodzka","Duszniki-Zdrój (Muzeum papírnictví)","Zlatý Stok / Złoty Stok (jeskyně a zlatý důl)"}'::text[], '{"Polsko","Česko"}'::text[], false, 1400, 'approved');

  -- Karkonosze a Dolní Slezsko  (1410_pl_karkonosze.json)
  delete from public.routes where name = 'Karkonosze a Dolní Slezsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Karkonosze a Dolní Slezsko', 'Dvoudenní scénická okružní jízda polskou stranou Krkonoš (Karkonosze) a bohatým Dolním Slezskem, plná horských serpentin, gotických zámků a památek UNESCO. Trasa záměrně vede po klidných regionálních a horských silnicích a zcela se vyhýbá dálnicím (autostrada A4) i rychlostním silnicím — jedeme kvůli výhledům, ne kvůli rychlosti. První den (cca 2,5 hodiny čisté jízdy) věnujeme srdci Krkonoš: Szklarska Poręba s vodopádem Kamieńczyka, Karpacz s dřevěným norským kostelem Wang, výstup na Śnieżku, ruiny hradu Chojnik a nocleh v Jelení Hoře (Jelenia Góra). Druhý den (cca 4 hodiny jízdy) míří přes majestátní zámek Książ a Kostel míru ve Świdnici na listu UNESCO až do velkolepé Vratislavi (Wrocław) s jejím Rynkem a slavnými trpaslíky. Zpáteční cesta se opět drží vedlejších silnic podél úpatí Sudet. Vhodné boty a rezerva času na výstupy jsou nutností, protože nejkrásnější místa se dají dosáhnout jen pěšky.', 'poi', 385, 690, 'medium',
     '[{"lat": 50.81365, "lng": 15.49683, "label": "Wodospad Kamieńczyka (Szklarska Poręba)"}, {"lat": 50.77759, "lng": 15.7238, "label": "Kostel Wang (Karpacz)"}, {"lat": 50.73595, "lng": 15.73978, "label": "Śnieżka (polská strana)"}, {"lat": 50.83427, "lng": 15.64431, "label": "Hrad Chojnik (Sobieszów)"}, {"lat": 50.90441, "lng": 15.71936, "label": "Jelenia Góra (Plac Ratuszowy)"}, {"lat": 50.90435, "lng": 15.71945, "label": "Restaurace: Kuźnia Smaku (Jelenia Góra)"}, {"lat": 50.8378, "lng": 16.29501, "label": "Zámek Książ (Wałbrzych)"}, {"lat": 50.8458, "lng": 16.4892, "label": "Restaurace: Rynek 43 (Świdnica)"}, {"lat": 50.84652, "lng": 16.49164, "label": "Kostel míru (Świdnica, UNESCO)"}, {"lat": 51.1097, "lng": 17.0326, "label": "Wrocław (Rynek a trpaslíci)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.81365,15.49683&destination=51.1097,17.0326&travelmode=driving&waypoints=50.77759,15.7238%7C50.73595,15.73978%7C50.83427,15.64431%7C50.90441,15.71936%7C50.90435,15.71945%7C50.8378,16.29501%7C50.8458,16.4892%7C50.84652,16.49164', 'https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska%20Por%C4%99ba,%20wodospad%20Kamie%C5%84czyka%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska%20Por%C4%99ba,%20wodospad%20Kamie%C5%84czyka%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karpacz%20Poland%20Church%20Wang%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Anie%C5%BCka%20z%20zachodu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chojnik%20Castle%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wa%C5%82brzych,%20zamek%20Ksi%C4%85%C5%BC%20(Aw58)MW%20DSC07533.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wroc%C5%82aw,%20Rynek-Ratusz%20(1).jpg"}'::text[], '{"Wodospad Kamieńczyka (Szklarska Poręba)","Kostel Wang (Karpacz)","Śnieżka (polská strana)","Hrad Chojnik (Sobieszów)","Jelenia Góra (Plac Ratuszowy)","Restaurace: Kuźnia Smaku (Jelenia Góra)","Zámek Książ (Wałbrzych)","Restaurace: Rynek 43 (Świdnica)","Kostel míru (Świdnica, UNESCO)","Wrocław (Rynek a trpaslíci)"}'::text[], '{"Polsko"}'::text[], false, 1410, 'approved');

  -- Kraków, Wieliczka a Ojców  (1420_pl_krakov.json)
  delete from public.routes where name = 'Kraków, Wieliczka a Ojców' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kraków, Wieliczka a Ojców', 'Dvoudenní scénická smyčka po okolí Krakova, která spojuje královské památky, podzemní zázraky a divokou přírodu Krakovsko-čenstochovské jury. Trasa se záměrně vyhýbá dálnicím a rychlostním silnicím (A4, S7) a vede klidnými krajskými a lokálními silnicemi údolím řeky Prądnik a kolem Visly, aby si motorkář užil zatáčky, výhledy a klid. První den poznáte srdce Krakova s Wawelem a Rynkiem Głównym, sestoupíte do solného dolu ve Wieliczce a přenocujete ve městě. Druhý den zamíříte na sever do Ojcovského národního parku k bizarní skále Maczuga Herkulesa a zámku Pieskowa Skała, poté na jih do poutních míst Kalwaria Zebrzydowska a Wadowice a přes benediktinské opatství Tyniec a jezero Zakrzówek zpět. Den 1: Kraków (Wawel, Rynek), Wieliczka a večer nocleh v Krakově. Den 2: Ojców, Pieskowa Skała, Kalwaria Zebrzydowska, Wadowice, Tyniec a Zakrzówek. Poznámka: celá trasa je vedena mimo dálnice, po malebných silnicích nižších tříd.', 'poi', 165, 540, 'easy',
     '[{"lat": 50.0544, "lng": 19.9354, "label": "Wawelský hrad (Kraków)"}, {"lat": 50.0617, "lng": 19.9367, "label": "Rynek Główny (Kraków)"}, {"lat": 49.98349, "lng": 20.05503, "label": "Solný důl Wieliczka (UNESCO)"}, {"lat": 50.06194, "lng": 19.93778, "label": "Restaurace: Pod Aniołami (Kraków)"}, {"lat": 50.233, "lng": 19.781, "label": "Maczuga Herkulesa (Ojcowski NP)"}, {"lat": 50.23306, "lng": 19.78056, "label": "Zámek Pieskowa Skała"}, {"lat": 49.86021, "lng": 19.67158, "label": "Kalwaria Zebrzydowska (UNESCO)"}, {"lat": 49.8834, "lng": 19.4929, "label": "Wadowice"}, {"lat": 49.8845, "lng": 19.4938, "label": "Restaurace: Pestka Restaurant (Wadowice)"}, {"lat": 50.01895, "lng": 19.80211, "label": "Opatství Tyniec (benediktini)"}, {"lat": 50.03675, "lng": 19.91037, "label": "Zakrzówek (Kraków)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.0544,19.9354&destination=50.03675,19.91037&travelmode=driving&waypoints=50.0617,19.9367%7C49.98349,20.05503%7C50.06194,19.93778%7C50.233,19.781%7C50.23306,19.78056%7C49.86021,19.67158%7C49.8834,19.4929%7C49.8845,19.4938', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wawel%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wawel%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%20salt%20mine.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Maczuga-Herkulesa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Pieskowa%20Skala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sanktuarium%20pasyjno-maryjne%20w%20Kalwarii%20Zebrzydowskiej1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Opactwo%20benedyktynow%20w%20Tyncu%2012.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/ZAKRZ%C3%93WEK%20Krak%C3%B3w%200061.jpg"}'::text[], '{"Wawelský hrad (Kraków)","Rynek Główny (Kraków)","Solný důl Wieliczka (UNESCO)","Restaurace: Pod Aniołami (Kraków)","Maczuga Herkulesa (Ojcowski NP)","Zámek Pieskowa Skała","Kalwaria Zebrzydowska (UNESCO)","Wadowice","Restaurace: Pestka Restaurant (Wadowice)","Opatství Tyniec (benediktini)","Zakrzówek (Kraków)"}'::text[], '{"Polsko"}'::text[], false, 1420, 'approved');

  -- Istrie – Rovinj, Motovun a Pula  (1500_hr_istrie.json)
  delete from public.routes where name = 'Istrie – Rovinj, Motovun a Pula' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Istrie – Rovinj, Motovun a Pula', 'Okružní projížďka srdcem Istrie spojuje pobřežní klenoty s kopcovitým vnitrozemím a jeho středověkými městečky posazenými na vrcholech kopců. Trasa záměrně vede po malebných regionálních a místních silnicích a zcela se vyhýbá dálnicím (istrijskému ipsilonu A8/A9) – jede se pomalu, s výhledy na vinice, olivové háje a moře. První den: Rovinj – Limský záliv – Poreč – Grožnjan – Motovun s přenocováním v okolí Motovunu nebo Pazinu. Druhý den: Pazin – Hum – zpět dolů k jihu a přes vnitrozemí do Puly a zpět podél západního pobřeží do Rovinje. Silnice jsou úzké a klikaté, proto počítejte s pomalejším tempem a častými zastávkami na fotografování; ideální jsou jarní a podzimní měsíce mimo hlavní sezónu.', 'loop', 235, 420, 'medium',
     '[{"lat": 45.08318, "lng": 13.63098, "label": "Rovinj – kostel sv. Eufemie"}, {"lat": 45.0817, "lng": 13.636, "label": "Restaurace: Monte (Rovinj)"}, {"lat": 45.13701, "lng": 13.72088, "label": "Limský záliv (Limska draga)"}, {"lat": 45.22869, "lng": 13.59389, "label": "Poreč – Eufraziova bazilika (UNESCO)"}, {"lat": 45.37728, "lng": 13.72145, "label": "Grožnjan"}, {"lat": 45.33432, "lng": 13.82522, "label": "Motovun – hradby"}, {"lat": 45.24028, "lng": 13.93056, "label": "Pazin – jáma a hrad"}, {"lat": 45.34833, "lng": 14.04528, "label": "Hum – nejmenší město"}, {"lat": 44.87322, "lng": 13.85013, "label": "Pula – amfiteátr Arena"}, {"lat": 44.8167, "lng": 13.8667, "label": "Restaurace: Konoba Batelina (Banjole)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.08318,13.63098&destination=44.8167,13.8667&travelmode=driving&waypoints=45.0817,13.636%7C45.13701,13.72088%7C45.22869,13.59389%7C45.37728,13.72145%7C45.33432,13.82522%7C45.24028,13.93056%7C45.34833,14.04528%7C44.87322,13.85013', 'https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Rovinj%20St%20Euphemia%20church%20BW%202014-10-08%2014-23-33.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Rovinj%20St%20Euphemia%20church%20BW%202014-10-08%2014-23-33.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rovinj%20Saint%20Euphemia%20tower%20limestone%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limski%20Istria%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Euphrasian%20Basilica%20in%20the%20Historic%20Centre%20of%20Pore%C4%8D%20-%20panoramio%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Gro%C5%BEnjan%20ulica%20Umberta%20Gorjana-1574.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Motovun%20%E2%80%93%20General%20view%20-%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pazin%20Burg%20-%20Torhalle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hum%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Amphitheater%20Pula.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Amfi%20pula.JPG"}'::text[], '{"Rovinj – kostel sv. Eufemie","Restaurace: Monte (Rovinj)","Limský záliv (Limska draga)","Poreč – Eufraziova bazilika (UNESCO)","Grožnjan","Motovun – hradby","Pazin – jáma a hrad","Hum – nejmenší město","Pula – amfiteátr Arena","Restaurace: Konoba Batelina (Banjole)"}'::text[], '{"Chorvatsko"}'::text[], false, 1500, 'approved');

  -- Plitvická jezera a Lika  (1510_hr_plitvice.json)
  delete from public.routes where name = 'Plitvická jezera a Lika' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Plitvická jezera a Lika', 'Dvoudenní scénická cesta srdcem chorvatského vnitrozemí, která propojuje slavná Plitvická jezera s divokým a málo turisticky vytíženým krajem Lika pod pohořím Velebit. Trasa se záměrně vyhýbá dálnici A1 i rychlostním úsekům a vede výhradně po klikatých státních a horských silnicích (D1, D25, D50 a průsmyk Baške Oštarije), takže si užijete pomalou jízdu s výhledy místo tunelů a mýtných bran. První den vede od kaskád Plitvických jezer přes vodopády Rastoke a krápníkové jeskyně Barać až k Národnímu parku Sjeverni Velebit a přenocování v okolí Gospiće. Druhý den seskočíte velebitským průsmykem Baške Oštarije, prohlédnete si historické město Gospić, sestoupíte k obřím Cerovackým jeskyním u Rizvanuše a cestu zakončíte v malebném Otočci nad řekou Gackou. Počítejte s úzkými serpentinami, kozami na silnici a čerpacími stanicemi jen ve větších obcích - nádrž doplňte v Gospići.', 'poi', 330, 540, 'medium',
     '[{"lat": 44.8806, "lng": 15.6161, "label": "Národní park Plitvická jezera"}, {"lat": 45.12073, "lng": 15.58633, "label": "Rastoke (Slunj)"}, {"lat": 44.98444, "lng": 15.72667, "label": "Barać jeskyně (Rakovica)"}, {"lat": 44.6892, "lng": 15.0042, "label": "NP Sjeverni Velebit"}, {"lat": 44.52668, "lng": 15.17164, "label": "Baške Oštarije (velebitský průsmyk)"}, {"lat": 44.54611, "lng": 15.37472, "label": "Gospić"}, {"lat": 44.54815, "lng": 15.37382, "label": "Restaurace: Maki (Gospić)"}, {"lat": 44.27502, "lng": 15.88837, "label": "Cerovac jeskyně (Rizvanuša)"}, {"lat": 44.86944, "lng": 15.2375, "label": "Otočac"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.8806,15.6161&destination=44.86944,15.2375&travelmode=driving&waypoints=45.12073,15.58633%7C44.98444,15.72667%7C44.6892,15.0042%7C44.52668,15.17164%7C44.54611,15.37472%7C44.54815,15.37382%7C44.27502,15.88837', 'https://commons.wikimedia.org/wiki/Special:FilePath/Plitvice%20Lakes%20National%20Park%2064.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plitvice%20Lakes%20National%20Park%2064.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Slunj%2C%20Rastoke%2C%20waterfalls%20of%20the%20Slunjcica%20river.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baraceve%20spilje%20caves.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Sjeverni%20Velebit.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A1ke%20O%C5%A1tarije%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cerova%C4%8Dke%20%C5%A1pilje%20(Cerovac%20caves).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dac%20(Croatia)%20-%20centar.JPG"}'::text[], '{"Národní park Plitvická jezera","Rastoke (Slunj)","Barać jeskyně (Rakovica)","NP Sjeverni Velebit","Baške Oštarije (velebitský průsmyk)","Gospić","Restaurace: Maki (Gospić)","Cerovac jeskyně (Rizvanuša)","Otočac"}'::text[], '{"Chorvatsko"}'::text[], false, 1510, 'approved');

  -- Dalmácie – Split, Krka a Trogir  (1520_hr_dalmacie.json)
  delete from public.routes where name = 'Dalmácie – Split, Krka a Trogir' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dalmácie – Split, Krka a Trogir', 'Panoramatická dalmatská smyčka spojuje antické, středověké i přírodní klenoty střední Dalmácie a záměrně se vyhýbá dálnici A1 – jede se výhradně po pobřežní silnici D8 (Jadranská magistrála) a klikatých vnitrozemských okreskách, což je pomalejší, ale mnohem malebnější. Trasa začíná v Splitu s Diokleciánovým palácem, míří do vodopádů národního parku Krka, k UNESCO památkám v Trogiru a Šibeniku a vrací se přes dramatický kaňon Cetiny v Omiši. Doporučujeme rozdělit cestu na 2–3 dny. 1. den: Split – pevnost Klis – Trogir – Primošten s noclehem v okolí Šibeniku (pobřežní magistrála D8). 2. den: Šibenik – Skradinski buk – Roški slap v NP Krka a zpět. 3. den: návrat podél moře přes Primošten do Omiše ke kaňonu Cetiny a do Splitu. Bez použití dálnice – veškeré přejezdy vedou po pobřežních a vnitrozemských silnicích s výhledy na moře.', 'poi', 265, 660, 'medium',
     '[{"lat": 43.5083, "lng": 16.4406, "label": "Split (Diokleciánův palác)"}, {"lat": 43.56004, "lng": 16.52415, "label": "Pevnost Klis"}, {"lat": 43.51722, "lng": 16.25167, "label": "Trogir (UNESCO)"}, {"lat": 43.5863, "lng": 15.92302, "label": "Primošten"}, {"lat": 43.73583, "lng": 15.88917, "label": "Šibenik (katedrála sv. Jakuba UNESCO)"}, {"lat": 43.80583, "lng": 15.96417, "label": "NP Krka (Skradinski buk)"}, {"lat": 43.90556, "lng": 15.97806, "label": "Vodopád Roški slap"}, {"lat": 43.4449, "lng": 16.6913, "label": "Omiš (kaňon Cetiny)"}, {"lat": 43.73583, "lng": 15.88944, "label": "Restaurace: Pelegrini (Šibenik)"}, {"lat": 43.81639, "lng": 15.92528, "label": "Restaurace: Konoba Toni (Skradin)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.5083,16.4406&destination=43.81639,15.92528&travelmode=driving&waypoints=43.56004,16.52415%7C43.51722,16.25167%7C43.5863,15.92302%7C43.73583,15.88917%7C43.80583,15.96417%7C43.90556,15.97806%7C43.4449,16.6913%7C43.73583,15.88944', 'https://commons.wikimedia.org/wiki/Special:FilePath/Peristyle%20of%20Diocletian''s%20Palace%20-%20Split%20-%2051387487617.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peristyle%20of%20Diocletian''s%20Palace%20-%20Split%20-%2051387487617.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Klis%20Fortress,%20Croatia%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20de%20la%20ville%20de%20Trogir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Primo%C5%A1ten,%20Croatia%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skradinski%20buk%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Krka,%20Ro%C5%A1ki%20slap%20(2023).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cetina-Canyon%20in%20Omis,%20Croatia.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Krka%20Skradinski%20buk%20mills%205.jpg"}'::text[], '{"Split (Diokleciánův palác)","Pevnost Klis","Trogir (UNESCO)","Primošten","Šibenik (katedrála sv. Jakuba UNESCO)","NP Krka (Skradinski buk)","Vodopád Roški slap","Omiš (kaňon Cetiny)","Restaurace: Pelegrini (Šibenik)","Restaurace: Konoba Toni (Skradin)"}'::text[], '{"Chorvatsko"}'::text[], false, 1520, 'approved');

  -- Toskánsko – Val d'Orcia a Chianti  (1600_it_toskansko.json)
  delete from public.routes where name = 'Toskánsko – Val d''Orcia a Chianti' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Toskánsko – Val d''Orcia a Chianti', 'Malebná okružní jízda srdcem Toskánska propojuje ikonická středověká města s pastelovou krajinou Val d''Orcia, kterou UNESCO chrání jako mistrovské dílo lidského a přírodního souznění. Trasa vede výhradně po klikatých panoramatických silnicích SR2 (Via Cassia) a lokálních cestách mezi vinicemi Chianti a Brunella – dálnicím a autostrádám se zcela vyhýbáme, protože smyslem cesty je vychutnat si cypřišové aleje, kopce a jílové vlny krajiny. Vyjíždíme ze Sieny přes San Gimignano a Chianti, sjíždíme do renesanční Pienzy, Montepulciana a Montalcina a končíme mezi cypřiši u San Quirica d''Orcia a v termální Bagno Vignoni. Ideálně rozvržte trasu na 2–3 dny: první den Siena – San Gimignano – Greve in Chianti, druhý den Pienza – Montepulciano – Montalcino, třetí den Val d''Orcia a Bagno Vignoni. Jeďte v klidu, silnice jsou úzké a plné vyhlídek, kde se vyplatí zastavit a fotit. Vyhněte se poledním vedrům a naplánujte si obědové zastávky ve vinařských městech.', 'poi', 245, 660, 'medium',
     '[{"lat": 43.31833, "lng": 11.33139, "label": "Siena (Piazza del Campo)"}, {"lat": 43.46763, "lng": 11.04349, "label": "San Gimignano (věže)"}, {"lat": 43.58444, "lng": 11.31557, "label": "Greve in Chianti (Piazza Matteotti)"}, {"lat": 43.07652, "lng": 11.67891, "label": "Pienza"}, {"lat": 43.0764, "lng": 11.6793, "label": "Restaurace: Trattoria Latte di Luna (Pienza)"}, {"lat": 43.09244, "lng": 11.78147, "label": "Montepulciano (Piazza Grande)"}, {"lat": 43.0921, "lng": 11.7809, "label": "Restaurace: Osteria Acquacheta (Montepulciano)"}, {"lat": 43.05589, "lng": 11.51089, "label": "Montalcino"}, {"lat": 43.06267, "lng": 11.55885, "label": "San Quirico d''Orcia (cypřiše Val d''Orcia)"}, {"lat": 43.0279, "lng": 11.6186, "label": "Bagno Vignoni"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.31833,11.33139&destination=43.0279,11.6186&travelmode=driving&waypoints=43.46763,11.04349%7C43.58444,11.31557%7C43.07652,11.67891%7C43.0764,11.6793%7C43.09244,11.78147%7C43.0921,11.7809%7C43.05589,11.51089%7C43.06267,11.55885', 'https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena)%2006.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena)%2006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Towers%20of%20San%20Gimignano,%20Tuscany,%20Italy.%20View%20from%20Torre%20Grossa%20tower.%202014.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Greve%20in%20Chianti%20-%20Piazza%20Giacomo%20Matteotti-9295.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20Piazza%20Pio%20II.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20italy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano,%20piazza%20grande%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano-view.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montalcino%20Fortezza.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cipressi%20di%20San%20Quirico%20d''Orcia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bagno%20Vignoni.jpg"}'::text[], '{"Siena (Piazza del Campo)","San Gimignano (věže)","Greve in Chianti (Piazza Matteotti)","Pienza","Restaurace: Trattoria Latte di Luna (Pienza)","Montepulciano (Piazza Grande)","Restaurace: Osteria Acquacheta (Montepulciano)","Montalcino","San Quirico d''Orcia (cypřiše Val d''Orcia)","Bagno Vignoni"}'::text[], '{"Itálie"}'::text[], false, 1600, 'approved');

  -- Passo Gavia a Mortirolo  (1610_it_gavia.json)
  delete from public.routes where name = 'Passo Gavia a Mortirolo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Passo Gavia a Mortirolo', 'Náročná jednodenní smyčka italskými Alpami spojující dva legendární průsmyky – divoký Passo Gavia (2621 m) a strmý Passo del Mortirolo, který proslavila cyklistika. Trasa vede úzkými horskými silnicemi plnými serpentin, přes zelené doliny Valcamoniky a Valtelliny a nabízí dechberoucí výhledy na ledovce masivu Ortles-Cevedale. Jede se výhradně po scénických horských silnicích (SS300, SS42, provinční cesty) a dálnicím se zcela vyhýbá – žádná autostrada, jen zatáčky a průsmyky. Silnice jsou úzké, místy bez svodidel a technicky náročné, proto je trasa vhodná pro zkušené jezdce. Ideální sezóna je léto, kdy jsou průsmyky spolehlivě bez sněhu (Gavia bývá otevřen zhruba od června do října). Počítejte s prudkými stoupáními, chladem ve výškách a doporučujeme vyjet brzy ráno, dokud je provoz nízký.', 'loop', 118, 300, 'hard',
     '[{"lat": 46.3395, "lng": 10.4862, "label": "Passo Gavia"}, {"lat": 46.248, "lng": 10.2991, "label": "Passo del Mortirolo"}, {"lat": 46.25889, "lng": 10.51028, "label": "Ponte di Legno"}, {"lat": 46.2667, "lng": 10.5833, "label": "Passo del Tonale"}, {"lat": 46.17924, "lng": 10.33033, "label": "Edolo"}, {"lat": 46.28393, "lng": 10.5211, "label": "Restaurace: Ristorante Frigidolfo (Ponte di Legno)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.3395,10.4862&destination=46.28393,10.5211&travelmode=driving&waypoints=46.248,10.2991%7C46.25889,10.51028%7C46.2667,10.5833%7C46.17924,10.33033', 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Gavia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Gavia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Mortirolo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ponte%20di%20Legno%20visto%20dalla%20seggiovia%20-%20Ponte%20di%20Legno%203%20settembre%202000.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Tonale%201%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20M%C3%B9%20-%20Edolo%20(Foto%20Luca%20Giarelli).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Torrente%20Frigidolfo%20-%20Ponte%20di%20Legno%20(ph%20Luca%20Giarelli).jpg"}'::text[], '{"Passo Gavia","Passo del Mortirolo","Ponte di Legno","Passo del Tonale","Edolo","Restaurace: Ristorante Frigidolfo (Ponte di Legno)"}'::text[], '{"Itálie"}'::text[], false, 1610, 'approved');

  -- Lago di Como a průsmyk Splügen  (1620_it_como.json)
  delete from public.routes where name = 'Lago di Como a průsmyk Splügen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lago di Como a průsmyk Splügen', 'Dvoudenní okruh kolem severního cípu jezera Lago di Como, který spojuje elegantní jezerní městečka s divokým alpským průsmykem Passo dello Spluga na hranici Itálie a Švýcarska. Z Coma stoupáte serpentinami k slavné kapli Madonna del Ghisallo, patronky cyklistů, a pak sjíždíte k třpytivým vodám jezera v Bellagiu, Varenně a Menaggiu. Druhý den vás čeká výjezd do Chiavenny a přes vysokohorský Splügenpass s jeho ikonickými zatáčkami až na švýcarskou stranu, odkud se vracíte zpět k jezeru. Trasa záměrně vede po malebných horských a jezerních silnicích a zcela se vyhýbá dálnicím (autostradě A9) i tunelovým zkratkám. Počítejte s úzkými serpentinami, převýšením přes 2000 metrů na průsmyku a nádhernými výhledy, které patří k nejkrásnějším v celých Alpách.', 'loop', 245, 600, 'medium',
     '[{"lat": 45.8118, "lng": 9.08366, "label": "Como (katedrála)"}, {"lat": 45.9289, "lng": 9.2658, "label": "Madonna del Ghisallo (kaple + muzeum cyklistiky)"}, {"lat": 45.98775, "lng": 9.26198, "label": "Bellagio"}, {"lat": 46.01078, "lng": 9.28465, "label": "Varenna"}, {"lat": 46.327, "lng": 9.43, "label": "Restaurace: Crotto Quartino - Valchiavenna (Piuro)"}, {"lat": 46.3206, "lng": 9.3982, "label": "Chiavenna"}, {"lat": 46.50556, "lng": 9.33028, "label": "Passo dello Spluga (Splügenpass, hranice IT/CH)"}, {"lat": 46.02171, "lng": 9.23883, "label": "Menaggio"}, {"lat": 45.9862, "lng": 9.2605, "label": "Restaurace: B-Lake Restaurant (Bellagio)"}, {"lat": 45.85298, "lng": 9.39007, "label": "Lecco"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.8118,9.08366&destination=45.85298,9.39007&travelmode=driving&waypoints=45.9289,9.2658%7C45.98775,9.26198%7C46.01078,9.28465%7C46.327,9.43%7C46.3206,9.3982%7C46.50556,9.33028%7C46.02171,9.23883%7C45.9862,9.2605', 'https://commons.wikimedia.org/wiki/Special:FilePath/Como_-_Duomo_di_Como_-_2024-09-01%2021-27-34%20001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Como_-_Duomo_di_Como_-_2024-09-01%2021-27-34%20001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Santuario_della_Madonna_del_Ghisallo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bellagio_panorama_from_Lake_Como_ferry.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/I_colori_di_Varenna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valchiavenna_1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Via_Dolzino_Chiavenna_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo_dello_spluga_in_inverno.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Menaggio_Piazza_Garibaldi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_dalla_Punta_Spartivento_a_Bellagio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/042_Lecco_-_sullo_sfondo_il_Resegone.jpg"}'::text[], '{"Como (katedrála)","Madonna del Ghisallo (kaple + muzeum cyklistiky)","Bellagio","Varenna","Restaurace: Crotto Quartino - Valchiavenna (Piuro)","Chiavenna","Passo dello Spluga (Splügenpass, hranice IT/CH)","Menaggio","Restaurace: B-Lake Restaurant (Bellagio)","Lecco"}'::text[], '{"Itálie","Švýcarsko"}'::text[], false, 1620, 'approved');

  -- Bled, Bohinj a Pokljuka  (1700_si_bled.json)
  delete from public.routes where name = 'Bled, Bohinj a Pokljuka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bled, Bohinj a Pokljuka', 'Okružní vyjížďka srdcem Julských Alp, která spojuje dvě nejkrásnější slovinská jezera s divokými soutěskami a tichou horskou plošinou. Z Bledu se vydáte přes soutěsku Vintgar dolů do údolí a odtud po malebných okreskách k Bohinjskému jezeru a vodopádu Savica. Zpáteční část vede přes lesnatou plošinu Pokljuka a končí v medovém městečku Radovljica. Trasa je koncipovaná jako celodenní až dvoudenní zážitek s množstvím zastávek na fotografování a procházky. Silnice jsou úzké, klikaté a horské, proto jeďte opatrně a počítejte s nižší průměrnou rychlostí. Záměrně se celá trasa vyhýbá dálnicím a rychlostním silnicím (žádná dálnice / dálniční známka není potřeba) a vede výhradně po scénických regionálních silnicích.', 'loop', 92, 420, 'medium',
     '[{"lat": 46.36256, "lng": 14.09022, "label": "Bledské jezero (ostrov a hrad Bled)"}, {"lat": 46.39098, "lng": 14.08387, "label": "Soutěska Vintgar"}, {"lat": 46.28556, "lng": 13.86194, "label": "Bohinjské jezero"}, {"lat": 46.29002, "lng": 13.80247, "label": "Vodopád Savica"}, {"lat": 46.29842, "lng": 13.8854, "label": "Soutěska Mostnica (Stara Fužina)"}, {"lat": 46.3449, "lng": 13.9222, "label": "Pokljuka (plošina)"}, {"lat": 46.34064, "lng": 14.1759, "label": "Radovljica (medové centrum)"}, {"lat": 46.28764, "lng": 13.8938, "label": "Restaurace: Gostilna Mihovc (Stara Fužina)"}, {"lat": 46.3713, "lng": 14.1043, "label": "Restaurace: Pizzeria Rustika (Bled)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.36256,14.09022&destination=46.3713,14.1043&travelmode=driving&waypoints=46.39098,14.08387%7C46.28556,13.86194%7C46.29002,13.80247%7C46.29842,13.8854%7C46.3449,13.9222%7C46.34064,14.1759%7C46.28764,13.8938', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bled_Overview.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bled_Overview.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Blejski%20vintgar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bohinjsko%20jezero%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Slap%20Savica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mostnica%20Gorge%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pokljuka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poljce%20Radovljica%20Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stara%20Fu%C5%BEina%20-%20Rib%C4%8Dev%20Laz%20-%20Lake%20Bohinj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bled-Lake%20and%20Island%20from%20Castle.JPG"}'::text[], '{"Bledské jezero (ostrov a hrad Bled)","Soutěska Vintgar","Bohinjské jezero","Vodopád Savica","Soutěska Mostnica (Stara Fužina)","Pokljuka (plošina)","Radovljica (medové centrum)","Restaurace: Gostilna Mihovc (Stara Fužina)","Restaurace: Pizzeria Rustika (Bled)"}'::text[], '{"Slovinsko"}'::text[], false, 1700, 'approved');

  -- Logarská dolina a Solčavská panoramatická cesta  (1710_si_logarska.json)
  delete from public.routes where name = 'Logarská dolina a Solčavská panoramatická cesta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Logarská dolina a Solčavská panoramatická cesta', 'Náročný jednodenní okruh po nejkrásnějším koutu slovinských Kamnicko-Savinjských Alp, který spojuje ledovcovou Logarskou dolinu s vyhlídkovou Solčavskou panoramatickou cestou. Trasa je pojatá záměrně bez dálnic (dálnice) a vede výhradně po klikatých horských a údolních silnicích s ostrými serpentinami, prudkými stoupáními a nádhernými výhledy na alpské štíty. Z Kamniku se vydáte přes Kamnickou Bistrici k lanovce na Velikou planinu, poté horskými průsmyky do Solčavska, projedete Logarskou dolinu až k vodopádu Rinka a vrátíte se přes vysoko položené Jezersko s jezerem Planšarsko. Kvůli velkému převýšení, úzkým vozovkám a technicky náročným úsekům je okruh vhodný pro zkušené motorkáře a počítejte s celodenním tempem. Panoramatické úseky si vyloženě žádají časté zastávky u vyhlídek a horských statků.', 'loop', 118, 300, 'hard',
     '[{"lat": 46.2257, "lng": 14.6119, "label": "Kamnik"}, {"lat": 46.31222, "lng": 14.60674, "label": "Velika planina (lanovka)"}, {"lat": 46.4201, "lng": 14.6841, "label": "Solčava"}, {"lat": 46.43, "lng": 14.65, "label": "Solčavská panoramatická cesta"}, {"lat": 46.39811, "lng": 14.63133, "label": "Logarská dolina"}, {"lat": 46.37111, "lng": 14.59254, "label": "Vodopád Rinka"}, {"lat": 46.4029, "lng": 14.51598, "label": "Jezersko (Planšarsko jezero)"}, {"lat": 46.3915, "lng": 14.6378, "label": "Restaurace: Hotel Plesnik (Logarská dolina)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.2257,14.6119&destination=46.3915,14.6378&travelmode=driving&waypoints=46.31222,14.60674%7C46.4201,14.6841%7C46.43,14.65%7C46.39811,14.63133%7C46.37111,14.59254%7C46.4029,14.51598', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kamnik-Mali%20grad%20defense%20tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kamnik-Mali%20grad%20defense%20tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velika%20planina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Robanov%20kot%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%BB%D0%BE%D0%B2%D0%B5%D0%BD%D0%B8%D1%8F%20%D0%B0%D1%83%D1%8B%D0%BB%D1%8B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/LogarskaDolina.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rinka%20Fall%20(2955241140).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plan%C5%A1arsko%20jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Logarska%20dolina%20-%20slap%20Palenk.jpg"}'::text[], '{"Kamnik","Velika planina (lanovka)","Solčava","Solčavská panoramatická cesta","Logarská dolina","Vodopád Rinka","Jezersko (Planšarsko jezero)","Restaurace: Hotel Plesnik (Logarská dolina)"}'::text[], '{"Slovinsko"}'::text[], false, 1710, 'approved');

  -- Eger, Bükk a Tokaj  (1800_hu_eger.json)
  delete from public.routes where name = 'Eger, Bükk a Tokaj' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Eger, Bükk a Tokaj', 'Dvoudenní scénická okružní jízda severním Maďarskem, která spojuje barokní Eger, lesnaté hory Bükku a proslulé vinice Tokaje. Trasa záměrně vede po klikatých okreskách a horských silnicích (č. 25, 24, 2506 a 26) a zcela se VYHÝBÁ dálnicím (M3) — jedeme kvůli zážitku, ne kvůli rychlosti. První den vyrazíte z Egeru přes Szilvásvárad s lipicány a horské serpentiny k vodopádu v Lillafüredu, den zakončíte v jeskynních lázních Miskolctapolca. Druhý den zamíříte k vinicím Tokaje pod ochranou UNESCO, ke krápníkové jeskyni Baradla v Aggteleku a k pohádkové vesnici Hollókő. Počítejte s úzkými, ale nádhernými úseky lesních silnic přes Bükk — jsou to nejkrásnější kilometry celé cesty. Rozdělení: 1. den Eger → Szilvásvárad → Lillafüred → Miskolctapolca (cca 130 km), 2. den Miskolctapolca → Tokaj → Aggtelek → Hollókő (cca 210 km).', 'poi', 340, 660, 'medium',
     '[{"lat": 47.9039, "lng": 20.3794, "label": "Egerský hrad"}, {"lat": 47.9028, "lng": 20.3746, "label": "Egerský minaret"}, {"lat": 47.8925, "lng": 20.3544, "label": "Údolí krásných paní (Szépasszony-völgy)"}, {"lat": 47.9033, "lng": 20.3775, "label": "Restaurace: Macok Bisztró (Eger)"}, {"lat": 48.107, "lng": 20.3875, "label": "Szilvásvárad — lipicáni"}, {"lat": 48.1, "lng": 20.6333, "label": "Lillafüred a vodopád Szinva"}, {"lat": 48.0632, "lng": 20.7524, "label": "Jeskynní lázně Miskolctapolca"}, {"lat": 48.1172, "lng": 21.4089, "label": "Tokaj — vinice UNESCO"}, {"lat": 48.1313, "lng": 21.3499, "label": "Restaurace: Bobajka (Tarcal)"}, {"lat": 48.47185, "lng": 20.49536, "label": "Jeskyně Baradla, Aggtelek"}, {"lat": 47.9953, "lng": 19.5881, "label": "Hollókő — vesnice UNESCO"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.9039,20.3794&destination=47.9953,19.5881&travelmode=driving&waypoints=47.9028,20.3746%7C47.8925,20.3544%7C47.9033,20.3775%7C48.107,20.3875%7C48.1,20.6333%7C48.0632,20.7524%7C48.1172,21.4089%7C48.1313,21.3499', 'https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Minaret_-_Eger,_2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0434_-_Hungary_-_Valley_of_Beautiful_Women_(Sz%C3%A9passzonyv%C3%B6lgy).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Szilv%C3%A1sv%C3%A1rad,_Szalajka-v%C3%B6lgy._A_fels%C5%91_t%C3%B3_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vizeses-Lillafured-Miskolc-Hungary-Europe.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miskolctapolca_Barlangf%C3%BCrd%C5%91_(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aggtelek_National_Park,_Baradla_Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holloko_Village_Center.jpg"}'::text[], '{"Egerský hrad","Egerský minaret","Údolí krásných paní (Szépasszony-völgy)","Restaurace: Macok Bisztró (Eger)","Szilvásvárad — lipicáni","Lillafüred a vodopád Szinva","Jeskynní lázně Miskolctapolca","Tokaj — vinice UNESCO","Restaurace: Bobajka (Tarcal)","Jeskyně Baradla, Aggtelek","Hollókő — vesnice UNESCO"}'::text[], '{"Maďarsko"}'::text[], false, 1800, 'approved');

  -- Dunakanyar – ohyb Dunaje a Budapešť  (1810_hu_dunakanyar.json)
  delete from public.routes where name = 'Dunakanyar – ohyb Dunaje a Budapešť' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dunakanyar – ohyb Dunaje a Budapešť', 'Okružní jednodenní jízda Dunakanyarem (Ohybem Dunaje) severně od Budapešti patří k nejmalebnějším trasám v Maďarsku. Z Budapešti stoupáte podél pravého břehu Dunaje přes Szentendre do Visegrádu s jeho královským palácem a citadelou, pokračujete do Esztergomu s obří bazilikou a přes Zebegény a Vác se vracíte zpět do metropole. Trasa vede záměrně po klidných silnicích druhé a třetí třídy kopírujících řeku a horské hřbety Visegrádského pohoří, s nádhernými výhledy na zákrut Dunaje. Cíleně se vyhýbá dálnicím (M0, M2) – ty sice ušetří čas, ale ochudí vás o panoramata, serpentiny a atmosféru starých dunajských městeček. Počítejte s častými zastávkami na vyhlídkách a v historických centrech, ideální je vyrazit brzy ráno a klidné úseky si vychutnat bez spěchu.', 'loop', 165, 300, 'easy',
     '[{"lat": 47.6694, "lng": 19.0756, "label": "Szentendre – staré město"}, {"lat": 47.7969, "lng": 18.9811, "label": "Visegrád – citadela (Fellegvár)"}, {"lat": 47.7913, "lng": 18.973, "label": "Visegrád – královský palác"}, {"lat": 47.793, "lng": 18.9749, "label": "Restaurace: Renaissance Étterem (Visegrád)"}, {"lat": 47.73884, "lng": 18.9204, "label": "Prédikálószék – vyhlídka (Dunakanyar)"}, {"lat": 47.7995, "lng": 18.7379, "label": "Esztergom – bazilika"}, {"lat": 47.8028, "lng": 18.9104, "label": "Zebegény – dunajská vesnice"}, {"lat": 47.7759, "lng": 19.1361, "label": "Vác – hlavní náměstí"}, {"lat": 47.5019, "lng": 19.0343, "label": "Budapešť – Hradní vrch a Rybářská bašta"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.6694,19.0756&destination=47.5019,19.0343&travelmode=driving&waypoints=47.7969,18.9811%7C47.7913,18.973%7C47.793,18.9749%7C47.73884,18.9204%7C47.7995,18.7379%7C47.8028,18.9104%7C47.7759,19.1361', 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Main%20Square,%20Szentendre,%20Hungary.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Main%20Square,%20Szentendre,%20Hungary.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Visegr%C3%A1d%20Citadel%20from%20the%20bank%20of%20the%20Danube,%202012-03-20-3.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Visegr%C3%A1d%20-%20Royal%20Palace.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/F%C5%91%20utca%2011,%202018%20Visegr%C3%A1d.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dunakanyar,%20Nagymaros.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20in%20Esztergom,%20Hungary%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/D%C5%91ry%20Mansion,%202020%20Zebeg%C3%A9ny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Convent%20of%20the%20Sisters%20of%20Charity.%201751.%20-%20M%C3%A1rcius%2015%20Square,%20V%C3%A1c.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Fisherman''s%20Bastion,%20Budapest,%20Hungary.jpg"}'::text[], '{"Szentendre – staré město","Visegrád – citadela (Fellegvár)","Visegrád – královský palác","Restaurace: Renaissance Étterem (Visegrád)","Prédikálószék – vyhlídka (Dunakanyar)","Esztergom – bazilika","Zebegény – dunajská vesnice","Vác – hlavní náměstí","Budapešť – Hradní vrch a Rybářská bašta"}'::text[], '{"Maďarsko"}'::text[], false, 1810, 'approved');

  -- Passo dello Stelvio – král alpských průsmyků  (210_stelvio.json)
  delete from public.routes where name = 'Passo dello Stelvio – král alpských průsmyků' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Passo dello Stelvio – král alpských průsmyků', 'Legendární Passo dello Stelvio je se svými 2758 m druhým nejvyšším asfaltovým průsmykem Alp a nejvyšší silnicí italských Alp. Ze severní strany z Prata allo Stelvio čeká na motorkáře 48 očíslovaných serpentin (tornanti), které se v nekonečné kaskádě šplhají po úbočí Ortleru – jde o jednu z nejikoničtějších silnic na světě. Sjezd na jižní stranu do lázeňského Bormia je otevřenější a rychlejší, po cestě lze odbočit přes Passo Umbrail do Švýcarska. Ideální doba pro průjezd je červen až září, kdy je průsmyk spolehlivě otevřený; mimo sezonu bývá kvůli sněhu uzavřen. Počítejte s chladem a mlhou i v létě, hustým provozem cyklistů a aut o víkendech a nutností plné koncentrace v úzkých vlásenkách.', 'poi', 49, 110, 'hard',
     '[{"lat": 46.61841, "lng": 10.5914, "label": "Prato allo Stelvio (start)"}, {"lat": 46.55225, "lng": 10.51029, "label": "Trafoi"}, {"lat": 46.52861, "lng": 10.45278, "label": "Passo dello Stelvio – vrchol 2758 m"}, {"lat": 46.54306, "lng": 10.425, "label": "Passo Umbrail (odbočka do Švýcarska)"}, {"lat": 46.5, "lng": 10.41, "label": "Serpentiny jižní strany"}, {"lat": 46.46762, "lng": 10.37815, "label": "Bormio (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.61841,10.5914&destination=46.46762,10.37815&travelmode=driving&waypoints=46.55225,10.51029%7C46.52861,10.45278%7C46.54306,10.425%7C46.5,10.41', 'https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Collegiata%20Kirche%20Bormio%202.jpg"}'::text[], '{"Prato allo Stelvio","Passo dello Stelvio – vrchol s 48 serpentinami (2758 m)","Passo Umbrail (odbočka do Švýcarska)","Trafoi","Bormio","Restaurace: La Rasiga (Bormio)"}'::text[], '{"Itálie","Švýcarsko"}'::text[], false, 210, 'approved');

  -- Grossglockner Hochalpenstraße – alpská legenda  (220_grossglockner.json)
  delete from public.routes where name = 'Grossglockner Hochalpenstraße – alpská legenda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Grossglockner Hochalpenstraße – alpská legenda', 'Grossglockner Hochalpenstraße je jedna z nejslavnějších horských panoramatických silnic v Evropě a spojuje Bruck v Salcbursku s Heiligenblutem v Korutanech. Trasa se vine 36 serpentinami vzhůru až do nadmořské výšky 2504 m u tunelu Hochtor, s odbočkou na vyhlídku Edelweißspitze ve 2571 m. Jde o placenou vyhlídkovou silnici (mýto), nikoli o dálnici – dálnicím se zcela vyhýbá a nabízí čistě zážitkovou jízdu horami. Nejlepší období je od poloviny května do konce října, mimo tuto dobu bývá silnice kvůli sněhu uzavřená. I v létě zde počítej s výrazně nižšími teplotami, náhlými změnami počasí, mlhou a chladem ve výškách – vezmi si teplé a nepromokavé oblečení a jeď opatrně v serpentinách.', 'poi', 48, 120, 'hard',
     '[{"lat": 47.286, "lng": 12.826, "label": "Bruck an der Glocknerstraße"}, {"lat": 47.121, "lng": 12.831, "label": "Edelweißspitze"}, {"lat": 47.079, "lng": 12.845, "label": "Hochtor"}, {"lat": 47.075, "lng": 12.752, "label": "Kaiser-Franz-Josefs-Höhe"}, {"lat": 47.041, "lng": 12.842, "label": "Heiligenblut"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.286,12.826&destination=47.041,12.842&travelmode=driving&waypoints=47.121,12.831%7C47.079,12.845%7C47.075,12.752', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Edelweissspitze.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Franz-Josefs-H%C3%B6he,_2014_(01).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG"}'::text[], '{"Bruck an der Glocknerstraße","Edelweißspitze","Hochtor","Kaiser-Franz-Josefs-Höhe","Restaurace: Kärntnerhof Heiligenblut (Heiligenblut)","Heiligenblut"}'::text[], '{"Rakousko"}'::text[], false, 220, 'approved');

  -- Dolomity – Sella Ronda (čtyři průsmyky)  (230_dolomity.json)
  delete from public.routes where name = 'Dolomity – Sella Ronda (čtyři průsmyky)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dolomity – Sella Ronda (čtyři průsmyky)', 'Sella Ronda je legendární okruh kolem masivu Sella v italských Dolomitech, který spojuje čtyři vysokohorské průsmyky – Passo Pordoi, Passo Sella, Passo Gardena (Grödner Joch) a Passo Campolongo. Trasa se zcela vyhýbá dálnicím a rychlostním silnicím; jede se výhradně po klikatých horských silnicích plných serpentin a vlásenek s dechberoucími výhledy na dolomitské štíty. Nejlepší období pro jízdu je od června do září, kdy jsou průsmyky spolehlivě průjezdné a bez sněhu. Počítejte s hustým provozem cyklistů, karavanů i turistických busů, zejména v létě a o víkendech, proto jeďte defenzivně a v serpentinách předvídejte pomalá vozidla. Okruh lze projet oběma směry a je klidně zvládnutelný za jeden den s pauzami na jednotlivých sedlech.', 'loop', 52, 180, 'hard',
     '[{"lat": 46.476, "lng": 11.77, "label": "Canazei (start)"}, {"lat": 46.487, "lng": 11.812, "label": "Passo Pordoi"}, {"lat": 46.52, "lng": 11.878, "label": "Passo Campolongo"}, {"lat": 46.546, "lng": 11.81, "label": "Passo Gardena / Grödner Joch"}, {"lat": 46.557, "lng": 11.756, "label": "Selva di Val Gardena"}, {"lat": 46.508, "lng": 11.762, "label": "Passo Sella"}, {"lat": 46.476, "lng": 11.77, "label": "Canazei (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.476,11.77&destination=46.476,11.77&travelmode=driving&waypoints=46.487,11.812%7C46.52,11.878%7C46.546,11.81%7C46.557,11.756%7C46.508,11.762', 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%ABlva%20Wolkenstein%20Selva%20di%20Val%20Gardena%20Sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg"}'::text[], '{"Passo Pordoi","Passo Sella","Passo Gardena / Grödner Joch","Passo Campolongo","Restaurace: Ristorante Cialdira Ladina (Corvara)","Canazei / Val di Fassa"}'::text[], '{"Itálie"}'::text[], false, 230, 'approved');

  -- Timmelsjoch – panoramatická horská cesta  (240_timmelsjoch.json)
  delete from public.routes where name = 'Timmelsjoch – panoramatická horská cesta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Timmelsjoch – panoramatická horská cesta', 'Timmelsjoch (italsky Passo del Rombo) je jedna z nejvýše položených zpoplatněných horských silnic v Alpách, jejíž vrchol leží ve výšce 2 509 m n. m. na hranici Rakouska a Itálie. Trasa spojuje tyrolské Ötztal se severoitalským údolím Passeier a cíleně se vyhýbá dálnicím – jede se čistě po panoramatické horské cestě plné serpentin a přibližně 60 zatáček s ostrými vlásenkami a stoupáním až 12,7 %. Mýto se platí nad obcí Hochgurgl na rakouské straně a projet lze pouze přes den v letní sezóně. V zimě je silnice kvůli sněhu uzavřená, takže ideální doba pro jízdu je od června do září. Odměnou motorkářům jsou úchvatné výhledy na ledovce, moderní architektura muzeí Timmelsjoch Experience a jeden z nejlepších řidičských zážitků v Alpách.', 'poi', 35, 95, 'hard',
     '[{"lat": 46.9667, "lng": 11.0, "label": "Sölden – start v Ötztalu"}, {"lat": 46.9096, "lng": 11.0533, "label": "Hochgurgl – mýtná stanice"}, {"lat": 46.9028, "lng": 11.0967, "label": "Timmelsjoch / Passo del Rombo 2509 m"}, {"lat": 46.86, "lng": 11.12, "label": "Serpentiny italské strany"}, {"lat": 46.79436, "lng": 11.08807, "label": "Moso in Passiria / Moos in Passeier"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.9667,11.0&destination=46.79436,11.08807&travelmode=driving&waypoints=46.9096,11.0533%7C46.9028,11.0967%7C46.86,11.12', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B6lden_Restaurant_Ice_Q_am_Gaislachkogel_2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_view_south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hochgurgl-Top_Mountain_Motorcycle_Museum-06NTD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG"}'::text[], '{"Sölden","Restaurace: ice Q (Sölden)","Hochgurgl","Timmelsjoch / Passo del Rombo 2509 m","Top Mountain Motorcycle Museum (Passmuseum)","Moso in Passiria / Moos in Passeier"}'::text[], '{"Rakousko","Itálie"}'::text[], false, 240, 'approved');

  -- Okolo Lago di Garda  (250_garda.json)
  delete from public.routes where name = 'Okolo Lago di Garda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Okolo Lago di Garda', 'Okruh kolem největšího italského jezera Lago di Garda patří k nejkrásnějším motorkářským zážitkům v Alpách. Západní břeh vede po slavné Gardesana Occidentale, sérii serpentin a tunelů vytesaných přímo do skal nad hladinou, s dechberoucími výhledy na tyrkysovou vodu a masiv Monte Baldo. Východní břeh (Gardesana Orientale) nabízí plynulejší jízdu podél malebných městeček jako Malcesine s hradem Scaligero a lanovkou na Monte Baldo. Pozor na hustý turistický provoz v hlavní sezoně, úzké tunely bez osvětlení a cyklisty; nejlepší období je konec jara (květen–červen) a začátek podzimu (září), kdy je počasí příjemné a doprava snesitelnější. Naplánujte si celý den – zastávky u jezera, kávu na promenádě a projížďku starou silnicí Ponale nad Rivou si nenechte ujít.', 'loop', 165, 330, 'medium',
     '[{"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}, {"lat": 45.85271, "lng": 10.8812, "label": "Torbole / Ponale"}, {"lat": 45.81468, "lng": 10.79322, "label": "Limone sul Garda"}, {"lat": 45.65, "lng": 10.635, "label": "Gargnano"}, {"lat": 45.5536, "lng": 10.5675, "label": "Salò"}, {"lat": 45.49744, "lng": 10.60507, "label": "Sirmione"}, {"lat": 45.5525, "lng": 10.7596, "label": "Bardolino"}, {"lat": 45.677, "lng": 10.7157, "label": "Torri del Benaco"}, {"lat": 45.76442, "lng": 10.81024, "label": "Malcesine"}, {"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.88577,10.84117&destination=45.88577,10.84117&travelmode=driving&waypoints=45.85271,10.8812%7C45.81468,10.79322%7C45.65,10.635%7C45.5536,10.5675%7C45.49744,10.60507%7C45.5525,10.7596%7C45.677,10.7157%7C45.76442,10.81024', 'https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Scaligero%20Castle%20of%20Sirmione,%20town%20centre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG"}'::text[], '{"Riva del Garda","Torbole / Ponale","Limone sul Garda","Restaurace: QB Duepuntozero (Salò)","Sirmione","Restaurace: Ristorante Mignon (Malcesine)","Malcesine"}'::text[], '{"Itálie"}'::text[], false, 250, 'approved');

  -- Julské Alpy – průsmyk Vršič a údolí Soči  (260_vrsic.json)
  delete from public.routes where name = 'Julské Alpy – průsmyk Vršič a údolí Soči' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Julské Alpy – průsmyk Vršič a údolí Soči', 'Ikonická horská trasa Julskými Alpami, která se zcela vyhýbá dálnicím a vede jen po úzkých panoramatických silnicích. Z Kranjské Gory stoupá 50 očíslovanými serpentinami až na Vršič (1611 m) – nejvyšší silniční průsmyk ve Slovinsku, přičemž několik zatáček na východním svahu má stále původní dlažební kostky, které jsou za deště kluzké. Za sedlem trasa klesá do romantického údolí Trenta k prameni Soče a dále podél smaragdové řeky až do městečka Bovec. Nejlepší období je od června do září, kdy je průsmyk bez sněhu; brzy zjara a na podzim hrozí led a silnice se přes zimu uzavírá. Pozor na úzkou vozovku, cyklisty, turistické autobusy a náhlé změny počasí ve výškách.', 'poi', 50, 150, 'hard',
     '[{"lat": 46.485, "lng": 13.786, "label": "Kranjska Gora – start"}, {"lat": 46.469, "lng": 13.788, "label": "Jezero Jasna"}, {"lat": 46.433, "lng": 13.747, "label": "Průsmyk Vršič 1611 m"}, {"lat": 46.409, "lng": 13.719, "label": "Pramen Soči (Trenta)"}, {"lat": 46.357, "lng": 13.635, "label": "Údolí Soči"}, {"lat": 46.338, "lng": 13.552, "label": "Bovec – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.485,13.786&destination=46.338,13.552&travelmode=driving&waypoints=46.469,13.788%7C46.433,13.747%7C46.409,13.719%7C46.357,13.635', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Julian_Alps_from_Vrsic_Pass_(16).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velika_korita_So%C4%8De_So%C4%8Da_(Bovec)_01.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Hotel_Kanin.jpg"}'::text[], '{"Kranjska Gora","Jezero Jasna","Průsmyk Vršič (1611 m)","Pramen Soči (Izvir Soče)","Restaurace: Gostilna Metoja (Soča)","Bovec"}'::text[], '{"Slovinsko"}'::text[], false, 260, 'approved');

  -- Jadranská magistrála – chorvatské pobřeží  (270_jadran.json)
  delete from public.routes where name = 'Jadranská magistrála – chorvatské pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Jadranská magistrála – chorvatské pobřeží', 'Jadranská magistrála (Jadranska magistrala, státní silnice D8) je legendární pobřežní trasa vedoucí těsně nad hladinou Jadranu – záměrně se vyhýbá vnitrozemské dálnici A1 a nabízí nekonečné výhledy na moře, skalnaté útesy a ostrovy. Silnice se vine v serpentinách podél mohutného pohoří Velebit, střídá stoupání a klesání a odměňuje motorkáře plynulými zatáčkami s panoramaty modré vody. Nejlepší období pro jízdu je pozdní jaro (květen–červen) a začátek podzimu (září), kdy je provoz slabší a teploty snesitelnější. Pozor na nárazový vítr bóru pod Velebitem, který dokáže i za slunečného dne prudce zesílit, a na letní vedra na nechráněných úsecích. Trasa začíná u Opatije a Rijeky a míří přes Senj, Karlobag a Paklenicu až do historického Zadaru.', 'poi', 230, 300, 'medium',
     '[{"lat": 45.339, "lng": 14.306, "label": "Opatija / Rijeka – start magistrály"}, {"lat": 44.99, "lng": 14.903, "label": "Senj – pevnost Nehaj"}, {"lat": 44.529, "lng": 15.078, "label": "Karlobag pod Velebitem"}, {"lat": 44.283, "lng": 15.463, "label": "NP Paklenica"}, {"lat": 44.116, "lng": 15.226, "label": "Zadar – staré město"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.339,14.306&destination=44.116,15.226&travelmode=driving&waypoints=44.99,14.903%7C44.529,15.078%7C44.283,15.463', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg"}'::text[], '{"Opatija / Rijeka – začátek Jadranské magistrály","Senj – pevnost Nehaj","Karlobag pod Velebitem","Restaurace: Restaurant & Pizzeria OK Karlobag (Karlobag)","Národní park Paklenica","Zadar – staré město a mořské varhany"}'::text[], '{"Chorvatsko"}'::text[], false, 270, 'approved');

  -- Transfăgărășan – nejkrásnější silnice Karpat  (280_transfagarasan.json)
  delete from public.routes where name = 'Transfăgărășan – nejkrásnější silnice Karpat' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Transfăgărășan – nejkrásnější silnice Karpat', 'Transfăgărășan (silnice DN7C) je legendární horská cesta klikatící se přes rumunské Karpaty (pohoří Fagaraš) a rozhodně to není dálnice – celá trasa se vyhýbá rychlostním silnicím a nabízí nekonečné serpentiny stoupající až do výšky 2042 m. Cestou projedete tmavým 887 m dlouhým tunelem Bâlea těsně pod nejvyšším bodem a minete přehradu Vidraru, Drákulův hrad Poenari i ledovcové jezero Bâlea. Silnice je otevřená pouze od července do října; ve zbytku roku ji uzavírá sníh. Počítejte s proměnlivým horským počasím – i v létě zde bývá mlha, náhlé deště, chlad a mokrá vozovka, proto jeďte opatrně a s rezervou. Průměrná rychlost je kvůli zatáčkám kolem 40 km/h, na celý přejezd si vyhraďte klidně 5–6 hodin.', 'poi', 90, 360, 'hard',
     '[{"lat": 45.363, "lng": 24.634, "label": "Přehrada Vidraru"}, {"lat": 45.352, "lng": 24.635, "label": "Hrad Poenari"}, {"lat": 45.45, "lng": 24.6, "label": "Serpentiny jižní strany"}, {"lat": 45.596, "lng": 24.617, "label": "Tunel Bâlea (nejvyšší bod)"}, {"lat": 45.604, "lng": 24.617, "label": "Jezero Bâlea"}, {"lat": 45.618, "lng": 24.622, "label": "Vodopád Bâlea"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.363,24.634&destination=45.618,24.622&travelmode=driving&waypoints=45.352,24.635%7C45.45,24.6%7C45.596,24.617%7C45.604,24.617', 'https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg"}'::text[], '{"Restaurace: Bistro Subcarpați (Curtea de Argeș)","Přehrada Vidraru (Lacul Vidraru)","Hrad Poenari (Drákulův hrad)","Tunel Bâlea","Jezero Bâlea (Bâlea Lac)","Vodopád Bâlea (Cascada Bâlea)"}'::text[], '{"Rumunsko"}'::text[], false, 280, 'approved');

  -- Švýcarská trojice – Furka, Grimsel, Susten  (290_furka.json)
  delete from public.routes where name = 'Švýcarská trojice – Furka, Grimsel, Susten' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švýcarská trojice – Furka, Grimsel, Susten', 'Legendární okruh přes tři vysoké alpské průsmyky – Furka (2429 m), Grimsel (2164 m) a Susten (2224 m) – patří k nejkrásnějším motorkářským trasám ve Švýcarsku a záměrně se vyhýbá dálnicím i tunelům, takže jedete výhradně po panoramatických horských silnicích. Ze sedla Furka je nádherný výhled na ledovec Rhône a slavný hotel Belvédère, u Grimselu vás ohromí tyrkysová přehradní jezera Grimselsee a Totensee. Serpentiny jsou úzké, s množstvím vlásenek a místy bez svodidel, proto vyžadují zkušenost a plnou koncentraci. Nejlepší období je červen až září, mimo tuto sezónu bývají průsmyky uzavřené kvůli sněhu. Pozor na chlad ve výškách, náhlé změny počasí, cyklisty, autobusy a vlhký asfalt ve stinných úsecích.', 'loop', 120, 180, 'hard',
     '[{"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (start)"}, {"lat": 46.7267, "lng": 8.446, "label": "Sustenpass"}, {"lat": 46.561, "lng": 8.333, "label": "Grimselpass"}, {"lat": 46.573, "lng": 8.389, "label": "Ledovec Rhône / Belvédère"}, {"lat": 46.572, "lng": 8.415, "label": "Furkapass"}, {"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.6353,8.5941&destination=46.6353,8.5941&travelmode=driving&waypoints=46.7267,8.446%7C46.561,8.333%7C46.573,8.389%7C46.572,8.415', 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG"}'::text[], '{"Furkapass","Ledovec Rhône a Belvédère","Grimselpass","Sustenpass","Restaurace: Ochsen (Andermatt)","Andermatt"}'::text[], '{"Švýcarsko"}'::text[], false, 290, 'approved');

  -- Nockalmstraße a přehrada Kölnbreinsperre  (300_nockalm.json)
  delete from public.routes where name = 'Nockalmstraße a přehrada Kölnbreinsperre' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nockalmstraße a přehrada Kölnbreinsperre', 'Panoramatický okruh, který spojuje dva klenoty korutanských Alp a záměrně se vyhýbá dálnicím i rychlostním silnicím. Placená Nockalmstraße stoupá 52 vlásenkami mírnými zaoblenými horami Nockberge až na svůj nejvyšší bod Eisentalhöhe ve výšce 2042 m, odkud se otevírá dech beroucí výhled. Druhým vrcholem je jízda údolím Maltatal na masivní přehradu Kölnbreinsperre, nejvyšší přehradu Rakouska (200 m), s tyrkysovým jezerem a vyhlídkovou plošinou Airwalk. Ideální sezona je od začátku května do konce října, kdy jsou obě horské silnice sjízdné; mýto na Nockalmstraße činí přibližně 18,50 € pro motorky. Trasu doplňuje odpočinek u jezera Millstätter See, druhého největšího korutanského jezera, které je perfektním místem na kávu a zchlazení nohou.', 'loop', 175, 330, 'medium',
     '[{"lat": 46.8002, "lng": 13.583, "label": "Start – Millstätter See"}, {"lat": 46.965, "lng": 13.51, "label": "Údolí Maltatal"}, {"lat": 47.078, "lng": 13.352, "label": "Kölnbreinsperre – přehrada"}, {"lat": 46.929, "lng": 13.688, "label": "Innerkrems"}, {"lat": 46.885, "lng": 13.7, "label": "Nockalmstraße – panoramatická silnice"}, {"lat": 46.883, "lng": 13.7, "label": "Eisentalhöhe 2042 m"}, {"lat": 46.7903, "lng": 13.5745, "label": "Cíl – Millstätter See"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.8002,13.583&destination=46.7903,13.5745&travelmode=driving&waypoints=46.965,13.51%7C47.078,13.352%7C46.929,13.688%7C46.885,13.7%7C46.883,13.7', 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg"}'::text[], '{"Kölnbreinsperre – přehrada v údolí Maltatal","Innerkrems","Nockalmstraße – panoramatická silnice","Eisentalhöhe – nejvyšší bod 2042 m","Restaurace: Seerestaurant 1884 (Millstatt am See)","Millstätter See"}'::text[], '{"Rakousko"}'::text[], false, 300, 'approved');

  raise notice 'Seed tras (část 1/2) hotov: 53 tras k pobočce %', v_branch;
end $$;
