  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodní nádrž Trnávka', 'Přehrada na řece Trnavě mezi Želivem a Červenou Řečicí, vybudovaná v letech 1977–1981. Původně měla zachytávat splaveniny před vodárenskou nádrží Švihov, dnes slouží i k rekreaci a koupání. Pro motorkáře je to příjemná zastávka s možností občerstvení a klidnou hladinou obklopenou lesy.', 49.518, 15.212, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG"}'::text[], 0),
    (v_route, 'Klášter Želiv', 'Premonstrátský klášter založený roku 1139, jehož barokní podobu navrhl slavný architekt Jan Blažej Santini-Aichel. Areál nabízí prohlídky, klášterní pivovar i kavárnu, což je ideální pastva pro tělo i ducha při zastávce na trase. Leží přímo v údolí Želivky, takže sem pohodlně dojedete klidnými silnicemi bez nutnosti dálnice.', 49.53, 15.215, 'https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20the%20Nativity%20of%20the%20Virgin%20Mary%20(%C5%BDeliv)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20the%20Nativity%20of%20the%20Virgin%20Mary%20(%C5%BDeliv)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20%C5%BDeliv%20(1).jpg"}'::text[], 1),
    (v_route, 'Vodní nádrž Švihov (Želivka)', 'Největší vodárenská nádrž v Česku i střední Evropě, jejíž sypaná hráz je vysoká 58 metrů a dlouhá 850 metrů. Nádrž zásobuje pitnou vodou Prahu a její okolí, a proto je většina břehů chráněná a koupání zakázané. Z okolních silnic a mostů se ale otevírají velkolepé výhledy na táhlé rameno přehrady – ideální bod obratu celé okružní jízdy.', 49.676, 15.151, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20Svihov%20A.%20Hraz-Lavka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20Svihov%20A.%20Hraz-Lavka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zahr%C3%A1dka%20-%20Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0vihov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20Svihov%20C.%20KorunaHraze.jpg"}'::text[], 2),
    (v_route, 'Vodní nádrž Sedlice', 'Nejstarší přehrada na Želivce, vybudovaná v letech 1921–1927 zhruba 7 km jihozápadně od Humpolce. Zděná hráz s vodní elektrárnou je od roku 2012 kulturní památkou a hladina obklopená lesy láká k rybaření i klidné zastávce. Přístupová cesta vede malebnými zatáčkami po silnicích nižších tříd, přesně v duchu této pohodové trasy mimo dálnice.', 49.51377, 15.27026, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Sedlice%2C%20kvalita%20vody.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Mahler Penzion (Kaliště)', 'Restaurace v pečlivě zrekonstruovaném rodném domě skladatele Gustava Mahlera v Kališti u Humpolce, jen kousek od trasy. Kuchyně staví na sezónních a lokálních surovinách a tradiční české klasice, kterou hosté i kritici opakovaně chválí. Na TripAdvisoru drží skvělé hodnocení kolem 4,9 z 5 hvězd, takže jde o ideální zastávku na oběd při návratu přes Humpolec.', 49.4295, 15.3095, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gustav%20Mahler%20birth%20house%20in%20Kali%C5%A1t%C4%9B%2C%20Pelh%C5%99imov%20District.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gustav%20Mahler%20birth%20house%20in%20Kali%C5%A1t%C4%9B%2C%20Pelh%C5%99imov%20District.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek a náměstí Telč', 'Renesanční perla Vysočiny s jedinečným dlouhým náměstím Zachariáše z Hradce, lemovaným barevnými měšťanskými domy s podloubím. Zámek s nádhernými sály a arkádovým nádvořím patří od roku 1992 na seznam UNESCO. Ideální zastávka na kávu i procházku pěší zónou – motorku pohodlně zaparkujete kousek za historickým jádrem.', 49.184, 15.453, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Tel%C4%8D%20kaple%20V%C5%A1ech%20svat%C3%BDch.JPG"}'::text[], 0),
    (v_route, 'Zámek Jaroměřice nad Rokytnou', 'Jeden z největších barokních zámeckých komplexů v Česku s rozlehlou francouzskou zahradou a chrámem sv. Markéty. Monumentální stavba hraběte Questenberga byla ve své době centrem hudebního života Moravy. Klidná zastávka na trase mezi Telčí a Třebíčí, kde se dá protáhnout v parku a nadechnout před další jízdou.', 49.093, 15.893, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice%20nad%20rokytnou%20barocco%20castle%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice%20nad%20rokytnou%20barocco%20castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jarom%C4%9B%C5%99ice%20-%20z%C3%A1mek%2002.JPG"}'::text[], 1),
    (v_route, 'Restaurace: Adam''s Bar & Bistro (Třebíč)', 'Oblíbené bistro na Komenského náměstí v historickém centru Třebíče, kousek od baziliky sv. Prokopa. Nabízí sezónní moderní kuchyni, poctivé obědy a domácí limonády – restaurace patří s hodnocením kolem 4,9 hvězdičky k nejlépe hodnoceným podnikům ve městě a získala i uznání průvodce Gault&Millau. Skvělá zastávka na oběd zhruba v polovině vyjížďky.', 49.2153, 15.8814, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg"}'::text[], 2),
    (v_route, 'Bazilika sv. Prokopa v Třebíči', 'Vrcholně románsko-gotická bazilika z 13. století je považována za skvost středoevropské sakrální architektury a je součástí UNESCO. Ohromí vás mohutná klenba, rozetové okno a unikátní krypta. Stojí nad městem u bývalého benediktinského kláštera – z motorky sem dojedete přímo do areálu zámku.', 49.22, 15.874, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika-Prokopa2007.JPG"}'::text[], 3),
    (v_route, 'Židovská čtvrť Třebíč', 'Nejzachovalejší židovské ghetto ve střední Evropě a jediná židovská památka mimo Izrael zapsaná samostatně na seznam UNESCO. Spleť úzkých uliček, dvě synagogy a starý hřbitov vás přenesou o staletí zpět. Čtvrť leží jen pár kroků od baziliky, obojí se dá pohodlně spojit do jedné zastávky.', 49.218, 15.879, 'https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Jewish%20Synagogue.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Jewish%20Synagogue.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Jewish%20Synagogue%20(2).JPG"}'::text[], 4),
    (v_route, 'Poutní kostel sv. Jana Nepomuckého na Zelené hoře', 'Geniální barokně-gotická stavba architekta Jana Blažeje Santiniho-Aichela na kopci nad Žďárem, celá založená na symbolice čísla pět a tvaru hvězdy. Od roku 1994 je zapsána na seznamu UNESCO a patří k nejoriginálnějším sakrálním stavbám Evropy. Závěrečný cíl vyjížďky nabízí krásný výhled a klidné zákoutí k odpočinku po celodenní jízdě.', 49.588, 15.942, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zelen%C3%A1%20hora%20-%20poutn%C3%AD%20kostel.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Lipnice nad Sázavou', 'Mohutný gotický hrad ze 14. století se tyčí na skalním ostrohu nad městečkem a patří k největším v Čechách. Z jeho hradeb je nádherný rozhled do údolí Sázavy a k blízkému lomu, kde je pochován spisovatel Jaroslav Hašek. Pro motorkáře je to ideální první zastávka s parkováním pod hradem a příjemnou vyhlídkou.', 49.614, 15.413, 'https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg"}'::text[], 0),
    (v_route, 'Zámek Světlá nad Sázavou', 'Klasicistně přestavěný zámek s rozlehlým anglickým parkem leží přímo nad řekou Sázavou. Areál s kašnou, skleníkem a klidnými zákoutími nabízí příjemnou přestávku uprostřed trasy. Silnice sem vede pohodovým údolím a nabízí plynulou jízdu.', 49.669, 15.404, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek2.jpg"}'::text[], 1),
    (v_route, 'Hrad Ledeč nad Sázavou', 'Gotický hrad s dominantní válcovou věží stráží řeku Sázavu z vysokého skalnatého ostrohu nad městem. Z nádvoří i z okolí se otevírají pěkné pohledy na řeku a historické jádro Ledče. Cesta k hradu vede malebným údolím se svižnými zatáčkami.', 49.696, 15.278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG"}'::text[], 2),
    (v_route, 'Hrad Český Šternberk', 'Jeden z nejlépe dochovaných gotických hradů v Čechách se dramaticky vypíná na skalním hřebeni přímo nad řekou Sázavou. Nejkrásnější pohled je z mostu přes řeku, odkud hrad působí jako z pohádky. Přístupová silnice údolím patří k nejhezčím úsekům celé trasy.', 49.81, 14.928, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-hrad2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-%2012.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Pod Hradem (Český Šternberk)', 'Oblíbená restaurace přímo pod hradem Český Šternberk s terasou nad řekou Sázavou. Nabízí českou kuchyni, čerstvé ryby a výborné točené pivo v malebném prostředí. Hosté ji hodnotí skvěle (kolem 4,4 hvězdičky z tisíců recenzí) a je ideální zastávkou zhruba v polovině trasy.', 49.812, 14.93, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-%2028.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-%2028.JPG"}'::text[], 4),
    (v_route, 'Sázavský klášter', 'Benediktinský klášter založený svatým Prokopem roku 1032 leží nad řekou Sázavou a je kolébkou slovanské vzdělanosti v Čechách. Areál s nedostavěným gotickým chrámem svatého Prokopa tvoří klidný a působivý závěr celé vyjížďky. Okolní silnice podél řeky jsou svižné a scénické.', 49.876, 14.898, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter%20(kaple).JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Skalní útvar Devět skal', 'Devět skal je s nadmořskou výškou 836 m nejvyšší bod Žďárských vrchů a druhý nejvyšší vrchol celé Českomoravské vrchoviny. Skalní labyrint tvoří tři dlouhé hřebeny s devíti mohutnými žulovými věžemi, ke kterým dojedete po klikatých lesních silnicích. Ideální zastávka na protažení nohou a rozhled do drsné vrchoviny.', 49.67079, 16.03238, 'https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg"}'::text[], 0),
    (v_route, 'Skály Čtyři palice', 'Čtyři palice jsou nápadné migmatitové skály nad Milovy, tvořící přírodní rezervaci s bučinami a bory. Hlavní skupina skal dosahuje výšky kolem 33 metrů a je vyhledávaným cílem horolezců i turistů. Pro motorkáře je okolí odměnou v podobě úzkých zatáček a lesních průsmyků.', 49.68606, 16.09333, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/PR%20%C4%8Cty%C5%99i%20palice.jpg"}'::text[], 1),
    (v_route, 'Skalní útvar Drátník', 'Drátník (též Dráteník či Drátenická skála) je téměř 200 metrů dlouhý skalní hřeben a jedna z nejvýraznějších dominant střední části CHKO Žďárské vrchy. Leží na zalesněném vrcholu mezi Blatinami a Samotínem ve výšce okolo 775 m. Cesta k němu vede tichými lesními okreskami plnými zatáček.', 49.66056, 16.07222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tenick%C3%A1%20sk%C3%A1la.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Hotel Sněžné – Restaurace (Sněžné)', 'Restaurace rodinného wellness hotelu Sněžné leží přímo v obci v srdci CHKO Žďárské vrchy a nabízí poctivou tradiční českou kuchyni. Hosté ji na Firmy.cz hodnotí skvělou známkou 4,6 z 5 a chválí si kvalitu jídla i příjemnou obsluhu. Ideální zastávka na doplnění sil uprostřed okruhu mezi skalními útvary.', 49.6636, 16.0533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg"}'::text[], 3),
    (v_route, 'Městys Sněžné (Milovy)', 'Sněžné je horský městys v srdci Žďárských vrchů, ke kterému patří i osada Milovy pod skalami. Nabízí občerstvení, ubytování a je ideálním výchozím bodem pro okolní skalní útvary jako Drátník a Čtyři palice. Barokní kostel a klidné náměstí lákají k zastávce a doplnění sil.', 49.6636, 16.0533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg"}'::text[], 4),
    (v_route, 'Rozhledna Karasín', 'Rozhledna Karasín u Bystřice nad Pernštejnem stojí ve výšce kolem 619 m a nabízí po 128 schodech kruhový výhled na jižní část Žďárských vrchů. Je to skvělá zastávka na jižním konci okruhu, k níž vede příjemná zvlněná silnice. Vstup bývá zdarma a v okolí je dostatek místa k zaparkování motorky.', 49.55497, 16.27954, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karas%C3%ADn%20z%20rozhledny.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Jindřichův Hradec', 'Třetí největší zámecký komplex v Česku, malebně položený nad řekou Nežárkou a rybníkem Vajgar. Rozsáhlý renesanční areál s arkádovými nádvořími a unikátním hudebním pavilonem Rondel je skvělým startem trasy. Přímo pod hradbami najdete klidná parkovací místa i příjemné kavárny pro první zastávku.', 49.144, 15.003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jind%C5%99ich%C5%AFv.Hradec.z%C3%A1mek.rondel1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jind%C5%99ich%C5%AFv_Hradec_Schloss_-_Brunnen_4b.jpg"}'::text[], 0),
    (v_route, 'Zámek Červená Lhota', 'Pohádkový vodní zámek s jasně červenou fasádou, který se zrcadlí na hladině rybníka a je přístupný jen po kamenném mostě. Patří k nejfotogeničtějším místům jižních Čech a k zámku vede příjemná klikatá silnička lesem. Ideální místo na krátkou procházku kolem vody a odpočinek v sedle.', 49.198, 15.077, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C4%8Cerven%C3%A1_Lhota_jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cervena_Lhota,_Czech_Republic.jpg"}'::text[], 1),
    (v_route, 'Rybník Rožmberk – hráz', 'Největší rybník v Česku o rozloze téměř 490 hektarů, vybudovaný Jakubem Krčínem v 16. století. Po jeho monumentální hrázi lemované staletými duby vede klidná cesta s nádhernými výhledy na vodní hladinu. Rovinatý úsek je jako stvořený pro pomalou vyjížďku a zastávku u vody.', 49.061, 14.804, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka_(3).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk_a_K%C3%A1%C5%88ov.JPG"}'::text[], 2),
    (v_route, 'Schwarzenberská hrobka', 'Novogotická rodová hrobka Schwarzenbergů z let 1874–1877, ukrytá v anglickém parku u břehu rybníka Svět. Bílá stavba obklopená zelení působí nezvykle klidně a romanticky. K hrobce vede příjemná cesta parkem, kde se dá pěkně protáhnout po delší jízdě.', 49.02, 14.783, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka_(01).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka_(08).jpg"}'::text[], 3),
    (v_route, 'Restaurace: Šupina a Šupinka (Třeboň)', 'Proslulá rybí restaurace přímo u hráze rybníka Svět, kde se od roku 1993 podávají třeboňský kapr, candát i sumec z místních rybníků. Kuchyně staví na čerstvých sladkovodních rybách a tradiční jihočeské gastronomii a hosté ji dlouhodobě hodnotí velmi vysoko. Ideální zastávka na oběd v samém srdci Třeboně.', 49.0035, 14.7695, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_u_T%C5%99ebon%C4%9B.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_u_T%C5%99ebon%C4%9B.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99ebo%C5%88,_Masarykovo_n%C3%A1m%C4%9Bst%C3%AD_99_a_100,_spo%C5%99itelna.jpg"}'::text[], 4),
    (v_route, 'Třeboň – zámek a rybník Svět', 'Historické lázeňské město s dochovaným renesančním jádrem, zámkem a hradbami, obklopené sítí rybníků. Rybník Svět přímo u města láká k procházce po hrázi i k občerstvení v přilehlých restauracích. Ideální cíl trasy s dostatkem parkování a možností delší zastávky.', 49.003, 14.771, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_u_T%C5%99ebon%C4%9B.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99ebo%C5%88_Schloss_-_Rosenberger_Tor_2.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodní nádrž Orlík – hráz', 'Mohutná betonová hráz Orlické přehrady o výšce 91 metrů zadržuje druhou největší vodní nádrž v Česku. Vznikla v rámci Vltavské kaskády v letech 1954 až 1961 a nabízí pohled na strojní srdce celé přehrady. Silnice v okolí hráze jsou svižné a lemované lesy, ideální pro klidnou jízdu.', 49.539, 14.164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg"}'::text[], 0),
    (v_route, 'Zámek Orlík nad Vltavou', 'Romantický zámek rodu Schwarzenbergů stojí na skalnatém ostrohu přímo nad hladinou Orlické přehrady. Původně gotický hrad byl přestavěn do dnešní novogotické podoby a obklopuje jej rozlehlý anglický park. Pro motorkáře je to ideální zastávka s parkováním a výhledy na vodu, odkud lze pokračovat podél přehrady dál.', 49.5175, 14.16972, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg"}'::text[], 1),
    (v_route, 'Restaurace: U Cvrků (Orlík nad Vltavou)', 'Rodinná restaurace na příjezdové cestě jen asi kilometr od zámku Orlík, ideální zastávka na oběd v polovině okruhu. Specializuje se na českou kuchyni a zejména na zvěřinové speciality, které si pochvalují hosté díky poctivé domácí přípravě a příjemným cenám. Návštěvníci vyzdvihují vstřícnou obsluhu a klidné prostředí se zahrádkou i parkováním přímo ve dvoře.', 49.5108, 14.1655, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg"}'::text[], 2),
    (v_route, 'Kostel Červená nad Vltavou', 'Kostel svatého Bartoloměje je poslední památkou na vesnici Červená nad Vltavou, kterou pohltily vody přehrady. Před zaplavením byl přenesen výše nad údolí, kde dnes osaměle stojí nad vodní hladinou v malebné krajině. Klidné místo stranou hlavních cest je příjemnou zastávkou na okruhu podél Vltavy.', 49.4, 14.29, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerven%C3%A1%20014.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerven%C3%A1%20014.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerven%C3%A1%20016.jpg"}'::text[], 3),
    (v_route, 'Podolský most', 'Impozantní obloukový most přes zátoku Orlické přehrady patří k technickým skvostům své doby a klene se ve velké výšce nad vodní hladinou. Přejezd po tomto vysokém mostě je pro motorkáře nezapomenutelný zážitek s panoramatem na řeku Vltavu. U mostu se dá zastavit a pokochat se pohledem do hloubky.', 49.35645, 14.26352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(20).jpg"}'::text[], 4),
    (v_route, 'Hrad Zvíkov', 'Zvíkov, přezdívaný král českých hradů, se tyčí na skalním ostrohu nad soutokem Vltavy a Otavy. Patří k nejvýznamnějším raně gotickým hradům u nás a jeho arkádové nádvoří i Hlízová věž stojí za prohlídku. Cesta k hradu vede úzkými zatáčkami nad přehradou a nabízí strhující výhledy.', 49.437, 14.1885, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zv%C3%ADkov%20castle%20in%20spring%202011%20(8).JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tábor – Žižkovo náměstí a hrad Kotnov', 'Historické jádro Tábora s malebným Žižkovým náměstím a věží Kotnov je srdcem husitského hnutí a městskou památkovou rezervací. Věž hradu Kotnov spolu s Bechyňskou branou tvoří dominantu města nad údolím Lužnice. Pro motorkáře je to ideální zastávka na kávu v dlážděných uličkách i vstup do slavného táborského podzemí.', 49.4111, 14.6558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov2_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(02).jpg"}'::text[], 0),
    (v_route, 'Restaurace: Goldie (Tábor)', 'Restaurace Goldie v boutique hotelu Nautilus přímo na Žižkově náměstí nabízí špičkovou českou i mezinárodní kuchyni z lokálních surovin. V roce 2026 získala prestižní ocenění Michelin Bib Gourmand za výjimečné jídlo za rozumnou cenu. Elegantní interiér s díly českých umělců a výhled na náměstí z ní dělají skvělou zastávku na oběd uprostřed trasy.', 49.4144, 14.658, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg"}'::text[], 1),
    (v_route, 'Kozí hrádek', 'Romantická zřícenina gotického hrádku ukrytá v lese u Sezimova Ústí, kde v letech 1413–1414 pobýval a kázal mistr Jan Hus. Národní kulturní památka láká na klidnou procházku hlubokým lesem k dochovaným zdem a příkopům. Skvělé místo na krátký oddech mimo ruch silnic.', 49.39775, 14.72642, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg"}'::text[], 2),
    (v_route, 'Chýnovská jeskyně', 'Nejstarší zpřístupněná jeskyně v Česku, otevřená veřejnosti už od roku 1868, s výraznou barevnou hrou bílého mramoru a tmavé amfibolitové horniny. Prohlídková trasa vede strmými schody podzemím se zajímavými geologickými útvary a je významným zimovištěm netopýrů. Příjemné osvěžení v horkém dni po jízdě zvlněnou krajinou.', 49.42944, 14.83306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg"}'::text[], 3),
    (v_route, 'Zámek Bechyně a most Duha', 'Renesanční zámek Bechyně stojí na skalním ostrohu nad soutokem Smutné a Lužnice a spolu s klenutým železobetonovým mostem Duha z roku 1928 tvoří jeden z nejfotogeničtějších pohledů jižních Čech. Most se klene 50 metrů nad hladinou řeky a nabízí dech beroucí výhled do údolí. Zastávka spojující historii, techniku i krásnou přírodu.', 49.297, 14.469, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20most%20Duha,%20od%20z%C3%A1mku.jpg"}'::text[], 4),
    (v_route, 'Rozhledna Hýlačka', 'Dřevěná rozhledna na kopci Hýlačka v lokalitě Větrovy nad Táborem ve výšce přes 500 metrů nad mořem nabízí kruhový rozhled po Táborsku a za dobrého počasí až k šumavským hřebenům. Znovupostavená věž je oblíbeným výletním cílem s posezením v okolí. Ideální tečka výletu s výhledem, než se vydáte zpět na základnu.', 49.389, 14.643, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Adršpašsko-teplické skály', 'Národní přírodní rezervace Adršpašsko-teplické skály je největší skalní město ve střední Evropě a od roku 1933 patří k nejnavštěvovanějším přírodním památkám Česka. Bludiště pískovcových věží, soutěsek a jezírek se prochází po značených okruzích a nabízí zážitek jako z jiného světa. Pro motorkáře je to ideální první zastávka okruhu s velkým parkovištěm hned u vstupu.', 50.61526, 16.12271, 'https://commons.wikimedia.org/wiki/Special:FilePath/Adr%C5%A1pa%C5%A1skoteplick%C3%A9%20sk%C3%A1ly%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Adr%C5%A1pa%C5%A1skoteplick%C3%A9%20sk%C3%A1ly%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Adr%C5%A1pa%C5%A1sko-teplick%C3%A9%20sk%C3%A1ly%20picture-004.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Skalne%20Miasto%20Adrspach%20ska%C5%82y%204.jpg"}'::text[], 0),
    (v_route, 'Broumovské stěny', 'Broumovské stěny jsou nápadný hřbet pískovcových skalních útvarů táhnoucí se mezi Broumovskou a Polickou kotlinou. Národní přírodní rezervace chrání skalní věže, rokle i vyhlídky, mezi nimiž vyniká Supí hnízdo s výhledem do polského vnitrozemí a barokní kaple Hvězda. Po klikatých silničkách sem dojedete od Police nad Metují nebo od Broumova a nahoru pak vyrazíte pěšky.', 50.527, 16.315, 'https://commons.wikimedia.org/wiki/Special:FilePath/NPR%20Broumovsk%C3%A9%20st%C4%9Bny%2C%20Sup%C3%AD%20hn%C3%ADzdo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NPR%20Broumovsk%C3%A9%20st%C4%9Bny%2C%20Sup%C3%AD%20hn%C3%ADzdo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kov%C3%A1%C5%99ova%20rokle%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hv%C4%9Bzda%20(kaple)%20-%20pohled%20k%20Broumovu.JPG"}'::text[], 1),
    (v_route, 'Zámek Náchod', 'Renesanční zámek Náchod se tyčí na ostrohu nad městem a patří k nejvýznamnějším památkám Kladského pomezí. Za jeho dnešní podobou stojí rod Piccolominiů a později Schaumburg-Lippové, po nichž zůstaly bohaté sbírky i zámecké interiéry. Z valů a z okrouhlé věže je krásný rozhled na město i okolní kopce, což z něj dělá vděčnou zastávku prvního dne.', 50.41857, 16.1619, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2006.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2003.JPG"}'::text[], 2),
    (v_route, 'Restaurace: U Slovana (Náchod)', 'Restaurace U Slovana patří k nejlépe hodnoceným podnikům v Náchodě (Google 4,4) a nabízí poctivou českou kuchyni i denní menu. Je vhodnou zastávkou na oběd prvního dne, protože leží přímo ve městě u zámku. Interiér je příjemný a porce vydatné, ideální po dopoledni stráveném ve skalách.', 50.4155, 16.166, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20N%C3%A1chod%20in%202009%2013.JPG"}'::text[], 3),
    (v_route, 'Pevnost Dobrošov', 'Dělostřelecká tvrz Dobrošov je nedostavěnou pevností československého pohraničního opevnění z let 1937–1938 a dnes je národní kulturní památkou. Návštěvníci si mohou prohlédnout dělostřelecký srub Zelený, podzemní chodby i muzeum věnované obraně republiky. Na kopec nad Náchodem vede příjemná okreska a od pevnosti je krásný výhled do kraje.', 50.402, 16.202, 'https://commons.wikimedia.org/wiki/Special:FilePath/N-S%2075%20(Dobrosov)%20a%20budova%20muzea.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N-S%2075%20(Dobrosov)%20a%20budova%20muzea.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N-S%2075.JPG"}'::text[], 4),
    (v_route, 'Deštné v Orlických horách', 'Horská obec Deštné v Orlických horách leží v nadmořské výšce kolem 650 metrů a je oblíbeným výchozím bodem pro výlety na hřeben. Dominantou obce je barokní kostel svaté Máří Magdalény, kolem něhož vedou příjemné motocyklové silničky k Šerlichu. V zimě i v létě sem míří turisté a Deštné je ideálním místem pro přespání mezi prvním a druhým dnem okruhu.', 50.30163, 16.35442, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panoramatick%C3%BD%20pohled%20na%20Orlick%C3%A9%20Z%C3%A1ho%C5%99%C3%AD%2C%20okres%20Rychnov%20nad%20Kn%C4%9B%C5%BEnou.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panoramatick%C3%BD%20pohled%20na%20Orlick%C3%A9%20Z%C3%A1ho%C5%99%C3%AD%2C%20okres%20Rychnov%20nad%20Kn%C4%9B%C5%BEnou.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20sv.%20M%C3%A1%C5%99%C3%AD%20Magdal%C3%A9ny%20(De%C5%A1tn%C3%A9%20v%20Orlick%C3%BDch%20hor%C3%A1ch).JPG"}'::text[], 5),
    (v_route, 'Restaurace: Kozí chlívek (Deštné v Orlických horách)', 'Rodinný penzion a restaurace Kozí chlívek v centru Deštného patří s hodnocením 4,5 na Googlu k nejoblíbenějším podnikům v Orlických horách. Kuchyně sází na tradiční českou a domácí kuchyni doplněnou o sezónní speciality z čerstvých surovin. Je to skvělá zastávka poblíž poloviny okruhu, kde načerpáte síly před cestou na Šerlich.', 50.30163, 16.35442, 'https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg"}'::text[], 6),
    (v_route, 'Masarykova chata na Šerlichu', 'Masarykova chata na Šerlichu stojí v nadmořské výšce kolem 1019 metrů poblíž česko-polské hranice a je jednou z nejznámějších horských chat Orlických hor. Vznikla ve 20. letech 20. století podle návrhu architekta Bohuslava Fuchse a dodnes slouží turistům k občerstvení i ubytování. Přístupová horská silnice od Deštného patří k nejhezčím motorkářským úsekům celého okruhu.', 50.32564, 16.38635, 'https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Schronisko%20Masarykova%20Chata.jpg"}'::text[], 7),
    (v_route, 'Peklo (Bartoňova útulna)', 'Peklo je romantické zalesněné údolí při soutoku Metuje a Olešenky mezi Náchodem a Novým Městem nad Metují. Jeho srdcem je Bartoňova útulna, bývalý mlýn přestavěný roku 1910 podle návrhu architekta Dušana Jurkoviče na výletní restauraci. Přírodní rezervace s meandry řeky a skalními stěnami je oázou klidu, kterou proťatá klidná silnice dělá vděčnou zastávkou druhého dne.', 50.37924, 16.18716, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20nad%20Metuj%C3%AD%20Peklo%202011%203.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20nad%20Metuj%C3%AD%20Peklo%202011%203.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20nad%20Metuj%C3%AD%20Peklo%202011%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20M%C4%9Bsto%20nad%20Metuj%C3%AD%20Peklo%202011%201.jpg"}'::text[], 8),
    (v_route, 'Nové Město nad Metují (zámek)', 'Nové Město nad Metují proslulo malebným renesančním náměstím s podloubím a zámkem, který ve 20. století upravili architekti Dušan Jurkovič a Pavel Janák. Zámecké zahrady s dřevěným mostem patří k nejkrásnějším ukázkám moderní architektury zasazené do historického jádra. Město bývá označováno za jedno z nejhezčích v Čechách a je příjemnou zastávkou na zpáteční cestě.', 50.34377, 16.1497, 'https://commons.wikimedia.org/wiki/Special:FilePath/NMM%20zamek%20z%20nam%20DSC00231.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NMM%20zamek%20z%20nam%20DSC00231.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NMMet%20nam%20z%20podl%20ke%20kost%20DSCN3141.JPG"}'::text[], 9),
    (v_route, 'Kunětická hora', 'Kunětická hora je osamělý čedičový vrch nad Polabskou nížinou, korunovaný pozdně gotickým hradem viditelným z dálky. Hrad prošel renesanční přestavbou a dnes láká na prohlídky, výstavy i výhledy do kraje z hradních věží. Jako poslední zastávka okruhu je efektní tečkou před návratem a dojezd k parkovišti pod kopcem je snadný.', 50.08, 15.81306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad-kuneticka%20hora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad-kuneticka%20hora.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kun%C4%9Btick%C3%A1%20hora%20-%20Pohled%20od%20hradeb.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kun%C4%9Btick%C3%A1%20hora%20od%20parkovi%C5%A1t%C4%9B.jpg"}'::text[], 10);
