  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek a náměstí Telč', 'Renesanční klenot na seznamu UNESCO od roku 1992 s dlouhým náměstím Zachariáše z Hradce lemovaným podloubími a štíty. Nad městem se tyčí renesanční zámek Zachariáše z Hradce mezi dvěma rybníky. Skvělá zastávka na kávu a fotky uprostřed okruhu. Dlažba náměstí bývá kluzká, jeďte opatrně.', 49.184, 15.453, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tel%C4%8D.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Restaurant Zach (Telč)', 'Oblíbená restaurace přímo na renesančním náměstí Zachariáše z Hradce s moderně zrekonstruovaným interiérem a výhledem na podloubí. Nabízí českou i mezinárodní kuchyni a patří mezi nejlépe hodnocené podniky ve městě. Ideální zastávka na oběd uprostřed okruhu, s parkováním kousek od náměstí.', 49.1841, 15.4529, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg"}'::text[], 1),
    (v_route, 'Mrákotín – žulové lomy a pomník', 'Městys proslulý těžbou žuly už od 19. století; odtud pochází monolit na třetím nádvoří Pražského hradu vylámaný roku 1925. Na náměstí stojí žulový pomník padlým z roku 1937 postavený místními lomaři. Okolní silničky ke Studené a k Javořici patří mezi nejzatáčkovitější v oblasti. Pěkná zastávka pro milovníky kamene i klikatého asfaltu.', 49.157, 15.412, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn%20z%20Javo%C5%99ice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn%20z%20Javo%C5%99ice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn%20s%20Javo%C5%99ic%C3%AD.jpg"}'::text[], 2),
    (v_route, 'Javořice', 'Nejvyšší vrchol Vysočiny a celé Českomoravské vrchoviny (837 m) s výrazným televizním vysílačem z roku 1989. K vrcholu vedou úzké lesní asfaltky plné zatáček, které patří k nejlepším v kraji. Kousek pod vrcholem je vyhlídková plošina s výhledem k Telči. Ideální zastávka pro motorkáře hledající klid hlubokých smrčin.', 49.153, 15.351, 'https://commons.wikimedia.org/wiki/Special:FilePath/Javorice%202014-08%2012560.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Javorice%202014-08%2012560.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Javorice-vysilac-v-noci.jpg"}'::text[], 3),
    (v_route, 'Velký Pařezitý rybník', 'Přírodní rezervace a oblíbený rybník u Řásné, který nechal založit Zachariáš z Hradce roku 1565. Leží ve výšce kolem 670 m obklopen lesy a rašeliništi, koupání je zde povolené. Skvělé místo na osvěžení a odpočinek uprostřed klikaté lesní trasy. Okolní silničky nabízejí příjemné zatáčky ve stínu stromů.', 49.17, 15.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%202020-06-16.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%202020-06-16.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/PR%20Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%20(5).JPG"}'::text[], 4),
    (v_route, 'Hrad Roštejn', 'Romantický lovecký hrad ukrytý v lesích Roštejnské obory, dominantou je sedmiboká věž. Původně gotická tvrz sloužila pánům z Hradce jako lovecké sídlo v nadmořské výšce kolem 670 m. Přístupová lesní cesta je klikatá a atmosférická, ideální pro pomalou svižnou jízdu. Vhodná zastávka na prohlídku i piknik v tichu lesa.', 49.272, 15.484, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Ro%C5%A1tejn%201.jpg"}'::text[], 5);
