  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Milešovka', 'Milešovka (837 m n. m.) je nejvyšší hora Českého středohoří a zároveň největrnější místo v Česku. Na vrcholu stojí meteorologická stanice a rozhledna, ze které se za dobré viditelnosti otevírá kruhový výhled na desítky vyhaslých sopek regionu. Kuželovitý čedičový vrch je turistickou ikonou celé oblasti a jeho zdolání patří k vrcholům každého výletu do středohoří.', 50.55491, 13.93109, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mile%C5%A1ovka%20(837%20m),%20pohled%20z%20lesa%20na%20%C3%BApat%C3%AD.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mile%C5%A1ovka%20(837%20m),%20pohled%20z%20lesa%20na%20%C3%BApat%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/National%20nature%20reserve%20Mile%C5%A1ovka%20in%20summer%202014%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Milesovka%20ppost.jpg"}'::text[], 0),
    (v_route, 'Říp (rotunda sv. Jiří)', 'Hora Říp (456 m n. m.) je bájné místo spjaté s pověstí o praotci Čechovi a patří k nejvýznamnějším symbolům české státnosti. Na vrcholu stojí románská rotunda svatého Jiří a svatého Vojtěcha, jedna z nejstarších dochovaných staveb v zemi, poprvé zmíněná roku 1126. Výstup na Říp odměňuje širokým rozhledem do polabské roviny a je oblíbeným cílem výletníků z celé republiky.', 50.38645, 14.28957, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rotunda%20svat%C3%A9ho%20Ji%C5%99%C3%AD%20a%20svat%C3%A9ho%20Vojt%C4%9Bcha%20%C5%98%C3%ADp.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rotunda%20svat%C3%A9ho%20Ji%C5%99%C3%AD%20a%20svat%C3%A9ho%20Vojt%C4%9Bcha%20%C5%98%C3%ADp.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20sv.%20Ji%C5%99%C3%AD,%20rotunda%20s%20horou%20%C5%98%C3%ADp%20(Mnet%C4%9B%C5%A1).JPG"}'::text[], 1),
    (v_route, 'hrad Házmburk', 'Zřícenina hradu Házmburk se tyčí na výrazném čedičovém vrchu nad obcí Klapý a její dvojice věží je jednou z nejtypičtějších dominant Českého středohoří. Z bílé věže vysoké 26 metrů je nádherný rozhled po okolní krajině vyhaslých sopek a Polabí. Hrad ze 13. století patřil rodu Zajíců z Házmburka a dnes je oblíbeným výletním místem s dobře přístupným parkovištěm v Klapém.', 50.434, 14.01557, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20H%C3%A1zmburk%20(Klap%C3%BD)%20-%20%C4%8Cern%C3%A1%20v%C4%9B%C5%BE.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20H%C3%A1zmburk%20(Klap%C3%BD)%20-%20%C4%8Cern%C3%A1%20v%C4%9B%C5%BE.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%99%C3%ADcenina%20hradu%20H%C3%A1zmburk%20(Klap%C3%BD).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Hazmburk.JPG"}'::text[], 2),
    (v_route, 'Terezín (památník)', 'Terezín je bývalé pevnostní město, jehož Malá pevnost sloužila za druhé světové války jako věznice gestapa a je součástí Památníku Terezín. Nad vstupní branou je dodnes cynický nápis Arbeit macht frei, který připomíná utrpení tisíců vězňů. Návštěva pietního místa je silným a naléhavým zážitkem a připomínkou hrůz nacistické perzekuce. Památník je jedním z nejvýznamnějších míst paměti v Česku.', 50.51306, 14.15889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Czech-2013-Terezin-Theresienstadt-Arbeit%20macht%20frei.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Czech-2013-Terezin-Theresienstadt-Arbeit%20macht%20frei.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pevnost%20Terez%C3%ADn.jpg"}'::text[], 3),
    (v_route, 'Litoměřice (náměstí)', 'Historické Mírové náměstí v Litoměřicích tvoří jádro tohoto starobylého vinařského města už od středověku. Lemují jej barokní i renesanční domy, mezi nimiž vyniká dům Kalich s vyhlídkovou věží ve tvaru kalicha připomínající zdejší vinařskou tradici. Náměstí je ideálním místem na odpočinek, kávu a procházku uličkami plnými historie. Litoměřice bývají označovány za bránu do Českého středohoří.', 50.53412, 14.1313, 'https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20M%C3%ADrov%C3%A9%20n%C3%A1m.%20%C4%8Dp.160-161.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20M%C3%ADrov%C3%A9%20n%C3%A1m.%20%C4%8Dp.160-161.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20M%C3%ADrov%C3%A9%20n%C3%A1m.%20%C4%8Dp.168.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Dobrá Bašta (Litoměřice)', 'Dobrá Bašta v Litoměřicích je vysoce hodnocená restaurace ve stylu první republiky, patřící mezi nejlepší v celém okrese. Nabízí poctivou českou kuchyni z lokálních surovin, sezónní zvěřinové speciality a příjemné venkovní posezení u městských hradeb. Ocenění hostů i vysoké recenze z ní dělají ideální zastávku na oběd zhruba v polovině okruhu.', 50.53318, 14.1376, 'https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20Mezibran%C3%AD,%20hradby%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20Mezibran%C3%AD,%20hradby%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Litom%C4%9B%C5%99ice,%20Mezibran%C3%AD,%20hradby%20(2).jpg"}'::text[], 5),
    (v_route, 'Střekov (hrad, Ústí nad Labem)', 'Hrad Střekov stojí na strmé znělcové skále vysoko nad pravým břehem Labe v Ústí nad Labem a patří k nejromantičtějším zříceninám v Česku. Gotický hrad ze 14. století inspiroval řadu umělců, mimo jiné skladatele Richarda Wagnera. Z hradních hradeb se otevírá nezapomenutelný pohled na řeku, zdymadlo a údolí středohoří. Dominantní silueta hradu nad Labem je jedním z klasických motivů severních Čech.', 50.639, 14.051, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Strekov%20Usti%20nad%20Labem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Strekov%20Usti%20nad%20Labem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Strekov%20brana%20Usti%20nad%20Labem.jpg"}'::text[], 6),
    (v_route, 'Porta Bohemica (vyhlídka)', 'Porta Bohemica, česky Brána Čech, je působivé místo, kde řeka Labe prořezává hřbet Českého středohoří a vytváří několik kilometrů dlouhé skalnaté údolí. Z okolních vyhlídek nad Velkými Žernoseky se otevírají jedny z nejkrásnějších pohledů na meandry Labe lemované vinicemi a čedičovými kopci. Je to vyhledávaný cíl fotografů i milovníků přírody. Zdejší svahy patří k tradičním vinařským oblastem regionu.', 50.539, 14.066, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9%20%C5%BDernoseky,%20Porta%20Bohemica,%20p%C5%99%C3%ADrodn%C3%AD%20rezervace%20Kalv%C3%A1rie.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9%20%C5%BDernoseky,%20Porta%20Bohemica,%20p%C5%99%C3%ADrodn%C3%AD%20rezervace%20Kalv%C3%A1rie.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9%20%C5%BDernoseky,%20pohled%20na%20%C4%8Ceskou%20br%C3%A1nu%20od%20p%C5%99%C3%ADvozu.JPG"}'::text[], 7),
    (v_route, 'zámek Ploskovice', 'Barokní zámek Ploskovice leží nedaleko Litoměřic a byl vybudován v letech 1720 až 1730 podle návrhu Kiliána Ignáce Dientzenhofera pro Annu Marii Františku Toskánskou. Skvostem zámku jsou umělé vodní jeskyně zvané grotty a rozlehlý osmihektarový park. V 19. století sloužil zámek jako letní rezidence Habsburků, zejména císaře Ferdinanda V. Dobrotivého. Dnes je oblíbeným výletním cílem s prohlídkovými okruhy a klidnou zahradou.', 50.5598, 14.2012, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ploskovice%20Schloss4.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ploskovice%20Schloss4.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Ploskovice,%20Ploskovice%201,%20Ploskovice,%20okr.%20Litom%C4%9B%C5%99ice,%20%C3%9Asteck%C3%BD%20kraj%2014.jpg"}'::text[], 8);
