  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vranov nad Dyjí (zámek)', 'Barokní skvost tyčící se na strmé skále nad meandrem řeky Dyje patří k nejkrásnějším zámkům Moravy. Nejobdivovanější je monumentální Sál předků s freskovou výzdobou a zámecká kaple. Z nádvoří i okolních vyhlídek se otevírá dechberoucí pohled do hlubokého údolí. Zámek je ideálním startem trasy Vranovskem a Podyjím.', 48.89257, 15.81085, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji%20Castle%20CZ%20873.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji%20Castle%20CZ%20873.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/POhledy%20na%20z%C3%A1mek%20Vranov%20nad%20Dyj%C3%AD%20z%20okoln%C3%ADch%20kopc%C5%AF%2005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyj%C3%AD%20(Frain)%20-%20panorama.JPG"}'::text[], 0),
    (v_route, 'Vranovská přehrada', 'Rozlehlá vodní nádrž na řece Dyji je oblíbeným rekreačním rájem a jednou z nejčistších přehrad v Česku. Klikatí se mezi zalesněnými svahy v délce téměř třiceti kilometrů a nabízí koupání, lodní dopravu i nádherné výhledy z okolních serpentin. Betonová hráz z 30. let 20. století patří k technicky pozoruhodným stavbám. Silnice kolem přehrady je jedním z nejzábavnějších úseků celé trasy.', 48.90982, 15.81181, 'https://commons.wikimedia.org/wiki/Special:FilePath/GuentherZ%201995%20IMG0028%20Vranov%20nad%20Dyji%20TalsperreIMG.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GuentherZ%201995%20IMG0028%20Vranov%20nad%20Dyji%20TalsperreIMG.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03(js).jpg"}'::text[], 1),
    (v_route, 'Hrad Bítov', 'Jeden z nejstarších a nejlépe dochovaných hradů na Moravě stojí na ostrožně nad Vranovskou přehradou. Původně přemyslovský strážní hrad byl později přebudován v romantické sídlo s bohatými sbírkami. Bítov je proslulý unikátní kolekcí vycpaných psů a expozicí zbraní. Okolní lesy a výhledy na hladinu přehrady dotvářejí kouzelnou atmosféru místa.', 48.944, 15.701, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20bitov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20bitov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20B%C3%ADtov%2C%20br%C3%A1na.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%ADtov%2C%20okres%20Znojmo%2C%20015.JPG"}'::text[], 2),
    (v_route, 'Zřícenina Cornštejn', 'Působivé zbytky gotického hradu se tyčí na skalnatém ostrohu nad zátokou Vranovské přehrady. Cornštejn kdysi střežil přístup k Bítovu a proslul mohutným opevněním, jehož torza dodnes budí respekt. Z hradních zdí a vyhlídek je jeden z nejkrásnějších pohledů na modrou hladinu pod skalami. Klidné místo obklopené lesy je odměnou za krátký výstup od parkoviště.', 48.929, 15.721, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20resevoir%20from%20Corn%C5%A1tejn%20viewpoint%2C%20B%C3%ADtov%2C%20Znojmo%20District.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20resevoir%20from%20Corn%C5%A1tejn%20viewpoint%2C%20B%C3%ADtov%2C%20Znojmo%20District.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/East%20view%20from%20bridge%20near%20Corn%C5%A1tejn%20of%20Vranov%20resevoir%2C%20B%C3%ADtov%2C%20Znojmo%20District%2002.JPG"}'::text[], 3),
    (v_route, 'Restaurace: U Vodnáře (Vranov nad Dyjí)', 'Rodinná restaurace a pizzerie leží přímo na břehu Vranovské přehrady s venkovním posezením u vody a výhledem na hladinu. Je hodnocena kolem 4,4 hvězdy a proslula pizzou z pece na dřevo i regionálními specialitami. Klidné místo zhruba v polovině první části trasy je ideální na oběd s výhledem.', 48.90989, 15.82118, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03(js).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03(js).jpg"}'::text[], 4),
    (v_route, 'NP Podyjí – Sealsfieldův kámen', 'Skalní vyhlídka nad kaňonem Dyje patří k nejkrásnějším místům Národního parku Podyjí. Ze dřevěného altánu se otevírá strhující pohled na meandrující řeku hluboko dole a zalesněné svahy chráněného území. Místo je pojmenováno po spisovateli Charlesi Sealsfieldovi, rodákovi z nedalekých Popic. K vyhlídce vede pěší stezka, motorku necháte v Popicích a dojdete pěšky.', 48.853, 16.059, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podyj%C3%AD%2C%20Sealsfield%C5%AFv%20k%C3%A1men%20-%20vyhl%C3%ADdka%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podyj%C3%AD%2C%20Sealsfield%C5%AFv%20k%C3%A1men%20-%20vyhl%C3%ADdka%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Podyj%C3%AD%2C%20Sealsfield%C5%AFv%20k%C3%A1men%20(01).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vyhl%C3%ADdkov%C3%A1%20sk%C3%A1la%20Sealsfield%C5%AFv%20k%C3%A1men.JPG"}'::text[], 5),
    (v_route, 'Hardegg', 'Nejmenší rakouské město leží idylicky v údolí Thaya (Dyje) přímo na hranici s Českem. I přes svůj městský status má jen několik desítek obyvatel a nad domky se tyčí romantický hrad Burg Hardegg. Přes řeku vede lávka spojující rakouský a český břeh a národní parky Thayatal a Podyjí. Malebné historické centrum je příjemnou zastávkou na rakouské straně údolí.', 48.85, 15.87, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thayatal%2CHardegg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Thayatal%2CHardegg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zentrum-Hardegg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stadthardegg.jpg"}'::text[], 6),
    (v_route, 'Znojmo – rotunda svaté Kateřiny', 'Národní kulturní památka rotunda svaté Kateřiny stojí v areálu bývalého přemyslovského hradu ve Znojmě. Proslula unikátními románskými nástěnnými malbami z roku 1134, které zachycují přemyslovskou dynastii. Malá kruhová stavba je jedním z nejcennějších klenotů středověkého umění v Česku. Nachází se v historickém jádru města nad soutokem Dyje.', 48.85541, 16.04352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20(Znaim)%20-%20Rotunda%20svat%C3%A9%20Kate%C5%99iny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20(Znaim)%20-%20Rotunda%20svat%C3%A9%20Kate%C5%99iny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20Rotunda%2020190217.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo-rotunda-svKate%C5%99iny2009d.jpg"}'::text[], 7),
    (v_route, 'Znojemské podzemí', 'Rozsáhlý labyrint chodeb a sklepů pod historickým jádrem Znojma vznikl na přelomu 13. a 14. století. Původně sloužil jako skladovací sklepy měšťanských domů, v dobách válek se sem obyvatelé ukrývali před nájezdy. Prohlídkové trasy vedou několika patry tajemných chodeb v hloubce až osmi metrů. Vstup se nachází na Slepičím trhu v centru města.', 48.8557, 16.0487, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo-The%20Underground%20Passages%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo-The%20Underground%20Passages%201.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Bistrograf (Znojmo)', 'Stylová restaurace v přízemí secesní budovy kina Svět v centru Znojma nabízí celodenní menu a kvalitní kávu. S hodnocením kolem 4,7 hvězdy patří k nejoblíbenějším podnikům ve městě a hosté chválí steaky, poctivou kuchyni i příjemnou atmosféru. Je vhodnou zastávkou v cíli druhého dne trasy.', 48.8544, 16.0492, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kino%20Sv%C4%9Bt%2C%20Znojmo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kino%20Sv%C4%9Bt%2C%20Znojmo.JPG"}'::text[], 9),
    (v_route, 'Šatov', 'Vinařská obec u rakouských hranic je proslulá unikátním Malovaným sklepem, jehož stěny zdobí barevné reliéfy vytvořené místním rodákem Maxmiliánem Appeltauerem. V okolí se nachází i síť sklepních uliček a pěchotní srub MJ-S 3 Zahrada z předválečného opevnění. Šatov je ideálním místem na ochutnávku znojemských vín na závěr cesty. Obklopují ho vinice v teplém podnebí Podyjí.', 48.796, 16.01, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov%2C%20Malovan%C3%BD%20sklep.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov%2C%20Malovan%C3%BD%20sklep.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/MJ-S%203%20Zahrada%20(by%20Pudelek).JPG"}'::text[], 10);
  insert into public.routes
