  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Plzeň – Pivovar Plzeňský Prazdroj', 'Světoznámý pivovar, kde se od roku 1842 vaří ležák Pilsner Urquell, je ideálním startem okruhu. Prohlídka vás provede historickými i moderními varnami a devět kilometrů dlouhým labyrintem ručně tesaných sklepů, kde ochutnáte nefiltrované pivo přímo z ležáckých tanků. Symbolem areálu je secesní Jubilejní brána z roku 1892.', 49.74675, 13.38758, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88sk%C3%BD%20Prazdroj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88sk%C3%BD%20Prazdroj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88sk%C3%BD%20Prazdroj%202.jpg"}'::text[], 0),
    (v_route, 'Plzeň – Katedrála sv. Bartoloměje', 'Gotická katedrála z konce 13. století dominuje náměstí Republiky a její věž je se 102,6 metry nejvyšší kostelní věží v Česku. Po zdolání 301 schodů se otevře jedinečný výhled na město i okolní kraj. Uvnitř najdete cennou Plzeňskou madonu z konce 14. století.', 49.74745, 13.37761, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88%20Cathedral%20of%20Saint%20Bartholomew-0146%20crop.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88%20Cathedral%20of%20Saint%20Bartholomew-0146%20crop.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20St%20Bartholomew%20Plzen%20113.JPG"}'::text[], 1),
    (v_route, 'Vodní hrad Švihov', 'Dokonale zachovalý pozdně gotický vodní hrad na řece Úhlavě patří k nejkrásnějším v Česku. Postavil ho Půta Švihovský z Rýzmberka a na opevnění se podílel i slavný stavitel Benedikt Rejt. Hrad proslul jako filmová kulisa pohádky Tři oříšky pro Popelku a dodnes jej obklopuje vodní příkop.', 49.4832, 13.2818, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20Hrad%20%C5%A0vihov%20-%20Water%20Castle%20Svihov%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20Hrad%20%C5%A0vihov%20-%20Water%20Castle%20Svihov%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Hrad Rabí', 'Zřícenina hradu Rabí na skalním ostrohu nad řekou Otavou je s rozlohou zhruba jednoho hektaru největší hradní zříceninou v Čechách. Mohutné opevnění a dělostřelecké bašty dvakrát obléhal husitský vojevůdce Jan Žižka, který zde podle pověsti přišel o druhé oko. Z válcové věže je nádherný rozhled na Šumavské podhůří.', 49.27997, 13.619, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Rab%C3%AD%20Castle%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Rab%C3%AD%20Castle%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Rab%C3%AD%20Castle%20(2).JPG"}'::text[], 3),
    (v_route, 'Domažlice – náměstí Míru a Chodský hrad', 'Historické centrum Domažlic, hlavního města Chodska, tvoří dlouhé podloubím lemované náměstí Míru s šikmou věží kostela a Dolejší bránou. Na západním konci stojí Chodský hrad založený Přemyslem Otakarem II., v němž dnes sídlí Muzeum Chodska. Město je proslulé chodskými kroji, keramikou a slavnostmi u příležitosti Chodských slavností.', 49.44054, 12.92649, 'https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20a%20Dolej%C5%A1%C3%AD%20br%C3%A1na%20(8856).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20a%20Dolej%C5%A1%C3%AD%20br%C3%A1na%20(8856).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Městský pivovar Domažlice (Domažlice)', 'Oblíbená restaurace u obnoveného městského pivovaru nabízí čerstvé pivo přímo z tanků a poctivou českou i chodskou kuchyni. Ochutnáte zvěřinové speciality, steaky a domácí klobásy a v létě posedíte na terase. Ideální zastávka na oběd v polovině okruhu, jen pár kroků od Chodského hradu.', 49.44199, 12.92722, 'https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20Komensk%C3%A9ho%2011,%20m%C4%9Bstsk%C3%BD%20pivovar%20(9326).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Doma%C5%BElice,%20Komensk%C3%A9ho%2011,%20m%C4%9Bstsk%C3%BD%20pivovar%20(9326).jpg"}'::text[], 5),
    (v_route, 'Hrad Přimda – nejstarší hrad v Česku', 'Na temeni 848 metrů vysokého vrchu v severozápadní části Českého lesa se tyčí zřícenina Přimdy, nejstaršího kamenného hradu v Česku. První zmínka o něm pochází z Kosmovy kroniky k roku 1121 a Přemyslovci ho střežili jako pevnost i vězení na hranici s Bavorskem. Ze zachovalé románské obytné věže je působivý výhled do kraje.', 49.67783, 12.67206, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Primda%20Gesamtansicht.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Primda%20Gesamtansicht.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Primda%201.%20OG%20Nordwand.jpg"}'::text[], 6),
    (v_route, 'Čerchov – Kurzova rozhledna (Klenčí pod Čerchovem)', 'Čerchov je se 1042 metry nejvyšší horou Českého lesa a stojí na něm kamenná Kurzova rozhledna z let 1904–1905. Z vyhlídkové plošiny ve výšce 16 metrů se otevírá kruhový výhled na Šumavu i bavorské pohraničí. Výchozím bodem pro pěší i cyklisty je nedaleký městys Klenčí pod Čerchovem, rodiště spisovatele Jindřicha Šimona Baara.', 49.38134, 12.78246, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerchov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerchov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cerchov%20czech%20republic%20may%202006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kurzova%20rozhledna.jpg"}'::text[], 7),
    (v_route, 'Rozhledna Koráb (Kdyně)', 'Ocelová rozhledna Koráb stojí na stejnojmenném vrchu (775 m) v Chudenické vrchovině nad městem Kdyně. Zastřešená vyhlídková plošina je ve výšce 29 metrů a nabízí rozhled na Chodsko, Šumavu i Český les. U rozhledny je turistická chata s občerstvením, ideální na odpočinek při zpáteční cestě.', 49.39547, 13.0753, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kdyn%C4%9B%20-%20rozhledna%20Kor%C3%A1b,%20schodi%C5%A1t%C4%9B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kdyn%C4%9B%20-%20rozhledna%20Kor%C3%A1b,%20schodi%C5%A1t%C4%9B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kdyn%C4%9B%20-%20rozhledna%20Kor%C3%A1b,%20vstup%20obr01.jpg"}'::text[], 8),
    (v_route, 'Klatovy – Černá věž a katakomby', 'Pozdně gotická Černá věž z 16. století se tyčí do výšky 81,6 metru na náměstí Míru vedle renesanční radnice a je vyhlídkovým i zvonovým skvostem Klatov. Z ochozu je za jasného počasí vidět Šumava i hřebeny Českého lesa. Pod nedalekým jezuitským kostelem se nachází proslulé klatovské katakomby s mumifikovanými ostatky.', 49.39722, 13.28694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez%20Klatovy%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez%20Klatovy%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez%20Klatovy%2002.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Pilsner Urquell Original Restaurant Střelnice (Klatovy)', 'Stylová pivnice a restaurace z 19. století v centru Klatov láká na poctivou českou kuchyni a tankový Pilsner Urquell. Interiér zdobí historické předměty z pivovarského oboru a v létě si posedíte na terase v historickém jádru města. Skvělá poslední zastávka před návratem do Plzně.', 49.39723, 13.29443, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klatovy%20namesti.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klatovy%20namesti.JPG"}'::text[], 10);
