  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vrátna dolina (Terchová)', 'Vrátna dolina je nejznámější údolí Malé Fatry a přírodní srdce Terchovska, obklopené strmými vrcholy Krivánské Fatry. Serpentiny vedoucí od Terchové sem patří k nejkrásnějším motorkářským úsekům regionu. Nahoře čeká kabinková lanovka na Snilovské sedlo a bezpočet turistických tras. Údolí je vstupní branou k soutěskám i k vrcholům Rozsutců.', 49.2086, 19.0396, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Such%C3%A1%20dolina%20-%20valley%20in%20Mal%C3%A1%20Fatra%2001.jpg"}'::text[], 0),
    (v_route, 'Jánošíkove diery', 'Jánošíkove diery jsou soustava divokých soutěsek, vodopádů a kaskád v Krivánské Malé Fatře nad osadou Biely Potok. Systém Dolných, Nových a Horných dier se prochází po lávkách, žebřících a řetězech přímo v korytě potoka. Je to jedna z nejnavštěvovanějších turistických atrakcí Slovenska. Motorku necháte na parkovišti u Hotelu Diery a dál pokračujete pěšky.', 49.2534, 19.0727, 'https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Doln%C3%A9%20diery%20-%20vodop%C3%A1d.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio%20(6).jpg"}'::text[], 1),
    (v_route, 'Rozhľadňa / socha Jánošík (Terchová)', 'Nad Terchovou se tyčí monumentální nerezová socha zbojníka Juraje Jánošíka, vysoká 7,5 metru. Vytvořil ji akademický sochař Ján Kulich a odhalena byla v roce 1988 k 300. výročí Jánošíkova narození. Od sochy je nádherný výhled do Vrátné doliny a na hřebeny Malé Fatry. Je to symbolické místo celého Terchovska a oblíbený fotostop.', 49.2543, 19.0378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Terchov%C3%A1%20-%20Socha%20J%C3%A1no%C5%A1%C3%ADka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Terchov%C3%A1%20-%20Socha%20J%C3%A1no%C5%A1%C3%ADka.jpg"}'::text[], 2),
    (v_route, 'Malý Rozsutec', 'Malý Rozsutec (1344 m) je výrazný skalnatý vrchol v Krivánské části Malé Fatry, ležící asi 5 km východně od Terchové. Spolu s vyšším Veľkým Rozsutcem tvoří jednu z nejfotogeničtějších dvojic slovenských hor. Výstup vede přes Jánošíkove diery a nabízí strmé závěry se zajištěnými pasážemi. Z vrcholu je kruhový rozhled na celou Vrátnu dolinu.', 49.217, 19.0972, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1rodn%C3%AD%20park%20Mal%C3%A1%20Fatra,%20NPR%20Rozsutec%20-%20Mal%C3%BD%20Rozsutec.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1rodn%C3%AD%20park%20Mal%C3%A1%20Fatra,%20NPR%20Rozsutec%20-%20Mal%C3%BD%20Rozsutec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mal%C3%A1%20Fatra,%20hiking%20to%20Ve%C4%BEk%C3%BD%20Rozsutec%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Koliba Starý dvor Vrátna (Terchová)', 'Tradiční koliba v srdci Vrátné doliny nabízí poctivou slovenskou kuchyni v dřevěném salaši s ohništěm. Hodnocení hostů se drží vysoko nad 4,4 hvězdy a chválena jsou zejména halušky a grilované speciality. Ideální zastávka po túře do dolní části Malé Fatry. Prostředí pod horami dokresluje pravou terchovskou atmosféru.', 49.2033, 19.0539, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stefanova%20mala%20fatra.jpg"}'::text[], 4),
    (v_route, 'Hrad Strečno', 'Gotický hrad Strečno se tyčí na vápencové skále vysoko nad ohybem Váhu, asi 16 km východně od Žiliny. Kdysi střežil obchodní stezku a výběr mýta, dnes je zrekonstruovaným muzeem s expozicemi a vyhlídkou na řeku a Malou Fatru. Pod hradem se nachází i historický vojenský památník. Přístupová silnica podél Váhu je sama o sobě krásným motorkářským úsekem.', 49.17694, 18.86278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stre%C4%8Dno%20castle%20Slovakia%20Frontlook.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stre%C4%8Dno%20castle%20Slovakia%20Frontlook.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Old%20Stre%C4%8Dno%20Castle%20Slovakia.jpg"}'::text[], 5),
    (v_route, 'Čičmany (maľované domy)', 'Čičmany jsou proslulá horská obec s dřevěnými sruby zdobenými bílými geometrickými vzory malovanými přímo na tmavé dřevo. Tato jedinečná lidová architektura patří k nejfotografovanějším místům Slovenska a inspirovala i moderní design. V obci najdete muzeum a několik původních chalup pod památkovou ochranou. Cesta sem přes Rajeckou dolinu je klidná a scénická.', 48.95, 18.51667, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Ci%C4%8Dmany%20(Csicsm%C3%A1ny,%20Zimmermannshau)%20-%20old%20house.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Ci%C4%8Dmany%20(Csicsm%C3%A1ny,%20Zimmermannshau)%20-%20old%20house.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Ci%C4%8Dmany%20(Csicsm%C3%A1ny,%20Zimmermannshau)%20-%20old%20house%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Ci%C4%8Dmany,%20m%C3%BAzeum%20Na%20dreve%20ma%C4%BEovan%C3%A9.jpg"}'::text[], 6),
    (v_route, 'Súľovské skaly', 'Súľovské skaly jsou národní přírodní rezervace s bizarními skalními věžemi, branami a okny vytvořenými erozí slepenců. Nachází se v Súľovských vrších nedaleko Žiliny a jsou rájem pro turisty i horolezce. Naučný chodník vede kolem Gotické brány a zřícenin Súľovského hradu. Skalní město nabízí strhující výhledy do Súľovské kotliny.', 49.165, 18.595, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1u%C4%8Dn%C3%BD%20chodn%C3%ADk%20S%C3%BA%C4%BEovsk%C3%A9%20skaly%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1u%C4%8Dn%C3%BD%20chodn%C3%ADk%20S%C3%BA%C4%BEovsk%C3%A9%20skaly%20-%20panoramio.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Terchovská Koliba Diery (Terchová)', 'Terchovská Koliba Diery patří k nejlépe hodnoceným restauracím v Terchové s hodnocením přes 4,4 hvězdy a leží přímo u vstupu do Jánošíkových dier. Nabízí poctivou domácí kuchyni, čerstvé suroviny, kvalitní slovenská vína i pivo z místního minipivovaru. Interiér s velkým krbem vytváří útulnou horskou atmosféru. Je to ideální zastávka před túrou do soutěsek nebo po ní.', 49.2512, 19.0692, 'https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Janosikove%20diery,%20Mala%20Fatra%20(agost%202012)%20-%20panoramio.jpg"}'::text[], 8),
    (v_route, 'Žilina', 'Žilina je živé krajské město na soutoku Váhu a Kysuce, přirozená brána do Malé Fatry i Súľovských vrchů. Srdcem historického jádra je Mariánske námestie s podloubím a renesančními měšťanskými domy. Ve městě najdete Budatínský zámek i řadu kaváren a restaurací pro odpočinek. Je to praktické místo pro nocleh a doplnění paliva na okružní trase.', 49.22315, 18.73941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zilina%20SVK%20Square01.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zilina%20SVK%20Square01.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Main%20square%20of%20%C5%BDilina.JPG"}'::text[], 9);
  insert into public.routes
