  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Slavonice – renesanční sgrafitové náměstí', 'Slavonice na pomezí Čech, Moravy a Rakouska okouzlí dvěma náměstími lemovanými měšťanskými domy s podloubím a bohatou renesanční sgrafitovou výzdobou ze 16. století. Pro motorkáře je to ideální cíl k procházce historickým jádrem a pauze v některé z kaváren. Město je zároveň skvělou vstupní branou do malebné krajiny České Kanady.', 48.999, 15.351, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru,%20podzem%C3%AD%2001.jpg"}'::text[], 0),
    (v_route, 'Hrad Landštejn', 'Mohutná románsko-gotická zřícenina Landštejna se tyčí na skalnatém návrší nad lesy České Kanady a patří k nejlépe dochovaným románským pevnostem u nás. Z vyhlídkové věže se otevírá dechberoucí rozhled do širokého okolí až k rakouským hranicím. Přístupová silnička plná zatáček je pro motorkáře zážitkem sama o sobě.', 48.9878, 15.22902, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn-1.JPG"}'::text[], 1),
    (v_route, 'Rybník Osika / Staré Město pod Landštejnem', 'Staré Město pod Landštejnem leží v srdci České Kanady mezi Slavonicemi a Novou Bystřicí, obklopené lesy a rybníky. Nedaleký rybník Osika i další vodní plochy lákají v létě ke koupání a osvěžení po jízdě. Klidné silnice s minimálním provozem vedou zvlněnou krajinou plnou žulových balvanů a borových hájů.', 48.995, 15.19, 'https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem,%20z%C3%A1mek%20Dobroho%C5%99%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem,%20z%C3%A1mek%20Dobroho%C5%99%2001.JPG"}'::text[], 2),
    (v_route, 'Nová Bystřice – úzkokolejka', 'Nová Bystřice je koncovou stanicí historické úzkorozchodné dráhy z Jindřichova Hradce, otevřené již v roce 1897. U nádraží se dají obdivovat staré parní i motorové lokomotivy a nasát atmosféru romantické železnice. Okolní silnice České Kanady jsou úzké a lesnaté, jako stvořené pro klidnou vyjížďku.', 49.02, 15.104, 'https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jindrichuv%20Hradec%20depot%20JHMD.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Pivovar Nová Bystřice (Nová Bystřice)', 'Rodinný minipivovar s útulnou restaurací a prostornou terasou přímo v Nové Bystřici, zhruba v polovině trasy. Kuchyně sází na poctivá česká jídla a sezonní suroviny, k tomu čepují vlastní vynikající piva – hosté chválí zejména vepřové koleno. Podnik má skvělé hodnocení a je ideální zastávkou k obědu i osvěžení po jízdě Českou Kanadou.', 49.0175, 15.1035, 'https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG"}'::text[], 4),
    (v_route, 'Zámek Jindřichův Hradec', 'Rozlehlý zámecký komplex v Jindřichově Hradci patří k největším v Česku a vznikl přestavbou původního gotického hradu nad soutokem Nežárky a rybníka Vajgar. Nádvoří s renesančními arkádami a proslulá kruhová Rondel jsou skvostem jihočeské architektury. Historické centrum města nabízí motorkářům příjemné zázemí k delší přestávce.', 49.142, 15.003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jind%C5%99ich%C5%AFv.Hradec.z%C3%A1mek.rondel1.JPG"}'::text[], 5);
