  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chopok (Jasná)', 'Chopok je se svými 2024 m třetím nejvyšším vrcholem Nízkých Tater a jedním z nejnavštěvovanějších míst pohoří. Na vrchol se pohodlně dostanete lanovkou ze střediska Jasná v Demänovské dolině a odměnou je kruhový výhled na hlavní hřeben s Ďumbierem. Poblíž vrcholu stojí známá Kamenná chata, kde se dá občerstvit. Okolní serpentiny a horské silnice patří k nejkrásnějším úsekům celé trasy.', 48.9433, 19.5911, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzk%C3%A9%20Tatry,%20Chopok%20(7).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzk%C3%A9%20Tatry,%20Chopok%20(7).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%ADzk%C3%A9%20Tatry,%20Chopok,%20chata%20a%20vrchol%20(5).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Chopok%20and%20Kamenn%C3%A1%20chata.JPG"}'::text[], 0),
    (v_route, 'Demänovská jaskyňa slobody', 'Demänovská jeskyně Svobody je nejnavštěvovanější jeskyní na Slovensku a klenot Demänovské doliny. Uchvátí bohatou krápníkovou výzdobou, barevnými sintrovými útvary a smaragdovými jezírky podzemního toku Demänovky. Prohlídkové okruhy vedou zpřístupněnými sály plnými fantastických tvarů. Zastávka je ideálním doplňkem k horskému programu na Chopku.', 48.99806, 19.58306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Demanova%20Cave%20of%20Freedom%2024.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Demanova%20Cave%20of%20Freedom%2024.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Demenovska%20jaskyna%20slobody-smaragdove%20jazierko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dem%C3%A4novsk%C3%A1%20jasky%C5%88a%20slobody%20-%20Slovakia.jpg"}'::text[], 1),
    (v_route, 'Demänovská ľadová jaskyňa', 'Demänovská ledová jeskyně patří k nejstarším známým a nejnavštěvovanějším jeskyním střední Evropy. Její kouzlo tkví v trvalé ledové výzdobě – zamrzlých vodopádech, ledových stěnách a podlahách, které se drží po celý rok. Jeskyně leží jen kousek od jeskyně Svobody ve stejné dolině. Chladné podzemí je vítaným osvěžením v horkém letním dni.', 49.01625, 19.58278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Demanovska%20ladova%20jaskyna%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Demanovska%20ladova%20jaskyna%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Demanova%20Ice%20Cave%2023.jpg"}'::text[], 2),
    (v_route, 'Vlkolínec (UNESCO)', 'Vlkolínec je dokonale zachovalá horská dědina zapsaná od roku 1993 na seznamu světového dědictví UNESCO. Tvoří ji přes čtyřicet původních srubových domů s roubenými štíty, dřevěnou zvonicí a kamennou studnou, zasazených pod vrchem Sidorovo. Působí jako živý skanzen lidové architektury Liptova. Úzká přístupová silnice od Ružomberku patří k romantickým úsekům trasy.', 49.03927, 19.2773, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vlkolinec%20Dom%209012.JPG"}'::text[], 3),
    (v_route, 'Liptovská Mara', 'Liptovská Mara je největší vodní nádrž na Slovensku a výrazná dominanta Liptova na řece Váh. Rozlehlá vodní hladina s panoramatem Tater v pozadí láká k projížďkám, koupání i vodním sportům. Z hladiny vystupuje kostelík v Havránku, připomínající zatopené obce. Silnice podél břehů nabízejí krásné výhledy na vodu i hory.', 49.09861, 19.48889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Liptovska%20Mara%20od%20pol.%20Ratkovie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Liptovska%20Mara%20od%20pol.%20Ratkovie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Liptovska%20Mara%20s%20kostolikom.JPG"}'::text[], 4),
    (v_route, 'Ružomberok', 'Ružomberok je historické centrum Liptova rozložené v údolí soutoku Váhu a Revúcy. Nabízí příjemné náměstí, kalvárii nad městem a pohodlné zázemí pro doplnění sil i přenocování. Je přirozenou branou k UNESCO dědině Vlkolínec i lanovce na Malinô Brdo. Město tvoří praktickou křižovatku obou dní této cesty.', 49.0769, 19.3084, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ru%C5%BEomberok,%20centrum.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ru%C5%BEomberok,%20centrum.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ru%C5%BEomberok.Bahnhof.JPG"}'::text[], 5),
    (v_route, 'Bystrá / Tále', 'Tále jsou rekreační a lyžařské středisko na jižním úpatí Nízkých Tater v malebné Bystré dolině. Rozlehlé louky obklopené vrcholy Dereše, Chopku a Ďumbieru dávají místu horský ráz. Nachází se zde známé golfové hřiště Gray Bear i výchozí body na hřebeny. Silnice Bystrou dolinou je klidná a scénická alternativa k rušným tahům.', 48.83, 19.58, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tatry%20Dolina%20Bystrej%20dron%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tatry%20Dolina%20Bystrej%20dron%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bystra%20dolina%20zo%20Srdiecka.JPG"}'::text[], 6),
    (v_route, 'Špania Dolina', 'Špania Dolina je půvabná hornická obec ukrytá v horách nad Banskou Bystricí s bohatou tradicí těžby mědi. Dominuje jí gotický kostel Proměnění Páně s renesančním portálem a zachovalé baníky domky s dřevěnými štíty. Nad obcí se tyčí Turecká bašta a staré haldy připomínají slávu zdejšího hornictví. Poslední zastávka trasy nabízí klid a autentickou atmosféru starého horního města.', 48.80747, 19.13401, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spania%20Dolina%202007%2011.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spania%20Dolina%202007%2011.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/SpaniaDolinaKostol.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0pania%20Dolina%20-%20Tureck%C3%A1%20ba%C5%A1ta.JPG"}'::text[], 7),
    (v_route, 'Restaurace: Slovenská Koliba Jasná (Demänovská Dolina)', 'Slovenská Koliba Jasná je rodinná reštaurácia v Demänovské dolině, dlouhodobě hodnocená jako jedna z nejlepších v okolí (přes 4,6). Ve stylovém kolibovém prostředí se podávají tradiční slovenské speciality jako bryndzové halušky, pirohy a grilované maso. Ideální zastávka po jízdě na Chopok a návštěvě jeskyní na konci prvního dne.', 48.972, 19.585, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jasn%C3%A1%20-%20Chopok,%20N%C3%ADzk%C3%A9%20Tatry-01.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jasn%C3%A1%20-%20Chopok,%20N%C3%ADzk%C3%A9%20Tatry-01.JPG"}'::text[], 8),
    (v_route, 'Restaurace: Koliba pod Vlkolíncom (Ružomberok)', 'Koliba pod Vlkolíncom se nachází v Bielom Potoku u Ružomberku, přímo pod UNESCO dědinou Vlkolínec, a má hodnocení kolem 4,5. Nabízí tradiční slovensko-liptovskou kuchyni v útulném kolibovém prostředí s letní terasou a výhledem do hor. Je vhodnou zastávkou na oběd druhého dne cesty nedaleko poloviny trasy.', 49.053, 19.294, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vlkol%C3%ADnec,%20v%20pozad%C3%AD%20Sidorovo.JPG"}'::text[], 9);
