  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Oravský hrad (Oravský Podzámok)', 'Oravský hrad se tyčí na strmé vápencové skále vysoko nad řekou Oravou a patří k nejkrásnějším hradům na Slovensku. Původně gotická pevnost ze 13. století byla postupně přestavěna do dnešní impozantní podoby, kdy jednotlivé paláce vystupují ve třech výškových úrovních přímo ze skalního masivu. Dnes v hradě sídlí Oravské múzeum s bohatými přírodovědnými i historickými expozicemi. Filmoví fanoušci ho znají jako kulisu němého hororu Upír Nosferatu z roku 1922.', 49.26185, 19.35854, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orava%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orava%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oravsk%C3%BD%20hrad%20-%20Oravsk%C3%BD%20Podz%C3%A1mok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slovakia-01893%20-%20Orava%20Castle%20(31909660610).jpg"}'::text[], 0),
    (v_route, 'Oravská priehrada', 'Oravská priehrada je rozlohou i objemem vody největší přehradní nádrž na Slovensku, přezdívaná také Oravské moře. Vodní plocha o rozloze zhruba 35 km² vznikla v 50. letech 20. století a zatopila několik oravských vesnic. Dnes je oblíbeným rekreačním cílem s plážemi, přístavišti a výhledy na okolní hory. Za klidného počasí se v hladině zrcadlí štíty Roháčů i vzdálených Tater.', 49.4, 19.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oravska%20priehrada.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oravska%20priehrada.JPG"}'::text[], 1),
    (v_route, 'Slanický ostrov umenia', 'Slanický ostrov umenia je malý ostrůvek uprostřed Oravské priehrady – poslední pozůstatek zatopené obce Slanica. Dominantou ostrova je barokní kostel Povýšení svatého kříže, v němž je dnes stálá expozice lidového umění a oravského kamenosochařství ze sbírek Oravské galérie. Na ostrov se v sezoně dostanete lodí z přístaviště u Slanické Osady. Návštěva připomíná osudy vesnic, které kvůli stavbě přehrady navždy zmizely pod hladinou.', 49.40673, 19.51618, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slanick%C3%BD%20ostrov%20umenia,%20Oravsk%C3%A1%20priehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slanick%C3%BD%20ostrov%20umenia,%20Oravsk%C3%A1%20priehrada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostol%20Pov%C3%BD%C5%A1enia%20Sv%C3%A4t%C3%A9ho%20kr%C3%AD%C5%BEa,%20Slanick%C3%BD%20ostrov%206.jpg"}'::text[], 2),
    (v_route, 'Trstená', 'Trstená je půvabné historické město na horní Oravě, které si dodnes zachovalo klidný ráz podhorského městečka. Dominantou náměstí M. R. Štefánika je farní kostel svatého Martina obklopený měšťanskými domy. Město je vhodnou zastávkou na cestě mezi přehradou a Roháči, kde si odpočinete a doplníte síly. Okolní krajina horní Oravy nabízí typické dřevěné stavby a výhledy na blízké hory.', 49.36085, 19.61061, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trsten%C3%A11.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trsten%C3%A11.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Koliba pod Roháčmi (Zuberec)', 'Koliba pod Roháčmi je tradiční horská koliba na začátku Roháčů, jen kousek od skanzenu Brestová a asi 3 km za Zubercem. Podává se zde poctivá oravská kuchyně – bryndzové halušky, pirohy a čerstvý pstruh – v příjemném dřevěném interiéru. S hodnocením kolem 4,7 na Restaurant Guru patří k oblíbeným zastávkám motorkářů i turistů. Ideální místo na oběd zhruba v polovině trasy před výjezdem na Zverovku.', 49.2661, 19.638, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20oravskej%20dediny%2C%20Zuberec-Brestova%20(15).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20oravskej%20dediny%2C%20Zuberec-Brestova%20(15).jpg"}'::text[], 4),
    (v_route, 'Zuberec (skanzen Brestová)', 'Múzeum oravskej dediny na Brestové u Zuberce je jedním z nejkrásnějších slovenských skanzenů, zasazený do podhůří Západních Tater. Na rozlehlé louce jsou přeneseny původní dřevěné oravské domy, hospodářské stavby i gotický kostelík, které přibližují život na Oravě v minulých staletích. Areál je oblíbený i pro folklorní slavnosti a řemeslné dílny. Skanzen je zároveň výchozím bodem k dalšímu stoupání do Roháčské doliny.', 49.26591, 19.66297, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20oravskej%20dediny%20Zuberec%20-%20Brestov%C3%A1%20(10).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20oravskej%20dediny%20Zuberec%20-%20Brestov%C3%A1%20(10).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20oravskej%20dediny%20Zuberec%20-%20Brestov%C3%A1%20(8).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20oravskej%20dediny%2C%20Zuberec-Brestova%20(09).jpg"}'::text[], 5),
    (v_route, 'Roháče / Zverovka (Ťatliakovo pleso)', 'Zverovka je horské sedlo a rozcestí na začátku Roháčské doliny, odkud vedou nejkrásnější túry Západních Tater. Od parkoviště se dá pěšky vystoupat k Ťatliakovu plesu, malebnému horskému jezírku pod mohutnými roháčskými štíty. Okolní hřebeny, vodopády a plesa patří k nejdivočejší přírodě na Slovensku. Pro motorkáře je Zverovka koncovým bodem asfaltové silnice a ideálním místem k odpočinku uprostřed hor.', 49.2291, 19.7126, 'https://commons.wikimedia.org/wiki/Special:FilePath/Roh%C3%A1%C4%8De,%20pleso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Roh%C3%A1%C4%8De,%20pleso.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pri%20Taliakovom%20plese%20-%20panoramio.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Reštaurácia Marína (Dolný Kubín)', 'Reštaurácia Marína se nachází přímo na Hviezdoslavově náměstí v srdci Dolného Kubína a už od roku 1990 udává v regionu vysokou gastronomickou úroveň. Podává kvalitní slovenskou i mezinárodní kuchyni a patří dlouhodobě k nejlépe hodnoceným podnikům na Oravě. Je vhodnou zastávkou při návratu z hor druhý den trasy. Klidné prostředí historického náměstí ocení každý unavený motorkář.', 49.20983, 19.30341, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20Kubin%20Hviezdoslavovo%20nam%202-1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20Kubin%20Hviezdoslavovo%20nam%202-1.JPG"}'::text[], 7),
    (v_route, 'Dolný Kubín', 'Dolný Kubín je přirozeným centrem Oravy a rodištěm mnoha slovenských literátů, mimo jiné básníka P. O. Hviezdoslava. Historické Hviezdoslavovo náměstí lemují měšťanské domy, radnice a kostel Povýšení svatého kříže. Ve městě sídlí Oravská galéria i Čaplovičova knihovna s cennými historickými tisky. Je příjemným místem k procházce a doplnění sil při návratu z hor.', 49.20983, 19.30341, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20kubin%20town%20center.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20kubin%20town%20center.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dolny%20Kubin%20Hviezdoslavovo%20nam%202-1.JPG"}'::text[], 8),
    (v_route, 'Kvačianska dolina', 'Kvačianska dolina je hluboká kaňonovitá roklina vyhloubená potokem Kvačianka mezi vápencovými a dolomitovými skalami Chočských vrchů. Naučným chodníkem projdete kolem vodopádů, skalních věží a historických vodních mlýnů Oblazy, které jsou dodnes funkční. Divoká a málo dotčená příroda z ní dělá jednu z nejkrásnějších dolin Liptova a Oravy. Klidná procházka je ideálním zakončením dvoudenní jízdy.', 49.19063, 19.54196, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kvacianska%20dolina%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kvacianska%20dolina%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%A9%20mlyny%20-%20Oblazy%20-%20Kva%C4%8Dianska%20dolina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mlyny%20oblazy,%20Kva%C4%8Dianska%20dolina.jpg"}'::text[], 9);
