  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Banská Štiavnica – Starý zámok', 'Starý zámok je opevněné jádro historické Banské Štiavnice, města zapsaného na seznamu UNESCO. Původní gotický kostel z 13. století byl v 16. století přebudován na protitureckou pevnost s baštami a hradbami. Dnes ukrývá muzeum s expozicemi báňské historie, zvonů i sakrálního umění. Z jeho věží se otevírá výhled na střechy starobylého horního města.', 48.45931, 18.89122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%BD%20z%C3%A1mok,%20Bansk%C3%A1%20%C5%A0tiavnica%20-%20hradn%C3%BD%20m%C3%BAr.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%BD%20z%C3%A1mok,%20Bansk%C3%A1%20%C5%A0tiavnica%20-%20hradn%C3%BD%20m%C3%BAr.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%BD%20z%C3%A1mok%20(Bansk%C3%A1%20%C5%A0tiavnica)-7.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1dvorie%20Star%C3%A9ho%20z%C3%A1mku.JPG"}'::text[], 0),
    (v_route, 'Banská Štiavnica – Nový zámok', 'Bílá renesanční věž Nového zámku vévodí panoramatu Banské Štiavnice z protějšího kopce. Byla vybudována v polovině 16. století jako strážní bod proti tureckým nájezdům a strážci z ní hlídali okolní údolí. Dnes zde sídlí muzeum věnované protitureckým bojům. Odtud je jeden z nejkrásnějších pohledů na město i na Kalvárii.', 48.45561, 18.896, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20from%20Nov%C3%BD%20z%C3%A1mok%202007.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20from%20Nov%C3%BD%20z%C3%A1mok%202007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20zhora.jpg"}'::text[], 1),
    (v_route, 'Kalvária Banská Štiavnica', 'Banskoštiavnická kalvária je považována za nejkrásnější barokní kalvárii na Slovensku. Byla vybudována roku 1751 na sopečném vrchu Scharffenberg z iniciativy jezuity Františka Pergera. Komplex tvoří tři kostely, kaple a zastavení křížové cesty stoupající po svahu. Z vrcholu se nabízí strhující výhled na Banskou Štiavnici a okolní kopce.', 48.4626, 18.908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalvaria%20Banska%20Stiavnica,%20Dolny%20kostol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kalvaria%20Banska%20Stiavnica,%20Dolny%20kostol.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20-%20Kalv%C3%A1ria%20-%20Sv%C3%A4t%C3%A9%20schody%20-%20m%C3%BAr.JPG"}'::text[], 2),
    (v_route, 'Kaštieľ Svätý Anton', 'Barokní kaštieľ ve Svätém Antone patří k nejvýznamnějším šlechtickým sídlům Slovenska. Rozlehlý zámek Coburgovců byl postaven v 18. století a je proslulý svým lesnickým a mysliveckým muzeem. Symbolika stavby odkazuje na kalendář – má 365 oken, 52 místností, 12 vchodů a 4 brány. Kolem se rozkládá anglický park s jezírky a starými stromy.', 48.4214, 18.94286, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1tie%C4%BE%20Sv%C3%A4t%C3%BD%20Anton%201%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1tie%C4%BE%20Sv%C3%A4t%C3%BD%20Anton%201%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1tie%C4%BE%20Sv%C3%A4t%C3%BD%20Anton%203%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Sitno – rozhľadňa', 'Sitno je s výškou 1009 metrů nejvyšším vrcholem Štiavnických vrchů a jeho andezitové skalní stěny mu dodávají mystickou atmosféru. Na vrcholu stojí kamenná rozhledna a zbytky středověkého hradu Sitno. Za jasného počasí je odtud vidět Nízké i Vysoké Tatry a značná část středního Slovenska. K vrcholu vedou turistické chodníky od Počúvadlianského jezera.', 48.40307, 18.87716, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhladna%20sitno.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhladna%20sitno.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zr%C3%BAcaniny%20hradu%20Sitno%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Sitno%20-%20panoramio.jpg"}'::text[], 4),
    (v_route, 'Tajch Počúvadlo', 'Počúvadlianske jazero je jedním z nejkrásnějších tajchů – umělých vodních nádrží, které vybudovali báňští odborníci pro pohon štiavnických dolů. Vodní hladina o rozloze zhruba 12 hektarů leží v objetí lesů pod masivem Sitna. Dnes je oblíbeným rekreačním střediskem pro koupání, rybaření i výchozím bodem túr. Kolem jezera je klidná atmosféra a nádherné zrcadlení okolních kopců.', 48.40953, 18.85678, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jazero%20Po%C4%8D%C3%BAvadlo%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jazero%20Po%C4%8D%C3%BAvadlo%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pocuvadlo%20-%20panoramio.jpg"}'::text[], 5),
    (v_route, 'Restaurace: 4Sochy Restaurant (Banská Štiavnica)', '4Sochy Restaurant patří k nejlépe hodnoceným podnikům v Banské Štiavnici (hodnocení kolem 4,6). Nachází se v historickém centru na Kammerhofské ulici a nabízí moderní gastropub kuchyni z lokálních surovin. Je to ideální zastávka zhruba v polovině okruhu na doplnění sil před další cestou. Příjemné prostředí a domácí atmosféra z něj dělají oblíbený cíl výletníků i motorkářů.', 48.45889, 18.8965, 'https://commons.wikimedia.org/wiki/Special:FilePath/969%2001%20Bansk%C3%A1%20%C5%A0tiavnica,%20Slovakia%20-%20panoramio%20(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/969%2001%20Bansk%C3%A1%20%C5%A0tiavnica,%20Slovakia%20-%20panoramio%20(4).jpg"}'::text[], 6),
    (v_route, 'Banská Bystrica – Námestie SNP', 'Náměstí SNP je tepajícím srdcem historické Banské Bystrice, lemované měšťanskými domy, kostely a barokní morovou soklou. Dominantou je šikmá Hodinová věž z roku 1552, která se odklání od osy o 68 centimetrů. Náměstí je centrem společenského dění a nabízí množství kaváren a obchodů. Odtud vede cesta k blízké rozhledně Vartovka.', 48.73529, 19.14511, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banska%20Bystrica%20SNP%20Square.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Banska%20Bystrica%20SNP%20Square.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20Bystrica%20-%20N%C3%A1m.%20SNP%205.JPG"}'::text[], 7),
    (v_route, 'Vartovka – rozhľadňa a hvezdáreň', 'Vartovka je bývalá protiturecká strážní věž na kopci jihovýchodně nad Banskou Bystricí. V 16. století sloužila jako varovný bod – z jejího názvu (vartovať = hlídat) je odvozeno i pojmenování. V roce 1956 byla přestavěna na hvězdárnu, která je dnes veřejnosti přístupná. Z okolí věže se otevírá pěkný výhled na město, Kremnické vrchy i Nízké Tatry.', 48.71789, 19.15364, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vartovka%20v%C4%9B%C5%BE.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vartovka%20v%C4%9B%C5%BE.JPG"}'::text[], 8);
