  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zádielska tiesňava', 'Zádielska tiesňava je najhlbšia roklina na Slovensku, ktorá vytvára úchvatný kaňon dlhý približne 2,2 km a hlboký miestami až 400 metrov. Vápencové steny sa na najužších miestach zbiehajú len na desať metrov a nad dnom sa týči nápadný skalný útvar Cukrová homoľa. Prechod tiesňavou popri potoku Blatnica patrí k najkrajším turistickým zážitkom v Slovenskom krase.', 48.6336, 20.82322, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zadiel%20canyon%20from%20north.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zadiel%20canyon%20from%20north.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cukrov%C3%A1%20homo%C4%BEa%20-%20%22sugary%20knoll%22%20-%20panoramio.jpg"}'::text[], 0),
    (v_route, 'Silická ľadnica', 'Silická ľadnica je najnižšie položená zaľadnená priepasť na svete, ktorá sa nachádza v strednej časti Silickej planiny asi dva kilometre západne od obce Silica. Ľad sa tu drží celoročne v nadmorskej výške len 503 metrov vďaka jedinečnej klimatickej inverzii vo vstupnej priepasti. Samotná jaskyňa nie je verejnosti prístupná, no jej mrazivý vstupný portál si možno prezrieť z upravenej vyhliadkovej terasy.', 48.5489, 20.5036, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silicka%20ladnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Silicka%20ladnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Silicka%20lednice%20led.jpg"}'::text[], 1),
    (v_route, 'jaskyňa Domica', 'Jaskyňa Domica je najväčšou jaskyňou Slovenského krasu a spolu s maďarskou Baradlou tvorí jeden podzemný systém dlhý takmer 25 kilometrov. Preslávili ju bohaté nálezy z obdobia neolitickej bukovohorskej kultúry, vďaka ktorým je významnou archeologickou lokalitou. Súčasťou prehliadky je za priaznivého vodného stavu aj romantická plavba na člnoch po podzemnej riečke Styx.', 48.4778, 20.4703, 'https://commons.wikimedia.org/wiki/Special:FilePath/Domica%20Cave%2022.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Domica%20Cave%2022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Domica%20-%20areal.jpg"}'::text[], 2),
    (v_route, 'Gombasecká jaskyňa', 'Gombasecká jaskyňa v chotári obce Slavec je známa predovšetkým unikátnymi tenkými sintrovými brčkami, ktoré dosahujú dĺžku až tri metre. Práve táto jaskyňa sa v roku 1955 stala prvou liečebňou speleoterapie na svete vďaka svojej čistej klíme. Farebná výzdoba siení, pagodovité stalagmity a jazierka z nej robia jednu z najkrajších sprístupnených jaskýň v regióne.', 48.5628, 20.4665, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia%20Gombasecka%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia%20Gombasecka%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia%20Gombasecka%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia%20Gombasecka%203.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Apetit reštaurácia (Rožňava)', 'Apetit reštaurácia v Rožňave patrí k najlepšie hodnoteným podnikom v meste a je ideálnou zastávkou na obed zhruba v polovici okruhu. Ponúka poctivú domácu kuchyňu za priaznivé ceny a zákazníci oceňujú najmä výdatné porcie a rýchlu obsluhu. Pokojné prostredie v centre Rožňavy je príjemným miestom na oddych medzi návštevami jaskýň a hradov.', 48.64956, 20.52661, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava-panorama.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava-panorama.JPG"}'::text[], 4),
    (v_route, 'hrad Krásna Hôrka', 'Hrad Krásna Hôrka sa týči na kužeľovitom kopci nad obcou Krásnohorské Podhradie a patrí k najzachovalejším hradom na Slovensku. Bol dlhé stáročia sídlom rodu Andrássyovcov a dnes je vyhľadávaným národným kultúrnym pamätníkom. Po ničivom požiari v roku 2012 prešiel rozsiahlou obnovou a znovu láka návštevníkov svojou impozantnou siluetou a bohatou históriou.', 48.65837, 20.60027, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%204.JPG"}'::text[], 5),
    (v_route, 'kaštieľ Betliar', 'Kaštieľ Betliar je romantické šľachtické sídlo rodu Andrássyovcov obklopené rozľahlým anglickým parkom s umelými jaskyňami, vodopádmi a altánkami. Interiéry patria k najlepšie zachovaným na Slovensku a ukrývajú vzácnu zbierku obrazov, zbraní, nábytku a knižnicu s tisíckami zväzkov. Kaštieľ ako jeden z mála prežil obe svetové vojny s pôvodným zariadením a dnes je vyhľadávaným múzeom.', 48.70603, 20.51045, 'https://commons.wikimedia.org/wiki/Special:FilePath/Betliar%2C%20ka%C5%A1tie%C4%BE%2C%20park%20(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Betliar%2C%20ka%C5%A1tie%C4%BE%2C%20park%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Betliar%2C%20ka%C5%A1tie%C4%BE%2C%20park%20(2).jpg"}'::text[], 6),
    (v_route, 'Jasovská jaskyňa', 'Jasovská jaskyňa na okraji obce Jasov bola historicky prvou sprístupnenou jaskyňou na Slovensku, sprístupnili ju už premonštráti v 19. storočí. Preslávila sa bohatou a farebnou sintrovou výzdobou, pagodami a tzv. netopierím dómom. Na jej stenách sa zachoval aj husitský nápis z roku 1452, ktorý pripomína dávnu ľudskú prítomnosť v podzemí.', 48.67696, 20.97617, 'https://commons.wikimedia.org/wiki/Special:FilePath/JasovskaJaskyna2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/JasovskaJaskyna2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jasovsk%C3%A1%20jasky%C5%88a%2C%20vstupn%C3%BD%20rozsah.jpg"}'::text[], 7),
    (v_route, 'Košice (Dóm sv. Alžbety)', 'Dóm svätej Alžbety je najväčším kostolom na Slovensku a najvýchodnejšie položenou gotickou katedrálou v Európe. Táto monumentálna päťloďová stavba dominuje historickému centru Košíc a je vrcholom celej okružnej trasy. V jej kráľovskej krypte odpočíva František II. Rákoci a z veže sa otvára nezabudnuteľný výhľad na metropolu východného Slovenska.', 48.71958, 21.25812, 'https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%B3m%20sv%C3%A4tej%20Al%C5%BEbety%20-%20z%20juhu%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%B3m%20sv%C3%A4tej%20Al%C5%BEbety%20-%20z%20juhu%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%A1ice%20-%20D%C3%B3m%20sv.%20Al%C5%BEbety%20-%20Hlavn%C3%BD%20olt%C3%A1r%20sv%C3%A4tej%20Al%C5%BEbety.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Med Malina (Košice)', 'Med Malina je poľsko-slovenská reštaurácia priamo na Hlavnej ulici v historickom centre Košíc a patrí roky k absolútnej gastronomickej špičke mesta. V útulnom rustikálnom interiéri si vychutnáte tradičné jedlá ako bryndzové halušky, poľské pirohy či boršč. Je ideálnym miestom na záverečnú večeru po celodennom putovaní Slovenským krasom.', 48.7234, 21.2569, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%A1ice%2C%20Hlavn%C3%A1%20ulica%203.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%A1ice%2C%20Hlavn%C3%A1%20ulica%203.JPG"}'::text[], 9);
  insert into public.routes
