  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Melk (Stift Melk)', 'Benediktinské opatství Melk je barokní skvost tyčící se na skalním ostrohu nad Dunajem u vstupu do Wachau. Založeno bylo roku 1089 a dnešní velkolepou podobu získalo počátkem 18. století podle plánů Jakoba Prandtauera. Nesmíte minout oslnivou klášterní knihovnu a bohatě zdobený klášterní kostel. Je to ideální místo pro start výletu údolím Wachau.', 48.2281, 15.33064, 'https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20-%20Stift.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20-%20Stift.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20-%20Stift%20(0).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Melk%20Abbey.JPG"}'::text[], 0),
    (v_route, 'Zřícenina Aggstein (Burgruine Aggstein)', 'Mohutná zřícenina hradu Aggstein se dramaticky vypíná na skalním hřebeni vysoko nad pravým břehem Dunaje. Hrad pochází z 12. století a je opředen pověstmi o loupeživých rytířích, kteří odtud přepadávali lodě na řece. Z hradeb se otevírá jeden z nejkrásnějších výhledů na celé údolí Wachau. Výstup se vyplatí i kvůli atmosféře středověké tvrze.', 48.3144, 15.4217, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20Aggstein%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20Aggstein%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20Aggstein%2001.JPG"}'::text[], 1),
    (v_route, 'Willendorf (naleziště Venuše)', 'Malá vinařská obec Willendorf v der Wachau se zapsala do dějin světové archeologie. V roce 1908 zde byla nalezena Venuše z Willendorfu – proslulá pravěká soška ženské postavy stará přes 25 tisíc let. Originál je dnes ve vídeňském přírodovědném muzeu, ale na místě nálezu připomíná objev pamětní místo. Zastávka je poklonou nejstarším stopám lidské kultury v údolí.', 48.3167, 15.3833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Willendorf-Venus-1468.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Willendorf-Venus-1468.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Venus%20of%20Willendorf.jpg"}'::text[], 2),
    (v_route, 'Spitz an der Donau', 'Idylické vinařské městečko Spitz leží v srdci Wachau na levém břehu Dunaje. Nad obcí se tyčí legendární vinařský kopec Tausendeimerberg – „Kopec tisíce věder“ – pojmenovaný podle vydatné úrody vína. Nad městem strážila okolí zřícenina hradu Hinterhaus. Spitz je vyhlášený svými víny Grüner Veltliner a Riesling a poklidnou atmosférou.', 48.36433, 15.41989, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spitz%20an%20der%20Donau%20-%20Ruine%20Hinterhaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spitz%20an%20der%20Donau%20-%20Ruine%20Hinterhaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Spitz-Donau%209004.JPG"}'::text[], 3),
    (v_route, 'Weißenkirchen in der Wachau (vinice)', 'Weißenkirchen je největší vinařská obec Wachau, obklopená strmými terasovitými vinicemi na svazích nad Dunajem. Zdejší vinohrady jako Achleiten patří k nejproslulejším v Rakousku a rodí špičkové Rieslingy a Grüner Veltlinery. Dominantou obce je opevněný gotický farní kostel Mariä Himmelfahrt. Zastavte se u některého z místních vinařů na sklenku bílého vína.', 48.3973, 15.4696, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau%20-%20Kirche.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Heuriger Walter Denk (Weißenkirchen)', 'Tradiční wachauský heuriger rodiny Denk nabízí domácí studenou kuchyni a vlastní vína přímo v srdci vinařské oblasti. Hosté oceňují srdečnou atmosféru, poctivé regionální speciality a nádherný výhled do údolí Wachau. S hodnocením kolem 4,8 hvězdy jde o ideální zastávku zhruba v polovině trasy k odpočinku a ochutnávce místního vína.', 48.3998, 15.4728, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau%20-%20Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fenkirchen%20in%20der%20Wachau%20-%20Kirche.JPG"}'::text[], 5),
    (v_route, 'Dürnstein (zřícenina a modrá věž)', 'Dürnstein je nejfotogeničtější městečko celé Wachau, proslulé svou modrobílou barokní věží kláštera, která se odráží v hladině Dunaje. Nad obcí se na skále tyčí zřícenina hradu Dürnstein, kde byl podle pověsti roku 1192 vězněn anglický král Richard Lví srdce. Úzkými uličkami se prochází mezi vinařskými dvory a obchůdky. Výstup ke zřícenině odmění nezapomenutelným výhledem na řeku a vinice.', 48.3975, 15.5219, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Duernstein%20Wachau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Duernstein%20Wachau.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20D%C3%BCrnstein%2040MP.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%BCrnstein%20-%20Burgruine%20(a).JPG"}'::text[], 6),
    (v_route, 'Krems an der Donau (Steiner Tor)', 'Krems an der Donau je historické centrum na východním okraji Wachau a jedno z nejstarších měst Rakouska. Symbolem města je Steiner Tor – zdobená středověká městská brána upravená v barokním slohu. Staré město láká dlážděnými uličkami, kostely a útulnými vinárnami. Krems je přirozeným cílem cesty údolím Dunaje.', 48.40984, 15.59646, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steiner%20Tor,%20Krems%20an%20der%20Donau,%20Lower%20Austria,%2020210729%201017%200929.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steiner%20Tor,%20Krems%20an%20der%20Donau,%20Lower%20Austria,%2020210729%201017%200929.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krems%20an%20der%20Donau,%20Steiner%20Tor%20(2).jpg"}'::text[], 7),
    (v_route, 'Klášter Göttweig (Stift Göttweig)', 'Benediktinské opatství Göttweig, přezdívané „rakouský Monte Cassino“, majestátně korunuje kopec na jižním okraji Wachau nad Kremží. Rozlehlý barokní komplex nabízí velkolepé nádvoří, slavnostní císařské schodiště a úchvatný panoramatický výhled na Dunaj a vinice. Klášter je zapsán na seznamu UNESCO jako součást kulturní krajiny Wachau. Je to důstojné zakončení výletu s výhledem na celé údolí.', 48.36778, 15.6125, 'https://commons.wikimedia.org/wiki/Special:FilePath/Furth%20bei%20G%C3%B6ttweig%20-%20Stift%20G%C3%B6ttweig%20(a).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furth%20bei%20G%C3%B6ttweig%20-%20Stift%20G%C3%B6ttweig%20(a).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Furth%20bei%20G%C3%B6ttweig%20-%20Stift%20G%C3%B6ttweig%20(b).JPG"}'::text[], 8);
  insert into public.routes
