  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Žďár nad Sázavou a Zelená hora', 'Barokní zámek s poutním kostelem svatého Jana Nepomuckého na Zelené hoře, unikátní stavbou architekta Jana Blažeje Santiniho-Aichela zapsanou na seznamu UNESCO. Kostel s pěticípým půdorysem patří k nejpozoruhodnějším sakrálním stavbám u nás. Zastávka nabízí klidné parkování a příjemnou procházku areálem.', 49.58806, 15.94167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zelen%C3%A1%20hora%20-%20poutn%C3%AD%20kostel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20St%20John%20of%20Nepomuk%20at%20Zelen%C3%A1%20hora%20CZ.jpg"}'::text[], 0),
    (v_route, 'Nové Město na Moravě – náměstí a Horácká galerie', 'Živé městečko v srdci Žďárských vrchů s malebným náměstím a Horáckou galerií sídlící v renesančním zámku. Ideální zastávka na kávu a protažení po klikatých silnicích okolí. Město je známé jako centrum běžeckého lyžování, ale i v létě nabízí příjemnou atmosféru a historické památky.', 49.56111, 16.07417, 'https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A1%20radnice%20%C4%8Dp%20114,%20Nov%C3%A9%20M%C4%9Bsto%20n%20Mor%202012-09%20(2).JPG"}'::text[], 1),
    (v_route, 'Restaurace: Penzion U Martina (Nové Město na Moravě)', 'Oblíbená rodinná restaurace v Rokytně u Nového Města na Moravě s vynikajícím hodnocením kolem 4,7 hvězdy z více než tří set recenzí. Kuchyně vsází na poctivá česká jídla, zvěřinu a domácí polévky, omáčky i ovocné knedlíky připravované přímo v kuchyni. Příjemná terasa a vstřícná obsluha z ní dělají ideální zastávku na oběd uprostřed okruhu.', 49.5647, 16.0736, 'https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG"}'::text[], 2),
    (v_route, 'Rozhledna Horní les', 'Devětapadesát metrů vysoká ocelová rozhledna nedaleko Rovečného, z jejíž vyhlídky ve výšce 38 metrů se otevírá dechberoucí kruhový výhled na Žďárské vrchy. K rozhledně se dostanete po zatáčkovitých lesních silnicích, které potěší každého motorkáře. Přístup je v sezóně zdarma a stojí za krátkou zastávku i výstup po 201 schodech.', 49.5899, 16.34235, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rove%C4%8Dn%C3%A9%20-%20rozhledna%20Horn%C3%AD%20les,%202024-10,%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rove%C4%8Dn%C3%A9%20-%20rozhledna%20Horn%C3%AD%20les,%202024-10,%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Horn%C3%AD%20les.jpg"}'::text[], 3),
    (v_route, 'Hrad Pernštejn', 'Jeden z nejlépe zachovaných gotických hradů v České republice, majestátně tyčící se nad údolím Svratky nedaleko Nedvědice. Přístupová silnice ke hradu je klikatá a lemovaná lesy, což z příjezdu dělá zážitek sám o sobě. Motorkáři ocení parkoviště pod hradem i možnost prohlídky bohatě zařízených interiérů.', 49.55028, 16.31333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pern%C5%A1tejn%20(Pernstein)%20-%20by%20Pudelek%2003.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pern%C5%A1tejn%20(Pernstein)%20-%20by%20Pudelek%2003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pernstejn%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pernstejn%202.JPG"}'::text[], 4),
    (v_route, 'Bystřice nad Pernštejnem a hrad Zubštejn', 'Zřícenina mohutného gotického hradu Zubštejn se tyčí nad údolím Svratky u Bystřice nad Pernštejnem a nabízí romantickou zastávku s výhledy do kraje. Samotné město je příjemným místem k občerstvení a doplnění paliva. Cesta k hradu vede po užších klikatých silničkách, které prověří jezdcovu jízdu v zatáčkách.', 49.524, 16.259, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pivonice%20-%20hrad%20Zub%C5%A1tejn,%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pivonice%20-%20hrad%20Zub%C5%A1tejn,%20obr01.jpg"}'::text[], 5);
  insert into public.routes
