  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hallstatt', 'Světoznámá vesnička na břehu Hallstättského jezera, zapsaná na seznamu UNESCO a proslulá dřevěnými domky nalepenými mezi vodu a strmé skály. Odtěžuje se tu sůl již od pravěku, po němž je pojmenována celá halštatská kultura doby železné. Malebné náměstí, kostní kaple a výhled na jezero patří k nejfotografovanějším místům celého Rakouska. V hlavní sezoně dorazte brzy ráno, abyste se vyhnuli davům.', 47.56223, 13.64926, 'https://commons.wikimedia.org/wiki/Special:FilePath/HALLSTATT.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/HALLSTATT.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hallstatt,%20Austria.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hallstatt%20Panorama.jpg"}'::text[], 0),
    (v_route, 'Dachstein – Krippenstein (Five Fingers)', 'Vyhlídkový vrchol Krippenstein nad Obertraunem, na který vás vyveze lanovka Dachstein-Krippensteinbahn z údolí. Nahoře čeká slavná vyhlídková plošina Five Fingers vybíhající nad srázy propasti a nezapomenutelné panorama masivu Dachstein a Hallstättského jezera. V okolí najdete i ledovcovou jeskyni a mamutí jeskyni. Motorku necháte na parkovišti u dolní stanice lanovky, samotný výstup je pak lanovkou a pěšky.', 47.5242, 13.69196, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dachstein%20Krippenstein-Seilbahn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dachstein%20Krippenstein-Seilbahn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dachstein-topview.jpg"}'::text[], 1),
    (v_route, 'Gosausee', 'Klidné horské jezero Vorderer Gosausee s dokonalým zrcadlením masivu Dachstein a jeho ledovce na hladině. Patří k nejfotogeničtějším místům Salzkammergutu a je oblíbeným výchozím bodem pro nenáročné procházky kolem jezera. Příjezdová silnice z Gosau je klikatá a scénická, ideální pro motorkáře. Jezero leží stranou hlavních tras, takže tu bývá klid a čistý horský vzduch.', 47.53333, 13.48333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vorderer%20Gosausee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vorderer%20Gosausee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vorderer%20Gosausee%201.jpg"}'::text[], 2),
    (v_route, 'Bad Ischl – Kaiservilla', 'Letní císařská rezidence Františka Josefa I. a Sisi, kde císař každé léto pobýval a odkud roku 1914 podepsal osudový manifest do války. Vilu obklopuje rozlehlý park a řeka Traun, interiéry jsou plné loveckých trofejí a dobového vybavení. Samotné lázeňské městečko Bad Ischl bylo Evropským hlavním městem kultury a je proslulé cukrárnou Zauner. Ideální zastávka na oběd a prohlídku uprostřed trasy.', 47.714, 13.6234, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaiservilla%20Bad%20Ischl.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaiservilla%20Bad%20Ischl.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Ischl%20Kaiservilla%20Zugangssteg.JPG"}'::text[], 3),
    (v_route, 'St. Wolfgang im Salzkammergut (Wolfgangsee)', 'Půvabné poutní městečko na břehu jezera Wolfgangsee, proslulé gotickým kostelem se slavným Pacherovým oltářem a legendárním hotelem Weisses Rössl. Nad městem se tyčí hora Schafberg, na kterou vyjíždí historická ozubnicová železnice. Uličkami se prochází kolem tradičních hostinců a nábřeží s výhledem na jezero. Skvělé místo pro nocleh na konci prvního dne.', 47.7393, 13.4467, 'https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Wolfgang%20im%20Salzkammergut%20-%20Ortsansicht.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Wolfgang%20im%20Salzkammergut%20-%20Ortsansicht.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Wolfgang%20am%20Wolfgangsee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Wolfgang%20im%20Salzkammergut%20-%20Kirche.JPG"}'::text[], 4),
    (v_route, 'Gmunden – zámek Ort (Traunsee)', 'Romantický vodní zámek Seeschloss Ort stojí na malém ostrůvku v jezeře Traunsee, propojený s pevninou dřevěným mostem. Proslavil ho stejnojmenný rakouský televizní seriál a patří k nejmalebnějším zámkům v zemi. Nad jezerem se tyčí strmá hora Traunstein a nábřeží Gmundenu láká k procházce i zmrzlině. Město je také známé svou keramikou s charakteristickým zeleným vzorem.', 47.91131, 13.79224, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Orth%20am%20Traunsee%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Orth%20am%20Traunsee%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gmunden%20-%20Schloss%20Ort%20(3).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Traunsee,%20Traunstein,%20Schloss%20Ort.jpg"}'::text[], 5),
    (v_route, 'Attersee', 'Největší jezero celého Salzkammergutu s výjimečně čistou tyrkysovou vodou, oblíbené mezi plavci, potápěči a jachtaři. Zdejší krajinu miloval malíř Gustav Klimt, který sem jezdil malovat, a dodnes tu vede tematická Klimtova stezka. Silnice lemující břeh nabízí jeden příjezerní výhled za druhým a je jako stvořená pro pomalou vyjížďku. V letních měsících se voda dostatečně prohřeje ke koupání.', 47.9, 13.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Attersee%20-%20S%C3%BCdostansicht.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Attersee%20-%20S%C3%BCdostansicht.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Altes%20Haus%20Salzkammergut%20Attersee.JPG"}'::text[], 6),
    (v_route, 'Mondsee', 'Teplé jezero Mondsee a stejnojmenné městečko s působivou žlutou bazilikou svatého Michaela, v níž se natáčela svatební scéna z filmu Za zvuků hudby. Bývalý benediktinský klášter dnes ukrývá muzeum a příjemné náměstí plné kaváren. Jezero patří k nejteplejším v Rakousku, a je proto vyhledávané ke koupání i vodním sportům. Odtud se trasa stáčí zpět k Hallstattu po vedlejších silnicích.', 47.85559, 13.34342, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mondsee%20-%20Basilika%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mondsee%20-%20Basilika%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mondsee%20(town).JPG"}'::text[], 7),
    (v_route, 'Restaurace: Weinhaus Attwenger (Bad Ischl)', 'Jeden z nejstarších domů v Bad Ischlu, jehož historie sahá až do 15. století, dnes ceněná restaurace s hodnocením 4,5. Podává se tu poctivá rakouská kuchyně v romantické zahradě u řeky Traun i v historických interiérech. Ideální zastávka na oběd v polovině prvního dne, kousek od císařské vily.', 47.7133, 13.6268, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kurhaus%20Bad%20Ischl.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kurhaus%20Bad%20Ischl.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Ischl%20-%20Rathaus.JPG"}'::text[], 8),
    (v_route, 'Restaurace: Seerestaurant im Weissen Rössl (St. Wolfgang)', 'Legendární hostinec přímo na břehu jezera Wolfgangsee, proslavený operetou i filmem Im weissen Rössl, s výborným hodnocením kolem 4,8. Terasa nad vodou nabízí úchvatný výhled na jezero a horu Schafberg a servíruje klasickou rakouskou kuchyni i sladké speciality. Skvělé místo pro večeři na konci prvního dne trasy.', 47.7387, 13.4481, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Wolfgang%20am%20Wolfgangsee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Wolfgang%20am%20Wolfgangsee.jpg"}'::text[], 9);
