  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Mayrhofen', 'Mayrhofen je živé horské středisko na konci hlavního údolí Zillertalu a přirozený výchozí bod celé trasy. Obklopují ho třítisícové vrcholy Zillertálských Alp a je proslulé lanovkami i legendární sjezdovkou Harakiri. V létě je oblíbenou základnou motorkářů i pěších turistů. Najdete zde spoustu kaváren, penzionů a servisů, kde se dá doplnit palivo i síly před náročným okruhem.', 47.16919, 11.86515, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mayrhofen%20view.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mayrhofen%20view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dorp%20Mayrhofen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mayrhofen.jpg"}'::text[], 0),
    (v_route, 'Zell am Ziller', 'Zell am Ziller je historické městečko uprostřed údolí, kde se odbočuje na Gerlos Alpenstrasse. Dominantou je monumentální kruhový farní kostel svatého Vitáka s freskovou kupolí. Město bývalo centrem těžby zlata a dodnes si zachovalo tyrolskou atmosféru. Je to poslední větší zastávka před stoupáním k průsmyku Gerlos.', 47.2336, 11.882, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pfarrkirche%20Zell%20a.%20Ziller%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pfarrkirche%20Zell%20a.%20Ziller%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zell%20am%20Ziller%20-%20Bezirksgericht%20und%20Kaiserdenkmal.jpg"}'::text[], 1),
    (v_route, 'Gerlos Alpenstrasse (Gerlospass)', 'Gerlos Alpenstrasse je jednou z nejkrásnějších alpských panoramatických silnic Rakouska a překonává průsmyk Gerlos ve výšce kolem 1530 metrů. Zpoplatněná horská silnice nabízí strhující serpentiny a slavný výhled na Krimmelské vodopády z vyhlídkové plošiny. Cesta byla postavena v 60. letech jako turistická spojnice mezi Tyrolskem a Salcburskem. Na trase najdete mýtnici, kde se platí mýto za průjezd.', 47.24286, 12.10939, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gerlospass%20mautstelle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gerlospass%20mautstelle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gerlos%20Alpenstra%C3%9Fe%20-%20Mautstelle%20-%20Richtung%20Krimml.jpg"}'::text[], 2),
    (v_route, 'Krimmelské vodopády (Krimml)', 'Krimmelské vodopády jsou s celkovou výškou 380 metrů nejvyšším vodopádem Rakouska a jedním z nejvyšších v Evropě. Voda se řítí ve třech mohutných kaskádách v Národním parku Vysoké Taury a vytváří ohromující divadlo. Podél vodopádů vede pohodlná stezka s mnoha vyhlídkovými body. Je to hlavní přírodní klenot celé trasy a ideální místo na delší zastávku.', 47.1922, 12.1695, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/1444%20-%20Nationalpark%20Hohe%20Tauern%20-%20Krimmler%20Wasserf%C3%A4lle.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Hanke''s Café Restaurant (Krimml)', 'Hanke''s Café Restaurant leží pouhých padesát metrů od dolního Krimmelského vodopádu a je ideální zastávkou přesně v polovině trasy. Z panoramatické terasy je nádherný pohled na padající vodu a restaurace nabízí tyrolské speciality, řízky a proslulý domácí jablečný závin. Díky výborným hodnocením a poloze přímo u vodopádů je oblíbeným cílem motorkářů i rodin.', 47.1928, 12.1715, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krimml,%20Unterer%20Wasserfall.jpg"}'::text[], 4),
    (v_route, 'Zillertaler Höhenstraße', 'Zillertaler Höhenstraße je zpoplatněná panoramatická silnice, která se táhne vysoko nad údolím ve výškách kolem 1700 až 2100 metrů. Nabízí jeden z nejúchvatnějších výhledů na ledovce Zillertálských Alp a nekonečné horské louky nad hranicí lesa. Trasa je úzká a klikatá, s řadou vyhlídkových zastávek a horských chat. Pro motorkáře je to adrenalinový zážitek s odměnou v podobě dechberoucích panoramat.', 47.2, 11.83, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zillertaler%20Hoehenstrasse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zillertaler%20Hoehenstrasse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zillertaler%20Hoehenstrasse%202.jpg"}'::text[], 5),
    (v_route, 'Achensee', 'Achensee je největší jezero Tyrolska s tyrkysově modrou vodou, sevřené mezi masivy Karwendel a Rofan. Bývá přezdíváno tyrolské moře a je oblíbeným cílem pro plavbu lodí, koupání i horské výlety. Silnice podél jeho břehů patří k nejmalebnějším v celém regionu. Na severním okraji trasy nabízí příjemné osvěžení a klidnější zastávku po náročných průsmycích.', 47.4333, 11.7167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Achensee%20Pertisau.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Achensee%20Pertisau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pertisau%20Achensee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Achensee-Tirol.jpg"}'::text[], 6),
    (v_route, 'Hintertux (ledovec)', 'Hintertux je jediný celoroční lyžařský ledovec v Rakousku a leží na samém konci bočního údolí Tuxertal. I v létě se zde dá lyžovat a ledovec láká turisty na výlety do ledovcového paláce s křišťálovými jeskyněmi. Cesta k němu vede úzkým horským údolím s výhledy na zasněžené vrcholy. Pro motorkáře je to působivá slepá odbočka a velkolepé zakončení okruhu.', 47.0639, 11.6639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hintertuxer%20Gletscher.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hintertuxer%20Gletscher.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hintertux%20glacier.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hintertux%20Glacier%20view.jpg"}'::text[], 7);
