  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bielerhöhe (Silvretta-Stausee)', 'Bielerhöhe je vrcholové sedlo Silvretta Hochalpenstrasse ve výšce 2032 metrů, kde se rozkládá tyrkysová přehradní nádrž Silvretta-Stausee. Z hráze se otevírá dechberoucí výhled na zaledněné vrcholy Silvretty včetně slavného Piz Buin. Místo je oblíbeným cílem motorkářů a výchozím bodem mnoha vysokohorských túr kolem jezera.', 46.91778, 10.09429, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silvretta_Stausee_001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Silvretta_Stausee_001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gaschurn_Silvretta-Stausee_Staumauer_B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gaschurn_Silvretta-Stausee_Staumauer.jpg"}'::text[], 0),
    (v_route, 'Partenen', 'Partenen je nejvýše položená obec vorarlberského údolí Montafon a tvoří západní bránu na Silvretta Hochalpenstrasse. Odsud začíná legendární stoupání s 34 serpentinami k sedlu Bielerhöhe. Malebná horská vesnička s tradiční montafonskou architekturou je ideálním místem pro odpočinek a doplnění paliva před náročným výstupem.', 46.96898, 10.06066, 'https://commons.wikimedia.org/wiki/Special:FilePath/Partenen_Vorarlberg_0486.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Partenen_Vorarlberg_0486.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kuratienkirche%20hl.%20Martin,%20Partenen%2091%20.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Montafonerhaus%20Partenen%20(1).JPG"}'::text[], 1),
    (v_route, 'Galtür', 'Galtür je nejvýše položená obec tyrolského údolí Paznaun a leží na východní straně Silvretta Hochalpenstrasse. Tato horská vesnice láká na klidnější atmosféru než sousední Ischgl a nabízí pěkný výhled na okolní vrcholy Silvretty a Verwallu. Dominantou obce je poutní kostel Panny Marie a moderní muzeum Alpinarium.', 46.96856, 10.18932, 'https://commons.wikimedia.org/wiki/Special:FilePath/Galtur-Wirl%20Tirol%20skiresort%20with%20comfortable%20lifts%20(Alpkogelbahn)%20at%2025%20Februari%202015%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Galtur-Wirl%20Tirol%20skiresort%20with%20comfortable%20lifts%20(Alpkogelbahn)%20at%2025%20Februari%202015%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Galtur%20and%20town%20hall%20by%20night%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Montafon (Schruns)', 'Schruns je hlavní obec malebného vorarlberského údolí Montafon a oblíbené letovisko s bohatou historií. V minulosti sem jezdil i spisovatel Ernest Hemingway a nechal se okouzlit zdejšími horami. Údolí Montafon obklopují mohutné masivy Rätikonu, Verwallu a Silvretty a nabízí ideální východisko pro výlety do vysokohorské přírody.', 47.0667, 9.9167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kronengasse_2_Schruns.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kronengasse_2_Schruns.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Denkmal,%20Landamann%20Johann%20Josef%20Batlogg,%20Schruns.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Skigebiet%20Silvretta%20Montafon%20-%20panoramio%20(2).jpg"}'::text[], 3),
    (v_route, 'Kops Stausee', 'Kops Stausee je horská přehradní nádrž ležící ve výšce 1809 metrů poblíž sedla Zeinisjoch na pomezí Silvretty a Verwallu. Vodní plocha se sytě modrou barvou obklopená loukami a horami je oblíbeným cílem výletníků a slouží energetice koncernu illwerke vkw. Kolem jezera vede pohodlná okružní stezka s nádhernými výhledy na okolní štíty.', 46.97219, 10.11939, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steigleitung%20vom%20Pumpwerk%20Kleinvermunt%20zum%20Kopssee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steigleitung%20vom%20Pumpwerk%20Kleinvermunt%20zum%20Kopssee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/050%20Kopssee%20vom%20Breitspitz%20f%C3%BCr%20Wiki.jpg"}'::text[], 4),
    (v_route, 'Bludenz', 'Bludenz je historické okresní město ve Vorarlbersku, kde se sbíhá pět alpských údolí, a bývá proto nazýváno Alpenstadt. Malebné staré město s dlážděnými uličkami, horní městskou branou a starou radnicí zve k procházce. Ve městě sídlí známá čokoládovna Suchard-Milka, díky které se Bludenzu přezdívá čokoládové město.', 47.153, 9.8219, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bludenz_Altes_Rathaus-2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bludenz_Altes_Rathaus-2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberes%20Stadttor%20Bludenz,%20Rathausgasse%209.JPG"}'::text[], 5),
    (v_route, 'Ischgl', 'Ischgl je světoznámé horské středisko v tyrolském údolí Paznaun a živý cíl na východním konci Silvretta Hochalpenstrasse. Vesnice v nadmořské výšce 1377 metrů je proslulá lyžařským areálem Silvretta Arena i pověstnou après-ski atmosférou. V okolí najdete zavěšený most Kitzloch, lanovky na Idalp a řadu horských chat s výhledy na Silvrettu.', 47.01184, 10.28842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Ischgl_Pardorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Ischgl_Pardorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde%20Ischgl,%20Austria%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ischgl.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Tiroler Stube (Galtür)', 'Tiroler Stube na hlavním náměstí v Galtüru je útulná tradiční restaurace hodnocená kolem 4,6 hvězdičky a patří k nejlepším podnikům v obci. Podává vydatnou tyrolskou domácí kuchyni v přátelské a srdečné atmosféře. Leží prakticky v polovině trasy, takže je ideálním místem na oběd před nebo po zdolání horského sedla.', 46.9678, 10.1878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Galtur%20and%20town%20hall%20by%20night%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Galtur%20and%20town%20hall%20by%20night%20-%20panoramio.jpg"}'::text[], 7);
