  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Semmering — viadukt Kalte Rinne (Semmeringbahn, UNESCO)', 'Semmeringská dráha z roku 1854 byla první horskou železnicí Evropy se standardním rozchodem a od roku 1998 je zapsána na seznam UNESCO. Její vizitkou je dvoupatrový kamenný viadukt Kalte Rinne, který se elegantně klene nad údolím u Breitensteinu. Z takzvaného 20-Schilling-Blicku se otevírá slavný pohled na oblouky mostu i projíždějící vlaky. Okolní serpentiny průsmyku Semmering patří k nejkrásnějším motorkářským úsekům regionu.', 47.643, 15.831, 'https://commons.wikimedia.org/wiki/Special:FilePath/Breitenstein%20-%20Semmeringbahn,%20Viadukt%20Kalte%20Rinne.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Breitenstein%20-%20Semmeringbahn,%20Viadukt%20Kalte%20Rinne.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Semmeringbahn%2020-Schilling-Blick%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kalte%20Rinne%20Viadukt%20-%20Semmeringbahn.jpg"}'::text[], 0),
    (v_route, 'Höllental a Rax — lanovka Raxseilbahn', 'Divoké údolí Höllental sevřené mezi masivy Rax a Schneeberg proslulo strmými skalními stěnami a řekou Schwarza. Z Hirschwangu vyjíždí Raxseilbahn — vůbec první osobní lanovka Rakouska z roku 1926 — na rozlehlou náhorní plošinu Rax ve výšce kolem 1 500 metrů. Nahoře čekají panoramatické výhledy, horské chaty a spousta turistických stezek. Cesta údolím nabízí motorkářům stinné zatáčky podél řeky a chladivý horský vzduch.', 47.6912, 15.8427, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichenau%20-%20Raxseilbahn,%20Talstation.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reichenau%20-%20Raxseilbahn,%20Talstation.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Reichenau%20-%20Raxseilbahn,%20Kabine%20und%20St%C3%BCtze.JPG"}'::text[], 1),
    (v_route, 'Schneeberg — zubačka Salamander (Puchberg am Schneeberg)', 'Schneeberg je nejvyšší hora Dolních Rakous a poslední dvoutisícovka na východním okraji Alp. Z nádraží v Puchbergu na něj šplhá historická ozubnicová dráha, jejíž moderní červené soupravy nesou přezdívku Salamander. Výlet nabízí romantiku parní éry i velkolepé rozhledy do kraje. Puchberg je zároveň ideálním startovním i cílovým bodem této okružní trasy.', 47.79036, 15.91088, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schneebergbahn%20Salamander%20Ausfahrt%20zum%20Schneeberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schneebergbahn%20Salamander%20Ausfahrt%20zum%20Schneeberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Triebwagen%20Salamander%20Schneebergbahn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puchberg%20Bahnhof%20mit%20Salamander%20und%20Desiro.jpg"}'::text[], 2),
    (v_route, 'Bruck an der Mur — Hauptplatz a Železná studna', 'Bruck an der Mur leží na soutoku řek Mur a Mürz a je půvabnou branou do Štýrska. Jeho hlavní náměstí zdobí proslulá renesanční Železná studna (Eiserner Brunnen) z roku 1626, jedno z nejkrásnějších děl kovářského umění v Rakousku. Nedaleko stojí gotický Kornmesserhaus s arkádami. Město je příjemnou zastávkou na jižní části okruhu, kousek od cesty k masivu Hochschwab.', 47.41, 15.275, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck%20Mur%20Hauptplatz%207952.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck%20Mur%20Hauptplatz%207952.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Eiserner%20Brunnen%20-%20Bruck%20an%20der%20Mur%2020110728-03.JPG"}'::text[], 3),
    (v_route, 'Hochschwab — vrchol masivu', 'Hochschwab je s výškou 2 277 metrů nejvyšší horou stejnojmenného vápencového pohoří v Horním Štýrsku. Rozlehlé náhorní plošiny, krasové útvary a horské louky vytvářejí drsnou, ale nádhernou krajinu domov kamzíků a vzácné alpské flóry. Obcí Seewiesen prochází malebná horská silnice s výhledy na masiv, po níž se motorkáři vydávají severním směrem k Mariazell. Je to jeden z nejdivočejších a nejtišších úseků celé trasy.', 47.6, 15.0833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hochschwab,%20Fleischer%20Biwak%20von%20G''hacktstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hochschwab,%20Fleischer%20Biwak%20von%20G''hacktstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Obere%20Dullwitz,%20Hochschwab.jpg"}'::text[], 4),
    (v_route, 'Mariazell — bazilika Panny Marie', 'Mariazell je nejvýznamnějším poutním místem Rakouska a jedním z nejnavštěvovanějších v celé střední Evropě. Dominuje mu monumentální bazilika Narození Panny Marie s charakteristickou gotickou věží mezi dvěma barokními báněmi. Uvnitř se v kapli Milostí uctívá zázračná soška Magna Mater Austriae. Městečko obklopené horami je přirozeným středobodem této okružní trasy a ideálním místem pro přespání při dvoudenní variantě.', 47.77275, 15.31863, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilika%20von%20Mariazell%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilika%20von%20Mariazell%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wallfahrtskirche%20Basilika%20Mariazell.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mariazell%20-%20Basilika1.JPG"}'::text[], 5),
    (v_route, 'Bärenschützklamm — soutěska (Mixnitz)', 'Bärenschützklamm je jedna z nejkrásnějších soutěsek Štýrska, kde se voda prodírá skalní roklí sérií vodopádů a kaskád. Návštěvníky vede přes 160 dřevěných můstků a žebříků, které stoupají strmě vzhůru přímo nad hučícím potokem. Soutěska leží nedaleko vesnice Mixnitz na jižní části okruhu a je oblíbeným cílem pěších výletů. Pro motorkáře je vítanou zastávkou k protažení nohou uprostřed přírody.', 47.33594, 15.37411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steiermark%20B%C3%A4rensch%C3%BCtzklamm%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steiermark%20B%C3%A4rensch%C3%BCtzklamm%2002.JPG"}'::text[], 6),
    (v_route, 'Restaurace: Brauhaus Mariazell (Mariazell)', 'Brauhaus Mariazell je tradiční pivnice a restaurace s vlastním pivovarem, jejíž historie sahá až do roku 1673. Hosté si pochvalují poctivou štýrskou kuchyni, čerstvě vařené pivo a útulnou atmosféru přímo v centru poutního městečka, jen pár kroků od baziliky. S hodnocením kolem 4,6 hvězdy patří k nejlépe hodnoceným podnikům v Mariazell. Je to ideální místo pro oběd zhruba v polovině okruhu.', 47.7732, 15.3198, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mariazell%20-%20Brunnen,%20Hauptplatz.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mariazell%20-%20Brunnen,%20Hauptplatz.JPG"}'::text[], 7);
