  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Neuschwanstein (Schwangau)', 'Pohádkový zámek krále Ludvíka II. Bavorského se tyčí na skalnatém ostrohu nad vesnicí Hohenschwangau a je nejslavnější stavbou celého Bavorska. Bílé věže a cimbuří inspirovaly i zámek Šípkové Růženky ve Disneylandu. Nejlepší výhled na celou stavbu je z mostu Marienbrücke přes soutěsku Pöllat. Odtud startuje naše alpská cesta na východ.', 47.55773, 10.74965, 'https://commons.wikimedia.org/wiki/Special:FilePath/Neuschwanstein_Castle_panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Neuschwanstein_Castle_panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Neuschwanstein_Castle_(view_from_the_northwest).jpg"}'::text[], 0),
    (v_route, 'Wieskirche (Steingaden)', 'Poutní kostel Wies je skvostem bavorského rokoka a od roku 1983 je zapsán na seznamu světového dědictví UNESCO. Zvenčí nenápadná stavba uprostřed alpských luk skrývá dechberoucí zdobený interiér s freskovou klenbou od bratří Zimmermannů. Kostel stojí osamoceně v kraji Pfaffenwinkel a je oblíbenou zastávkou motorkářů na cestě do hor.', 47.68055, 10.90044, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wieskirche_rococo_interior.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wieskirche_rococo_interior.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wieskirche_003.JPG"}'::text[], 1),
    (v_route, 'Oberammergau', 'Malebná horská vesnice proslulá tradicí pašijových her, které se hrají jednou za deset let už od roku 1634. Domy zdobí barevné fresky zvané Lüftlmalerei, které vyprávějí biblické i pohádkové výjevy přímo na fasádách. Oberammergau je také centrem řezbářství a dřevořezby. Cesta odsud pokračuje serpentinami k Garmisch-Partenkirchenu.', 47.59566, 11.07235, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oberammergau_L%C3%BCftlmalerei_3.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oberammergau_L%C3%BCftlmalerei_3.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pilatushaus_Oberammergau_2019.jpg"}'::text[], 2),
    (v_route, 'Garmisch-Partenkirchen (Zugspitze)', 'Horské středisko a brána k nejvyšší hoře Německa – Zugspitze (2 962 m). Zubačkou nebo lanovkou se lze vyvézt až na vrchol s ledovcem a panoramatickým výhledem přes čtyři země. Město hostilo zimní olympiádu 1936 a dodnes je rájem sportovců i motorkářů. Doporučujeme zde přenocovat po prvním dnu cesty.', 47.49209, 11.09576, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Buildings_top_Zugspitze.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Zum Wildschütz (Garmisch-Partenkirchen)', 'Útulná bavorská hospoda v centru Garmisch-Partenkirchenu, hodnocená kolem 4,5 hvězdy, je ideální zastávkou zhruba v polovině prvního dne. Podniky se pyšní zvěřinou z vlastního lovu, řízky a Käsespätzle v srdečné rustikální atmosféře. Po náročné jízdě horami zde doplníte energii tradiční kuchyní a čerstvým bavorským pivem.', 47.4922, 11.0947, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitzgipfel_24-Mai.JPG"}'::text[], 4),
    (v_route, 'Walchensee', 'Jedno z nejhlubších a nejkrásnějších alpských jezer Německa, proslulé sytě tyrkysovou barvou vody. Leží 75 km jižně od Mnichova v srdci Bavorských Alp a je oblíbeným cílem plavců, surfařů i motorkářů. Nejlepší výhled na jezero nabízí vrchol Herzogstand nad hladinou. Serpentiny kolem břehu patří k nejfotogeničtějším úsekům trasy.', 47.59225, 11.34685, 'https://commons.wikimedia.org/wiki/Special:FilePath/Walchensee-ortspanorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Walchensee-ortspanorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Blick_auf_die_Ortschaft_Walchensee_vom_Herzogstand.jpg"}'::text[], 5),
    (v_route, 'Sylvensteinsee', 'Umělá přehradní nádrž v údolí řeky Isar, přes kterou se klene elegantní silniční most. Tyrkysová voda obklopená zalesněnými horami vytváří jeden z nejmalebnějších úseků Alpské silnice. Přehrada chrání údolí Isaru před povodněmi a je vděčným motivem fotografů. Klidná jízda kolem hráze je odměnou po předchozích serpentinách.', 47.57935, 11.54403, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sylvensteinbruecke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sylvensteinbruecke.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sylvensteinspeicher_2020.JPG"}'::text[], 6),
    (v_route, 'Tegernsee', 'Elegantní lázeňské městečko na břehu stejnojmenného jezera, oblíbený rekreační kraj 50 km jihovýchodně od Mnichova. Nad hladinou se tyčí bývalý benediktinský klášter s vyhlášeným pivovarem Herzogliches Bräustüberl. Tegernsee je pověstné svou noblesou i klidnou atmosférou u vody. Zde končí druhý den cesty směřující dále na východ.', 47.7123, 11.7582, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tegernsee,_Miesbach,_Germany.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tegernsee,_Miesbach,_Germany.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama-Wallberg-Gipfel-zum-Tegernsee-hs.jpg"}'::text[], 7),
    (v_route, 'Berchtesgaden', 'Historické alpské město v národním parku Berchtesgaden, nad kterým se tyčí majestátní masiv Watzmann (2 713 m). Půvabné náměstí, královský zámek a solné doly patří k hlavním lákadlům. Město leží jen 30 km od rakovnského Salcburku a je výchozím bodem k jezeru Königssee. Odtud vede závěrečná část naší alpské cesty.', 47.63236, 13.00187, 'https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20150823_Watzmann,_Nationalpark_Berchtesgaden_(01912).jpg"}'::text[], 8),
    (v_route, 'Restaurace: Gasthof Neuhaus (Berchtesgaden)', 'Tradiční hostinec na náměstí Marktplatz v Berchtesgadenu sídlí v historickém domě ze 16. století a je hodnocen přes 4,5 hvězdy. Nabízí poctivou bavorskou kuchyni – vepřové koleno, kachnu s knedlíky a proslulý jablečný závin – a útulnou pivní zahradu. Je ideální zastávkou na začátku posledního dne trasy před výjezdem k Orlímu hnízdu.', 47.6305, 13.0032, 'https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_Berchtesgaden.jpg"}'::text[], 9),
    (v_route, 'Königssee', 'Nejčistší a jedno z nejromantičtějších jezer Německa, sevřené strmými skalními stěnami Berchtesgadenských Alp. Na poloostrově uprostřed hladiny stojí ikonický poutní kostel svatého Bartoloměje s červenými cibulovými věžemi. Po jezeře jezdí pouze tiché elektrické lodě, aby se zachovala nedotčená příroda. Ozvěna od skalní stěny Watzmann-Ostwand je zdejší proslulou atrakcí.', 47.55567, 12.97802, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6See_Bartholom%C3%A4_mit_Watzmann.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6See_Bartholom%C3%A4_mit_Watzmann.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Watzmann_k%C3%B6nigssee_st_bartholom%C3%A4.jpg"}'::text[], 10),
    (v_route, 'Roßfeld panoramatická silnice', 'Nejvýše položená panoramatická silnice Německa vystoupá do výšky přes 1 500 metrů a nabízí úchvatné výhledy na masiv Hoher Göll a rakouské Alpy. Okružní zpoplatněná silnice měří přes 15 kilometrů a její serpentiny patří k vrcholným zážitkům celé trasy. Na hřebeni krátce překračuje německo-rakouskou hranici. Pro motorkáře jde o naprosto povinnou zastávku.', 47.65083, 13.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Berchtesgaden_Rossfeld_Panoramastra%C3%9Fe_(Berchtesgaden)_1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark_Berchtesgaden_Rossfeld_Panoramastra%C3%9Fe_(Berchtesgaden)_1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Das_Gipfelkreuz_auf_dem_Ro%C3%9Ffeld_(Berchtesgaden).jpg"}'::text[], 11),
    (v_route, 'Kehlsteinhaus (Orlí hnízdo)', 'Kamenný dům na hřebeni Kehlsteinu ve výšce 1 834 metrů, postavený ve 30. letech 20. století jako dárek k narozeninám. Dnes slouží jako horská restaurace s ohromujícím kruhovým výhledem na Berchtesgadenské Alpy, Untersberg a Salcburk. Nahoru se jezdí speciálním autobusem a poté historickým mosazným výtahem vytesaným ve skále. Orlí hnízdo je působivým a symbolickým vyvrcholením celé Alpské silnice.', 47.61144, 13.04212, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kehlsteinhaus_mit_Blick_auf_den_Untersberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kehlsteinhaus_mit_Blick_auf_den_Untersberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kehlsteinhaus_280605_008.jpg"}'::text[], 12);
