  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Velký Javor (Großer Arber)', 'Velký Javor (Großer Arber, 1456 m) je nejvyšší hora Bavorského i Českého lesa a dominantou celého okruhu. Na zaoblený vrchol s charakteristickými radarovými kopulemi vede kabinová lanovka od jezera Großer Arbersee. Za jasného počasí se odsud otevírá kruhový výhled až na Alpy a hluboko do české Šumavy. Silnice pod horou patří k nejoblíbenějším motorkářským úsekům v regionu.', 49.1073, 13.134, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arber-Gipfelregion.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arber-Gipfelregion.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark%20Bayerischer%20Wald%20Gro%C3%9Fer%20Arber.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Arber%20Panorama%20Nord.jpg"}'::text[], 0),
    (v_route, 'Rachel (Großer Rachel)', 'Rachel (Großer Rachel, 1453 m) je druhá nejvyšší hora Bavorského lesa a nejvyšší vrchol národního parku. Na kamenitý vrchol s vrcholovým křížem a horskou kaplí se vystupuje pěšky lesními stezkami od Spiegelau nebo od jezera Rachelsee. Okolní pralesovité smrčiny patří k nejdivočejším koutům střední Evropy. Pro motorkáře je Rachel skvělou zastávkou na kratší túru mimo sedlo.', 48.97854, 13.38897, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fer%20Rachel,%20Bayerischen%20Wald.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fer%20Rachel,%20Bayerischen%20Wald.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bayerischer%20Wald%20-%20Rachel%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rachel%20-%20Gipfelkreuz.jpg"}'::text[], 1),
    (v_route, 'Zwiesel (sklárny)', 'Zwiesel je srdcem bavorského sklářského umění a přirozeným startem i cílem okruhu. Ve městě sídlí tradiční sklárny a sklářská škola, symbolem je velká skleněná pyramida na náměstí. V dílnách si můžete prohlédnout ruční foukání skla i nakoupit křišťál přímo od výrobců. Zwiesel je zároveň dobrým místem pro tankování a občerstvení před další etapou.', 49.0169, 13.2377, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zwiesel-Glasbl%C3%A4ser-1-Asio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zwiesel-Glasbl%C3%A4ser-1-Asio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Glaspyramide%20in%20Zwiesel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zwiesel,%20Glasberg.JPG"}'::text[], 2),
    (v_route, 'Bodenmais', 'Bodenmais je oblíbené lázeňské a výletní městečko na úpatí Velkého Javoru s upraveným náměstím a řadou sklářských obchodů. Nedaleko se nachází historický důlní vrch Silberberg s návštěvní štolou a bobovou dráhou. Městečko je výhodnou základnou pro výlety k jezeru Großer Arbersee i pro výstup na Javor. Přes Bodenmais vede jedna z nejpříjemnějších motorkářských spojek celého okruhu.', 49.0668, 13.0996, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marktplatz%20Bodenmais.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Marktplatz%20Bodenmais.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bodenmais.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bodenmais%20-%20Panorama%20-%202015.jpg"}'::text[], 3),
    (v_route, 'Korunová stezka Neuschönau (Baumwipfelpfad)', 'Korunová stezka (Baumwipfelpfad) v Neuschönau vede 1,3 km dlouhou dřevěnou lávkou v korunách stromů ve výšce 8 až 25 metrů. Vrcholem stezky je 44 metrů vysoká rozhledová věž ovinutá kolem tří živých stromů s výhledem až na Alpy. Stezka je součástí návštěvnického centra Lusen v národním parku Bavorský les. Jde o ideální rodinnou zastávku a nenáročnou procházku uprostřed lesa.', 48.89113, 13.48465, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baumturm,%20Baumwipfelpfad%20Neusch%C3%B6nau.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baumturm,%20Baumwipfelpfad%20Neusch%C3%B6nau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baumgipfelpfad%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baumwipfelpfad%20mit%20Alpenblick.JPG"}'::text[], 4),
    (v_route, 'Národní park Bavorský les (Nationalpark Bayerischer Wald)', 'Národní park Bavorský les je nejstarší národní park Německa a spolu s českou Šumavou tvoří největší chráněné lesní území ve střední Evropě. Chrání se zde divoký prales, rašeliniště i vzácná zvířata jako rys ostrovid, tetřev nebo jelen. Sítí značených stezek a naučných tras vede krajinou, kterou z velké části utváří přirozený rozklad lesa. Park je zážitkem pro každého, kdo hledá klid a nedotčenou přírodu.', 48.94, 13.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%BCrberg%20Bayerischer%20Wald.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%BCrberg%20Bayerischer%20Wald.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lynx%20Nationalpark%20Bayerischer%20Wald%2001.jpg"}'::text[], 5),
    (v_route, 'Frauenau (muzeum skla)', 'Frauenau je tradiční sklářská obec s významným Muzeem skla (Glasmuseum Frauenau), které mapuje 3000 let historie skla od antiky po moderní design. Součástí je i skleněná zahrada se sochami a informační středisko národního parku. V obci dosud fungují funkční sklárny, kde lze sledovat výrobu naživo. Frauenau je klidnou zastávkou pro milovníky umění a řemesla uprostřed okruhu.', 48.98811, 13.29838, 'https://commons.wikimedia.org/wiki/Special:FilePath/00%204562%20Glasmuseum%20Frauenau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/00%204562%20Glasmuseum%20Frauenau.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/00%204615%20Gl%C3%A4serner%20Garten%20von%20Frauenau.jpg"}'::text[], 6),
    (v_route, 'Regen (hrad Weißenstein)', 'Zřícenina hradu Weißenstein se tyčí na skalnatém křemenném hřbetu Pfahl nad městem Regen v nadmořské výšce 758 metrů. Z dochované věže je nádherný výhled do údolí řeky Regen a na okolní kopce Bavorského lesa. V areálu hradu sídlí literární muzeum věnované spisovateli Siegfriedu von Vegesackovi. Krátká odbočka k hradu je odměnou pro každého motorkáře díky výhledům i klidné atmosféře.', 48.9509, 13.1414, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burgruine%20Wei%C3%9Fenstein%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burgruine%20Wei%C3%9Fenstein%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burgruine%20Wei%C3%9Fenstein%20bei%20Regen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ruine%20Wei%C3%9Fenstein%20Regen.jpg"}'::text[], 7),
    (v_route, 'Lam', 'Lam leží v malebném údolí Lamer Winkel v horní části Bavorského lesa, sevřeném mezi horami Osser a Kaitersberg. Je vyhledávaným výchozím bodem pro turistiku i cyklistiku a příjemnou zastávkou na severním oblouku okruhu. Přes obec vedou klikaté horské silnice s výhledy na česko-bavorské pomezí. Osser na obzoru je symbolickou horou celého kraje.', 49.19718, 13.05089, 'https://commons.wikimedia.org/wiki/Special:FilePath/LamerWinkel.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/LamerWinkel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Osser%20-%20Sept.%202015%20-%20Osserwiese.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Zur Waldbahn (Zwiesel)', 'Hotelová restaurace Zur Waldbahn stojí přímo naproti historickému nádraží ve Zwieselu a patří k nejlépe hodnoceným podnikům ve městě. Nabízí poctivou bavorskou kuchyni, sezónní zvěřinu i ryby z místních potoků a vlídnou obsluhu. Díky poloze u nádraží je snadno dostupná a je ideální na oběd zhruba v první polovině okruhu.', 49.018, 13.236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bahnhof%20Zwiesel%20(Bay)%202016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bahnhof%20Zwiesel%20(Bay)%202016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glaspyramide%20in%20Zwiesel.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Genussrestaurant DAS FRANZ (Bodenmais)', 'Genussrestaurant DAS FRANZ v Bodenmais je vyhlášené vysokým hodnocením a kuchyní spojující tradiční bavorské pokrmy s moderní gastronomií. Restaurace nabízí slunečnou zahradu s výhledem do údolí Zellertal a je příjemným místem na odpočinek zhruba v druhé polovině okruhu. Servírují se zde hearty řízky, zvěřina i lehčí sezónní speciality.', 49.071, 13.087, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bodenmais%20-%20Panorama%20-%202015.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bodenmais%20-%20Panorama%20-%202015.jpg"}'::text[], 10);
