  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bastei (skalní most)', 'Bastei je nejznámější skalní útvar Saského Švýcarska, tyčící se 194 metrů nad řekou Labe. Kamenný Basteibrücke z roku 1851 spojuje skalní věže a nabízí dechberoucí výhled na Labské pískovce. Toto je nejfotografovanější místo celého národního parku.', 50.96146, 14.07306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bastei%20bridge,%20Nationalpark%20S%C3%A4chsische%20Schweiz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bastei%20bridge,%20Nationalpark%20S%C3%A4chsische%20Schweiz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basteibr%C3%BCcke%20morgens.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sachsen,%20Nationalpark%20S%C3%A4chsische%20Schweiz,%20Blick%20auf%20die%20Bastei.JPG"}'::text[], 0),
    (v_route, 'Pevnost Königstein', 'Festung Königstein, přezdívaná „saská Bastila“, je jednou z největších dochovaných horských pevností Evropy. Rozkládá se na stolové hoře vysoko nad Labem a nikdy nebyla dobyta. Z hradeb je úchvatný kruhový výhled na okolní pískovcové skály a údolí řeky.', 50.91917, 14.0574, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20photo%20of%20Festung%20K%C3%B6nigstein,%20October%202008.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20photo%20of%20Festung%20K%C3%B6nigstein,%20October%202008.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6nigstein%20Festung%20Panorama.JPG"}'::text[], 1),
    (v_route, 'Rathen – Amselsee', 'Amselsee je malebné jezírko vzniklé roku 1934 přehrazením potoka Grünbach v lázeňské obci Kurort Rathen. Po hladině obklopené strmými skalami se lze projet na pramicích. Nad jezerem se tyčí skalní útvar zvaný Lokomotive, oblíbený cíl fotografů i milovníků klidu.', 50.96439, 14.08139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kurort%20Rathen%20-%20Amselsee%20mit%20Fels%20Lokomotive.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kurort%20Rathen%20-%20Amselsee%20mit%20Fels%20Lokomotive.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rathen%20-%20Amselsee%20-%20Staumauer%20(Dscn3712).jpg"}'::text[], 2),
    (v_route, 'Lilienstein', 'Lilienstein je nápadná stolová hora vysoká 415 metrů a jediná svého druhu na pravém břehu Labe. Je symbolem národního parku Saské Švýcarsko a poznávacím znamením celé oblasti. Z náhorní plošiny se otevírá jedinečný panoramatický výhled na pevnost Königstein a labský oblouk.', 50.92472, 14.08333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lilienstein%20mountain%20from%20K%C3%B6nigstein%20fortress%20on%20a%20foggy%20morning.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lilienstein%20mountain%20from%20K%C3%B6nigstein%20fortress%20on%20a%20foggy%20morning.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Blick%20von%20der%20Festung%20K%C3%B6nigstein%20auf%20die%20Elbe%20und%20den%20Lilienstein....jpg"}'::text[], 3),
    (v_route, 'Restaurace: zum Franz (Bad Schandau)', 'Restaurace „zum Franz“ na náměstí Marktplatz v lázeňském městě Bad Schandau je nejlépe hodnocenou restaurací v okolí (hodnocení kolem 4,7 na Googlu). Šéfkuchař zde stále vaří osobně a se svým rodinným týmem nabízí čerstvou, poctivou domácí kuchyni. Ideální zastávka na oběd zhruba v polovině okruhu, přímo u historické kašny Sendigbrunnen.', 50.91775, 14.15361, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Schandau-Eberhard%20Wolf-Sendigbrunnen%2010%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Schandau-Eberhard%20Wolf-Sendigbrunnen%2010%2001.JPG"}'::text[], 4),
    (v_route, 'Schrammsteine', 'Schrammsteine tvoří protáhlou, silně rozeklanou skupinu skal východně od Bad Schandau. Vyhlídka Schrammsteinaussicht leží ve výšce kolem 417 metrů a patří ke klasickým panoramatům Saského Švýcarska. Přístup po značených stezkách odměňuje pohledem na divoké pískovcové věže.', 50.92556, 14.19806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schrammsteine%20in%20der%20S%C3%A4chsischen%20Schweiz%20(05).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schrammsteine%20in%20der%20S%C3%A4chsischen%20Schweiz%20(05).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zur%20Schrammsteinaussicht.jpg"}'::text[], 5),
    (v_route, 'Kuhstall', 'Kuhstall je druhá největší přírodní skalní brána Labských pískovců, prolomená ve skalním masivu Neuer Wildenstein nad údolím Kirnitzsch. Mohutným otvorem se otevírá romantický rámovaný výhled do lesnaté krajiny. Úzkým schodištěm zvaným Himmelsleiter lze vystoupat až na vrchol skály.', 50.91556, 14.26472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Felsentor%20Kuhstall%20-%20S%C3%A4chsische%20Schweiz%2022.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Felsentor%20Kuhstall%20-%20S%C3%A4chsische%20Schweiz%2022.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Saechsische%20Schweiz%20-%20neuer%20Wildenstein.jpg"}'::text[], 6),
    (v_route, 'Pirna (staré město)', 'Pirna je půvabné historické město na Labi, označované jako brána do Saského Švýcarska. Malebné náměstí s renesanční radnicí a domem Canaletto zvěčnil na svých obrazech malíř Bernardo Bellotto zvaný Canaletto. Dochované měšťanské domy a dlážděné uličky vytvářejí kouzelnou atmosféru starého města.', 50.96139, 14.03444, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Pirna%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Pirna%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Pirna%209.JPG"}'::text[], 7),
    (v_route, 'Stadt Wehlen', 'Stadt Wehlen je malé idylické městečko na břehu Labe, přezdívané perla Saského Švýcarska. Útulné náměstí s kostelem a přístaviště parníků lákají k příjemnému odpočinku u řeky. Odtud vede řada oblíbených turistických tras do okolních skal, včetně cesty k Bastei.', 50.9578, 14.03188, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dorf%20Wehlen%20Nationalpark%20S%C3%A4chsische%20Schweiz.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dorf%20Wehlen%20Nationalpark%20S%C3%A4chsische%20Schweiz.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Markt%204%20Stadt%20Wehlen%204.JPG"}'::text[], 8);
