  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pottenstein – Teufelská jeskyně (Teufelshöhle)', 'Teufelshöhle je jedna z největších krápníkových jeskyní Německa a hlavní přírodní skvost městečka Pottenstein. Návštěvníky provede zhruba tři čtvrtě kilometru dlouhá trasa mezi mohutnými stalaktity a stalagmity, mezi nimiž vyniká útvar zvaný Barbarossův vous. Nad městem se tyčí středověký hrad a okolní skalní stěny lákají horolezce, takže je to ideální výchozí bod celého okruhu.', 49.75435, 11.42007, 'https://commons.wikimedia.org/wiki/Special:FilePath/Teufelsh%C3%B6hle%2CBarbarossabart.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Teufelsh%C3%B6hle%2CBarbarossabart.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pottenstein%20Grosses%20Hasenloch.JPG"}'::text[], 0),
    (v_route, 'Tüchersfeld – Fränkische-Schweiz-Museum', 'Tüchersfeld je pokládán za symbol celého Franského Švýcarska díky hrázděným domům, které jako by byly nalepené přímo na bílé skalní věže. V historickém Judenhofu, komplexu domů z 18. století, dnes sídlí Fränkische-Schweiz-Museum přibližující geologii, dějiny a lidovou kulturu regionu. Nad vesnicí se zvedají dvě skalní jehly, na nichž kdysi stály hrady Ober- a Niederntüchersfeld.', 49.7678, 11.4266, 'https://commons.wikimedia.org/wiki/Special:FilePath/Felsburg%20T%C3%BCchersfeld.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Felsburg%20T%C3%BCchersfeld.jpg"}'::text[], 1),
    (v_route, 'Gößweinstein – bazilika a hrad', 'Gößweinsteinu vévodí trojiční poutní bazilika, kterou v letech 1730–1739 postavil podle plánů geniálního barokního architekta Balthasara Neumanna. Kousek nad ní stojí středověký hrad Gößweinstein, jehož silueta se skvěle vyjímá nad údolím tří řek. Obě dominanty patří k nejfotografovanějším místům Franského Švýcarska a nabízejí nádherné výhledy do okolní skalní krajiny.', 49.77, 11.34, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goessweinstein-Basilika2-Asio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Goessweinstein-Basilika2-Asio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6%C3%9Fweinstein%20Burg%20Luftbild-20220717-RM-172842.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basilika-Apotheke%20G%C3%B6ssweinstein%20Marktplatz.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Gasthof Zur Guten Einkehr (Gößweinstein-Morschreuth)', 'Rodinný Gasthof Zur Guten Einkehr v obci Morschreuth patří s hodnocením kolem 4,7 hvězdičky k nejoblíbenějším hospůdkám v okolí Gößweinsteinu. Kuchyně sází na poctivou franckou stravu a řízky, chválena bývá i přátelská obsluha a příjemný poměr cena/výkon. Leží zhruba v polovině okruhu, takže je to ideální místo na vydatný oběd a odpočinek uprostřed dne.', 49.75514, 11.26549, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilika-Apotheke%20G%C3%B6ssweinstein%20Marktplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilika-Apotheke%20G%C3%B6ssweinstein%20Marktplatz.jpg"}'::text[], 3),
    (v_route, 'Streitberg – zřícenina Streitburg a Neideck', 'Streitberg je jedny z nejstarších klimatických lázní Franského Švýcarska a leží v malebném údolí řeky Wiesent. Nad obcí se tyčí zřícenina hradu Streitburg a na protějším skalním ostrohu ruina Neideck, symbol celého kraje. Skalní stěny nad obcí, například tzv. Matterhornwand, patří k oblíbeným horolezeckým cílům.', 49.78333, 11.26667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Streitburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Streitburg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wiesenttal-Ruine-Neideck-P5083407.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Streitberg%20Matterhornwand%203040104.jpg"}'::text[], 4),
    (v_route, 'Muggendorf', 'Muggendorf je společně se Streitbergem nejstarší lázeňskou obcí Franského Švýcarska a dodnes si drží klidný lázeňský ráz. Leží přímo na řece Wiesent ve výšce kolem 304 metrů a je ideálním východiskem k okolním jeskyním a skalním vyhlídkám. Dominantou obce je farní kostel svatého Vavřince a historická radnice.', 49.80222, 11.26139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muggendorf%20Kirche%20-20191020-RM-103635.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muggendorf%20Kirche%20-20191020-RM-103635.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Muggendorf.jpg"}'::text[], 5),
    (v_route, 'Sanspareil – skalní zahrada a hrad Zwernitz', 'Skalní zahrada Sanspareil u obce Wonsees je jedinečný krajinářský park, který vznikl v letech 1744–1748 z popudu markraběnky Wilhelminy z Bayreuthu. Zahrada důmyslně využívá přírodní skalní útvary franckého Jury a doplňuje je romantickými stavbami, jako je Morgenländischer Bau a skalní ruinové divadlo. Přímo v areálu stojí středověký hrad Zwernitz s románským jádrem z roku 1200.', 49.9833, 11.36, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wonsees%2C%20Felsengarten%20Sanspareil%2C%20Morgenl%C3%A4ndischer%20Bau.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wonsees%2C%20Felsengarten%20Sanspareil%2C%20Morgenl%C3%A4ndischer%20Bau.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wonsees%2C%20Felsengarten%20Sanspareil%2C%20Ruinentheater%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Felsengarten%20Sanspareil%20Aeolusfelsen%20006.JPG"}'::text[], 6),
    (v_route, 'Hrad Rabenstein (Ahorntal)', 'Vrcholně středověký ostrožný hrad Rabenstein se tyčí na skalním výběžku nad údolím Ailsbachu, asi šest a půl kilometru severozápadně od Pottensteinu. Dnes v něm funguje hotel a hrad je proslulý zejména sokolnickými ukázkami, tedy leteckými představeními dravců. V podhradí leží kapová jeskyně Sophienhöhle, jedna z nejkrásnějších kapkových jeskyní regionu.', 49.8237, 11.3695, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Rabenstein-1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Rabenstein-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg-Rabenstein-Ailsbachtal-P1290149.jpg"}'::text[], 7),
    (v_route, 'Bamberg – historické centrum (UNESCO)', 'Bamberg je světové dědictví UNESCO a jedno z nejlépe dochovaných středověkých měst Německa, rozložené na sedmi pahorcích nad řekou Regnitz. Jeho nejslavnější stavbou je Staré radnice (Altes Rathaus) postavená přímo na ostrůvku uprostřed řeky a spojená s oběma břehy mosty. Nad městem se zvedá katedrála (Bamberger Dom) se čtyřmi věžemi a proslulou sochou Bamberského jezdce; město je také rájem pivařů díky svému uzenému pivu Rauchbier.', 49.89173, 10.88631, 'https://commons.wikimedia.org/wiki/Special:FilePath/Altes%20Rathaus%20(Bamberg)%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Altes%20Rathaus%20(Bamberg)%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bamberg%20Altes%20Rathaus%20BW%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bamberg%20Altes%20Rathaus%202.JPG"}'::text[], 8);
