  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Szczeliniec Wielki (Stolové hory / Góry Stołowe)', 'Szczeliniec Wielki je s výškou 919 m nejvyšším vrcholem Stolových hor a jedním z nejpůsobivějších skalních útvarů celé Kladské kotliny. Na vrchol vede od parkoviště v Karłówě strmé kamenné schodiště a nahoře čeká labyrint pískovcových věží, průrev a vyhlídek s dechberoucím rozhledem do Polska i Čech. Skalní útvary mají malebná jména jako Velbloud či Opičák a turistická stezka vede úzkými roklemi mezi obřími bloky.', 50.48438, 16.3416, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki_2007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Piekielko.JPG"}'::text[], 0),
    (v_route, 'Błędne Skały', 'Błędne Skały neboli Bludné skály tvoří bludiště obrovských pískovcových bloků ve výšce kolem 850 m nedaleko Kudowy-Zdrój. Značená stezka vede úzkými skalními průchody, které jsou místy tak těsné, že se jimi člověk protahuje jen bokem. Toto skalní město patří k nejfotogeničtějším místům Stolových hor a bylo kulisou i pro filmové Narnie. Na motorce sem vede úzká horská příjezdová silnice s řízeným střídavým provozem.', 50.46109, 16.30917, 'https://commons.wikimedia.org/wiki/Special:FilePath/B%C5%82%C4%99dne%20Ska%C5%82y.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/B%C5%82%C4%99dne%20Ska%C5%82y.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bledne_kolo.jpg"}'::text[], 1),
    (v_route, 'Kudowa-Zdrój', 'Kudowa-Zdrój je jedno z nejstarších a nejznámějších lázeňských měst v Kladské kotlině, ležící přímo u hranice s Českem. Srdcem města je rozlehlý lázeňský park (park zdrojowy) s pramennou halou, fontánami a květinovými záhony, který zve k procházce i odpočinku. Město je ideální výchozí bod pro výlety do Stolových hor a nabízí spoustu kaváren i restaurací. Klidná lázeňská atmosféra je příjemným kontrastem k adrenalinovým horským silnicím okolí.', 50.44272, 16.24266, 'https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2009.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2009.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2013.JPG"}'::text[], 2),
    (v_route, 'Wambierzyce (bazilika)', 'Wambierzyce jsou proslulé barokní bazilikou Navštívení Panny Marie, jednomu z nejvýznamnějších poutních míst Dolního Slezska. Monumentální chrám z let 1715–1723 stojí na vrcholu širokého schodiště a bývá označován jako Slezský Jeruzalém. V okolí se rozkládá rozsáhlá kalvárie s desítkami kaplí a poutních zastavení. Interiér baziliky s bohatou štukovou a malířskou výzdobou patří k vrcholům slezského baroka.', 50.49013, 16.45584, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wambierzyce%20-%20Bazylika.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wambierzyce%20-%20Bazylika.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wambierzyce,%20bazylika,%2003.JPG"}'::text[], 3),
    (v_route, 'Kłodzko (pevnost + podzemí)', 'Kłodzko je historické centrum celé kotliny s mohutnou pruskou pevností tyčící se nad městem na Pevnostní hoře. Rozsáhlý fortifikační komplex nabízí prohlídku hradeb, kasemat a labyrintu chodeb, ke kterému patří i známé podzemní turistické trasy protkávající skalní podloží pod městem. Ze zdí pevnosti je nádherný výhled na staré město s gotickým mostem svatého Jana. Kłodzko je přirozeným centrem a dobrým místem na oběd i nocleh během okruhu.', 50.44139, 16.65306, 'https://commons.wikimedia.org/wiki/Special:FilePath/2014%20K%C5%82odzko,%20don%C5%BCon%20na%20twierdzy%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2014%20K%C5%82odzko,%20don%C5%BCon%20na%20twierdzy%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2024%20Galeria%20Twierdza%20K%C5%82odzko%20(01).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Restauracja Korona (Kłodzko)', 'Restauracja Korona v Kłodzku je oblíbený podnik s hodnocením kolem 4,7 hvězdičky a tisíci spokojených hostů. Servíruje poctivou polskou i regionální kuchyni Kladské kotliny za rozumné ceny, ideální na vydatný oběd v polovině okruhu. Nachází se jen pár minut od náměstí a pevnosti, takže se dá snadno spojit s prohlídkou města.', 50.4349, 16.6615, 'https://commons.wikimedia.org/wiki/Special:FilePath/2024%20Galeria%20Twierdza%20K%C5%82odzko%20(07).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2024%20Galeria%20Twierdza%20K%C5%82odzko%20(07).jpg"}'::text[], 5),
    (v_route, 'Restaurace: Restauracja Merkury (Kudowa-Zdrój)', 'Restauracja Merkury v Kudowě-Zdrój patří s hodnocením kolem 4,8 hvězdičky a tisíci recenzí k nejlepším podnikům v celé kotlině a nese titul Perła Ziemi Kłodzkiej. Kuchyně kombinuje regionální, polské a italské speciality a je skvělou volbou na oběd před nebo po výletu do Stolových hor. Podnik na ulici Zdrojowa je snadno dostupný přímo v centru lázní.', 50.44272, 16.24266, 'https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2014%20Kudowa-Zdr%C3%B3j,%20park%20zdrojowy%2013.JPG"}'::text[], 6),
    (v_route, 'Bystrzyca Kłodzka', 'Bystrzyca Kłodzka je malebné středověké městečko s dochovaným historickým jádrem, hradbami a strmými uličkami stoupajícími k náměstí. Dominantou rynku je renesanční radnice s vyhlídkovou věží, ze které je krásný rozhled do údolí. Město proslulo unikátním Muzeem hasičství i výrobou zápalek a nabízí klidnou atmosféru mimo hlavní turistické proudy. Příjezd sem vede po pěkných venkovských silnicích podél řeky Nysy Kłodzkiej.', 50.30179, 16.64231, 'https://commons.wikimedia.org/wiki/Special:FilePath/2015%20Ratusz%20w%20Bystrzycy%20K%C5%82odzkiej%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2015%20Ratusz%20w%20Bystrzycy%20K%C5%82odzkiej%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bystrzyca%20K%C5%82odzka,%20Rynek%2010,%2011.JPG"}'::text[], 7),
    (v_route, 'Duszniki-Zdrój (Muzeum papírnictví)', 'Duszniki-Zdrój jsou historické lázně proslulé Muzeem papírnictví umístěným v unikátním papírenském mlýně ze 16. století. V dochované manufaktuře si lze prohlédnout dobové stroje a dokonce si vlastnoručně vyrobit list ručního papíru středověkou metodou. Město bývalo oblíbeným místem pobytu Fryderyka Chopina, po němž je pojmenován zdejší klavírní festival. Lázeňský park a klidné okolí jsou příjemnou zastávkou při návratu okruhu.', 50.4045, 16.39549, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki%20-%20muzeum.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki%20-%20muzeum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2015%20Otoczenie%20papierni%20w%20Dusznikach-Zdroju%2001.JPG"}'::text[], 8),
    (v_route, 'Zlatý Stok / Złoty Stok (jeskyně a zlatý důl)', 'Złoty Stok, česky Zlatý Stok, je nejstarší hornické město v Polsku, kde se po staletí těžilo zlato a arzén. Dnes je zde přístupný historický zlatý důl s podzemními štolami, které lze projít pěšky i svézt se důlním vláčkem. Největší atrakcí je jediný podzemní vodopád v Polsku ukrytý hluboko ve skále. Prohlídka dolu i muzea je poutavým zakončením okruhu Kladskou kotlinou nedaleko cesty zpět k českým Zlatým Horám.', 50.43983, 16.87475, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%82oty%20Stok%20-%20Muzeum%20Kopalni%20Z%C5%82ota.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%82oty%20Stok%20-%20Muzeum%20Kopalni%20Z%C5%82ota.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gold%20Mine%20Z%C5%82oty%20Stok%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%82oty%20Stok%20Underground%20Waterfall.JPG"}'::text[], 9);
  insert into public.routes
