  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Wodospad Kamieńczyka (Szklarska Poręba)', 'Nejvyšší vodopád polských Sudet padá ve třech kaskádách z výšky 27 metrů do divoké skalní rokle. Voda se dere úzkým žulovým kaňonem obklopeným smrkovým lesem Krkonošského národního parku. K vodopádu vede pohodlná značená stezka ze Szklarské Poręby, na jejímž konci se otvírá jedno z nejfotogeničtějších míst celých hor.', 50.81365, 15.49683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska%20Por%C4%99ba,%20wodospad%20Kamie%C5%84czyka%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska%20Por%C4%99ba,%20wodospad%20Kamie%C5%84czyka%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wodospad%20Kamie%C5%84czyka%20(Zackelfall).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska%20Por%C4%99ba,%20Wodospad%20Kamie%C5%84czyka%20(Zackelfall1).jpg"}'::text[], 0),
    (v_route, 'Kostel Wang (Karpacz)', 'Dřevěný roubený kostel ve stylu norských stavkirke pochází z přelomu 12. a 13. století a byl v roce 1842 rozebrán a přivezen z Norska do Karpacze. Je to nejstarší dřevěná svatyně tohoto typu v Polsku a jediná svého druhu na sever od Alp. Stavba bez jediného hřebíku stojí v horské zahradě s kamennou zvonicí a starým hřbitovem s výhledem na hřebeny Krkonoš.', 50.77759, 15.7238, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karpacz%20Poland%20Church%20Wang%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karpacz%20Poland%20Church%20Wang%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karpacz%20Swiatynia%20Wang.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karpacz,%20Ko%C5%9Bci%C3%B3%C5%82%20Wang,%20wn%C4%99trze%2001.JPG"}'::text[], 1),
    (v_route, 'Śnieżka (polská strana)', 'Śnieżka (česky Sněžka) je s 1603 metry nejvyšší hora Krkonoš a celých Sudet. Na jejím vrcholu se nachází charakteristická meteorologická observatoř tvaru létajících talířů a česká poštovna, přičemž hřebenem prochází polsko-česká hranice. Z holého vrcholu se za jasného počasí otevírá kruhový výhled na oba svahy pohoří. Výstup po polské straně je fyzicky náročný a odměnou je jeden z nejlepších rozhledů ve střední Evropě.', 50.73595, 15.73978, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Anie%C5%BCka%20z%20zachodu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Anie%C5%BCka%20z%20zachodu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sn%C4%9B%C5%BEka%20a%20Ob%C5%99%C3%AD%20d%C5%AFl.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sniezka%20from%20krucze%20skaly.jpg"}'::text[], 2),
    (v_route, 'Hrad Chojnik (Sobieszów)', 'Malebná zřícenina gotického hradu z 14. století korunuje zalesněný vrchol Chojnik nad Jelení Horou. Z jihovýchodní strany hrad chrání strmý 150metrový sráz spadající do Pekelné doliny. Na hrad, jenž nikdy nebyl dobyt, vede příjemná lesní stezka Krkonošským národním parkem a z jeho věže je široký výhled na krkonošské hřebeny.', 50.83427, 15.64431, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chojnik%20Castle%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chojnik%20Castle%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Chojnik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Chojnik%20(Burgruine-Kynast10).jpg"}'::text[], 3),
    (v_route, 'Jelenia Góra (Plac Ratuszowy)', 'Historické město pod Krkonošemi láká barevným náměstím Plac Ratuszowy s barokní radnicí a podloubím měšťanských domů. Jelenia Góra je přirozenou branou do polských hor a ideálním místem k přenocování mezi oběma dny cesty. Večerní procházka starým městem a posezení na náměstí jsou příjemným završením prvního dne.', 50.90441, 15.71936, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Kuźnia Smaku (Jelenia Góra)', 'Oblíbená restaurace přímo na náměstí Plac Ratuszowy v srdci Jelení Hory s vysokým hodnocením návštěvníků. Nabízí poctivou polskou i regionální kuchyni v příjemném prostředí starého města. Ideální zastávka pro nocleh a večeři na konci prvního dne cesty.', 50.90435, 15.71945, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia%20G%C3%B3ra,%20Plac%20Ratuszowy%2016.JPG"}'::text[], 5),
    (v_route, 'Zámek Książ (Wałbrzych)', 'Třetí největší zámek v Polsku, hned po Malborku a Wawelu, se tyčí na skalním ostrohu obklopeném lesy a terasovitými zahradami. Původně středověká pevnost byla postupně přestavěna do impozantní barokní a novorenesanční rezidence. Za druhé světové války v podzemí zámku Němci vybudovali tajemný systém tunelů, který dodnes obestírají legendy o ukrytých pokladech.', 50.8378, 16.29501, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wa%C5%82brzych,%20zamek%20Ksi%C4%85%C5%BC%20(Aw58)MW%20DSC07533.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wa%C5%82brzych,%20zamek%20Ksi%C4%85%C5%BC%20(Aw58)MW%20DSC07533.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wa%C5%82brzych,%20tarasy%20na%20zamku%20Ksi%C4%85%C5%BC(MW)%20-%209%20VIII%202009%20r..JPG"}'::text[], 6),
    (v_route, 'Restaurace: Rynek 43 (Świdnica)', 'Nejlépe hodnocená restaurace ve Świdnici se nachází v romantickém dvorku přímo pod věží radnice na hlavním náměstí. Kuchyně sází na kreativní pojetí tradičních polských jídel z lokálních surovin. Klidné posezení na patiu je příjemnou zastávkou zhruba v polovině druhého dne cesty.', 50.8458, 16.4892, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg"}'::text[], 7),
    (v_route, 'Kostel míru (Świdnica, UNESCO)', 'Kostel míru ve Świdnici je největší dřevěná barokní sakrální stavba v Evropě a od roku 2001 je zapsán na seznamu světového dědictví UNESCO. Byl postaven po vestfálském míru, který ukončil třicetiletou válku, a to pouze z dřeva, hlíny a slámy a bez věže. Uvnitř ohromuje bohatě zdobený interiér s galeriemi, malovaným stropem a barokními varhanami, který pojme několik tisíc věřících.', 50.84652, 16.49164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82%20Pokoju%20w%20%C5%9Awidnicy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kosciol%20pokoju%20w%20swidnicy%20wisnia6522.jpg"}'::text[], 8),
    (v_route, 'Wrocław (Rynek a trpaslíci)', 'Vratislavský Rynek patří k největším a nejkrásnějším středověkým náměstím v Evropě, jemuž vévodí gotická radnice s bohatě zdobenou fasádou. Kolem dokola stojí pestrobarevné měšťanské domy s kavárnami a restauracemi. Po celém městě se skrývají desítky bronzových soch trpaslíků (krasnale), které se staly milovaným symbolem Vratislavi a oblíbenou hrou pro návštěvníky všech věků.', 51.1097, 17.0326, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wroc%C5%82aw,%20Rynek-Ratusz%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wroc%C5%82aw,%20Rynek-Ratusz%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wroclaw%20krasnal%20Zyczliwek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rynek%20(Market%20Square)%20Scene%20-%20Wroclaw%20-%20Poland%20-%2005%20(9186360842).jpg"}'::text[], 9);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Wawelský hrad (Kraków)', 'Královský hrad na Wawelu je symbolem polské státnosti a bývalým sídlem polských králů. Renesanční arkádové nádvoří, katedrála s korunovačními hrobkami a legenda o wawelském drakovi z něj dělají nejnavštěvovanější památku Krakova. Skalní ostroh nad Vislou nabízí nádherné výhledy na řeku i staré město.', 50.0544, 19.9354, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wawel%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wawel%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wawel%20Royal%20Castle%20courtyard%20in%20Krak%C3%B3w,%20Poland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krak%C3%B3w%20-%20Wawel%20-%20Widok%20od%20wschodu%2001.jpg"}'::text[], 0),
    (v_route, 'Rynek Główny (Kraków)', 'Hlavní náměstí Krakova je jedno z největších středověkých náměstí v Evropě o rozloze kolem 40 000 m². Dominuje mu renesanční tržnice Sukiennice, gotická věž bývalé radnice a bazilika Nanebevzetí Panny Marie, z jejíž věže každou hodinu zaznívá hejnal. Živé náměstí plné kaváren, kočárů a pouličních umělců je přirozeným srdcem starého města.', 50.0617, 19.9367, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sukiennice%20and%20Main%20Market%20Square%20Krakow%20Poland.JPG"}'::text[], 1),
    (v_route, 'Solný důl Wieliczka (UNESCO)', 'Solný důl ve Wieliczce patří k nejstarším fungujícím dolům na světě a je zapsán na seznamu UNESCO. V hloubkách přes sto metrů se skrývají solné komory, podzemní jezera a ohromující kaple svaté Kingy vytesaná zcela ze soli včetně lustrů. Turistická trasa vede desítkami sálů a je zážitkem pro celou rodinu.', 49.98349, 20.05503, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%20salt%20mine.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%20salt%20mine.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%20salt%20mine%20Poland%2054.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%20salt%20mine%20chandelier.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Pod Aniołami (Kraków)', 'Stylová restaurace Pod Aniołami se nachází v gotických sklepích na ulici Grodzka mezi Rynkiem a Wawelem a nabízí tradiční polskou kuchyni s hodnocením kolem 4,4. Grilovaná jídla, pierogi a staropolské speciality doplňuje romantická atmosféra cihlových kleneb. Je to ideální zastávka na oběd během prvního dne v centru Krakova.', 50.06194, 19.93778, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krakow%20(Rynek%20Glowny%20-%20Sukiennice).JPG"}'::text[], 3),
    (v_route, 'Maczuga Herkulesa (Ojcowski NP)', 'Maczuga Herkulesa neboli Herkulův kyj je nápadná vápencová skalní věž vysoká přes 25 metrů v Ojcovském národním parku. Osamocený monolit u paty zámku Pieskowa Skała je oblíbeným cílem turistů i horolezců a opřádá jej legenda o čertovi, který sem kyj přinesl. Skála je jedním z nejfotografovanějších přírodních útvarů Krakovsko-čenstochovské jury.', 50.233, 19.781, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maczuga-Herkulesa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maczuga-Herkulesa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Maczuga%20Herkulesa%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ojc%C3%B3w-Maczuga-Herkulesa-front.jpg"}'::text[], 4),
    (v_route, 'Zámek Pieskowa Skała', 'Renesanční zámek Pieskowa Skała se tyčí na skále nad údolím Prądniku a je nejlépe dochovaným renesančním sídlem v okolí Krakova. Krásné arkádové nádvoří a expozice muzea připomínají jeho slavnou minulost jako součásti obranných tzv. Orlích hnízd. Ze zámeckých teras se otevírá výhled na Herkulův kyj i okolní bukové lesy národního parku.', 50.23306, 19.78056, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Pieskowa%20Skala.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Pieskowa%20Skala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20190525%20Zamek%20w%20Pieskowej%20Skale%200824%202492%20DxO.jpg"}'::text[], 5),
    (v_route, 'Kalwaria Zebrzydowska (UNESCO)', 'Poutní komplex Kalwaria Zebrzydowska je manýristický architektonický a krajinný park zapsaný na seznamu UNESCO. Bazilika Panny Marie Andělské a desítky kaplí rozesetých v kopcích tvoří symbolickou křížovou cestu, kam každoročně proudí tisíce poutníků. Klidné prostředí bernardinského kláštera zve k procházce i rozjímání s výhledy do kraje.', 49.86021, 19.67158, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanktuarium%20pasyjno-maryjne%20w%20Kalwarii%20Zebrzydowskiej1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sanktuarium%20pasyjno-maryjne%20w%20Kalwarii%20Zebrzydowskiej1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kalwaria%20Zebrzydowska%20-%20Bazylika-060GP.jpg"}'::text[], 6),
    (v_route, 'Wadowice', 'Wadowice jsou rodným městem papeže Jana Pavla II. a poutním cílem věřících z celého světa. Vévodí mu bazilika Obětování Panny Marie, kde byl budoucí papež pokřtěn, a hned vedle muzeum v jeho rodném domě. Nezapomenutelné jsou i místní krémové řezy zvané kremówki, které papež v mládí miloval.', 49.8834, 19.4929, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wadowice,%20Bazylika%20Mniejsza.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wadowice%20-%20Basilica%20A.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Pestka Restaurant (Wadowice)', 'Restaurace Pestka leží jen pár kroků od náměstí Jana Pavla II. v centru Wadowic a patří k nejlépe hodnoceným místům ve městě (kolem 4,4). Nabízí polskou i evropskou kuchyni v příjemném moderním prostředí a je vhodnou zastávkou na oběd během druhého dne. Ideální pauza před přejezdem k opatství Tyniec.', 49.8845, 19.4938, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20Wadowice.jpg"}'::text[], 8),
    (v_route, 'Opatství Tyniec (benediktini)', 'Benediktinské opatství v Tyńci je nejstarší klášter na polském území, založený v 11. století. Malebně se tyčí na vápencové skále nad zákrutem Visly a nabízí klidné nádvoří, románsko-gotický kostel svatého Petra a Pavla i vyhlídku na řeku. Klášter dodnes žije mnišským životem a láká poutníky i milovníky ticha.', 50.01895, 19.80211, 'https://commons.wikimedia.org/wiki/Special:FilePath/Opactwo%20benedyktynow%20w%20Tyncu%2012.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Opactwo%20benedyktynow%20w%20Tyncu%2012.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Opactwo%20benedyktynow%20w%20Tyncu%2020.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Krak%C3%B3w%20-%20Tyniec,%20klasztor%20benedyktyn%C3%B3w,%20kru%C5%BCganki.jpg"}'::text[], 9),
    (v_route, 'Zakrzówek (Kraków)', 'Zakrzówek je bývalý vápencový lom v Krakově, který se po zatopení proměnil v jezero s tyrkysovou vodou a strmými skalními stěnami. Dnes je z něj oblíbený rekreační park s koupacími zónami, plážemi a vyhlídkami nad vodní hladinou. Skalky Twardowského nad jezerem lákají horolezce a nabízejí krásné výhledy jako klidné zakončení celé trasy.', 50.03675, 19.91037, 'https://commons.wikimedia.org/wiki/Special:FilePath/ZAKRZ%C3%93WEK%20Krak%C3%B3w%200061.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ZAKRZ%C3%93WEK%20Krak%C3%B3w%200061.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20in%20Zakrz%C3%B3wek,%20Krak%C3%B3w.JPG"}'::text[], 10);
