  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rovinj – kostel sv. Eufemie', 'Barokní kostel sv. Eufemie se tyčí na vrcholu starého města Rovinje a jeho 60 metrů vysoká zvonice s měděnou sochou světice je symbolem celého poloostrova. Uvnitř je uložen sarkofág svaté Eufemie, patronky města, a z ochozu věže se otevírá jeden z nejkrásnějších výhledů na istrijské pobřeží. Úzké dlážděné uličky pod kostelem lákají k procházce a jsou ideálním startem celé okružní trasy.', 45.08318, 13.63098, 'https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Rovinj%20St%20Euphemia%20church%20BW%202014-10-08%2014-23-33.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Rovinj%20St%20Euphemia%20church%20BW%202014-10-08%2014-23-33.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rovinj-Basilica%20Saint%20Euphemia-2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rovinj%20Saint%20Euphemia%20tower%20view%2001.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Monte (Rovinj)', 'Restaurace Monte se nachází přímo pod kostelem sv. Eufemie v samém srdci starého Rovinje a je držitelem michelinské hvězdy. Kuchyně tvůrčím způsobem propojuje istrijské suroviny se světovou gastronomií a spolu s rozsáhlým vinným lístkem patří k tomu nejlepšímu, co lze na poloostrově ochutnat. Rezervace předem je nutná, atmosféra rustikálně elegantní.', 45.0817, 13.636, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rovinj%20Saint%20Euphemia%20tower%20limestone%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rovinj%20Saint%20Euphemia%20tower%20limestone%2001.jpg"}'::text[], 1),
    (v_route, 'Limský záliv (Limska draga)', 'Limský záliv je desetikilometrový úzký mořský fjord vklíněný mezi zalesněné svahy mezi Rovinjem a Vrsarem. Geologicky jde o největší ria ve Středozemním moři – zatopené říční údolí, kde se stýká sladká a slaná voda. Klidná hladina se zrcadlí mezi strmými srázy a nabízí ideální zastávku na fotografování i ochutnávku místních ústřic a slávek přímo od pěstitelů.', 45.13701, 13.72088, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limski%20Istria%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limski%20Istria%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limski%20Zaljev%20-%20Rezervat%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Limski%20Zaljev%20-%20Rezervat%203.JPG"}'::text[], 2),
    (v_route, 'Poreč – Eufraziova bazilika (UNESCO)', 'Eufraziova bazilika v Poreči je od roku 1997 zapsána na seznamu světového dědictví UNESCO a představuje nejúplněji dochovaný raně křesťanský biskupský komplex svého druhu. Byzantské mozaiky v apsidě ze 6. století patří k nejcennějším uměleckým dílům na Jadranu a spolu s baptistériem, atriem a biskupským palácem tvoří jedinečný celek. Historické centro Poreče na poloostrově je samo o sobě příjemné k procházce.', 45.22869, 13.59389, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Euphrasian%20Basilica%20in%20the%20Historic%20Centre%20of%20Pore%C4%8D%20-%20panoramio%20(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Euphrasian%20Basilica%20in%20the%20Historic%20Centre%20of%20Pore%C4%8D%20-%20panoramio%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pore%C4%8D,%20Euphrasian%20Basilica,%20mosaic.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pore%C4%8D%20Basilica%203.jpg"}'::text[], 3),
    (v_route, 'Grožnjan', 'Grožnjan je romantické městečko umělců posazené na kopci nad údolím řeky Mirny. Od roku 1965, kdy bylo vyhlášeno městem umělců, se do jeho úzkých uliček nastěhovali malíři, sochaři a hudebníci a dnes zde najdete přes dvacet galerií a ateliérů. Kamenné domy, loubí a květinami obrostlé uličky vytvářejí neopakovatelnou tvůrčí atmosféru, kterou v létě doplňují hudební festivaly.', 45.37728, 13.72145, 'https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Gro%C5%BEnjan%20ulica%20Umberta%20Gorjana-1574.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Gro%C5%BEnjan%20ulica%20Umberta%20Gorjana-1574.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Crkva%20sv.%20Kuzme%20i%20Damjana%20(Gro%C5%BEnjan)%201.jpg"}'::text[], 4),
    (v_route, 'Motovun – hradby', 'Motovun je asi nejznámější istrijské kopcovité město, obklopené prstencem středověkých hradeb, věží a městských bran budovaných mezi 14. a 17. stoletím. Z ochozu se otevírá kruhový výhled na vinice a lesy Motovunské doliny, kde se sbírají vyhlášené lanýže. Kombinace románských, gotických a renesančních prvků z Motovunu dělá jednu z nejfotogeničtějších zastávek celé trasy.', 45.33432, 13.82522, 'https://commons.wikimedia.org/wiki/Special:FilePath/Motovun%20%E2%80%93%20General%20view%20-%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Motovun%20%E2%80%93%20General%20view%20-%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20to%20Motovun.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Motovun%20-%20Castle%20gates%20-%2002.jpg"}'::text[], 5),
    (v_route, 'Pazin – jáma a hrad', 'Pazinský hrad (Kaštel) je největší a nejlépe zachovaná pevnost v Istrii, postavená na skále nad hlubokou propastí Pazinské jámy. Ponorná říčka Pazinčica se zde propadá do podzemí a dramatický kaňon prý inspiroval Julese Verna i Danteho. V hradu dnes sídlí Etnografické muzeum Istrie a Pazinské městské muzeum, nad propastí se dá projet i adrenalinovou zipline.', 45.24028, 13.93056, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pazin%20Burg%20-%20Torhalle%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pazin%20Burg%20-%20Torhalle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pazin%20(Fojba-Schlucht)%201.jpg"}'::text[], 6),
    (v_route, 'Hum – nejmenší město', 'Hum je zapsán jako nejmenší město na světě – žije v něm sotva třicet obyvatel a tvoří ho jen dvě uličky uvnitř středověkých hradeb. Poprvé je zmiňován roku 1102 a na jeho západní straně jsou domy vestavěny přímo do obranných zdí. Hum je také koncovým bodem sedmikilometrové Glagolské aleje z Roče a proslul výrobou tradiční jmelové pálenky biska.', 45.34833, 14.04528, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hum%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hum%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hum,%20Croatia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hum%E2%80%93The%20town%20gate-02.jpg"}'::text[], 7),
    (v_route, 'Pula – amfiteátr Arena', 'Pulská Arena je jeden z nejlépe dochovaných římských amfiteátrů na světě a šestý největší svého druhu. Byla postavena v 1. století a pojala až 20 000 diváků, kteří přicházeli na gladiátorské zápasy. Dnes se v jejích monumentálních obloucích konají koncerty a filmový festival; zachovaný vnější plášť ze čtyř pater vápence patří k nejpůsobivějším antickým památkám Jadranu.', 44.87322, 13.85013, 'https://commons.wikimedia.org/wiki/Special:FilePath/Amphitheater%20Pula.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Amphitheater%20Pula.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arena%20pula%20inside.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Croatia%20Pula%20Amphitheatre%202014-10-11%2011-04-27.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Konoba Batelina (Banjole)', 'Konoba Batelina v rybářské vesnici Banjole u Puly patří k nejuznávanějším rybím restauracím v celém Chorvatsku a je oceněna michelinským Bib Gourmand. Filozofie „z moře na stůl“ znamená, že se menu tvoří každý den podle toho, co ráno přivezou rybáři – tištěný jídelníček proto nečekejte, číšník vše představí ústně. Rezervace je nutná a večeře zde je zážitkem, který ocení každý milovník darů moře.', 44.8167, 13.8667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Amfi%20pula.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Amfi%20pula.JPG"}'::text[], 9);
