  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Národní park Plitvická jezera', 'Nejstarší a nejnavštěvovanější chorvatský národní park zapsaný na seznamu UNESCO, proslulý soustavou šestnácti tyrkysových jezer spojených bezpočtem vodopádů a kaskád. Vápencové travertinové bariéry zde vytvořily jedinečnou krajinu, kterou návštěvníci obcházejí po dřevěných chodníčcích přímo nad vodní hladinou. Doporučujeme dorazit brzy ráno, zaparkovat u vstupu 1 nebo 2 a vyhradit si na okruh několik hodin. Je to ideální startovní bod celé trasy do vnitrozemí Liky.', 44.8806, 15.6161, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plitvice%20Lakes%20National%20Park%2064.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plitvice%20Lakes%20National%20Park%2064.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Plitvice%20Lakes%20National%20Park%203.JPG"}'::text[], 0),
    (v_route, 'Rastoke (Slunj)', 'Půvabná vesnička na soutoku řek Slunjčica a Korana, přezdívaná malá Plitvická jezera. Řeka se zde tříští do desítek kaskád a vodopádů, mezi nimiž stojí staré vodní mlýny, z nichž některé fungují dodnes. Kamenné domky s dřevěnými mlýnskými koly patří od roku 1969 mezi chráněné památky. Zastávka na kávu nebo pstruha přímo nad vodopády je příjemným zpestřením cesty.', 45.12073, 15.58633, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slunj%2C%20Rastoke%2C%20waterfalls%20of%20the%20Slunjcica%20river.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slunj%2C%20Rastoke%2C%20waterfalls%20of%20the%20Slunjcica%20river.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rastoke%2C%20Slunj%2C%20Croatia%2C%20waterfall.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Slunj%2C%20Rastoke%2C%20waterfalls%20falling%20into%20Korana%20river.JPG"}'::text[], 1),
    (v_route, 'Barać jeskyně (Rakovica)', 'Trojice krápníkových jeskyní u vesnice Nova Kršlja poblíž Rakovice, pojmenovaná podle legendárního bojovníka Barače, který zde měl zvítězit nad Osmany. Pro veřejnost je zpřístupněna Horní Baračova jeskyně s bohatou krápníkovou výzdobou a prohlídkou s průvodcem. Nachází se stranou hlavních tras, takže sem míří jen málo turistů a zážitek je o to autentičtější. Vhodná odbočka mezi Plitvicemi a Velebitem.', 44.98444, 15.72667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baraceve%20spilje%20caves.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baraceve%20spilje%20caves.JPG"}'::text[], 2),
    (v_route, 'NP Sjeverni Velebit', 'Nejmladší chorvatský národní park pokrývající severní část mohutného pohoří Velebit, ráj pro milovníky drsné krasové přírody a pěší turistiky. Vstup Babić Siča se nachází nad horskou vesnicí Krasno a odtud vychází i slavná Premužićova stezka. Z rozeklaných vápencových vrcholů se otevírají výhledy až na Kvarnerské ostrovy. Cesta sem vede úzkými horskými silničkami, takže se nespěchá a jezdí opatrně.', 44.6892, 15.0042, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Sjeverni%20Velebit.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Sjeverni%20Velebit.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Sjeverni%20Velebit%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karstformationen%20Nationalpark-Nord-Velebit.JPG"}'::text[], 3),
    (v_route, 'Baške Oštarije (velebitský průsmyk)', 'Horské sedlo ve výšce kolem 920 metrů, kudy prochází jedna z nejstarších a nejnižších spojnic mezi vnitrozemím Liky a chorvatským pobřežím. Klikatá silnice D25 sem stoupá řadou serpentin a nabízí motorkářům jednu z nejkrásnějších jízd v celém regionu. Průsmyk je oblíbeným nástupním bodem pro horské túry po hřebeni Velebitu. Na vrcholu se vyplatí zastavit, protáhnout se a nadechnout horského vzduchu.', 44.52668, 15.17164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A1ke%20O%C5%A1tarije%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A1ke%20O%C5%A1tarije%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Croatie%20Velebit%2014082008%20-%20panoramio.jpg"}'::text[], 4),
    (v_route, 'Gospić', 'Správní centrum a největší město regionu Lika, ležící v širokém údolí obklopeném horami. Město je rodištěm chorvatského politika Ante Starčeviće a nabízí příjemné náměstí, katolický kostel svaté Máří Magdalény a mosty přes řeku Liku. Je to nejlepší místo na trase pro doplnění paliva, nákup zásob i přenocování. Dobré zázemí uprostřed jinak řídce osídleného kraje.', 44.54611, 15.37472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hl.%20Magdalena%20Kirche%20in%20Gospic.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ante%20Starcevic%20Platz%20in%20Gospic.JPG"}'::text[], 5),
    (v_route, 'Restaurace: Maki (Gospić)', 'Rodinná restaurace s tradicí od roku 1971, považovaná za jednu z nejlepších v celém regionu Lika, s hodnocením kolem 4,5 hvězdy. Specializuje se na poctivou místní kuchyni, zejména grilované maso, lický řízek a dušené jehněčí kalja. Porce jsou vydatné a ceny přátelské, takže je to ideální zastávka zhruba v polovině trasy. Najdete ji na adrese Budačka 200 přímo v Gospići.', 44.54815, 15.37382, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gospic%20panorama%20s%20novog%20mosta.JPG"}'::text[], 6),
    (v_route, 'Cerovac jeskyně (Rizvanuša)', 'Největší jeskynní komplex v Chorvatsku na jižním svahu Velebitu poblíž Gračace, tvořený spodní, střední a horní jeskyní se čtyřmi kilometry prozkoumaných chodeb. Návštěvníky lákají působivé krápníkové útvary i nálezy pozůstatků jeskynních medvědů. Jeskyně leží v chráněné oblasti přírodního parku Velebit a jsou přístupné s průvodcem. Chladné podzemí je vítanou úlevou během horkého letního dne.', 44.27502, 15.88837, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerova%C4%8Dke%20%C5%A1pilje%20(Cerovac%20caves).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerova%C4%8Dke%20%C5%A1pilje%20(Cerovac%20caves).jpg"}'::text[], 7),
    (v_route, 'Otočac', 'Klidné městečko v severozápadní části Liky, rozložené v údolí křišťálově čisté řeky Gacky, jedné z nejbohatších pstruhových řek Evropy. Nad městem se tyčí zbytky středověké pevnosti Fortica a v okolí najdete vodní mlýny i příjemné říční zákoutí. Otočac je klidným a příjemným zakončením dvoudenní cesty Likou. Odtud se snadno vracíte zpět po státní silnici D50 směrem na sever.', 44.86944, 15.2375, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dac%20(Croatia)%20-%20centar.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dac%20(Croatia)%20-%20centar.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tvr%C4%91ava%20Fortica%2C%20Oto%C4%8Dac%20(Croatia).JPG"}'::text[], 8);
