  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Split (Diokleciánův palác)', 'Diokleciánův palác je monumentální římská rezidence z počátku 4. století, kolem níž vyrostlo historické jádro Splitu zapsané na seznamu UNESCO. Srdcem palácového komplexu je nádvoří Peristyl obklopené sloupy, egyptskou sfingou a katedrálou sv. Domnia, která vznikla přestavbou Diokleciánova mauzolea. Úzké kamenné uličky, sklepení a promenáda Riva podél moře dělají ze Splitu ideální start dalmatské cesty.', 43.5083, 16.4406, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peristyle%20of%20Diocletian''s%20Palace%20-%20Split%20-%2051387487617.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peristyle%20of%20Diocletian''s%20Palace%20-%20Split%20-%2051387487617.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Peristyle%20of%20Diocletian''s%20Palace,%20Split%20(11907776284).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Diocletian''s%20Palace,%20Split,%20Croatia.JPG"}'::text[], 0),
    (v_route, 'Pevnost Klis', 'Středověká pevnost Klis se tyčí na skalnatém hřebeni nad průsmykem, který od antiky střeží přístup k Splitu. Sloužila jako sídlo chorvatských králů, později odolávala osmanským nájezdům a proslula i jako filmová kulisa seriálu Hra o trůny. Z hradeb se otevírá dechberoucí výhled na Split, moře a okolní ostrovy.', 43.56004, 16.52415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klis%20Fortress,%20Croatia%204.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klis%20Fortress,%20Croatia%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fortress%20of%20Klis%2004.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Klis%20castle,%20Croatia.JPG"}'::text[], 1),
    (v_route, 'Trogir (UNESCO)', 'Historické jádro Trogiru leží na malém ostrůvku mezi pevninou a ostrovem Čiovo a je zapsáno na seznamu UNESCO. Pravoúhlý půdorys ulic pochází z helénistického období a městu vévodí románsko-gotická katedrála sv. Vavřince s bohatě zdobeným Radovanovým portálem. Benátské paláce, kamenné náměstí a přímořská promenáda dělají z Trogiru jedno z nejlépe zachovaných středověkých měst Jadranu.', 43.51722, 16.25167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20de%20la%20ville%20de%20Trogir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20de%20la%20ville%20de%20Trogir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trogir%20-%20Trogirska%20katedrala%20sv.%20Lovre%20(49013124448).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Clock%20tower%20in%20Trogir.jpg"}'::text[], 2),
    (v_route, 'Primošten', 'Malebné městečko Primošten leží na skalnatém poloostrově vybíhajícím do tyrkysového moře mezi Šibenikem a Trogirem. Historické jádro se shlukem kamenných domů a kostelem sv. Jiří na vrcholku patří k nejfotografovanějším pohledům dalmatského pobřeží. Okolní vinice a oblázkové pláže lákají k zastavení a osvěžení během jízdy po magistrále.', 43.5863, 15.92302, 'https://commons.wikimedia.org/wiki/Special:FilePath/Primo%C5%A1ten,%20Croatia%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Primo%C5%A1ten,%20Croatia%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Primo%C5%A1ten,%20Croatia%2002.jpg"}'::text[], 3),
    (v_route, 'Šibenik (katedrála sv. Jakuba UNESCO)', 'Katedrála sv. Jakuba v Šibeniku je nejvýznamnější renesanční památkou Chorvatska a je zapsána na seznamu UNESCO. Její stavba trvala od roku 1431 do 1536 a je jedinou katedrálou v Evropě postavenou zcela z kamene bez použití dřeva či cihel. Fasáda apsid je proslulá vlysem sedmdesáti unikátních kamenných hlav a interiéru dominuje kamenná kupole. Šibenik navíc nabízí bludiště starých uliček a několik obranných pevností nad městem.', 43.73583, 15.88917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/HR-Sibenik-Kathedrale-01.jpg"}'::text[], 4),
    (v_route, 'NP Krka (Skradinski buk)', 'Skradinski buk je nejznámější a nejmohutnější vodopád národního parku Krka, tvořený sedmnácti travertinovými kaskádami rozprostřenými v délce zhruba 800 metrů. Voda řek Krka a Čikola zde překonává výškový rozdíl přes 45 metrů a vytváří jeden z nejkrásnějších vápencových vodopádů Evropy. Dřevěné chodníky vedou kolem tůní, starých mlýnů a bujné vegetace. Jde o ideální cíl pro celodenní pěší okruh v srdci parku.', 43.80583, 15.96417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skradinski%20buk%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skradinski%20buk%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/National%20park%20Krka%20skradinski%20buk%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Krka%20Skradinski%20buk%20mills%205.jpg"}'::text[], 5),
    (v_route, 'Vodopád Roški slap', 'Roški slap je šestý vodopád na řece Krce, dlouhý zhruba 650 metrů a vysoký přes 25 metrů. Je charakteristický travertinovými kaskádami na počátku bariéry, jimž se pro jejich krásu přezdívá „náhrdelníky“. U vodopádu stojí staré vodní mlýny a nachází se zde přístup k jezeru Visovac. Klidnější a méně přeplněná část parku Krka je ideální pro fotografování a procházku přírodou.', 43.90556, 15.97806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Krka,%20Ro%C5%A1ki%20slap%20(2023).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nacionalni%20park%20Krka,%20Ro%C5%A1ki%20slap%20(2023).jpg"}'::text[], 6),
    (v_route, 'Omiš (kaňon Cetiny)', 'Omiš leží u ústí řeky Cetiny do moře, sevřený mezi strmými vápencovými stěnami dramatického kaňonu. Kdysi útočiště obávaných pirátů dnes láká na středověké pevnosti Mirabella a Starigrad nad městem a na adrenalinové aktivity v kaňonu, jako je rafting a zipline. Silnice podél Cetiny nabízí jedny z nejúchvatnějších přírodních scenérií celé trasy. Je to symbolická brána zpět k Splitu.', 43.4449, 16.6913, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetina-Canyon%20in%20Omis,%20Croatia.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetina-Canyon%20in%20Omis,%20Croatia.JPG"}'::text[], 7),
    (v_route, 'Restaurace: Pelegrini (Šibenik)', 'Pelegrini je špičková restaurace s michelinskou hvězdou, umístěná v renesančním paláci hned vedle katedrály sv. Jakuba v Šibeniku. Šéfkuchař Rudolf Štefan zde nabízí moderní pojetí dalmatské kuchyně z místních surovin a vinný lístek s více než 500 etiketami. S hodnocením 4,6 patří k nejlépe hodnoceným podnikům v celé Dalmácii a je ideální zastávkou zhruba v polovině trasy.', 43.73583, 15.88944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2007.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20James,%20%C5%A0ibenik%2007.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Konoba Toni (Skradin)', 'Rodinná konoba Toni ve Skradinu je oblíbenou zastávkou u vstupu do národního parku Krka, jen kousek od vodopádu Skradinski buk. Specializuje se na tradiční dalmatské pokrmy připravované „pod pekou“, grilované maso a proslulý skradinský dort (skradinska torta). S vysokým hodnocením kolem 4,4–4,8 a přátelskou atmosférou je skvělou volbou pro oběd uprostřed přírodní části trasy.', 43.81639, 15.92528, 'https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Krka%20Skradinski%20buk%20mills%205.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NP%20Krka%20Skradinski%20buk%20mills%205.jpg"}'::text[], 9);
