  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Siena (Piazza del Campo)', 'Piazza del Campo je jedno z nejkrásnějších náměstí Evropy, proslavené svým vějířovitým tvarem a každoročními dostihy Palio. Dominuje mu štíhlá věž Torre del Mangia a gotický Palazzo Pubblico. Rozlehlá dlážděná plocha se svažuje jako mušle a láká k posezení v kavárnách po obvodu. Historické centrum Sieny je zapsáno na seznamu UNESCO.', 43.31833, 11.33139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena)%2006.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena)%2006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena)%202011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20del%20Campo%20(Siena).jpg"}'::text[], 0),
    (v_route, 'San Gimignano (věže)', 'San Gimignano se přezdívá středověký Manhattan díky souboru kamenných věží, které tvoří nezaměnitelnou siluetu na obzoru. Z původních desítek se dochovalo čtrnáct mohutných věží, jež stavěly bohaté rody na důkaz své moci. Uvnitř hradeb najdete malebná náměstí Piazza della Cisterna a Piazza del Duomo. Celé historické jádro chrání UNESCO.', 43.46763, 11.04349, 'https://commons.wikimedia.org/wiki/Special:FilePath/Towers%20of%20San%20Gimignano,%20Tuscany,%20Italy.%20View%20from%20Torre%20Grossa%20tower.%202014.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Towers%20of%20San%20Gimignano,%20Tuscany,%20Italy.%20View%20from%20Torre%20Grossa%20tower.%202014.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/San%20Gimignano.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/San%20Gimignano%20torri%201.jpg"}'::text[], 1),
    (v_route, 'Greve in Chianti (Piazza Matteotti)', 'Greve in Chianti je považováno za bránu do vinařské oblasti Chianti Classico a jeho srdcem je trojúhelníkové náměstí Piazza Matteotti. Náměstí lemují podloubí s obchůdky, vinotékami a řeznictvími, kde ochutnáte místní víno a uzeniny. Uprostřed stojí socha mořeplavce Giovanniho da Verrazzano, rodáka z okolí. Ideální zastávka pro degustaci vína Chianti přímo u zdroje.', 43.58444, 11.31557, 'https://commons.wikimedia.org/wiki/Special:FilePath/Greve%20in%20Chianti%20-%20Piazza%20Giacomo%20Matteotti-9295.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Greve%20in%20Chianti%20-%20Piazza%20Giacomo%20Matteotti-9295.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Greve%20in%20Chianti%20-%20Piazza%20Giacomo%20Matteotti-9293.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Greve%20piazza%20(cropped).JPG"}'::text[], 2),
    (v_route, 'Pienza', 'Pienza je učebnicovým příkladem renesančního ideálního města, které nechal na svém rodišti vybudovat papež Pius II. Ústřední náměstí Piazza Pio II tvoří harmonický celek katedrály, Palazza Piccolomini a radnice. Z hradebních teras se otevírají nádherné výhledy na kopce Val d''Orcia. Město proslulo také výborným ovčím sýrem pecorino.', 43.07652, 11.67891, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20Piazza%20Pio%20II.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20Piazza%20Pio%20II.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Pienza%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Palazzo%20Piccolomini%20Pienza.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Trattoria Latte di Luna (Pienza)', 'Rodinná trattoria v centru Pienzy patří k nejoblíbenějším v okolí a hodnocení se drží kolem 4,5 hvězdy. Vyhlášená je pečená selátka (porchetta), domácí těstoviny pici a poctivá toskánská kuchyně. V létě se sedí na malebné terase pod stromy ve staré uličce.', 43.0764, 11.6793, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20italy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pienza%20italy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/San%20Francesco%20Pienza.jpg"}'::text[], 4),
    (v_route, 'Montepulciano (Piazza Grande)', 'Montepulciano je vznešené renesanční město posazené na hřebeni kopce, proslulé silným červeným vínem Vino Nobile. Nejvýše položené náměstí Piazza Grande lemují palác Palazzo Comunale s věží a nedostavěná katedrála. Ze strmých uliček se otevírají výhledy do údolí Valdichiana a Val d''Orcia. Ve sklepích pod městem zrají tisíce lahví ušlechtilého vína.', 43.09244, 11.78147, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano,%20piazza%20grande%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano,%20piazza%20grande%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano%20Piazza%20Grande.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano,%20piazza%20grande%2001.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Osteria Acquacheta (Montepulciano)', 'Legendární osteria ve Via del Teatro je proslulá svým bifteksem bistecca alla fiorentina grilovaným na žhavém uhlí a společnými stoly, u nichž se hosté seznamují. Hodnocení dlouhodobě dosahuje 4,5 hvězdy a doporučuje se rezervace předem. Atmosféra opravdové toskánské krčmy s vůní uhlíků sem láká gurmány z celého světa.', 43.0921, 11.7809, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano-view.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montepulciano-view.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Il%20Pozzo%20-%20Piazza%20Grande%20Montepulciano%20480x640.jpg"}'::text[], 6),
    (v_route, 'Montalcino', 'Montalcino je světoznámé díky vínu Brunello di Montalcino, jednomu z nejcennějších italských červených vín. Městečku vévodí mohutná pevnost Fortezza ze 14. století, z jejíchž hradeb je panoramatický rozhled po vinicích. Uvnitř pevnosti sídlí vinotéka, kde ochutnáte místní ročníky. Klidné uličky lemují vinařství a obchůdky s regionálními specialitami.', 43.05589, 11.51089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montalcino%20Fortezza.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montalcino%20Fortezza.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fortezza-Montalcino-SI-IT.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montalcino,%20piazza%20del%20popolo%20e%20palazzo%20dei%20priori.JPG"}'::text[], 7),
    (v_route, 'San Quirico d''Orcia (cypřiše Val d''Orcia)', 'Slavné skupinky cypřišů na osamělých pahorcích u San Quirica d''Orcia patří k nejfotografovanějším symbolům Toskánska. Stromy rostou na holých jílových kopcích nad starou Via Cassií a v ranním či podvečerním světle vytvářejí kouzelnou scenerii. Krajina Val d''Orcia je zapsána na seznamu světového dědictví UNESCO. Zastavte se na okraji silnice a nechte se pohltit vlnící se toskánskou krajinou.', 43.06267, 11.55885, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cipressi%20di%20San%20Quirico%20d''Orcia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cipressi%20di%20San%20Quirico%20d''Orcia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cipressi%20di%20San%20Quirico%20d''Orcia%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/I%20cipressi%20di%20San%20Quirico%20d''Orcia.jpg"}'::text[], 8),
    (v_route, 'Bagno Vignoni', 'Bagno Vignoni je jedinečná vesnička, kde místo obvyklého náměstí najdete uprostřed velký kamenný bazén s termální vodou, Piazzu delle Sorgenti. Horké prameny tu využívali už Etruskové a Římané a lázně navštěvovala i svatá Kateřina Sienská. Voda vyvěrá z podzemí a paruje zejména v chladných rannách. Nedaleko můžete stále máčet nohy v teplých kaskádách Parco dei Mulini.', 43.0279, 11.6186, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bagno%20Vignoni.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bagno%20Vignoni.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bagno%20Vignoni%20Piazza%20delle%20Sorgenti%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bagno%20Vignoni%20long%20exposure.jpg"}'::text[], 9);
