  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Passo Gavia', 'Passo Gavia (2621 m) patří k nejdivočejším a nejkrásnějším průsmykům celých Alp. Úzká, místy nezpevněná silnice se vine v ostrých serpentinách vysokohorskou krajinou k horské chatě Rifugio Bonetta a jezírku Lago Nero. Odměnou za náročný výjezd jsou ohromující výhledy na ledovce masivu Ortles a naprostý pocit alpské samoty.', 46.3395, 10.4862, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Gavia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Gavia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20di%20Gavia,%20Gaviapass,%202652%20m.%20%C3%BC.%20NN.,%20Rifugio%20Bonetta%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20150610%2010%20Passo%20di%20Gavia%20(18583244129).jpg"}'::text[], 0),
    (v_route, 'Passo del Mortirolo', 'Passo del Mortirolo (též Passo della Foppa) je legendární horský průsmyk proslavený cyklistickým Girem d''Italia. Výjezd od Mazza di Valtellina patří k nejstrmějším v Evropě, s brutálními procenty a nekonečnou řadou zatáček v hlubokém lese. U vrcholu stojí pomník Marca Pantaniho, který sem přitahuje sportovce z celého světa.', 46.248, 10.2991, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Mortirolo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Mortirolo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/20150609%2012%20Passo%20della%20Foppa%20(Mortirolo)%20-%20Marco%20Pantani%20(18583253669).jpg"}'::text[], 1),
    (v_route, 'Ponte di Legno', 'Ponte di Legno je půvabné horské městečko na severním konci údolí Valcamonica, přirozené křižovatce k průsmykům Gavia, Tonale i Mortirolo. Kamenné domy, kostely a živé náměstí z něj dělají ideální zastávku na kávu i tankování před náročným výjezdem. V létě je základnou pro turisty i motorkáře mířící do okolních hor.', 46.25889, 10.51028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ponte%20di%20Legno%20visto%20dalla%20seggiovia%20-%20Ponte%20di%20Legno%203%20settembre%202000.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ponte%20di%20Legno%20visto%20dalla%20seggiovia%20-%20Ponte%20di%20Legno%203%20settembre%202000.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piazza%20di%20Ponte%20di%20Legno%20-%20dal%20campanile%20della%20Chiesa%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Passo del Tonale', 'Passo del Tonale (1884 m) je široký, otevřený průsmyk na hranici Lombardie a Trentina, obklopený ledovcem Presena a rozlehlými loukami. Na rozdíl od úzké Gavie nabízí pohodovou, plynulou jízdu s krásnými výhledy do okolních hor. Průsmyk je také místem pietní paměti bojů z první světové války, které tudy probíhaly.', 46.2667, 10.5833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Tonale%201%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Tonale%201%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tonale%20Pass%20Winter%20View.jpg"}'::text[], 3),
    (v_route, 'Edolo', 'Edolo je živé městečko v horní části údolí Valcamonica, kde se sbíhají silnice od Aprici, Mortirola i Tonale. Nad městem se tyčí historický hrad Castello di Mù a v centru najdete kostely i příjemné uličky k odpočinku. Je to praktická zastávka na doplnění paliva a občerstvení uprostřed náročné smyčky.', 46.17924, 10.33033, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20M%C3%B9%20-%20Edolo%20(Foto%20Luca%20Giarelli).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20M%C3%B9%20-%20Edolo%20(Foto%20Luca%20Giarelli).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Esterno%20del%20castello%20di%20M%C3%B9%20-%20Edolo%20(Foto%20Luca%20Giarelli).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Ristorante Frigidolfo (Ponte di Legno)', 'Rodinný hotel a restaurace Frigidolfo leží v osadě Precasaglio u vstupu do Valle delle Messi, přímo u potoka Frigidolfo a na úpatí výjezdu na Gaviu. Kuchyně je tradiční horská s výbornými domácími těstovinami a specialitami Valcamoniky, s hodnocením kolem 4,6 hvězdy. Je to ideální zastávka na obřad v polovině náročné smyčky, než se pustíte do serpentin průsmyku.', 46.28393, 10.5211, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torrente%20Frigidolfo%20-%20Ponte%20di%20Legno%20(ph%20Luca%20Giarelli).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torrente%20Frigidolfo%20-%20Ponte%20di%20Legno%20(ph%20Luca%20Giarelli).jpg"}'::text[], 5);
