  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Como (katedrála)', 'Katedrála Santa Maria Assunta, zvaná Duomo di Como, je největší gotická stavba severní Itálie a dominanta historického centra na břehu jezera. Její bohatě zdobené mramorové průčelí kombinuje pozdní gotiku s renesancí a je zdobené sochami. Como je ideálním startem okruhu, odkud se vydáte po jezerních silnicích na sever.', 45.8118, 9.08366, 'https://commons.wikimedia.org/wiki/Special:FilePath/Como_-_Duomo_di_Como_-_2024-09-01%2021-27-34%20001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Como_-_Duomo_di_Como_-_2024-09-01%2021-27-34%20001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cattedrale_di_Santa_Maria_Assunta_(Como).jpg"}'::text[], 0),
    (v_route, 'Madonna del Ghisallo (kaple + muzeum cyklistiky)', 'Svatyně Madonna del Ghisallo na vrcholu stejnojmenného kopce je zasvěcena patronce cyklistů celého světa a stojí u ní vyhlášené Muzeum cyklistiky. Výjezd sem po serpentinách nad Bellagiem je legendární etapou závodu Giro di Lombardia. Z terasy se otevírá dechberoucí výhled na obě ramena jezera Lago di Como. Zastávka potěší nejen milovníky kol, ale každého motorkáře.', 45.9289, 9.2658, 'https://commons.wikimedia.org/wiki/Special:FilePath/Santuario_della_Madonna_del_Ghisallo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Santuario_della_Madonna_del_Ghisallo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Museo_del_Ciclismo_Madonna_del_Ghisallo_23.JPG"}'::text[], 1),
    (v_route, 'Bellagio', 'Bellagio je nazýváno perlou jezera Lago di Como a leží na výběžku v místě, kde se jezero větví do dvou ramen. Dlážděné uličky se schody, květinové terasy a nábřeží s výhledem na Alpy z něj dělají jedno z nejfotogeničtějších míst Itálie. Historické vily a zahrady lákají návštěvníky z celého světa. Je to ideální místo na krátkou zastávku u vody.', 45.98775, 9.26198, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bellagio_panorama_from_Lake_Como_ferry.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bellagio_panorama_from_Lake_Como_ferry.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_dalla_Punta_Spartivento_a_Bellagio.jpg"}'::text[], 2),
    (v_route, 'Varenna', 'Varenna je malebná rybářská vesnička na východním břehu jezera s pastelově barevnými domy stoupajícími po strmém svahu. Romantická promenáda podél vody, zvaná Passeggiata degli Innamorati, spojuje přístav s centrem. Nad obcí se tyčí hrad Castello di Vezio s výhledem na celé jezero. Klidná atmosféra kontrastuje s ruchem větších letovisek.', 46.01078, 9.28465, 'https://commons.wikimedia.org/wiki/Special:FilePath/I_colori_di_Varenna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/I_colori_di_Varenna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_tra_Vezio_e_Varenna_sul_Sentiero_del_Viandante.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Crotto Quartino - Valchiavenna (Piuro)', 'Crotto Quartino je typický valchiavennský crotto s hodnocením 4,6 a leží poblíž vodopádů Acqua Fraggia nedaleko Chiavenny, přibližně v polovině trasy. Podává tradiční horskou kuchyni jako uzeniny bresaola, těstoviny pizzoccheri a domácí sýry v autentickém kamenném prostředí. Ideální místo na vydatný oběd před výjezdem na průsmyk Splügen.', 46.327, 9.43, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valchiavenna_1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Valchiavenna_1.JPG"}'::text[], 4),
    (v_route, 'Chiavenna', 'Chiavenna je historické městečko na křižovatce alpských údolí, proslulé svými crotti, přírodními jeskyněmi využívanými ke zrání sýrů a uzenin. Dlážděnou hlavní třídou Via Dolzino se procházíte kolem starobylých domů, kostelů a mostů přes řeku Mera. Město je poslední velkou zastávkou před stoupáním na Passo dello Spluga. Jeho gastronomie patří k nejbohatším v regionu.', 46.3206, 9.3982, 'https://commons.wikimedia.org/wiki/Special:FilePath/Via_Dolzino_Chiavenna_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Via_Dolzino_Chiavenna_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valchiavenna_1.JPG"}'::text[], 5),
    (v_route, 'Passo dello Spluga (Splügenpass, hranice IT/CH)', 'Passo dello Spluga, německy Splügenpass, je historický alpský průsmyk ve výšce 2115 metrů na hranici mezi Itálií a Švýcarskem. Silnice sem stoupá dramatickými serpentinami sevřenými skalami a je jednou z nejnáročnějších a nejkrásnějších horských tras v Alpách. Na italské straně míjíte přehradní jezero Montespluga, na švýcarské klesáte do údolí Rheinwald. Průsmyk bývá v zimě uzavřen a otevírá se jen v teplých měsících.', 46.50556, 9.33028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo_dello_spluga_in_inverno.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo_dello_spluga_in_inverno.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Spl%C3%BCgenpass02.JPG"}'::text[], 6),
    (v_route, 'Menaggio', 'Menaggio je živé letovisko na západním břehu jezera s příjemným náměstím Piazza Garibaldi přímo u vody a promenádou lemovanou palmami. Z místního přístavu vyplouvají trajekty do Bellagia a Varenny, které tvoří dopravní srdce středního jezera. Město je oblíbenou základnou pro výlety do okolních hor i k jezeru Lugano. Nabízí spoustu kaváren a restaurací s výhledem na hladinu.', 46.02171, 9.23883, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menaggio_Piazza_Garibaldi.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Menaggio_Piazza_Garibaldi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Car_ferry_Adda_on_Lake_Como_from_Menaggio_harbor.jpg"}'::text[], 7),
    (v_route, 'Restaurace: B-Lake Restaurant (Bellagio)', 'B-Lake Restaurant v Bellagiu má hodnocení 4,5 a nabízí moderní italskou kuchyni v příjemném prostředí blízko jezera. Mezi oblíbené pokrmy patří smažené květy cukety, čerstvé ryby a domácí těstoviny. Je to skvělá volba na klidnou večeři po prvním dni plném serpentin a jezerních výhledů.', 45.9862, 9.2605, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_dalla_Punta_Spartivento_a_Bellagio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_dalla_Punta_Spartivento_a_Bellagio.jpg"}'::text[], 8),
    (v_route, 'Lecco', 'Lecco leží na jihovýchodním rameni jezera pod strmým masivem hory Resegone a je proslulé jako dějiště románu Snoubenci od Alessandra Manzoniho. Nábřeží s výhledem na hory a jezero, bazilika San Nicolò s vysokou zvonicí a živé náměstí tvoří příjemné zakončení okruhu. Město spojuje jezerní atmosféru s blízkostí divokých hor. Odtud je to zpět do Coma po jezerní silnici jen kousek.', 45.85298, 9.39007, 'https://commons.wikimedia.org/wiki/Special:FilePath/042_Lecco_-_sullo_sfondo_il_Resegone.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/042_Lecco_-_sullo_sfondo_il_Resegone.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lago_di_lecco_di_sera.JPG"}'::text[], 9);
