  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bledské jezero (ostrov a hrad Bled)', 'Symbol Slovinska: smaragdové ledovcové jezero s jediným ostrovem v zemi, na němž stojí poutní kostel Panny Marie. Na skalním útesu nad hladinou se tyčí středověký hrad Bled, nejstarší dochovaný hrad v zemi, odkud je nejkrásnější výhled na celé jezero. K ostrovu se tradičně pluje dřevěnými loďkami zvanými pletna. Ideální místo pro start okruhu a šálek smetanového krémového dortu kremšnita.', 46.36256, 14.09022, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bled_Overview.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bled_Overview.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/The%20impressive%20Bled%20Island.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bled-Lake%20and%20Island%20from%20Castle.JPG"}'::text[], 0),
    (v_route, 'Soutěska Vintgar', 'Přibližně 1,6 km dlouhá soutěska, kterou vyhloubila křišťálově čistá řeka Radovna. Po celé délce vede dřevěná lávka z roku 1893, jež se nad peřejemi, tůněmi a vodopády několikrát kříží z jedné strany na druhou. Soutěska leží v Triglavském národním parku jen pár kilometrů severozápadně od Bledu. Procházka končí u půvabného vodopádu Šum.', 46.39098, 14.08387, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blejski%20vintgar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Blejski%20vintgar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bled%20Vintgar-Klamm%2027.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bled%20Vintgar-Klamm%2032.JPG"}'::text[], 1),
    (v_route, 'Bohinjské jezero', 'Největší přirozené jezero Slovinska, které leží v tiché ledovcové kotlině uprostřed Triglavského národního parku. Na rozdíl od rušného Bledu si zachovává klidnou, téměř nedotčenou atmosféru obklopenou vysokými štíty Julských Alp. U kamenného mostu ve vesnici Ribčev Laz stojí malebný kostelík sv. Jana Křtitele. Skvělé místo pro koupání, projížďku na loďce nebo procházku kolem břehu.', 46.28556, 13.86194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bohinjsko%20jezero%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bohinjsko%20jezero%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Bohinj%20from%20the%20Janez%20bridge,%20Rib%C4%8Dev%20Laz,%20Slovenia,%202013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stara%20Fu%C5%BEina%20-%20Rib%C4%8Dev%20Laz%20-%20Lake%20Bohinj.jpg"}'::text[], 2),
    (v_route, 'Vodopád Savica', 'Jeden z nejznámějších slovinských vodopádů, který padá z výšky 78 metrů v charakteristickém tvaru písmene A do smaragdově zeleného jezírka. Napájí ho krasový pramen Savica hned nad vodopádem a odtud pramení řeka Sava Bohinjka. K vyhlídce vede zhruba půlhodinová stezka s více než pěti sty schody nad západním koncem Bohinjského jezera. Vodopád opěvoval i slovinský básník France Prešeren.', 46.29002, 13.80247, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Slap%20Savica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Slap%20Savica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Savica%20Waterfall%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Savica%20Wasserfall%20-%20Slap%20Savica%20(48652160571).jpg"}'::text[], 3),
    (v_route, 'Soutěska Mostnica (Stara Fužina)', 'Zhruba dva kilometry dlouhá soutěska, kterou v údolí Voje vymlel potok Mostnica přímo do skály nad vesnicí Stara Fužina. Voda tu vytváří hluboké tůně, tobogány a bizarní skalní útvary, mezi nimiž je i skála připomínající slona. Přes soutěsku se klene starobylý kamenný Čertův most (Hudičev most) z roku 1777. Klidná a stinná procházka je příjemným protikladem k rušnějším místům u jezer.', 46.29842, 13.8854, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mostnica%20Gorge%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mostnica%20Gorge%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mostnica-Voje5.JPG"}'::text[], 4),
    (v_route, 'Pokljuka (plošina)', 'Rozlehlá lesnatá krasová plošina ve výšce kolem 1100 až 1400 metrů, rozprostírající se mezi Bledem a Bohinjem uvnitř Triglavského národního parku. Hustými smrkovými lesy tu vedou tiché horské silnice a mezi nimi se otevírají malebné pastviny jako Zajamniki s řadou dřevěných senic. Plošina je známá biatlonovým centrem, kde se konají závody Světového poháru. V létě je to ráj pro pěší i cyklistické výlety daleko od davů.', 46.3449, 13.9222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pokljuka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pokljuka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pokljuka%20-%20planina%20Zajamniki%20-%202013-08-10.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beautiful%20surroundings%20of%20Planina%20Zajamniki,%20Pokljuka%20plateau%20near%20Lake%20Bohinj,%20Julian%20Alps%20in%20Triglav%20National%20Park%20(52340724264).jpg"}'::text[], 5),
    (v_route, 'Radovljica (medové centrum)', 'Půvabné středověké městečko s dochovaným historickým jádrem kolem Linhartova náměstí, plné barokních a gotických domů s malovanými fasádami. Radovljica je proslulá dlouhou včelařskou tradicí a sídlí zde Muzeum včelařství s ukázkami malovaných úlových nástavců. Uličky lákají k procházce a ochutnávce medových specialit i tradičního perníku. Příjemná tečka na konci okruhu, jen kousek od Bledu.', 46.34064, 14.1759, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poljce%20Radovljica%20Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poljce%20Radovljica%20Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Obla%20Gorica%20Radovljica%20(3).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Building%20in%20Radovljica%20-%20P1030815.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Gostilna Mihovc (Stara Fužina)', 'Nejstarší tradiční hostinec v Bohinji, který v centru vesnice Stara Fužina hostí návštěvníky už po generace. Kuchyně sází na poctivá slovinská jídla z čerstvých místních surovin, od telecího a hovězího steaku po pstruha a domácí specialitu flija. Ideální zastávka zhruba v polovině okruhu s výborným hodnocením a přátelskou obsluhou.', 46.28764, 13.8938, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stara%20Fu%C5%BEina%20-%20Rib%C4%8Dev%20Laz%20-%20Lake%20Bohinj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stara%20Fu%C5%BEina%20-%20Rib%C4%8Dev%20Laz%20-%20Lake%20Bohinj.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Pizzeria Rustika (Bled)', 'Oblíbená restaurace a pizzerie v nejstarší části Bledu pod hradní skálou, hned vedle kostelíka sv. Martina. Nabízí chutné pizzy z pece i slovinská jídla za rozumné ceny a patří k nejlépe hodnoceným podnikům ve městě. Skvělé místo na start nebo zakončení okruhu s posezením v malebných uličkách.', 46.3713, 14.1043, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bled-Lake%20and%20Island%20from%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bled-Lake%20and%20Island%20from%20Castle.JPG"}'::text[], 8);
