  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kamnik', 'Malebné středověké městečko pod Kamnicko-Savinjskými Alpami je ideálním startem i cílem okruhu. Dominuje mu skalní ostroh Mali grad s gotickou kaplí a půvabná uliced Šutna s barevnými měšťanskými domy. Ve městě je řada kaváren a parkovišť, kde je snadné před vyjížďkou doplnit palivo i síly.', 46.2257, 14.6119, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kamnik-Mali%20grad%20defense%20tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kamnik-Mali%20grad%20defense%20tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Markovo%20Kamnik%20Slovenia.jpg"}'::text[], 0),
    (v_route, 'Velika planina (lanovka)', 'Rozlehlá vysokohorská pastvina proslulá největší dochovanou pastýřskou osadou v Evropě s charakteristickými dřevěnými bačovskými chatami. Ke spodní stanici lanovky v Kamnické Bistrici vede krásná údolní silnice a kabinka vás během několika minut vyveze do výšky přes 1600 metrů. Nahoře na motorkáře čekají panoramatické výhledy, klid pastvin a možnost ochutnat místní kyselé mléko.', 46.31222, 14.60674, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velika%20planina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velika%20planina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velika%20planina%2005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamni%C5%A1ka%20Bistrica%2C%20Nihalka%20Velika%20Planina%20(1).jpg"}'::text[], 1),
    (v_route, 'Solčava', 'Nejmenší a nejvýše položené horské městečko v této části Slovinska je srdcem Solčavska, kraje tří ledovcových údolí. Odtud vybíhají cesty do Logarské doliny, Robanova kotu i Matkova kotu a startuje odsud i panoramatická cesta. Poblíž se nachází přírodní památka Matkov škaf, skalní misa vytvořená vodou pod alpskými stěnami.', 46.4201, 14.6841, 'https://commons.wikimedia.org/wiki/Special:FilePath/Robanov%20kot%20(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Robanov%20kot%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Matkov%20%C5%A1kaf.jpg"}'::text[], 2),
    (v_route, 'Solčavská panoramatická cesta', 'Vyhlídková horská silnice dlouhá přes dvacet kilometrů vede po slunečných svazích nad Logarskou dolinou kolem osamělých horských statků v Podolševě. Nabízí dechberoucí výhledy na okolní alpské štíty a údolí a je jednou z nejkrásnějších motorkářských tras v celém Slovinsku. Úzká a klikatá vozovka s prudkými stoupáními vyžaduje soustředění, odměnou jsou ale nekonečné panoramata.', 46.43, 14.65, 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%BB%D0%BE%D0%B2%D0%B5%D0%BD%D0%B8%D1%8F%20%D0%B0%D1%83%D1%8B%D0%BB%D1%8B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%BB%D0%BE%D0%B2%D0%B5%D0%BD%D0%B8%D1%8F%20%D0%B0%D1%83%D1%8B%D0%BB%D1%8B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/LogarskaDolina.JPG"}'::text[], 3),
    (v_route, 'Logarská dolina', 'Jedno z nejkrásnějších alpských údolí Evropy, ledovcem vymodelovaná dolina uzavřená ze tří stran mohutnými vápencovými stěnami. Silnice údolím je součástí krajinného parku a nabízí klidnou jízdu mezi loukami, potoky a horskými statky. Na konci údolí je placené parkoviště, odkud vede pěší stezka k vodopádu Rinka.', 46.39811, 14.63133, 'https://commons.wikimedia.org/wiki/Special:FilePath/LogarskaDolina.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/LogarskaDolina.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Logarska%20dolina%20-%20slap%20Palenk.jpg"}'::text[], 4),
    (v_route, 'Vodopád Rinka', 'Působivý vodopád padající volným pádem z výšky zhruba devadesáti metrů je druhým nejvyšším vodopádem tohoto typu ve Slovinsku a pramenem řeky Savinji. Nachází se na samém konci Logarské doliny a od parkoviště k němu vede krátká lesní stezka. Nad vodopádem stojí horská chata Orlovo gnezdo s vyhlídkou na celé údolí.', 46.37111, 14.59254, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rinka%20Fall%20(2955241140).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rinka%20Fall%20(2955241140).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mala%20Rinka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Koro%C5%A1ka%20Rinka.JPG"}'::text[], 5),
    (v_route, 'Jezersko (Planšarsko jezero)', 'Vysokohorská obec Jezersko láká na malebné jezero Planšarsko ve tvaru srdce, které místní vytvořili na památku dávného ledovcového jezera. Klidná hladina se zrcadlí pod strmými stěnami Kamnicko-Savinjských Alp a okolí zve k procházce i zastávce na svačinu. K jezeru vede příjemná horská silnice bez dálnic, po celý rok obklopená alpskou přírodou.', 46.4029, 14.51598, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plan%C5%A1arsko%20jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plan%C5%A1arsko%20jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plan%C5%A1arsko%20jezero%20(1).jpg"}'::text[], 6),
    (v_route, 'Restaurace: Hotel Plesnik (Logarská dolina)', 'Rodinná restaurace v hotelu Plesnik uprostřed Logarské doliny patří k nejlépe hodnoceným podnikům v celém kraji a nese zelenou michelinskou hvězdu za udržitelnou kuchyni. Servírují se tu sezonní pokrmy z místních surovin od okolních horských statků, výborně připravené a s výhledem na alpské štíty. Je to ideální zastávka zhruba v polovině okruhu, kde se dá v klidu naobědvat a dobít baterky.', 46.3915, 14.6378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Logarska%20dolina%20-%20slap%20Palenk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Logarska%20dolina%20-%20slap%20Palenk.jpg"}'::text[], 7);
