  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Egerský hrad', 'Mohutná pevnost nad městem se proslavila roku 1552, kdy pouhých asi dva tisíce obránců odrazilo mnohonásobnou tureckou přesilu. Dnes tu najdete kazematy, muzeum a vyhlídku na barokní střechy Egeru. Je to ideální první zastávka — motorku pohodlně zaparkujete pod hradbami a k městskému centru máte pár kroků.', 47.9039, 20.3794, 'https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Egri_v%C3%A1r_(z%C3%A1szl%C3%B3)_2012-ben.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Eger_castle_(by_Pudelek)_01.JPG"}'::text[], 0),
    (v_route, 'Egerský minaret', 'Štíhlý čtyřicetimetrový minaret je nejsevernější dochovanou tureckou stavbou tohoto typu v Evropě, památkou na osmanskou nadvládu nad Egerem. Odvážlivci mohou vyšlapat 97 úzkých točitých schodů na ochoz s výhledem na město. Pěší dostupnost od hradu je pár minut, takže obě památky zvládnete za dopoledne.', 47.9028, 20.3746, 'https://commons.wikimedia.org/wiki/Special:FilePath/Minaret_-_Eger,_2013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Minaret_-_Eger,_2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Egri_Minaret.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Eger_Minaret_in_Eger,_2016_Hungary.jpg"}'::text[], 1),
    (v_route, 'Údolí krásných paní (Szépasszony-völgy)', 'Malebné údolí na okraji Egeru, kde je do měkkého riolitového tufu vytesáno na dvě stě vinných sklípků. Právě odtud pochází slavná Egerská bikaver (Býčí krev) a bílý Egri Leányka. Ideální místo na procházku mezi sklepy a ochutnávku — pamatujte ale na to, že za řídítka usedá jen ten, kdo nepil.', 47.8925, 20.3544, 'https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0434_-_Hungary_-_Valley_of_Beautiful_Women_(Sz%C3%A9passzonyv%C3%B6lgy).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0434_-_Hungary_-_Valley_of_Beautiful_Women_(Sz%C3%A9passzonyv%C3%B6lgy).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0417_-_Hungary_-_Valley_of_Beautiful_Women_(Sz%C3%A9passzonyv%C3%B6lgy).JPG"}'::text[], 2),
    (v_route, 'Restaurace: Macok Bisztró (Eger)', 'Rodinná bistro s vinným barem přímo pod hradbami egerského hradu, oceněná v průvodci Michelin (Bib Gourmand). Kombinuje pestrou maďarskou i středomořskou kuchyni a nabízí skvělý výběr místních vín. Skvělé místo na oběd na konci prvního bloku zastávek v Egeru, hodnocení kolem 4,5–4,7.', 47.9033, 20.3775, 'https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/IMG_0368_-_Hungary,_Eger_-_Castle.JPG"}'::text[], 3),
    (v_route, 'Szilvásvárad — lipicáni', 'Půvabná horská obec na okraji národního parku Bükk, proslulá chovem bílých lipicánských koní a hřebčínem s muzeem. Odtud vede malebné údolí Szalajka s vodopády a úzkokolejnou lesní železnicí. Cesta sem z Egeru po klikaté silnici č. 2506 je jedním z motorkářských vrcholů celé trasy.', 48.107, 20.3875, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szilv%C3%A1sv%C3%A1rad,_Szalajka-v%C3%B6lgy._A_fels%C5%91_t%C3%B3_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szilv%C3%A1sv%C3%A1rad,_Szalajka-v%C3%B6lgy._A_fels%C5%91_t%C3%B3_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szalajka_Valley_Forest_Railway_in_Szilv%C3%A1sv%C3%A1rad,_2016_Hungary.jpg"}'::text[], 4),
    (v_route, 'Lillafüred a vodopád Szinva', 'Horské letovisko uprostřed lesů Bükku s pohádkovým Palace Hotelem a nejvyšším maďarským vodopádem — dvacetimetrovou kaskádou řeky Szinva, která padá přímo do visutých teras u hotelu. Okolí láká k projížďkám úzkokolejkou i k procházkám k jezeru Hámori. Serpentiny silnice č. 2505 sem z údolí Bükku patří k nejkrásnějším v Maďarsku.', 48.1, 20.6333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vizeses-Lillafured-Miskolc-Hungary-Europe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vizeses-Lillafured-Miskolc-Hungary-Europe.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lillafured_Palacehotel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miskolc,_Lillaf%C3%BCred,_jezero.jpg"}'::text[], 5),
    (v_route, 'Jeskynní lázně Miskolctapolca', 'Unikátní termální lázně, kde plavete přímo v přírodních jeskynních chodbách vyhloubených teplou vodou ve vápenci. Vlažná voda bez výrazného obsahu síry je příjemná i pro delší pobyt a chodby vytvářejí neopakovatelnou atmosféru. Ideální relax na závěr prvního náročného dne v sedle.', 48.0632, 20.7524, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miskolctapolca_Barlangf%C3%BCrd%C5%91_(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miskolctapolca_Barlangf%C3%BCrd%C5%91_(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miskolctapolca_Barlangf%C3%BCrd%C5%91_(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miskolctapolca_Barlangf%C3%BCrd%C5%91_(5).jpg"}'::text[], 6),
    (v_route, 'Tokaj — vinice UNESCO', 'Světoznámá vinařská oblast Tokaj-Hegyalja zapsaná na seznamu UNESCO, kolébka sladkého vína Tokaji Aszú, kterému kdysi říkali „víno králů, král vín“. Městečko na soutoku Tisy a Bodrogu obklopují terasovité vinice na sopečných svazích. Přístupová cesta údolím řeky nabízí klidnou, plynulou jízdu bez dálnic.', 48.1172, 21.4089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Bobajka (Tarcal)', 'Elegantní restaurace v klenutém sklepě usedlosti Andrássy Kúria v Tarcalu kousek od Tokaje, doporučovaná průvodcem Michelin. Tradiční regionální pokrmy jako lángos či brassói tu dostávají moderní, barevné pojetí a doprovázejí je precizně vybraná tokajská vína. Hodnocení hostů je vynikající (kolem 4,9), ideální gastro zastávka druhého dne.', 48.1313, 21.3499, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vineyard_near_Tokaj,_Hungary.jpg"}'::text[], 8),
    (v_route, 'Jeskyně Baradla, Aggtelek', 'Nejdelší krápníková jeskyně Maďarska a součást krasu Aggtelek a Slovenského krasu na seznamu UNESCO. Podzemní chodby s obřími krápníky a stalagmity se táhnou přes dvacet kilometrů a některé sály mají tak výjimečnou akustiku, že se v nich konají koncerty. Cesta sem vede krajinou národního parku po tichých okreskách daleko od dálnic.', 48.47185, 20.49536, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aggtelek_National_Park,_Baradla_Cave.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aggtelek_National_Park,_Baradla_Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Baradla-barlang_aggteleki_f%C5%91bej%C3%A1rat.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aggtelek_-_Baradla.jpg"}'::text[], 9),
    (v_route, 'Hollókő — vesnice UNESCO', 'Jediná vesnice v Maďarsku zapsaná na seznamu UNESCO, dokonale zachovaná ukázka lidové architektury národopisné skupiny Palóc s bílými hrázděnými domky a dřevěnými verandami. Nad obcí se tyčí zřícenina středověkého hradu s výhledem do kraje. Závěrečná zastávka trasy, kam se z Aggteleku dojede příjemnými silnicemi přes kopce Nógrádu.', 47.9953, 19.5881, 'https://commons.wikimedia.org/wiki/Special:FilePath/Holloko_Village_Center.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Holloko_Village_Center.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holl%C3%B3k%C5%91_%C3%93falu_F%C5%91_utca_(r%C3%A9szlet)_002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holl%C3%B3k%C5%91,_a_v%C3%A1r_l%C3%A9gi_felv%C3%A9telen.jpg"}'::text[], 10);
