  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Szentendre – staré město', 'Szentendre je malebné umělecké městečko na břehu Dunaje jen kousek od Budapešti, proslulé barokními domy, dlážděnými uličkami a pravoslavnými kostely srbské komunity. Srdcem starého města je hlavní náměstí Fő tér s pravoslavným křížem a kostelem Blagoveštenska z roku 1752. Najdete tu spoustu galerií, kaváren a řemeslných dílen, díky čemuž patří k nejoblíbenějším výletním cílům v okolí metropole.', 47.6694, 19.0756, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Main%20Square,%20Szentendre,%20Hungary.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Main%20Square,%20Szentendre,%20Hungary.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Blagovesztenszka%20g%C3%B6r%C3%B6gkeleti%20templom%20(Szentendre).JPG"}'::text[], 0),
    (v_route, 'Visegrád – citadela (Fellegvár)', 'Středověká citadela Fellegvár se tyčí na skalním ostrohu vysoko nad zákrutem Dunaje a nabízí jeden z nejslavnějších výhledů celého Maďarska. Horní hrad začali stavět kolem let 1250–1260 král Béla IV. a jeho manželka a v pozdním středověku zde byla střežena i svatoštěpánská koruna. Z trojúhelníkových hradeb dohlédnete na celý ohyb řeky, protější Nagymaros i Vyšehradské pohoří. Výstup nahoru odmění návštěvníka nezapomenutelným panoramatem.', 47.7969, 18.9811, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Visegr%C3%A1d%20Citadel%20from%20the%20bank%20of%20the%20Danube,%202012-03-20-3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20Visegr%C3%A1d%20Citadel%20from%20the%20bank%20of%20the%20Danube,%202012-03-20-3.jpg"}'::text[], 1),
    (v_route, 'Visegrád – královský palác', 'Zbytky renesančního letního paláce krále Matyáše Korvína leží přímo pod citadelou na břehu Dunaje. V letech 1477–1484 nechal Matyáš celý komplex přestavět v pozdně gotickém a raně renesančním slohu; v době jeho vlády měl palác na 350 místností. Dochovala se mimo jiné Herkulova kašna a arkádové nádvoří, dnes je zde muzeum krále Matyáše. Vykopávky a restaurování probíhaly od roku 1934.', 47.7913, 18.973, 'https://commons.wikimedia.org/wiki/Special:FilePath/Visegr%C3%A1d%20-%20Royal%20Palace.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Visegr%C3%A1d%20-%20Royal%20Palace.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Renaissance Étterem (Visegrád)', 'Renaissance Étterem stojí přímo na dunajském břehu na hlavní ulici Fő utca 11 ve Visegrádu, na dohled od královského paláce a citadely. Restaurace věrně oživuje atmosféru hostin krále Matyáše – kostýmovaní obsluhující, dobové interiéry a jídla servírovaná v keramických nádobách vás přenesou do renesančního zlatého věku Uher. Díky poloze zhruba v polovině okruhu je ideální zastávkou na oběd; hosté ji hodnotí velmi vysoko (Restaurant Guru 4,9).', 47.793, 18.9749, 'https://commons.wikimedia.org/wiki/Special:FilePath/F%C5%91%20utca%2011,%202018%20Visegr%C3%A1d.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/F%C5%91%20utca%2011,%202018%20Visegr%C3%A1d.jpg"}'::text[], 3),
    (v_route, 'Prédikálószék – vyhlídka (Dunakanyar)', 'Prédikálószék v nadmořské výšce 639 m je jedním z nejoblíbenějších turistických cílů Visegrádského pohoří a bývá označován za nejkrásnější vyhlídku na celý ohyb Dunaje. V roce 2016 zde vyrostla dvanáctimetrová rozhledna se třemi terasami, z nichž se postupně otevírá dechberoucí panorama zákrutu řeky. Odsud dohlédnete na Visegrád, Nagymaros i vzdálené hřebeny Börzsöny. K rozhledně vede několik značených turistických tras.', 47.73884, 18.9204, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dunakanyar,%20Nagymaros.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dunakanyar,%20Nagymaros.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/A%20dunakanyar.jpg"}'::text[], 4),
    (v_route, 'Esztergom – bazilika', 'Esztergomská bazilika je největším kostelem Maďarska a sídlem prímase; tyčí se na hradním kopci nad Dunajem zhruba 46 km severozápadně od Budapešti. Monumentální klasicistní stavba s obří kupolí dominuje celému okolí a je vidět už z dálky. Uvnitř najdete jednu z největších oltářních maleb na jediném plátně na světě a bohatě zdobené varhany. Z ochozu kupole je úchvatný výhled na řeku i na slovenské Štúrovo na druhém břehu.', 47.7995, 18.7379, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20in%20Esztergom,%20Hungary%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20in%20Esztergom,%20Hungary%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/EsztergomBasilica-South.jpg"}'::text[], 5),
    (v_route, 'Zebegény – dunajská vesnice', 'Zebegény je půvabná historická vesnice v ohybu Dunaje asi 60 km severně od Budapešti, přezdívaná „mramor Dunakanyaru“. Leží v nádherné přírodě na hranici Národního parku Duna–Ipoly, mezi řekou a kopci Börzsöny, a láká na písečné pláže, lesy a klidnou atmosféru. K místním dominantám patří secesní eklektická vila Dőry z počátku 20. století. Vesnice je oblíbeným cílem malířů i výletníků.', 47.8028, 18.9104, 'https://commons.wikimedia.org/wiki/Special:FilePath/D%C5%91ry%20Mansion,%202020%20Zebeg%C3%A9ny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/D%C5%91ry%20Mansion,%202020%20Zebeg%C3%A9ny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zebeg%C3%A9ny%20vas%C3%BAt%C3%A1llom%C3%A1s,%201.jpg"}'::text[], 6),
    (v_route, 'Vác – hlavní náměstí', 'Vác je klidné historické město na levém břehu Dunaje s barokním centrem soustředěným kolem náměstí Március 15. tér. Náměstí lemují měšťanské domy, cukrárny a historické budovy včetně bývalého dominikánského kostela zvaného „Kostel bílých“ (Fehérek temploma) z roku 1699. Vác je jediné maďarské město s dochovaným barokním vítězným obloukem a nabízí příjemnou procházku po nábřeží s výhledem na řeku.', 47.7759, 19.1361, 'https://commons.wikimedia.org/wiki/Special:FilePath/Convent%20of%20the%20Sisters%20of%20Charity.%201751.%20-%20M%C3%A1rcius%2015%20Square,%20V%C3%A1c.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Convent%20of%20the%20Sisters%20of%20Charity.%201751.%20-%20M%C3%A1rcius%2015%20Square,%20V%C3%A1c.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A1c,%20M%C3%A1rcius%2015.%20t%C3%A9r%205.JPG"}'::text[], 7),
    (v_route, 'Budapešť – Hradní vrch a Rybářská bašta', 'Rybářská bašta (Halászbástya) je novogotická terasa s bílými věžičkami a arkádami na Hradním vrchu v budínské části Budapešti. Z jejích ochozů se otevírá jeden z nejkrásnějších výhledů na Dunaj, parlament a peštskou stranu města. Bašta byla postavena na přelomu 19. a 20. století v místech někdejších středověkých hradeb a jejích sedm věží připomíná sedm zakládajících maďarských kmenů. Vedle stojí Matyášův kostel a jezdecká socha svatého Štěpána, jde o ideální tečku za okružní jízdou Dunakanyarem.', 47.5019, 19.0343, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fisherman''s%20Bastion,%20Budapest,%20Hungary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fisherman''s%20Bastion,%20Budapest,%20Hungary.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fishermans%20bastion%20Budapest%20IMG%201429.JPG"}'::text[], 8);
