  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Prato allo Stelvio', 'Jihotyrolská obec Prato allo Stelvio (německy Prad am Stilfserjoch) v nadmořské výšce kolem 915 m je klasickým startem výjezdu na Stelvio ze severní strany. Zde se doplňuje nádrž i síly před 48 serpentinami. Poklidné alpské městečko s dobrým zázemím pro motorkáře je bránou do celé oblasti Ortleru.', 46.61841, 10.5914, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20004.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20005.JPG"}'::text[], 0),
    (v_route, 'Passo dello Stelvio – vrchol s 48 serpentinami (2758 m)', 'Vrchol Stelvia ve výšce 2758 m je svatým grálem alpských motorkářů – nejvyšší silniční průsmyk Itálie a druhý nejvyšší v Alpách. Severní stranu tvoří 48 očíslovaných vlásenek, které tvoří slavnou kamennou kaskádu pod ledovcem Ortleru. Na vrcholu najdete stánky, občerstvení a nezaměnitelný výhled, ale i chlad a proměnlivé počasí i v létě.', 46.52861, 10.45278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stelvio%20tornanti.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stelvio-pass-1.JPG"}'::text[], 1),
    (v_route, 'Passo Umbrail (odbočka do Švýcarska)', 'Kousek pod vrcholem Stelvia odbočuje na Passo Umbrail (2501 m), nejvýše položenou silnici Švýcarska. Průsmyk vede z italské strany do údolí Val Müstair a nabízí klidnější alternativu k přetíženému Stelviu. Pro motorkáře je to skvělá zajížďka spojující dva státy a dvě dechberoucí panoramata.', 46.54306, 10.425, 'https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piz%20Umbrail.jpg"}'::text[], 2),
    (v_route, 'Trafoi', 'Malebná horská obec Trafoi (asi 1540 m) leží přímo pod hlavní kaskádou serpentin na severní straně Stelvia. Je posledním sídlem před náročným výstupem a poskytuje úchvatný pohled na masiv Ortleru. Ideální místo na krátkou zastávku, kávu a fotku před soubojem s vlásenkami.', 46.55225, 10.51029, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chiesadi%20Trafoi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cascate%20Trafoi.JPG"}'::text[], 3),
    (v_route, 'Bormio', 'Lázeňské městečko Bormio (asi 1225 m) v údolí Valtellina je cílem na jižní straně Stelvia a známé svými termálními prameny. Po náročném sjezdu je to příjemné místo k odpočinku, s historickým centrem a bohatou nabídkou restaurací. Slouží také jako křižovatka pro další legendární průsmyky jako Gavia či Foscagno.', 46.46762, 10.37815, 'https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Collegiata%20Kirche%20Bormio%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bagni%20vecchi%20di%20Bormio.JPG"}'::text[], 4),
    (v_route, 'Restaurace: La Rasiga (Bormio)', 'Typická valtellinská restaurace umístěná v půvabné bývalé pile v Bormiu, ideální zastávka po náročném sjezdu ze Stelvia. Servírují se zde poctivé místní speciality jako pizzoccheri (pohanková pasta) a sciatt (smažené sýrové knedlíčky). Podnik sklízí výborná hodnocení hostů za autentickou kuchyni a příjemnou atmosféru.', 46.46589, 10.37356, 'https://commons.wikimedia.org/wiki/Special:FilePath/Collegiata%20Kirche%20Bormio%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Collegiata%20Kirche%20Bormio%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bruck an der Glocknerstraße', 'Salcburská obec na severním úpatí Vysokých Taur je oficiálním startovním bodem Grossglockner Hochalpenstraße. Odtud se vydáváš vzhůru do hor, ještě než začnou první serpentiny. Ideální místo na doplnění paliva a poslední kávu před náročným výjezdem.', 47.286, 12.826, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_gro%C3%9Fglocknerstra%C3%9Fe.jpg"}'::text[], 0),
    (v_route, 'Edelweißspitze', 'Nejvyšší přístupný bod celé silnice ve výšce 2571 m, kam vede krátká dlážděná odbočka plná ostrých serpentin. Z vrcholové vyhlídky se otevírá kruhový výhled na více než 30 alpských vrcholů. Dlažba bývá kluzká, proto zde jeď opatrně a v klidu.', 47.121, 12.831, 'https://commons.wikimedia.org/wiki/Special:FilePath/Edelweissspitze.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Edelweissspitze.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Edelweisshuette.JPG"}'::text[], 1),
    (v_route, 'Hochtor', 'Průsmyk a tunel Hochtor ve výšce 2504 m tvoří nejvyšší bod hlavní trasy a historickou hranici mezi Salcburskem a Korutany. Tunel pod vrcholem hřebene je vytesán do skály a i v létě zde bývá výrazně chladno. Za tunelem se ti otevře pohled na korutanskou stranu Vysokých Taur.', 47.079, 12.845, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fglockner-Hochalpenstra%C3%9Fe_68_Tunnel.JPG"}'::text[], 2),
    (v_route, 'Kaiser-Franz-Josefs-Höhe', 'Slavná vyhlídková terasa na konci boční odbočky nabízí přímý pohled na nejvyšší horu Rakouska Grossglockner (3798 m) a ledovec Pasterze. Je zde velké parkoviště, návštěvnické centrum i restaurace. Jedno z nejfotografovanějších míst celé trasy a povinná zastávka každého motorkáře.', 47.075, 12.752, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Franz-Josefs-H%C3%B6he,_2014_(01).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Franz-Josefs-H%C3%B6he,_2014_(01).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_near_Kaiser-Franz-Josefs-H%C3%B6he,_Grossglockner_High_Alpine_Road.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Kärntnerhof Heiligenblut (Heiligenblut)', 'Rodinná restaurace přímo v Heiligenblutu, jen kousek od gotického kostela pod masivem Grossglockneru. Nabízí poctivou korutanskou a rakouskou kuchyni a na TripAdvisoru drží skvělé hodnocení 5,0 hvězdy. Ideální místo, kde po náročné jízdě serpentinami dobít síly.', 47.041, 12.842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_(1).JPG"}'::text[], 4),
    (v_route, 'Heiligenblut', 'Malebná horská obec na korutanském konci silnice, proslulá gotickým kostelem sv. Vincence s vysokou štíhlou věží na pozadí masivu Grossglockneru. Tvoří jižní bránu celé trasy a je oblíbeným cílem pro odpočinek. Skvělé místo, kde zakončit legendární alpskou jízdu.', 47.041, 12.842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_(2).JPG"}'::text[], 5);
