  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Passo Pordoi', 'Nejvyšší bod okruhu Sella Ronda ve výšce 2239 m mezi masivem Sella a Marmoladou. Slavný horský průsmyk s množstvím serpentin, který milují motorkáři i cyklisté – stoupá se sem po 33 vlásenkách. Na vrcholu najdete lanovku na Sass Pordoi, restaurace a pomník cyklisty Fausta Coppiho.', 46.487, 11.812, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Pordoi-bops%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Marmolada%20da%20Passo%20Pordoi.jpg"}'::text[], 0),
    (v_route, 'Passo Sella', 'Průsmyk ve výšce 2244 m nabízí snad nejúchvatnější výhledy celé trasy – přímo pod majestátní skupinou Sassolungo (Langkofel). Klikatá silnice s ostrými zatáčkami je rájem pro řidiče, kteří si užijí jak jízdu, tak panorama. Na sedle je horská chata a odpočinkové místo s parkovištěm.', 46.508, 11.762, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Sella%20-%20Citt%C3%A0%20dei%20Sassi%20-%20Sella%20-%20Marmolada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rifugio%20Passo%20Sella%20-%20panoramio.jpg"}'::text[], 1),
    (v_route, 'Passo Gardena / Grödner Joch', 'Severní vrchol okruhu ve výšce 2121 m spojuje Val Gardena s Alta Badia. Průsmyk lemují travnaté louky a strmé dolomitské stěny, silnice je zde o něco plynulejší, ale stále bohatá na zatáčky. U sedla stojí Rifugio Frara a nabízí se odsud výhled na skupinu Sella i Sassolungo.', 46.546, 11.81, 'https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%B6dner%20Joch.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cappella%20di%20San%20Maurizio%20-%20Passo%20Gardena%20-%2002.jpg"}'::text[], 2),
    (v_route, 'Passo Campolongo', 'Nejnižší z průsmyků okruhu (1875 m) spojuje Arabbu s Corvarou v Alta Badia. Kratší a mírnější stoupání s krásnými výhledy na masiv Sella je příjemným oddechem mezi náročnějšími sedly. Oblíbený úsek slavného cyklistického závodu Maratona dles Dolomites.', 46.52, 11.878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20View%20to%20Sella%20Ronda%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Maratona%20dles%20Dolomites%20-%20Campolongo%20Pass.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Ristorante Cialdira Ladina (Corvara)', 'Rodinná restaurace přímo v centru Corvary v Alta Badia, ležící u okruhu Sella Ronda mezi Passo Campolongo a Passo Gardena. Kuchyně vsází na tradiční ladinské suroviny a lokální speciály z Dolomit ozvláštněné moderním pojetím. Na Tripadvisoru sbírá skvělé hodnocení 4,5 z 5 hvězd a je oblíbenou zastávkou na oběd během náročné jízdy.', 46.55, 11.874, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%ABlva%20Wolkenstein%20Selva%20di%20Val%20Gardena%20Sella.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%ABlva%20Wolkenstein%20Selva%20di%20Val%20Gardena%20Sella.jpg"}'::text[], 4),
    (v_route, 'Canazei / Val di Fassa', 'Malebná horská obec v údolí Val di Fassa je ideálním výchozím bodem okruhu Sella Ronda. Nabízí ubytování, restaurace, čerpací stanice i servis – vše, co motorkář před náročnou trasou ocení. Z Canazei se vydáte na Passo Pordoi nebo Passo Sella a uzavřete kolem masivu Sella celý okruh.', 46.476, 11.77, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Casa%20dipinta%20(Canazei)03.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Canazei,%20chiesa%20della%20Madonna%20della%20Neve%2005.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sölden', 'Sölden je známé horské středisko v rakouském údolí Ötztal a přirozený výchozí bod pro jízdu na Timmelsjoch. Leží ve výšce 1 377 m n. m. a nabízí spoustu možností k občerstvení, natankování i přenocování před náročným výjezdem do hor. Odsud pokračuje silnice přes Zwieselstein a Obergurgl směrem k mýtné stanici.', 46.9667, 11.0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio.jpg"}'::text[], 0),
    (v_route, 'Restaurace: ice Q (Sölden)', 'Gurmánská restaurace ice Q stojí ve výšce 3 048 m n. m. na vrcholu Gaislachkogl nad Söldenem a je skvěle hodnocenou zastávkou hned na startu trasy. Nabízí moderní alpskou kuchyni v proskleném krychlovém objektu s dechberoucím panoramatem – restaurace je uvedena v průvodci Michelin a získala dvě čepice Gault Millau. Místo navíc proslavil natáčení bondovky Spectre, takže sem zajíždějí i filmoví fanoušci.', 46.9367, 10.9825, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B6lden_Restaurant_Ice_Q_am_Gaislachkogel_2016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B6lden_Restaurant_Ice_Q_am_Gaislachkogel_2016.jpg"}'::text[], 1),
    (v_route, 'Hochgurgl', 'Hochgurgl je poslední osada na rakouské straně před vrcholem průsmyku a najdeš tu mýtnou stanici Top Mountain Crosspoint, kde se platí za průjezd. Ve výšce kolem 2 175 m n. m. odsud začíná nejkrásnější serpentinová část silnice. Je to ideální místo na zastávku, tankování a poslední kávu před stoupáním na hřeben.', 46.9096, 11.0533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_am_Timmelsjoch.jpg"}'::text[], 2),
    (v_route, 'Timmelsjoch / Passo del Rombo 2509 m', 'Nejvyšší bod celé trasy ve výšce 2 509 m n. m. leží přímo na hranici mezi Rakouskem a Itálií. Na vrcholu stojí symbolická stavba Pass Museum, která doslova překračuje hranici obou zemí a je součástí projektu Timmelsjoch Experience. Otevírá se odsud dechberoucí panoráma Ötztalských Alp a ledovců – povinná fotozastávka každého motorkáře.', 46.9028, 11.0967, 'https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_view_south.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_view_south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tunnel_am_Timmelsjoch.jpg"}'::text[], 3),
    (v_route, 'Top Mountain Motorcycle Museum (Passmuseum)', 'Nejvýše položené motorkářské muzeum v Evropě (2 175 m n. m.) v Hochgurglu vystavuje kolem 450 historických motocyklů a automobilů v moderní dřevěné budově. Muzeum založili v roce 2016 dvojčata Alban a Attila Scheiberovi; po ničivém požáru v lednu 2021 bylo znovu postaveno. Součástí komplexu je i restaurace a mýtná stanice pro silnici Timmelsjoch – ideální zastávka pro každého fanouška motorek.', 46.867, 11.024, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hochgurgl-Top_Mountain_Motorcycle_Museum-06NTD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hochgurgl-Top_Mountain_Motorcycle_Museum-06NTD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hochgurgl-Top_Mountain_Motorcycle_Museum-04NTD.jpg"}'::text[], 4),
    (v_route, 'Moso in Passiria / Moos in Passeier', 'Moos in Passeier (italsky Moso in Passiria) je horská obec v jihotyrolském údolí Passeier a představuje cíl trasy na italské straně průsmyku. Leží ve výšce 1 036 m n. m. na soutoku potoků Plan a Passirio. Po sjezdu plném serpentin je to příjemné místo k odpočinku a ochutnávce jihotyrolské kuchyně.', 46.79436, 11.08807, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wasserwerk_Moos.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Riva del Garda', 'Malebné městečko na severním cípu jezera obklopené strmými skalními stěnami je ideálním startem i cílem okruhu. Nabízí živou promenádu, středověkou věž Apponale a spoustu kaváren, kde si motorkáři odpočinou před nebo po jízdě. Díky poloze v Trentinu tu potkáte alpskou atmosféru snoubící se s jižní pohodou.', 45.88577, 10.84117, 'https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20am%20Gardasee%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20Garda%20-%2011.jpg"}'::text[], 0),
    (v_route, 'Torbole / Ponale', 'Větrné městečko Torbole na severovýchodě je rájem surfařů a bránou ke staré silnici Ponale, jednomu z nejslavnějších úseků nad jezerem. Původní vozovka vytesaná do skalní stěny dnes slouží cyklistům a turistům a nabízí neopakovatelné výhledy z výšky přímo na hladinu. Pro motorkáře je to nezapomenutelná zastávka s panoramatem severního Garda.', 45.85271, 10.8812, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Garda%20Torbole%20Fiume%20Sarca.jpg"}'::text[], 1),
    (v_route, 'Limone sul Garda', 'Klenot západního břehu na silnici Gardesana Occidentale, proslulý úzkými uličkami, citrusovými zahradami a řadou tunelů vytesaných do skály nad hladinou. Jízda sem patří k nejfotogeničtějším úsekům celého okruhu. Zastavte se v přístavu a vychutnejte si výhled na jezero i okolní hory.', 45.81468, 10.79322, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda%20Hotel%20001.JPG"}'::text[], 2),
    (v_route, 'Restaurace: QB Duepuntozero (Salò)', 'Vyhlášená restaurace na promenádě Saló přímo u malého přístavu, uváděná v průvodci Michelin. Kuchyně staví na čerstvých sezonních surovinách a rybích specialitách z jezera v moderním pojetí. Skvělá hodnocení strávníků chválí kvalitu, výhled na hladinu i příjemnou letní terasu.', 45.6058, 10.5228, 'https://commons.wikimedia.org/wiki/Special:FilePath/Scaligero%20Castle%20of%20Sirmione,%20town%20centre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Scaligero%20Castle%20of%20Sirmione,%20town%20centre.jpg"}'::text[], 3),
    (v_route, 'Sirmione', 'Úzký poloostrov na jižním konci jezera zakončený mohutným vodním hradem Scaligero z 13. století, obklopeným vodním příkopem. Kromě hradu tu najdete termální lázně a antické zbytky Grotte di Catullo. Historické centrum je pro motorky uzavřené, zaparkujte proto před vjezdem a projděte se pěšky.', 45.49744, 10.60507, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20Scaligero%20di%20Sirmione.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Italy%20-%20Sirmione%20-%20Scaligero%20Castle.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Ristorante Mignon (Malcesine)', 'Oblíbená rodinná restaurace v historickém centru Malcesine kousek od hradu a přístavu. Nabízí italskou kuchyni s těstovinami, čerstvými rybami i pizzou a příjemnou terasu s výhledem na jezero. Vysoká hodnocení hostů (kolem 4,5–4,6) vyzdvihují chuť jídel i vstřícnou obsluhu.', 45.7659, 10.8098, 'https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG"}'::text[], 5),
    (v_route, 'Malcesine', 'Půvabné městečko na východním břehu s dominantním hradem Scaligero tyčícím se nad jezerem. Odtud vede lanovka na vrchol Monte Baldo (1760 m) s panoramatem celého Garda a Dolomit. Klikaté uličky a přístav lákají k zastávce a doplnění sil.', 45.76442, 10.81024, 'https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Scaliger%20Castle%20view%20Malcesine.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20malcesine%20lake%20garda%20veneto%20italy.JPG"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kranjska Gora', 'Známé horské středisko na severozápadě Slovinska a ideální startovní bod výjezdu na Vršič. V centru najdete kavárny, čerpací stanici i poslední možnost doplnit palivo před průsmykem. Odtud začíná řada 50 očíslovaných serpentin – motorkářský ráj Julských Alp.', 46.485, 13.786, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_Podkoren_Pr%60Gavedarjo_10072015_5730.jpg"}'::text[], 0),
    (v_route, 'Jezero Jasna', 'Idylické tyrkysové jezero hned na úpatí průsmyku, se sochou kozoroha Zlatoroga a zrcadlícími se vrcholky Julských Alp. Ideální první zastávka na fotku hned po pár kilometrech jízdy z Kranjské Gory. Kolem vede pěší okruh a je tu i parkoviště pro motorky.', 46.469, 13.788, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Altanok_Jasna.JPG"}'::text[], 1),
    (v_route, 'Průsmyk Vršič (1611 m)', 'Nejvyšší silniční průsmyk ve Slovinsku a vrchol celé trasy s dechberoucími výhledy na okolní štíty. Na vrcholu je horská chata, parkoviště a startovní bod krátkých túr. Východní sjezd tvoří původní dlážděné serpentiny, které jsou za mokra zrádné – jeďte opatrně.', 46.433, 13.747, 'https://commons.wikimedia.org/wiki/Special:FilePath/Julian_Alps_from_Vrsic_Pass_(16).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Julian_Alps_from_Vrsic_Pass_(16).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Julian_Alps_from_Vrsic_Pass_(4).jpg"}'::text[], 2),
    (v_route, 'Pramen Soči (Izvir Soče)', 'Pramen smaragdové řeky Soči v divokém údolí Trenta, kam se dostanete krátkou strmou stezkou od silnice. Křišťálově čistá voda vyvěrá přímo ze skalní stěny a je startem 138 km dlouhého toku řeky. Skvělá zastávka na oddech po sjezdu z průsmyku.', 46.409, 13.719, 'https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Gostilna Metoja (Soča)', 'Rodinná gostilna přímo na trase v obci Soča mezi pramenem řeky a Bovcem, ideální zastávka na oběd v polovině cesty. Vaří poctivou domácí kuchyni údolí Trenta – proslulé jsou grilované pstruhy a místní speciality čompe. S hodnocením 4,5 hvězdy patří k nejlépe hodnoceným v okolí a láká i nádherným výhledem na hory z terasy.', 46.345, 13.652, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velika_korita_So%C4%8De_So%C4%8Da_(Bovec)_01.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velika_korita_So%C4%8De_So%C4%8Da_(Bovec)_01.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zadnja_Trenta_village_under_the_mountains.jpg"}'::text[], 4),
    (v_route, 'Bovec', 'Adrenalinové městečko v srdci údolí Soči a cíl celé trasy pod masivem Kaninu. Nabízí rafting, kavárny, restaurace i ubytování a je výborným místem na přenocování nebo doplnění paliva. Odtud lze pokračovat dál údolím Soči nebo se vrátit stejnou trasou.', 46.338, 13.552, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Hotel_Kanin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Hotel_Kanin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zipline_Bovec_Slovenia.jpg"}'::text[], 5);
